(301101, 3011, 'K22-C1-L1-O01', null, 1, 'أن يميز الطالب بين طاقة الوضع و الطاقة الحركية.', 'أن يميّز الطالب بين طاقة الوضع والطاقة الحركية.', '[]'::jsonb, 'أن يميّز الطالب بين طاقة الوضع والطاقة الحركية.', 'ضبط «يميّز» وحذف المسافة قبل حرف العطف.', 'إملائي', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["طاقة الوضع","الطاقة الحركية"]'::jsonb, null, '[12,13,18]'::jsonb, 'مغطى', 'تعتمد طاقة الوضع على تركيب الجسم أو موضعه، والحركية عن حركته؛ مثال المتزلج (الشكل 1-1، ص12) والسد (ص13)، وس8 في التقويم (ص18).', null, 'approved', '2026-11-03'::timestamptz),
(301102, 3011, 'K22-C1-L1-O02', null, 2, 'أن يميز الطالب بين الحرارة و درجة الحرارة.', 'أن يميّز الطالب بين الحرارة ودرجة الحرارة.', '[]'::jsonb, 'أن يميّز الطالب بين الحرارة ودرجة الحرارة.', 'ضبط «يميّز» وحذف المسافة قبل حرف العطف.', 'إملائي', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["الحرارة q","درجة الحرارة","الطاقة الحركية للجسيمات"]'::jsonb, null, '[12,14,42]'::jsonb, 'مغطى', 'درجة الحرارة مقياس متوسط الطاقة الحركية للجسيمات (مراجعة المفردات ص12)، والحرارة طاقة تنتقل من الجسم الساخن إلى الأبرد (ص14)؛ س44 (ص42).', null, 'approved', '2026-11-03'::timestamptz),
(301103, 3011, 'K22-C1-L1-O03', null, 3, 'أن يذكر الطالب وحدات قياس كمية الحرارة.', 'أن يذكر الطالب وحدات قياس الحرارة (السُّعر، والسُّعر الغذائي، والجول).', '[]'::jsonb, 'أن يذكر الطالب وحدات قياس الحرارة (السُّعر، والسُّعر الغذائي، والجول).', 'تحديد الوحدات المقصودة كما يعرضها الكتاب.', 'صياغة', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["السُّعر cal","السُّعر الغذائي Cal","الجول J","kJ"]'::jsonb, null, '[14,18]'::jsonb, 'مغطى', 'السعر cal، والسعر الغذائي Cal = 1 kcal = 1000 cal، والجول وحدة النظام الدولي (ص14).', null, 'approved', '2026-11-03'::timestamptz),
(301104, 3011, 'K22-C1-L1-O04', null, 4, 'أن يميز الطالب بين السعر و الحرارة النوعية.', 'أن يميّز الطالب بين السُّعر والحرارة النوعية.', '[]'::jsonb, 'أن يميّز الطالب بين السُّعر والحرارة النوعية.', 'ضبط «يميّز» وتشكيل «السُّعر».', 'إملائي', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["السُّعر","الحرارة النوعية c"]'::jsonb, null, '[14,15]'::jsonb, 'مغطى', 'السعر: كمية الحرارة اللازمة لرفع درجة حرارة 1g من الماء النقي 1°C (ص14)؛ الحرارة النوعية: لرفع 1g من أي مادة 1°C، وللماء 4.184 J/g·°C (ص15).', null, 'approved', '2026-11-03'::timestamptz),
(301105, 3011, 'K22-C1-L1-O05', null, 5, 'أن يحدد الطالب العلاقة بين وحدات الطاقة المختلفة.', 'أن يحوّل الطالب بين وحدات الطاقة المختلفة (J، cal، Cal، kJ).', '[]'::jsonb, 'أن يحوّل الطالب بين وحدات الطاقة المختلفة (J، cal، Cal، kJ).', '«يحدد العلاقة» غير قابل للقياس مباشرة؛ الكتاب يطلب التحويل بين الوحدات.', 'تحويل إلى هدف قابل للقياس', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["1 J = 0.2390 cal","1 cal = 4.184 J","1 Cal = 1000 cal"]'::jsonb, null, '[14,15,42]'::jsonb, 'مغطى', 'الجدول 1-1 وعوامل التحويل (ص14)، والمثال 1-1 ومسائل 1–3 (ص15)، ومسائل 53–57 (ص42).', null, 'approved', '2026-11-03'::timestamptz),
(301106, 3011, 'K22-C1-L1-O06', null, 6, 'أن يعرف الطالب المسعر.', 'أن يعرّف الطالب المسعر.', '[]'::jsonb, 'أن يعرّف الطالب المسعر.', 'ضبط «يعرّف». المستوى في الملف «فهم» والتعريف تذكر.', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["المسعر","مسعر القنبلة","كأس البوليسترين"]'::jsonb, null, '[19]'::jsonb, 'مغطى', '«المسعر جهاز معزول حراريًا يستخدم لقياس كمية الحرارة الممتصة أو المنطلقة» (ص19). يرد في الكتاب ضمن الدرس 1-2.', null, 'approved', '2026-11-03'::timestamptz),
(301107, 3011, 'K22-C1-L1-O07', null, 7, 'أن يحسب الطالب الحرارة النوعية للمادة.', 'أن يحسب الطالب الحرارة النوعية لمادة باستعمال العلاقة q = c × m × ΔT.', '[]'::jsonb, 'أن يحسب الطالب الحرارة النوعية لمادة باستعمال العلاقة q = c × m × ΔT.', 'ربط الهدف بالعلاقة المستعملة في الكتاب.', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["q = c × m × ΔT","الحرارة النوعية"]'::jsonb, null, '[16,17,21]'::jsonb, 'مغطى', 'معادلة حساب الحرارة (ص16)، والمثال 1-2: الحرارة النوعية للحديد 0.449 J/g·°C (ص17)، ومسائل 4–6 و12–15.', null, 'approved', '2026-11-03'::timestamptz),
(301108, 3011, 'K22-C1-L1-O08', null, 8, 'أن يعرّف الطالب الطاقة.', 'أن يعرّف الطالب الطاقة.', '[]'::jsonb, 'أن يعرّف الطالب الطاقة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["الطاقة"]'::jsonb, null, '[12,18,41]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). «تعرف الطاقة بأنها القدرة على بذل شغل أو إنتاج حرارة» (ص12)، وهي من أهداف الكتاب للدرس.', null, 'approved', '2026-11-03'::timestamptz),
(301109, 3011, 'K22-C1-L1-O09', null, 9, 'أن ينص الطالب على قانون حفظ الطاقة ويطبقه على تحولات الطاقة.', 'أن ينص الطالب على قانون حفظ الطاقة ويطبقه على تحولات الطاقة.', '[]'::jsonb, 'أن ينص الطالب على قانون حفظ الطاقة ويطبقه على تحولات الطاقة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وقوانين', '["قانون حفظ الطاقة","القانون الأول في الديناميكا الحرارية"]'::jsonb, null, '[13,18,42]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). «في أي تفاعل كيميائي أو عملية فيزيائية يمكن أن تتحول الطاقة من شكل إلى آخر، ولكنها لا تستحدث ولا تفنى» (ص13)، وس45–47 (ص42).', null, 'approved', '2026-11-03'::timestamptz),
(301110, 3011, 'K22-C1-L1-O10', null, 10, 'أن يوضح الطالب المقصود بطاقة الوضع الكيميائية والعوامل التي تعتمد عليها.', 'أن يوضح الطالب المقصود بطاقة الوضع الكيميائية والعوامل التي تعتمد عليها.', '[]'::jsonb, 'أن يوضح الطالب المقصود بطاقة الوضع الكيميائية والعوامل التي تعتمد عليها.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["طاقة الوضع الكيميائية","الروابط","ترتيب الذرات"]'::jsonb, null, '[13,18]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). «الطاقة المخزنة في الروابط الكيميائية للمادة… تعتمد على عدد ونوع الذرات وترتيبها» (ص13، خلاصة ص18)، وهي من أهداف الكتاب للدرس.', null, 'approved', '2026-11-03'::timestamptz),
(301111, 3011, 'K22-C1-L1-O11', null, 11, 'أن يحسب الطالب درجة الحرارة النهائية أو كتلة المادة باستعمال علاقة الحرارة النوعية.', 'أن يحسب الطالب درجة الحرارة النهائية أو كتلة المادة باستعمال علاقة الحرارة النوعية.', '[]'::jsonb, 'أن يحسب الطالب درجة الحرارة النهائية أو كتلة المادة باستعمال علاقة الحرارة النوعية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'حل مسائل', '["q = c × m × ΔT","ΔT = Tf − Ti"]'::jsonb, null, '[17,21,43]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). مسألة 6 (ص17) ومسائل 13 و15 (ص21) ومسائل 65–68 (ص43).', null, 'approved', '2026-11-03'::timestamptz),
(301112, 3011, 'K22-C1-L1-O12', null, 12, 'أن يرتب الطالب مواد مختلفة وفق سرعة ارتفاع درجة حرارتها اعتمادًا على قيم حرارتها النوعية.', 'أن يرتب الطالب مواد مختلفة وفق سرعة ارتفاع درجة حرارتها اعتمادًا على قيم حرارتها النوعية.', '[]'::jsonb, 'أن يرتب الطالب مواد مختلفة وفق سرعة ارتفاع درجة حرارتها اعتمادًا على قيم حرارتها النوعية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'مفاهيم', '["الحرارة النوعية","الجدول 1-2"]'::jsonb, null, '[16,18]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الجدول 1-2 للحرارة النوعية (ص16)، وس11: ترتيب الألومنيوم والذهب والحديد والفضة (ص18).', null, 'approved', '2026-11-03'::timestamptz),
(301113, 3011, 'K22-C1-L1-O13', null, 13, 'أن يصف الطالب استعمالات الطاقة الشمسية والخلايا الكهروضوئية وجهود المملكة في مجال الطاقة المتجددة.', 'أن يصف الطالب استعمالات الطاقة الشمسية والخلايا الكهروضوئية وجهود المملكة في مجال الطاقة المتجددة.', '[]'::jsonb, 'أن يصف الطالب استعمالات الطاقة الشمسية والخلايا الكهروضوئية وجهود المملكة في مجال الطاقة المتجددة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'حقائق ومصطلحات', '["الطاقة الشمسية","الخلايا الكهروضوئية","رؤية 2030","مدينة الملك عبدالعزيز للعلوم والتقنية"]'::jsonb, null, '[18]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الطاقة الشمسية والخلايا الكهروضوئية، وجائزة الملك فيصل لمايكل جراتزل (1436هـ)، ومدينة الملك عبدالعزيز للعلوم والتقنية، ورؤية 2030 (ص18).', null, 'approved', '2026-11-03'::timestamptz),
(301201, 3012, 'K22-C1-L2-O01', null, 1, 'أن يعرف الطالب الكيمياء الحرارية.', 'أن يعرّف الطالب الكيمياء الحرارية.', '[]'::jsonb, 'أن يعرّف الطالب الكيمياء الحرارية.', 'ضبط «يعرّف».', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["الكيمياء الحرارية"]'::jsonb, null, '[21,24]'::jsonb, 'مغطى', '«الكيمياء الحرارية تدرس تغيرات الحرارة التي ترافق التفاعلات الكيميائية وتغيرات الحالة الفيزيائية» (ص21).', null, 'approved', '2026-11-03'::timestamptz),
(301202, 3012, 'K22-C1-L2-O02', null, 2, 'أن يوضح الطالب كيفية انتقال الحرارة في الأنظمة الحرارية.', 'أن يوضح الطالب اتجاه انتقال الحرارة بين النظام والمحيط في التفاعلات الطاردة والماصة للحرارة.', '[]'::jsonb, 'أن يوضح الطالب اتجاه انتقال الحرارة بين النظام والمحيط في التفاعلات الطاردة والماصة للحرارة.', 'تحديد المقصود بـ«الأنظمة الحرارية» كما في الكتاب.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["النظام","المحيط","انتقال الحرارة"]'::jsonb, null, '[22,24]'::jsonb, 'مغطى', 'في الكمادة الساخنة تنتقل الحرارة من النظام إلى المحيط، وفي تفاعل هيدروكسيد الباريوم مع ثيوسيانات الأمونيوم من المحيط إلى النظام (الشكل 1-6، ص22).', null, 'approved', '2026-11-03'::timestamptz),
(301203, 3012, 'K22-C1-L2-O03', null, 3, 'أن يحدد الطالب العمليات الحرارية في الأنظمة الحرارية.', 'أن يحدد الطالب النظام والمحيط والكون في عملية حرارية معطاة.', '[]'::jsonb, 'أن يحدد الطالب النظام والمحيط والكون في عملية حرارية معطاة.', '«يحدد العمليات الحرارية» عبارة عامة؛ الكتاب يعرّف النظام والمحيط والكون ويطلب تطبيقها.', 'تحويل إلى هدف قابل للقياس', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["النظام","المحيط","الكون = النظام + المحيط"]'::jsonb, null, '[22,24,42]'::jsonb, 'مغطى', 'تعريف النظام والمحيط والكون (ص22)، وس20 (ص24) وس61 (ص42).', null, 'approved', '2026-11-03'::timestamptz),
