insert into public.revisions (entity, entity_id, action, before_json, after_json, note, user_name, at)
select 'objective', o.id, 'approve', '{"reviewStatus":"pending","approvedText":null}'::jsonb, jsonb_build_object('reviewStatus', 'approved', 'approvedText', o.approved_text),
  'مالك المشروع: اعتماد مراجعة الأهداف الرسمية', 'مالك المشروع', '2026-11-03'::timestamptz
from public.objectives o where o.code like 'K22-%' and o.review_status = 'approved'
  and (o.memo_note like 'هدف مضاف من الكتاب%') = false
  and not exists (select 1 from public.revisions r where r.entity = 'objective' and r.entity_id = o.id and r.action = 'approve');

insert into public.revisions (entity, entity_id, action, before_json, after_json, note, user_name, at)
select 'objective', o.id, 'approve', '{"reviewStatus":"pending","approvedText":null}'::jsonb, jsonb_build_object('reviewStatus', 'approved', 'approvedText', o.approved_text),
  'مالك المشروع: اعتماد الأهداف المضافة من الكتاب المدرسي', 'مالك المشروع', '2026-11-03'::timestamptz
from public.objectives o where o.code like 'K22-%' and o.review_status = 'approved'
  and (o.memo_note like 'هدف مضاف من الكتاب%') = true
  and not exists (select 1 from public.revisions r where r.entity = 'objective' and r.entity_id = o.id and r.action = 'approve');

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C1-L1-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالطاقة الحركية؟', null, null, '["الطاقة التي تعتمد على تركيب الجسم أو موضعه","الطاقة الناتجة عن حركة الأجسام","الطاقة المخزنة في الروابط الكيميائية للمادة","الطاقة التي تنتقل من الجسم الساخن إلى الأبرد"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 12 — طبيعة الطاقة (طاقة الوضع والطاقة الحركية)'),
('mcq', 2, 'على أيّ شيء تعتمد طاقة الوضع لجسم ما؟', null, null, '["سرعة حركة الجسم","درجة حرارة الوسط المحيط بالجسم","كمية الحرارة التي يفقدها الجسم","تركيب الجسم أو موضعه"]'::jsonb, 'تذكر', 'تذكر خاصية', 'سهل', 'الكتاب ص 12 — طبيعة الطاقة (طاقة الوضع والطاقة الحركية)'),
('mcq', 3, 'متزلج يقف ساكنًا عند نقطة البداية في أعلى مسار التزلج. أيّ وصف لطاقته في هذه اللحظة صحيح؟', null, null, '["طاقة وضعه أكبر ما يمكن، ولا يملك طاقة حركية","طاقته الحركية أكبر ما يمكن، ولا يملك طاقة وضع","طاقة وضعه تساوي طاقته الحركية تمامًا","لا يملك طاقة وضع ولا طاقة حركية"]'::jsonb, 'فهم', 'تفسير موقف', 'سهل', 'الكتاب ص 12 — طبيعة الطاقة (طاقة الوضع والطاقة الحركية)'),
('mcq', 4, 'يتدفق الماء المخزون خلف سد عبر فتحة الخزان إلى الأسفل فيدير التوربينات. ما تحوّل الطاقة الذي يحدث للماء في أثناء تدفقه إلى الأسفل؟', null, null, '["تتحول طاقته الحركية إلى طاقة وضع","تفنى طاقة وضعه وتُستحدث بدلًا منها طاقة كهربائية","تتحول طاقة وضعه إلى طاقة حركية","تتحول الحرارة المخزنة فيه إلى طاقة وضع"]'::jsonb, 'فهم', 'تفسير تحول طاقة', 'متوسط', 'الكتاب ص 13 — قانون حفظ الطاقة (محطة التوليد الكهرومائية)'),
('mcq', 5, 'أيّ الأمثلة الآتية يمثّل طاقة وضع؟', null, null, '["ماء نهر جارٍ","كتب موضوعة على رفوف","سيارات في سباق","ثلج منهار من قمة جبل"]'::jsonb, 'فهم', 'تصنيف أمثلة', 'متوسط', 'الكتاب ص 18 — التقويم 1-1 (س8)'),
('mcq', 6, 'تنطلق طاقة على شكل حرارة عند احتراق غاز البروبان C₃H₈. في أيّ صورة كانت هذه الطاقة مخزنة في البروبان قبل احتراقه؟', null, null, '["طاقة حركية ناتجة عن حركة جزيئاته","حرارة مخزنة داخل جزيئاته","طاقة وضع ناتجة عن ارتفاع الأسطوانة عن الأرض","طاقة وضع كيميائية في الروابط بين ذراته"]'::jsonb, 'فهم', 'تفسير مفهوم', 'متوسط', 'الكتاب ص 13 — قانون حفظ الطاقة وطاقة الوضع الكيميائية'),
('mcq', 7, 'ينزلق متزلج من أعلى المسار إلى أسفله، وكان مجموع طاقتي الوضع والحركة له 5000 J. بإهمال الاحتكاك، إذا أصبحت طاقة وضعه عند نقطة ما من المسار 2000 J، فما طاقته الحركية عند تلك النقطة؟', null, null, '["3000 J","2000 J","5000 J","7000 J"]'::jsonb, 'تطبيق', 'حساب باستعمال حفظ الطاقة', 'صعب', 'الكتاب ص 12، 13 — المتزلج وقانون حفظ الطاقة'),
('essay', 1, 'ميّز بين طاقة الوضع والطاقة الحركية من حيث: (أ) ما تعتمد عليه كل منهما. (ب) مثال واحد على كل منهما.', null, null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 12 — طبيعة الطاقة (طاقة الوضع والطاقة الحركية)'),
('essay', 2, 'صنّف كل حالة مما يأتي إلى طاقة وضع أو طاقة حركية، مع ذكر السبب: (1) ماء مخزون خلف سد. (2) كرة تتدحرج على أرض مستوية. (3) جزيئات غاز تتحرك عشوائيًا. (4) الروابط في جزيء الجلوكوز. (5) مغناطيسان منفصلان. (6) سيارة تسير على طريق.', null, null, null, 'تطبيق', 'تصنيف وتعليل', 'صعب', 'الكتاب ص 12، 13، 18 — طاقة الوضع والطاقة الحركية'),
('essay', 3, 'يبدأ متزلج ساكنًا عند بوابة البداية في أعلى المسار، ثم ينزلق حتى يصل إلى خط النهاية في أسفله. حلّل ما يحدث لطاقة وضعه ولطاقته الحركية: (أ) عند بوابة البداية. (ب) في أثناء الانزلاق. (ج) فسّر ذلك في ضوء قانون حفظ الطاقة.', null, null, null, 'تحليل', 'تحليل تحولات الطاقة', 'صعب', 'الكتاب ص 12، 13 — المتزلج وقانون حفظ الطاقة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C1-L1-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الطاقة الحركية هي الطاقة الناتجة عن حركة الأجسام؛ فكل جسم متحرك يمتلك طاقة حركية.', '["هذا تعريف طاقة الوضع لا الطاقة الحركية.","","هذا وصف طاقة الوضع الكيميائية، وهي صورة من صور طاقة الوضع.","هذا تعريف الحرارة q، وليس تعريف الطاقة الحركية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-03T20:51:23.815Z"}'::jsonb),
('mcq', 2, 3, 'طاقة الوضع هي الطاقة التي تعتمد على تركيب الجسم أو موضعه، مثل المتزلج في أعلى المسار أو الماء المخزون خلف سد.', '["سرعة الجسم تحدد طاقته الحركية لا طاقة وضعه.","درجة حرارة الوسط المحيط لا تحدد طاقة وضع الجسم؛ فهي مرتبطة بمتوسط الطاقة الحركية لجسيماته.","الحرارة المفقودة طاقة منتقلة، ولا تحدد طاقة الوضع التي يمتلكها الجسم بسبب تركيبه أو موضعه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:51:23.816Z"}'::jsonb),
('mcq', 3, 0, 'المتزلج في أعلى المسار تكون طاقة وضعه أكبر ما يمكن بسبب موضعه المرتفع، ولأنه ساكن لا يملك طاقة حركية.', '["","الطاقة الحركية تنتج عن الحركة، والمتزلج ساكن؛ وطاقة وضعه في أعلى المسار هي الأكبر لا المعدومة.","المتزلج الساكن لا يملك طاقة حركية، فلا يمكن أن تتساوى الطاقتان.","موضعه المرتفع يمنحه طاقة وضع كبيرة، فلا يصح القول إنه لا يملك طاقة وضع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-03T20:51:23.816Z"}'::jsonb),
('mcq', 4, 2, 'الماء المخزون في الأعلى يمتلك طاقة وضع بسبب موضعه، وعندما يتدفق إلى الأسفل تتحول طاقة وضعه إلى طاقة حركية يُحوَّل جزء منها إلى طاقة كهربائية في التوربينات.', '["الاتجاه معكوس؛ فالماء يفقد ارتفاعه في أثناء نزوله، فتقل طاقة وضعه وتزداد طاقته الحركية.","الطاقة لا تفنى ولا تُستحدث وفق قانون حفظ الطاقة، وإنما تتحول من شكل إلى آخر.","","الحرارة طاقة منتقلة وليست مخزنة في الماء، والتحول الحادث هو من طاقة وضع إلى طاقة حركية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-03T20:51:23.816Z"}'::jsonb),
('mcq', 5, 1, 'الكتب الموضوعة على الرفوف ساكنة، وطاقتها ناتجة عن موضعها المرتفع؛ لذا تمثل طاقة وضع.', '["ماء النهر الجاري متحرك، فطاقته الغالبة طاقة حركية.","","السيارات في السباق تتحرك، فطاقتها طاقة حركية.","الثلج المنهار يتحرك إلى الأسفل، فطاقته الغالبة طاقة حركية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-03T20:51:23.817Z"}'::jsonb),
('mcq', 6, 3, 'الطاقة المخزنة في الروابط الكيميائية للمادة تسمى طاقة الوضع الكيميائية؛ وتنتج في البروبان عن ترتيب ذرات الكربون والهيدروجين وقوة الروابط بينها، وتتحرر في صورة حرارة عند احتراقه.', '["الطاقة الحركية للجزيئات مرتبطة بدرجة الحرارة، وليست مصدر الطاقة التي تتحرر عند الاحتراق.","الحرارة طاقة منتقلة من جسم ساخن إلى أبرد، ولا تُخزَّن داخل المادة بهذا الاسم.","طاقة الاحتراق لا تعتمد على ارتفاع الأسطوانة، بل على الروابط الكيميائية في الجزيئات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-03T20:51:23.817Z"}'::jsonb),
('mcq', 7, 0, 'وفق قانون حفظ الطاقة يبقى مجموع طاقتي الوضع والحركة ثابتًا: 5000 J − 2000 J = 3000 J؛ فقد تحوّل 3000 J من طاقة الوضع إلى طاقة حركية.', '["","هذا يفترض خطأً أن الطاقة الحركية تساوي طاقة الوضع دائمًا.","هذا يعني أن كل طاقة الوضع تحولت إلى حركية، مع أن المتزلج ما زال يملك 2000 J طاقة وضع.","جُمعت الطاقتان بدلًا من الطرح، وهذا يعني استحداث طاقة تخالف قانون حفظ الطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:51:23.817Z"}'::jsonb),
('essay', 1, null::int, null, null, 'طاقة الوضع: طاقة تعتمد على تركيب الجسم أو موضعه، ومثالها الماء المخزون خلف سد، أو المتزلج في أعلى المسار، أو طاقة الوضع الكيميائية المخزنة في روابط البروبان. الطاقة الحركية: طاقة ناتجة عن حركة الأجسام، ومثالها الماء المتدفق إلى التوربينات، أو المتزلج في أثناء انزلاقه إلى الأسفل.', '["طاقة الوضع تعتمد على تركيب الجسم أو موضعه","الطاقة الحركية تنتج عن حركة الجسم","مثال صحيح على طاقة الوضع","مثال صحيح على الطاقة الحركية"]'::jsonb, '[]'::jsonb, '[{"element":"ما تعتمد عليه طاقة الوضع","marks":1},{"element":"ما تعتمد عليه الطاقة الحركية","marks":1},{"element":"مثال طاقة الوضع","marks":1},{"element":"مثال الطاقة الحركية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يذكر أساس كل نوع بدقة ومثالًا صحيحًا لكل منهما"},{"level":"2–3 درجات","description":"يذكر أساس النوعين دون مثالين صحيحين، أو يخلط في أحد العنصرين"},{"level":"1 درجة","description":"يذكر عنصرًا واحدًا صحيحًا فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ربط طاقة الوضع بالسرعة بدلًا من الموضع أو التركيب","إهمال التركيب الكيميائي مصدرًا لطاقة الوضع","ذكر مثال لجسم متحرك على أنه طاقة وضع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:51:23.818Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) طاقة وضع؛ بسبب موضع الماء المرتفع. (2) طاقة حركية؛ لأن الكرة تتحرك. (3) طاقة حركية؛ لأن الجزيئات في حركة دائمة. (4) طاقة وضع كيميائية؛ مخزنة في الروابط وتعتمد على ترتيب الذرات ونوعها. (5) طاقة وضع؛ تعتمد على موضع كل مغناطيس بالنسبة إلى الآخر. (6) طاقة حركية؛ لأن السيارة تتحرك.', '["(1) وضع","(2) حركية","(3) حركية","(4) وضع كيميائية","(5) وضع","(6) حركية"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة 1 مع السبب","marks":1},{"element":"الحالة 2 مع السبب","marks":1},{"element":"الحالة 3 مع السبب","marks":1},{"element":"الحالة 4 مع السبب","marks":1},{"element":"الحالة 5 مع السبب","marks":1},{"element":"الحالة 6 مع السبب","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"يصنف الحالات الست تصنيفًا صحيحًا مع تعليل كل منها"},{"level":"3–5 درجات","description":"يصنف معظم الحالات صحيحًا أو يغفل التعليل في بعضها"},{"level":"1–2 درجة","description":"يصنف حالة أو حالتين صحيحًا فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الروابط الكيميائية طاقة حركية","عدّ المغناطيسين المنفصلين طاقة حركية لعدم وجود ارتفاع","الاكتفاء بالتصنيف دون ذكر السبب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-03T20:51:23.818Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) عند البداية تكون طاقة الوضع أكبر ما يمكن بسبب الموضع المرتفع، والطاقة الحركية صفرًا لأنه ساكن. (ب) في أثناء الانزلاق يقل الارتفاع فتقل طاقة الوضع، وتزداد السرعة فتزداد الطاقة الحركية. (ج) تتحول طاقة الوضع إلى طاقة حركية، والطاقة لا تُستحدث ولا تفنى، وإنما تتحول من شكل إلى آخر ويبقى مجموعها ثابتًا.', '["طاقة الوضع عظمى والحركية صفر عند البداية","تقل طاقة الوضع في أثناء الانزلاق","تزداد الطاقة الحركية في أثناء الانزلاق","الطاقة تتحول ولا تفنى ولا تستحدث ويبقى مجموعها ثابتًا"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الحالة عند البداية","marks":1},{"element":"تغير طاقة الوضع","marks":1},{"element":"تغير الطاقة الحركية","marks":1},{"element":"الربط بقانون حفظ الطاقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحلل المراحل كلها ويربطها بقانون حفظ الطاقة ربطًا صحيحًا"},{"level":"2–3 درجات","description":"يصف التغيرين صحيحًا مع نقص في وصف البداية أو في الربط بالقانون"},{"level":"1 درجة","description":"يذكر عنصرًا واحدًا صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن طاقة الوضع تفنى عند خط النهاية","القول إن للمتزلج الساكن طاقة حركية","نسيان أن مجموع الطاقتين يبقى ثابتًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:51:23.819Z"}'::jsonb)
