('mcq', 6, 'بأيّ وحدة تقاس كل من درجة الحرارة والحرارة؟', null, null, '["درجة الحرارة بـ °C، والحرارة بـ J","كل منهما يقاس بـ J","درجة الحرارة بـ J، والحرارة بـ °C","كل منهما يقاس بـ °C"]'::jsonb, 'فهم', 'تمييز بالوحدات', 'سهل', 'الكتاب ص 14، 16 — قياس الحرارة ومعادلة حساب الحرارة'),
