('mcq', 3, 3, 'الحرارة طاقة تنتقل من الجسم الساخن (الفلز) إلى الأبرد (الماء)؛ فيفقد الفلز طاقة فتنخفض درجة حرارته، ويمتص الماء طاقة فترتفع درجة حرارته، ويستمر الانتقال حتى تتساوى درجتا حرارتهما.', '["درجة الحرارة مقياس لمتوسط الطاقة الحركية للجسيمات، ولا تنتقل؛ الذي ينتقل هو الحرارة.","البرودة ليست طاقة تنتقل؛ الذي ينتقل هو الحرارة من الفلز الساخن إلى الماء.","الاتجاه معكوس؛ فالحرارة تنتقل من الجسم الساخن إلى الأبرد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-03T20:51:23.820Z"}'::jsonb),
('mcq', 4, 1, 'الطاقة الحركية للجسيمات ترتبط بحركتها العشوائية وتتناسب مع درجة الحرارة؛ فعندما ترتفع درجة الحرارة يزداد متوسط طاقتها الحركية وتزداد سرعة حركتها.', '["انخفاض متوسط الطاقة الحركية يصاحب انخفاض درجة الحرارة لا ارتفاعها.","","كتلة الجسيمات لا تتغير بالتسخين، وارتفاع درجة الحرارة يعني زيادة متوسط الطاقة الحركية.","حركة الجسيمات دائمة ولا تتوقف بالتسخين، بل تزداد سرعتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-03T20:51:23.821Z"}'::jsonb),
('mcq', 5, 2, 'الحرارة طاقة منتقلة تقاس بالجول J، وتنتقل من الأسخن (الشاي) إلى الأبرد (الكوب)؛ أما درجة الحرارة فتقاس بـ °C ولا تنتقل.', '["درجة الحرارة لا تقاس بالجول ولا تنتقل؛ فالجول وحدة للحرارة.","الذي ينتقل هو الحرارة، أما درجة الحرارة فمقياس لمتوسط الطاقة الحركية ولا تنتقل.","","الحرارة طاقة منتقلة تقاس بالجول، و°C وحدة لدرجة الحرارة لا للحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-03T20:51:23.821Z"}'::jsonb),
('mcq', 6, 0, 'درجة الحرارة تقاس بالدرجة السيليزية °C (أو الكلفن)، أما الحرارة فطاقة تقاس بالجول J (أو cal).', '["","الجول وحدة للطاقة (الحرارة)، ولا تقاس به درجة الحرارة.","الوحدتان معكوستان؛ فالجول للحرارة و°C لدرجة الحرارة.","°C وحدة لدرجة الحرارة فقط، أما الحرارة فطاقة تقاس بالجول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-03T20:51:23.821Z"}'::jsonb),
('mcq', 7, 3, 'التغير في درجة الحرارة 10°C في العينتين، لكن الحرارة الممتصة تعتمد على الكتلة: q = c × m × ΔT، فهي 4184 J للعينة 100 g و8368 J للعينة 200 g، أي الضعف.', '["تساوي التغير في درجة الحرارة لا يعني تساوي الحرارة؛ فالحرارة تعتمد أيضًا على الكتلة.","العلاقة معكوسة؛ فالعينة الأكبر كتلة هي التي تمتص حرارة أكبر.","العينتان سُخنتا إلى درجة الحرارة نفسها، فالتغير في درجة الحرارة متساوٍ (10°C).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-03T20:51:23.822Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الحرارة طاقة تنتقل من الجسم الساخن إلى الجسم الأبرد، أما درجة الحرارة فمقياس لمتوسط الطاقة الحركية للجسيمات في عينة من المادة. (ب) رمز الحرارة q، ورمز درجة الحرارة T. (ج) تقاس الحرارة بالجول J (أو السُّعر cal)، وتقاس درجة الحرارة بالدرجة السيليزية °C.', '["تعريف الحرارة","تعريف درجة الحرارة","الرمزان q وT","الوحدتان J و°C"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الحرارة","marks":2},{"element":"تعريف درجة الحرارة","marks":2},{"element":"الرمزان","marks":1},{"element":"الوحدتان","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة كاملة صحيحة في الجوانب الثلاثة"},{"level":"3–5 درجات","description":"تعريفان صحيحان مع خطأ أو نقص في الرمز أو الوحدة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف درجة الحرارة بأنها كمية الحرارة في الجسم","قياس الحرارة بـ °C","الخلط بين الرمز q والرمز c"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-03T20:51:23.822Z"}'::jsonb),
