('mcq', 3, 0, 'تقاس الطاقة الحرارية الناتجة عن الغذاء بالسُّعرات الغذائية (Cal)، والسُّعر الغذائي الواحد يساوي 1000 cal.', '["","السُّعر (cal) أصغر بألف مرة من السُّعر الغذائي، وطاقة الغذاء يعبر عنها بالسُّعر الغذائي Cal.","الدرجة السيليزية وحدة لدرجة الحرارة لا للطاقة.","الوحدة J/g·°C وحدة الحرارة النوعية لا وحدة الطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-03T20:51:23.824Z"}'::jsonb),
('mcq', 4, 2, 'السُّعر الغذائي الواحد يساوي 1 kcal، أي 1000 cal.', '["4.184 هو عدد الجولات في السُّعر الواحد (1 cal = 4.184 J).","البادئة كيلو تعني 1000 لا 100.","","0.2390 هو عدد السُّعرات في الجول الواحد (1 J = 0.2390 cal)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-03T20:51:23.824Z"}'::jsonb),
('mcq', 5, 3, 'السُّعر الواحد يعادل 4.184 J، أي 1 cal = 4.184 J (ويكافئ ذلك 1 J = 0.2390 cal).', '["العلاقة معكوسة؛ فالسُّعر أكبر من الجول، و1 J = 0.2390 cal.","العلاقة معكوسة؛ فالجول الواحد هو الذي يساوي 0.2390 cal.","العدد 1000 يربط السُّعر الغذائي بالسُّعر (1 Cal = 1000 cal)، لا السُّعر بالجول.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-03T20:51:23.824Z"}'::jsonb),
('mcq', 6, 1, 'بالتعبير عن كل وحدة بالجول: 1 J، و1 cal = 4.184 J، و1 kJ = 1000 J، و1 Cal = 1000 cal = 4184 J؛ لذا الترتيب: J ثم cal ثم kJ ثم Cal.', '["السُّعر (4.184 J) أكبر من الجول، والسُّعر الغذائي (4184 J) أكبر من الكيلوجول (1000 J).","","السُّعر الغذائي يساوي 4184 J، فهو أكبر من الكيلوجول (1000 J).","هذا ترتيب الوحدات من الأكبر إلى الأصغر، أي عكس المطلوب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-03T20:51:23.824Z"}'::jsonb),
('mcq', 7, 0, 'البادئة كيلو تعني 1000؛ فالكيلوجول 1000 J، والكيلوسُعر 1000 cal ويساوي سُعرًا غذائيًا واحدًا.', '["","البادئة كيلو تعني 1000، أما 100 فلا تمثلها.","0.001 تمثل البادئة ملّي، لا كيلو.","4.184 عامل تحويل بين السُّعر والجول، وليس معنى البادئة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-03T20:51:23.825Z"}'::jsonb),
('essay', 1, null::int, null, null, 'السُّعر ورمزه cal، والسُّعر الغذائي ورمزه Cal (ويساوي 1 kcal)، والجول ورمزه J. والجول هو وحدة النظام الدولي للوحدات.', '["السُّعر cal","السُّعر الغذائي Cal","الجول J","الجول وحدة النظام الدولي"]'::jsonb, '[]'::jsonb, '[{"element":"السُّعر ورمزه","marks":1},{"element":"السُّعر الغذائي ورمزه","marks":1},{"element":"الجول ورمزه","marks":1},{"element":"تحديد وحدة النظام الدولي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يذكر الوحدات الثلاث برموزها ويحدد الجول وحدةً للنظام الدولي"},{"level":"2–3 درجات","description":"يذكر وحدتين أو ثلاثًا مع خطأ في رمز أو في تحديد وحدة النظام الدولي"},{"level":"1 درجة","description":"يذكر وحدة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين رمزي cal وCal","ذكر °C وحدةً للحرارة","عدّ السُّعر وحدة النظام الدولي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:51:23.825Z"}'::jsonb),
('essay', 2, null::int, null, null, 'السُّعر (cal) هو كمية الحرارة اللازمة لرفع درجة حرارة 1 g من الماء النقي 1°C، ويرمز له بحرف c صغير. السُّعر الغذائي (Cal) وحدة أكبر تستعمل لقياس الطاقة الناتجة عن الغذاء، ويرمز له بحرف C كبير. العلاقة: 1 Cal = 1 kcal = 1000 cal.', '["تعريف السُّعر","السُّعر الغذائي وحدة لطاقة الغذاء","الفرق في الرمز (c صغير وC كبير)","1 Cal = 1 kcal = 1000 cal"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف السُّعر","marks":1},{"element":"استعمال السُّعر الغذائي","marks":1},{"element":"الفرق في الرمز","marks":1},{"element":"العلاقة الصحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة كاملة مع العلاقة"},{"level":"2–3 درجات","description":"العلاقة صحيحة مع نقص في المقارنة، أو مقارنة صحيحة دون العلاقة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة 1 Cal = 1 cal","كتابة 1 Cal = 100 cal","عدّ السُّعر الغذائي أصغر من السُّعر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-03T20:51:23.825Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) 1 J = 0.2390 cal. (ب) 1 cal = 4.184 J. (ج) 1 Cal = 1000 cal. عاملا التحويل من (ب): (4.184 J / 1 cal) و(1 cal / 4.184 J). للتحويل من cal إلى J نستعمل (4.184 J / 1 cal)؛ لأن وحدة cal في المقام تُختصر مع cal في الكمية المعطاة، فيبقى J.', '["1 J = 0.2390 cal","1 cal = 4.184 J","1 Cal = 1000 cal","عاملا التحويل","اختيار العامل الصحيح مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"العلاقة (أ)","marks":1},{"element":"العلاقة (ب)","marks":1},{"element":"العلاقة (ج)","marks":1},{"element":"عاملا التحويل","marks":1},{"element":"اختيار العامل وتعليله","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"العلاقات الثلاث صحيحة مع عاملي التحويل والاختيار المعلل"},{"level":"3–4 درجات","description":"العلاقات صحيحة مع خطأ في اختيار العامل أو غياب التعليل"},{"level":"1–2 درجة","description":"علاقة أو علاقتان صحيحتان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس العلاقة: 1 J = 4.184 cal","اختيار عامل التحويل الذي لا تُختصر فيه الوحدة","كتابة 1 Cal = 1000 J"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-03T20:51:23.825Z"}'::jsonb)
