from (values
('mcq', 1, 2, 'الحرارة النوعية لأي مادة هي كمية الحرارة اللازمة لرفع درجة حرارة جرام واحد من تلك المادة درجة سيليزية واحدة.', '["هذا تعريف السُّعر، وهو خاص بالماء النقي.","هذا تعريف درجة الحرارة لا الحرارة النوعية.","","الحرارة النوعية تخص 1 g من المادة تحديدًا، لا أي كتلة منها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-03T20:51:23.826Z"}'::jsonb),
('mcq', 2, 0, 'كلاهما يتعلق برفع درجة حرارة 1 g بمقدار 1°C، لكن السُّعر خاص بالماء النقي، أما الحرارة النوعية فتعرف لأي مادة، ولكل مادة حرارة نوعية مميزة لها.', '["","السُّعر يخص 1 g من الماء النقي لا 1 kg، والحرارة النوعية تعرف لأي مادة.","العكس هو الصحيح؛ فالسُّعر وحدة طاقة، والحرارة النوعية خاصية مميزة لكل مادة.","التعريفان كلاهما مرتبط برفع درجة الحرارة 1°C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-03T20:51:23.827Z"}'::jsonb),
('mcq', 3, 3, 'لكل مادة تركيب مختلف عن غيرها؛ لذا فلكل مادة حرارة نوعية مميزة لها، أما السُّعر والجول والسُّعر الغذائي فوحدات ثابتة لقياس الطاقة.', '["السُّعر وحدة طاقة ثابتة القيمة، ولا يختلف من مادة إلى أخرى.","الجول وحدة طاقة في النظام الدولي، وليس خاصية للمادة.","السُّعر الغذائي وحدة طاقة تساوي 1000 cal، وليس خاصية للمادة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-03T20:51:23.827Z"}'::jsonb),
('mcq', 4, 1, 'بالتحويل: 4.184 J/g·°C × (1 cal / 4.184 J) = 1.000 cal/g·°C؛ وهذا يتفق مع تعريف السُّعر بأنه الحرارة اللازمة لرفع 1 g من الماء النقي 1°C.', '["هذا الرقم نفسه بعد تغيير الوحدة دون تحويل.","","0.2390 هو عدد السُّعرات في الجول الواحد، وليس الحرارة النوعية للماء بوحدة cal/g·°C.","ضُرب في 4.184 بدلًا من القسمة عليه (4.184 × 4.184 ≈ 17.51)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-03T20:51:23.828Z"}'::jsonb),
('mcq', 5, 2, 'الحرارة النوعية هي الطاقة اللازمة لرفع 1 g من المادة 1°C؛ وبما أن الحرارة النوعية للأسمنت (0.84 J/g·°C) أقل من الحرارة النوعية للماء (4.184 J/g·°C)، فإن الأسمنت يحتاج إلى طاقة أقل.', '["العكس هو الصحيح؛ فالحرارة النوعية للأسمنت 0.84 J/g·°C، وهي أقل من الحرارة النوعية للماء.","السُّعر وحدة لقياس الطاقة المنتقلة، وليس شيئًا تحتويه المادة ويحدد حاجتها إلى الطاقة.","","الطاقة اللازمة لرفع درجة الحرارة 1°C لا تعتمد على درجة الحرارة الابتدائية، بل على الحرارة النوعية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:51:23.828Z"}'::jsonb),
('mcq', 6, 0, 'السُّعر يرفع درجة حرارة 1 g من الماء 1°C تمامًا. أما الحديد فـ ΔT = q / (c × m) = 4.184 J / (0.449 J/g·°C × 1 g) ≈ 9.3°C؛ لأن حرارته النوعية أصغر.', '["","السُّعر يرفع درجة حرارة 1 g من الماء فقط 1°C، ولكل مادة حرارة نوعية مختلفة.","الوصف معكوس؛ فالماء ذو الحرارة النوعية الكبرى هو الذي يرتفع 1°C فقط.","قُسمت الحرارة النوعية للحديد على الحرارة النوعية للماء (0.449/4.184 ≈ 0.11)، والصحيح أن المادة الأقل حرارة نوعية ترتفع أكثر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-03T20:51:23.828Z"}'::jsonb),
('mcq', 7, 3, 'الحرارة النوعية تقاس بالوحدة J/g·°C (طاقة لكل جرام لكل درجة)، أما السُّعر فهو نفسه وحدة لقياس الطاقة ورمزه cal.', '["الوحدتان معكوستان؛ فـ J/g·°C للحرارة النوعية، وcal رمز السُّعر.","°C وحدة لدرجة الحرارة، وJ رمز الجول لا السُّعر.","cal وحدة طاقة فقط، والحرارة النوعية تحتاج إلى وحدة تتضمن الكتلة والتغير في درجة الحرارة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-03T20:51:23.828Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) السُّعر: كمية الحرارة اللازمة لرفع درجة حرارة 1 g من الماء النقي 1°C. الحرارة النوعية: كمية الحرارة اللازمة لرفع درجة حرارة 1 g من المادة 1°C. (ب) السُّعر مرتبط بالماء النقي فقط، والحرارة النوعية تعرف لأي مادة. (ج) السُّعر وحدة لقياس الطاقة (cal)، أما الحرارة النوعية فخاصية مميزة لكل مادة تقاس بالوحدة J/g·°C.', '["تعريف السُّعر","تعريف الحرارة النوعية","السُّعر للماء النقي والحرارة النوعية لأي مادة","السُّعر وحدة، والحرارة النوعية خاصية مميزة","وحدة الحرارة النوعية J/g·°C"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف السُّعر","marks":1},{"element":"تعريف الحرارة النوعية","marks":1},{"element":"المادة المرتبطة بكل منهما","marks":2},{"element":"وحدة أم خاصية","marks":1},{"element":"وحدة الحرارة النوعية","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تمييز صحيح كامل في الجوانب الثلاثة مع الوحدة"},{"level":"3–5 درجات","description":"تعريفان صحيحان مع نقص في أحد الجوانب الأخرى"},{"level":"1–2 درجة","description":"تعريف واحد صحيح أو عنصر واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف الحرارة النوعية بأنها خاصة بالماء","عدّ الحرارة النوعية وحدة طاقة","نسيان أن السُّعر يخص 1 g فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:51:23.829Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) يلزم 2.44 J من الحرارة لرفع درجة حرارة 1 g من الإيثانول 1°C. (ب) 2.44 J/g·°C × 0.2390 cal/J = 0.583 cal/g·°C. (ج) الماء يحتاج إلى 1 cal لكل 1 g لكل 1°C، والإيثانول يحتاج إلى 0.583 cal فقط؛ أي أن الإيثانول يحتاج إلى طاقة أقل من الماء لرفع درجة حرارة الكتلة نفسها بالمقدار نفسه.', '["تفسير معنى 2.44 J/g·°C","التحويل إلى 0.583 cal/g·°C","المقارنة بسُعر واحد للماء","الاستنتاج"]'::jsonb, '["اضرب 2.44 J/g·°C في عامل التحويل 0.2390 cal / 1 J","2.44 × 0.2390 = 0.583 cal/g·°C","قارن بالقيمة 1 cal/g·°C للماء"]'::jsonb, '[{"element":"المعنى","marks":1},{"element":"التحويل الصحيح","marks":2},{"element":"المقارنة والاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح وتحويل صحيح بأرقام معنوية مناسبة ومقارنة سليمة"},{"level":"2–3 درجات","description":"تفسير صحيح مع خطأ في التحويل أو في المقارنة"},{"level":"1 درجة","description":"تفسير المعنى فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القسمة على 0.2390 بدلًا من الضرب","القول إن 1 kg من الإيثانول يحتاج إلى 2.44 J","نسيان أن سُعر الماء يخص 1 g فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-03T20:51:23.829Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الحرارة النوعية هي الطاقة اللازمة لرفع 1 g من المادة 1°C. الماء يحتاج إلى 4.184 J لكل جرام لكل درجة، والأسمنت يحتاج إلى 0.84 J فقط. فعند امتصاص الطاقة نفسها بالكتلة نفسها يكون ΔT = q/(c × m)، أي أن ΔT يتناسب عكسيًا مع c، والنسبة 4.184 / 0.84 ≈ 5؛ لذا يرتفع الأسمنت نحو خمسة أمثال ارتفاع الماء. أما السُّعر فوحدة ثابتة لقياس الطاقة معرّفة بالماء النقي فقط، ولا تعبر عن اختلاف المواد؛ والخاصية التي تختلف من مادة إلى أخرى هي الحرارة النوعية.', '["ΔT يتناسب عكسيًا مع c عند تساوي q وm","حساب النسبة 4.184 / 0.84 ≈ 5","الأسمنت ذو حرارة نوعية أقل فيسخن أكثر","السُّعر وحدة ثابتة معرفة بالماء ولا تميز المواد"]'::jsonb, '["ΔT = q / (c × m)","عند تساوي q وm: ΔT(أسمنت)/ΔT(ماء) = c(ماء)/c(أسمنت)","4.184 / 0.84 ≈ 5.0"]'::jsonb, '[{"element":"العلاقة العكسية بين ΔT وc","marks":2},{"element":"حساب النسبة","marks":1},{"element":"الاستنتاج","marks":1},{"element":"تمييز السُّعر من الحرارة النوعية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحليل صحيح كامل يربط الحرارة النوعية بالنسبة العددية ويميز السُّعر"},{"level":"3–4 درجات","description":"تفسير صحيح بالحرارة النوعية مع نقص في الحساب أو في تمييز السُّعر"},{"level":"1–2 درجة","description":"يذكر أن الحرارة النوعية للأسمنت أقل دون تحليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ العلاقة بين ΔT وc طردية","القول إن الأسمنت يمتص حرارة أكثر","الخلط بين السُّعر والحرارة النوعية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-03T20:51:23.829Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C1-L1-O04') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C1-L1-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
