('mcq', 1, 'عبّر عن طاقة مقدارها 525 cal بوحدة الجول.', null, null, '["125 J","2.20 J","2.20×10³ J","2.20×10⁶ J"]'::jsonb, 'تطبيق', 'تحويل وحدات', 'سهل', 'الكتاب ص 14، 15 — تحويل وحدات الطاقة (الجدول 1-1، المثال 1-1)'),
('mcq', 2, 'تحتوي وجبة خفيفة على 250 Cal. ما مقدار هذه الطاقة بوحدة السُّعر cal؟', null, null, '["2.50×10⁵ cal","0.250 cal","1.05×10³ cal","2.50×10⁴ cal"]'::jsonb, 'تطبيق', 'تحويل وحدات', 'سهل', 'الكتاب ص 14، 15 — السُّعر الغذائي (مسائل تدريبية)'),
('mcq', 3, 'يطلق تفاعل كيميائي 12.5 kJ من الحرارة. ما مقدار هذه الحرارة بوحدة السُّعر cal؟', null, null, '["5.23×10⁴ cal","2.99 cal","2.99×10⁶ cal","2.99×10³ cal"]'::jsonb, 'تطبيق', 'تحويل متعدد الخطوات', 'متوسط', 'الكتاب ص 14، 15 — عوامل التحويل (مسألة 2)'),
('mcq', 4, 'تمتص عملية 0.750 kcal من الطاقة. ما مقدار هذه الطاقة بوحدة الجول J؟', null, null, '["3.14 J","3.14×10³ J","179 J","750 J"]'::jsonb, 'تطبيق', 'تحويل متعدد الخطوات', 'متوسط', 'الكتاب ص 14، 42 — عوامل التحويل (س54)'),
('mcq', 5, 'ينطلق 2808 kJ عند احتراق 1 mol من الجلوكوز. ما مقدار هذه الطاقة بوحدة السُّعر الغذائي Cal؟', null, null, '["6.71×10⁵ Cal","1.17×10⁴ Cal","0.671 Cal","671 Cal"]'::jsonb, 'تطبيق', 'تحويل متعدد الخطوات', 'صعب', 'الكتاب ص 14، 42 — عوامل التحويل (س55، س57)'),
('mcq', 6, 'أيّ كميات الطاقة الآتية هي الأكبر؟', null, null, '["1.00 Cal","3.00 kJ","500 cal","1000 J"]'::jsonb, 'تحليل', 'مقارنة بعد التحويل', 'صعب', 'الكتاب ص 14، 15 — تحويل وحدات الطاقة (الجدول 1-1، المثال 1-1)'),
('mcq', 7, 'ما عامل التحويل المناسب لتحويل كمية طاقة من الجول J إلى السُّعر cal؟', null, null, '["4.184 J / 1 cal","0.2390 cal / 1 J","1 J / 0.2390 cal","1000 cal / 1 Cal"]'::jsonb, 'فهم', 'اختيار عامل تحويل', 'سهل', 'الكتاب ص 14 — عوامل التحويل (الجدول 1-1)'),
('essay', 1, 'وجبة إفطار تحتوي على 350 Cal من الطاقة. عبّر عن هذه الطاقة بوحدة الجول J ثم بوحدة الكيلوجول kJ، موضحًا عامل التحويل في كل خطوة.', null, null, null, 'تطبيق', 'مسألة تحويل', 'متوسط', 'الكتاب ص 14، 15 — المثال 1-1'),
('essay', 2, 'يطلق تفاعل طارد للحرارة 45.0 kJ. عبّر عن هذه الحرارة بوحدة السُّعر cal ثم بوحدة السُّعر الغذائي Cal، مع كتابة خطوات الحل.', null, null, null, 'تطبيق', 'مسألة تحويل', 'متوسط', 'الكتاب ص 14، 15 — عوامل التحويل (مسألة 2)'),
('essay', 3, 'مكتوب على عبوة وجبة خفيفة A أنها تحتوي على 180 Cal، وعلى عبوة وجبة B أنها تحتوي على 850 kJ. أيّ الوجبتين تحتوي على طاقة أكبر؟ وضّح ذلك بتحويل الكميتين إلى الوحدة نفسها، وبيّن الخطأ الذي يقع فيه من يقارن العددين 180 و850 مباشرة.', null, null, null, 'تحليل', 'مقارنة بعد التحويل', 'صعب', 'الكتاب ص 14، 15 — تحويل وحدات الطاقة (الجدول 1-1، المثال 1-1)')
