('mcq', 2, 0, '250 Cal × (1000 cal / 1 Cal) = 250000 cal = 2.50×10⁵ cal.', '["","قُسم على 1000 بدلًا من الضرب؛ فالسُّعر الغذائي أكبر من السُّعر.","ضُرب في 4.184 (عامل تحويل cal إلى J) بدلًا من 1000.","ضُرب في 100 بدلًا من 1000؛ فالسُّعر الغذائي يساوي 1000 cal."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-03T20:51:23.830Z"}'::jsonb),
('mcq', 3, 3, 'أولًا: 12.5 kJ = 12500 J. ثانيًا: 12500 J × (0.2390 cal / 1 J) = 2987.5 cal ≈ 2.99×10³ cal.', '["ضُرب في 4.184 بدلًا من 0.2390، أي استُعمل عامل التحويل معكوسًا.","لم يُحوَّل kJ إلى J قبل الضرب في 0.2390.","ضُرب في 10⁶ عند تحويل kJ إلى J بدلًا من 10³.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-03T20:51:23.830Z"}'::jsonb),
('mcq', 4, 1, '0.750 kcal = 750 cal، ثم 750 cal × (4.184 J / 1 cal) = 3138 J ≈ 3.14×10³ J.', '["لم يُحوَّل kcal إلى cal قبل الضرب في 4.184.","","ضُرب 750 cal في 0.2390 بدلًا من 4.184.","حُوِّل kcal إلى cal فقط، ولم يُحوَّل cal إلى J."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-03T20:51:23.830Z"}'::jsonb),
('mcq', 5, 3, '2808 kJ = 2.808×10⁶ J؛ ثم × 0.2390 cal/J = 6.71×10⁵ cal؛ ثم ÷ 1000 cal/Cal = 671 Cal.', '["هذا الناتج بوحدة cal؛ لم يُقسم على 1000 للتحويل إلى Cal.","ضُرب 2808 في 4.184 بدلًا من 0.2390، ولم تُحوَّل البادئة.","قُسم على 1000 مرة زائدة بعد التحويل إلى Cal.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-03T20:51:23.830Z"}'::jsonb),
('mcq', 6, 0, 'بالتحويل إلى الجول: 1.00 Cal = 1000 cal = 4184 J، و3.00 kJ = 3000 J، و500 cal = 2092 J، و1000 J؛ إذن 1.00 Cal هي الأكبر.', '["","3.00 kJ = 3000 J، وهي أقل من 1.00 Cal (4184 J).","500 cal = 2092 J، وهي أقل من 1.00 Cal (4184 J).","1000 J أصغر الكميات؛ فالعدد الكبير لا يعني طاقة أكبر قبل توحيد الوحدات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-03T20:51:23.831Z"}'::jsonb),
('mcq', 7, 1, 'يجب أن تكون الوحدة J في المقام لتختصر مع J في الكمية المعطاة ويبقى cal؛ لذا نستعمل 0.2390 cal / 1 J.', '["هذا العامل يضع cal في المقام، فلا تختصر وحدة الجول.","","هذا العامل يضع J في البسط، فلا تختصر وحدة الجول بل تتضاعف.","هذا العامل يحول من Cal إلى cal، ولا علاقة له بالجول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-03T20:51:23.831Z"}'::jsonb),
('essay', 1, null::int, null, null, '350 Cal × (1000 cal / 1 Cal) = 3.50×10⁵ cal. ثم 3.50×10⁵ cal × (4.184 J / 1 cal) = 1.46×10⁶ J. ثم 1.46×10⁶ J × (1 kJ / 1000 J) = 1.46×10³ kJ.', '["تحويل Cal إلى cal","تحويل cal إلى J","تحويل J إلى kJ","أرقام معنوية ووحدات صحيحة"]'::jsonb, '["350 Cal × 1000 cal/Cal = 3.50×10⁵ cal","3.50×10⁵ cal × 4.184 J/cal = 1.4644×10⁶ J ≈ 1.46×10⁶ J","1.46×10⁶ J ÷ 1000 J/kJ = 1.46×10³ kJ"]'::jsonb, '[{"element":"التحويل إلى cal","marks":1},{"element":"التحويل إلى J","marks":2},{"element":"التحويل إلى kJ","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الخطوات الثلاث صحيحة مع عوامل التحويل والوحدات والأرقام المعنوية"},{"level":"2–3 درجات","description":"خطوتان صحيحتان أو خطأ في الأرقام المعنوية"},{"level":"1 درجة","description":"خطوة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الضرب في 4.184 مباشرة دون تحويل Cal إلى cal","الضرب في 0.2390 بدلًا من 4.184","الضرب في 1000 عند التحويل من J إلى kJ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-03T20:51:23.831Z"}'::jsonb),
('essay', 2, null::int, null, null, '45.0 kJ = 4.50×10⁴ J. ثم 4.50×10⁴ J × (0.2390 cal / 1 J) = 1.08×10⁴ cal. ثم 1.08×10⁴ cal × (1 Cal / 1000 cal) = 10.8 Cal.', '["تحويل kJ إلى J","تحويل J إلى cal","تحويل cal إلى Cal"]'::jsonb, '["45.0 kJ × 1000 J/kJ = 4.50×10⁴ J","4.50×10⁴ J × 0.2390 cal/J = 10755 cal ≈ 1.08×10⁴ cal","1.08×10⁴ cal ÷ 1000 cal/Cal = 10.8 Cal"]'::jsonb, '[{"element":"التحويل إلى J","marks":1},{"element":"التحويل إلى cal","marks":2},{"element":"التحويل إلى Cal","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الخطوات كلها صحيحة بالوحدات والأرقام المعنوية"},{"level":"2–3 درجات","description":"خطأ واحد في خطوة أو في الأرقام المعنوية"},{"level":"1 درجة","description":"خطوة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان تحويل kJ إلى J","الضرب في 4.184 بدلًا من 0.2390","الضرب في 1000 بدلًا من القسمة عند التحويل إلى Cal"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-03T20:51:23.832Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نحوّل A إلى kJ: 180 Cal × 1000 cal/Cal = 1.80×10⁵ cal؛ × 4.184 J/cal = 7.53×10⁵ J = 753 kJ. إذن B (850 kJ) تحتوي على طاقة أكبر من A (753 kJ). من يقارن 180 و850 مباشرة يقارن عددين بوحدتين مختلفتين؛ ولا تصح المقارنة إلا بعد توحيد الوحدات، فالسُّعر الغذائي (4.184 kJ) أكبر بكثير من الكيلوجول.', '["تحويل 180 Cal إلى 753 kJ (أو 850 kJ إلى 203 Cal)","استنتاج أن B أكبر","تفسير ضرورة توحيد الوحدات"]'::jsonb, '["180 Cal × 1000 cal/Cal = 1.80×10⁵ cal","1.80×10⁵ cal × 4.184 J/cal = 7.53×10⁵ J = 753 kJ","المقارنة: 850 kJ > 753 kJ"]'::jsonb, '[{"element":"التحويل الصحيح","marks":2},{"element":"الاستنتاج","marks":1},{"element":"تفسير الخطأ","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحويل صحيح واستنتاج صحيح وتفسير واضح لضرورة توحيد الوحدات"},{"level":"2–3 درجات","description":"تحويل صحيح واستنتاج صحيح دون تفسير، أو خطأ حسابي بسيط"},{"level":"1 درجة","description":"استنتاج صحيح دون تحويل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ 1 Cal = 1 kJ","نسيان التحويل من Cal إلى cal","المقارنة المباشرة بين العددين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-03T20:51:23.832Z"}'::jsonb)
