('mcq', 1, 'ما المسعر؟', null, null, '["جهاز يقيس متوسط الطاقة الحركية لجسيمات المادة مباشرة","جهاز معزول حراريًا يستخدم لقياس كمية الحرارة الممتصة أو المنطلقة","جهاز موصل للحرارة يستخدم لتسخين المواد إلى درجة حرارة محددة","وحدة لقياس كمية الطاقة الناتجة عن الغذاء"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 19 — المسعر'),
('mcq', 2, 'لماذا يجب أن يكون المسعر معزولًا حراريًا؟', null, null, '["لرفع درجة حرارة الماء داخله بسرعة","لزيادة كمية الحرارة المنطلقة من التفاعل","لمنع حدوث التفاعل الكيميائي قبل الاشتعال","لمنع تبادل الحرارة مع المحيط فتقاس الحرارة بدقة"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 19 — المسعر'),
('mcq', 3, 'ما الذي يُقاس في المسعر لحساب كمية الحرارة الممتصة أو المنطلقة؟', null, null, '["التغير في درجة حرارة كتلة معلومة من الماء","التغير في كتلة الماء داخل المسعر","الحرارة النوعية للمادة المتفاعلة مباشرة","الضغط داخل حجرة التفاعل"]'::jsonb, 'تذكر', 'تذكر مبدأ العمل', 'متوسط', 'الكتاب ص 19 — المسعر'),
('mcq', 4, 'أيّ وصف ينطبق على مسعر القنبلة الذي يستخدمه كيميائيو التغذية؟', null, null, '["توضع العينة في كأس بوليسترين مفتوحة على الجو ويضاف إليها الماء","توضع العينة في حجرة زجاجية مفتوحة ويُسخَّن الماء حولها باللهب","توضع العينة في حجرة فولاذية مملوءة بالأكسجين المضغوط ويحيط بها ماء","توضع العينة في حجرة فولاذية مفرغة من الهواء دون ماء حولها"]'::jsonb, 'تذكر', 'تذكر وصف', 'متوسط', 'الكتاب ص 19 — مسعر القنبلة (الشكل 1-4)'),
('mcq', 5, 'لماذا تحدث التفاعلات في مسعر كأس البوليسترين تحت ضغط ثابت؟', null, null, '["لأنه محكم الإغلاق ومملوء بالأكسجين المضغوط","لأن الكأس مفتوحة على الهواء الجوي","لأن البوليسترين موصل جيد للحرارة","لأن الماء فيه يحرَّك بمحرك قليل الاحتكاك"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 19 — تحديد الحرارة النوعية (مسعر البوليسترين)'),
('mcq', 6, 'لماذا يُستعمل كوب البوليسترين مسعرًا بدلًا من الكأس الزجاجية؟', null, null, '["لأن البوليسترين عازل حراري يقلل فقد الحرارة إلى المحيط","لأن البوليسترين يمتص كمية كبيرة من الحرارة المنطلقة","لأن الزجاج عازل حراري أفضل من البوليسترين","لأن البوليسترين يتفاعل مع المواد فيسرّع التفاعل"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 19، 42 — المسعر (س59)'),
('mcq', 7, 'في مسعر معزول، وُضعت قطعة فلز ساخنة في الماء، فاكتسب الماء 2510 J من الحرارة. بافتراض عدم فقد حرارة إلى المحيط، ما كمية الحرارة التي فقدها الفلز؟', null, null, '["صفر J، لأن المسعر معزول حراريًا","1255 J، أي نصف ما اكتسبه الماء","2510 J، وهي مساوية لما اكتسبه الماء","5020 J، أي ضعف ما اكتسبه الماء"]'::jsonb, 'تطبيق', 'تطبيق مبدأ المسعر', 'صعب', 'الكتاب ص 20 — حساب الحرارة في المسعر'),
('essay', 1, 'عرّف المسعر، واذكر نوعين منه.', null, null, null, 'تذكر', 'تعريف وتعداد', 'متوسط', 'الكتاب ص 19 — المسعر'),
('essay', 2, 'صف مسعر القنبلة وطريقة عمله، مبيّنًا وظيفة كل من: (أ) الحجرة الفولاذية المملوءة بالأكسجين المضغوط. (ب) الماء المحيط بها. (ج) المحرك. (د) مقياس الحرارة. ولماذا يجب ألا ينتج المحرك احتكاكًا؟', null, null, null, 'فهم', 'وصف جهاز', 'صعب', 'الكتاب ص 19 — مسعر القنبلة (الشكل 1-4)'),
('essay', 3, 'قارن بين مسعر القنبلة ومسعر كأس البوليسترين من حيث: (أ) بساطة التركيب. (ب) هل هو مفتوح أم مغلق، وأثر ذلك في الضغط. (ج) استعمال واحد لكل منهما. ثم بيّن الصفة المشتركة بينهما التي تجعل كلًّا منهما مسعرًا.', null, null, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 19 — المسعر')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
