from (values
('mcq', 1, 1, 'المسعر جهاز معزول حراريًا يستخدم لقياس كمية الحرارة الممتصة أو المنطلقة في أثناء عملية كيميائية أو فيزيائية.', '["هذا أقرب إلى وصف مقياس الحرارة؛ والمسعر يقيس كمية الحرارة الممتصة أو المنطلقة.","","المسعر معزول حراريًا لا موصل، ووظيفته القياس لا التسخين.","المسعر جهاز وليس وحدة؛ ووحدة طاقة الغذاء هي السُّعر الغذائي Cal."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:51:23.833Z"}'::jsonb),
('mcq', 2, 3, 'العزل الحراري يمنع فقد الحرارة إلى المحيط أو اكتسابها منه، فتكون الحرارة التي يمتصها الماء أو يفقدها مساوية لما أطلقه التفاعل أو امتصه.', '["العزل لا يسرع التسخين، بل يمنع تبادل الحرارة مع المحيط.","العزل لا يغير كمية الحرارة التي يطلقها التفاعل، بل يمنع ضياعها.","العزل الحراري لا علاقة له ببدء التفاعل أو منعه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:51:23.833Z"}'::jsonb),
('mcq', 3, 0, 'توضع كمية معلومة من الماء في حجرة معزولة لتمتص الطاقة المنطلقة من التفاعل أو تزوده بالطاقة، ثم يقاس التغير في درجة حرارة كتلة الماء.', '["","كتلة الماء معلومة ولا تتغير، والذي يقاس هو التغير في درجة حرارته.","الحرارة النوعية لا تقاس مباشرة، بل تحسب من الحرارة والكتلة والتغير في درجة الحرارة.","المسعر يعتمد على قياس التغير في درجة حرارة الماء لا على قياس الضغط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-03T20:51:23.833Z"}'::jsonb),
('mcq', 4, 2, 'في مسعر القنبلة توضع العينة في حجرة فولاذية داخلية تسمى القنبلة مملوءة بالأكسجين المضغوط، وحولها كمية معلومة من الماء تحرَّك بمحرك، ويبدأ التفاعل بشرارة.', '["هذا وصف مسعر كأس البوليسترين، لا مسعر القنبلة.","المسعر معزول ولا يسخَّن الماء فيه بلهب؛ فالحرارة تأتي من احتراق العينة.","","القنبلة مملوءة بالأكسجين المضغوط ليحدث الاحتراق، ويحيط بها ماء معلوم الكتلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-03T20:51:23.833Z"}'::jsonb),
('mcq', 5, 1, 'مسعر كأس البوليسترين مفتوح على الجو؛ لذلك فالتفاعلات التي تحدث فيه تكون تحت ضغط ثابت (الضغط الجوي).', '["هذا وصف مسعر القنبلة، وكأس البوليسترين مفتوحة لا محكمة الإغلاق.","","البوليسترين عازل حراري لا موصل، والعزل لا يحدد الضغط.","المحرك يحافظ على تجانس درجة الحرارة، ولا علاقة له بثبات الضغط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-03T20:51:23.833Z"}'::jsonb),
('mcq', 6, 0, 'يجب أن يكون المسعر معزولًا حراريًا، والبوليسترين مادة عازلة تقلل انتقال الحرارة بين محتويات المسعر والمحيط.', '["","المطلوب ألا يمتص المسعر نفسه الحرارة، بل أن تبقى في الماء لتقاس.","العكس هو الصحيح؛ فالزجاج ينقل الحرارة أكثر من البوليسترين.","مادة المسعر يجب ألا تتفاعل مع المواد، ووظيفتها العزل الحراري."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-03T20:51:23.833Z"}'::jsonb),
('mcq', 7, 2, 'إذا لم تُفقد حرارة إلى المحيط فإن الحرارة التي اكتسبها الماء تساوي الحرارة التي فقدها الفلز، أي 2510 J (q_metal = −2510 J).', '["العزل يمنع تبادل الحرارة مع المحيط فقط، أما بين الفلز والماء فتنتقل الحرارة.","لا تقسم الحرارة بين الفلز والماء؛ فكل ما فقده الفلز اكتسبه الماء.","","لا يمكن أن يفقد الفلز ضعف ما اكتسبه الماء دون فقد حرارة إلى المحيط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-03T20:51:23.834Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المسعر جهاز معزول حراريًا يستخدم لقياس كمية الحرارة الممتصة أو المنطلقة في أثناء عملية كيميائية أو فيزيائية. ومن أنواعه: مسعر القنبلة، ومسعر كأس البوليسترين.', '["جهاز معزول حراريًا","يقيس كمية الحرارة الممتصة أو المنطلقة","مسعر القنبلة","مسعر كأس البوليسترين"]'::jsonb, '[]'::jsonb, '[{"element":"معزول حراريًا","marks":1},{"element":"وظيفة القياس","marks":1},{"element":"النوع الأول","marks":1},{"element":"النوع الثاني","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل ونوعان صحيحان"},{"level":"2–3 درجات","description":"تعريف ناقص مع نوعين، أو تعريف كامل مع نوع واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال أن المسعر معزول حراريًا","تعريف المسعر بأنه يقيس درجة الحرارة فقط","الخلط بين المسعر والسُّعر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:51:23.834Z"}'::jsonb),
('essay', 2, null::int, null, null, 'توضع العينة في حجرة فولاذية داخلية محكمة الإغلاق تسمى القنبلة، وتحاط بكمية معلومة من الماء داخل وعاء معزول، ويبدأ التفاعل بشرارة وتسجل درجة الحرارة حتى تصل إلى أقصاها. (أ) الحجرة تحتوي على العينة والأكسجين المضغوط اللازم لاحتراقها كاملًا. (ب) الماء يمتص الحرارة المنطلقة من الاحتراق. (ج) المحرك يحرك الماء ليحافظ على درجة حرارة منتظمة فيه. (د) مقياس الحرارة يقيس التغير في درجة حرارة الماء. ويجب ألا ينتج المحرك احتكاكًا؛ لأن الاحتكاك يولد حرارة إضافية ترفع درجة حرارة الماء فتفسد دقة القياس.', '["وصف طريقة العمل","وظيفة الحجرة والأكسجين","وظيفة الماء","وظيفة المحرك","وظيفة مقياس الحرارة","تعليل منع الاحتكاك"]'::jsonb, '[]'::jsonb, '[{"element":"طريقة العمل","marks":1},{"element":"الحجرة","marks":1},{"element":"الماء","marks":1},{"element":"المحرك","marks":1},{"element":"مقياس الحرارة","marks":1},{"element":"الاحتكاك","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"وصف كامل لطريقة العمل والوظائف الأربع وتعليل منع الاحتكاك"},{"level":"3–5 درجات","description":"معظم الوظائف صحيحة مع نقص في الوصف أو التعليل"},{"level":"1–2 درجة","description":"وظيفة أو وظيفتان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الماء هو الذي يحترق","القول إن المحرك يسخن الماء","إغفال أن الاحتكاك مصدر حرارة إضافية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-03T20:51:23.834Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) مسعر كأس البوليسترين أبسط تركيبًا، ومسعر القنبلة أعقد (حجرة فولاذية، أكسجين مضغوط، محرك، شرارة). (ب) كأس البوليسترين مفتوحة على الجو فتحدث التفاعلات فيها تحت ضغط ثابت، أما القنبلة فحجرة محكمة الإغلاق مملوءة بالأكسجين المضغوط. (ج) يستعمل مسعر القنبلة لقياس الطاقة الناتجة عن احتراق الأغذية (القيم الحرارية)، ويستعمل مسعر البوليسترين لتحديد الحرارة النوعية لفلز مثلًا. الصفة المشتركة: كلاهما معزول حراريًا ويقيس الحرارة الممتصة أو المنطلقة من خلال التغير في درجة حرارة كتلة معلومة من الماء.', '["المقارنة في البساطة","مفتوح/مغلق وأثره في الضغط","استعمال مسعر القنبلة","استعمال مسعر البوليسترين","الصفة المشتركة"]'::jsonb, '[]'::jsonb, '[{"element":"البساطة","marks":1},{"element":"الفتح والإغلاق والضغط","marks":2},{"element":"الاستعمالان","marks":2},{"element":"الصفة المشتركة","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة كاملة صحيحة مع الصفة المشتركة"},{"level":"3–5 درجات","description":"مقارنة صحيحة في معظم الجوانب مع نقص في أحدها"},{"level":"1–2 درجة","description":"جانب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن مسعر البوليسترين مغلق ومضغوط","عدّ القنبلة مفتوحة على الجو","إغفال العزل الحراري صفةً مشتركة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-03T20:51:23.834Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C1-L1-O06') and x.type = v.type and x.number = v.number
