select (select id from public.objectives where code = 'K22-C1-L1-O07'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'امتصت عينة كتلتها 15.0 g من مادة 135 J من الحرارة، فارتفعت درجة حرارتها 10.0°C. ما الحرارة النوعية للمادة؟', null, null, '["9.00 J/g·°C","1.11 J/g·°C","13.5 J/g·°C","0.900 J/g·°C"]'::jsonb, 'تطبيق', 'حساب مباشر', 'سهل', 'الكتاب ص 16، 17 — معادلة حساب الحرارة والمثال 1-2'),
('mcq', 2, 'سُخّنت عينة من الجرانيت كتلتها 25.0 g من 20.0°C إلى 45.0°C، فامتصت 502 J. ما الحرارة النوعية للجرانيت؟', null, null, '["0.446 J/g·°C","0.803 J/g·°C","1.00 J/g·°C","1.25 J/g·°C"]'::jsonb, 'تطبيق', 'حساب مع ΔT', 'متوسط', 'الكتاب ص 16، 17 — معادلة حساب الحرارة والمثال 1-2'),
('mcq', 3, 'امتصت قطعة فلز كتلتها 40.0 g ما مقداره 539 J من الحرارة، فارتفعت درجة حرارتها من 20.0°C إلى 50.0°C. باستعمال القيم المعطاة، ما الفلز المرجح؟', '{"headers":["المادة","الحرارة النوعية (J/g·°C)"],"rows":[["الألومنيوم (s)","0.897"],["الحديد (s)","0.449"],["الفضة (s)","0.235"],["الذهب (s)","0.129"]]}'::jsonb, null, '["الألومنيوم","الفضة","الحديد","الذهب"]'::jsonb, 'تطبيق', 'حساب وتعرف مادة', 'متوسط', 'الكتاب ص 16، 17، 21 — الجدول 1-2 والمثال 1-3'),
('mcq', 4, 'بردت عينة من الأسمنت كتلتها 50.0 g من 80.0°C إلى 30.0°C، فأطلقت 2.10 kJ من الحرارة. ما الحرارة النوعية للأسمنت؟', null, null, '["0.840 J/g·°C","8.40×10⁻⁴ J/g·°C","0.525 J/g·°C","1.19 J/g·°C"]'::jsonb, 'تطبيق', 'حساب مع تحويل وحدة', 'متوسط', 'الكتاب ص 16 — حساب الحرارة المنطلقة'),
('mcq', 5, 'أيّ صيغة مما يأتي تعطي الحرارة النوعية c من العلاقة q = c × m × ΔT؟', null, null, '["c = q × m × ΔT","c = (m × ΔT) / q","c = q / (m × ΔT)","c = (q × ΔT) / m"]'::jsonb, 'فهم', 'إعادة ترتيب علاقة', 'سهل', 'الكتاب ص 17 — المثال 1-2'),
('mcq', 6, 'وُضعت قطعة فلز كتلتها 30.0 g ودرجة حرارتها 95.0°C في 100.0 g من الماء عند 22.00°C داخل مسعر، فأصبحت درجة الحرارة النهائية 25.00°C. ما الحرارة النوعية للفلز؟ (الحرارة النوعية للماء 4.184 J/g·°C)', null, null, '["0.440 J/g·°C","0.179 J/g·°C","1.67 J/g·°C","0.598 J/g·°C"]'::jsonb, 'تطبيق', 'حساب بالمسعر', 'صعب', 'الكتاب ص 19، 20 — تحديد الحرارة النوعية لفلز'),
('mcq', 7, 'امتصت عينتان A وB متساويتان في الكتلة كمية الحرارة نفسها، فارتفعت درجة حرارة A بمقدار 10°C، ودرجة حرارة B بمقدار 20°C. أيّ مقارنة بين حرارتيهما النوعيتين صحيحة؟', null, null, '["الحرارة النوعية لـ A ضعف الحرارة النوعية لـ B","الحرارة النوعية لـ B ضعف الحرارة النوعية لـ A","الحرارتان النوعيتان متساويتان","الحرارة النوعية لـ A أربعة أمثال الحرارة النوعية لـ B"]'::jsonb, 'تحليل', 'تحليل علاقة', 'متوسط', 'الكتاب ص 16 — معادلة حساب الحرارة'),
('essay', 1, 'امتصت عينة من فلز كتلتها 75.0 g ما مقداره 1.35 kJ من الحرارة، فارتفعت درجة حرارتها من 22.0°C إلى 42.0°C. (أ) احسب الحرارة النوعية للفلز. (ب) إذا علمت أن الحرارة النوعية للألومنيوم 0.897 J/g·°C، وللحديد 0.449 J/g·°C، وللفضة 0.235 J/g·°C، فما الفلز المرجح؟', null, null, null, 'تطبيق', 'مسألة حسابية', 'سهل', 'الكتاب ص 16، 17 — المثال 1-2 والجدول 1-2'),
('essay', 2, 'بردت عينة من الإيثانول كتلتها 120.0 g من 60.0°C إلى 20.0°C، فأطلقت 11.7 kJ من الحرارة. (أ) احسب الحرارة النوعية للإيثانول. (ب) لماذا تكون قيمة الحرارة النوعية موجبة مع أن العينة أطلقت حرارة؟', null, null, null, 'تطبيق', 'مسألة حسابية مع تفسير', 'صعب', 'الكتاب ص 16 — حساب الحرارة المنطلقة والجدول 1-2'),
('essay', 3, 'امتصت عينة من فلز كتلتها 20.0 g ما مقداره 897 J من الحرارة، فارتفعت درجة حرارتها من 25.0°C إلى 75.0°C. حسب أحد الطلاب الحرارة النوعية هكذا: c = 897 / (20.0 × 75.0) = 0.598 J/g·°C. (أ) قيّم حل الطالب وحدّد الخطأ. (ب) احسب القيمة الصحيحة. (ج) إذا علمت أن الحرارة النوعية للألومنيوم 0.897 J/g·°C وللحديد 0.449 J/g·°C، فما الفلز؟', null, null, null, 'تقويم', 'تقويم حل', 'صعب', 'الكتاب ص 16، 17 — معادلة حساب الحرارة والمثال 1-2')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
