('mcq', 2, 1, 'ΔT = 45.0°C − 20.0°C = 25.0°C؛ c = 502 J / (25.0 g × 25.0°C) = 0.803 J/g·°C.', '["استُعملت درجة الحرارة النهائية 45.0°C بدلًا من ΔT.","","استُعملت درجة الحرارة الابتدائية 20.0°C بدلًا من ΔT.","قُلبت العلاقة: (m × ΔT) / q."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-03T20:51:23.835Z"}'::jsonb),
('mcq', 3, 2, 'ΔT = 30.0°C؛ c = 539 J / (40.0 g × 30.0°C) = 0.449 J/g·°C، وهي الحرارة النوعية للحديد.', '["حرارته النوعية 0.897 J/g·°C، أي ضعف القيمة المحسوبة تقريبًا.","حرارتها النوعية 0.235 J/g·°C، وهي قريبة من نصف القيمة المحسوبة.","","حرارته النوعية 0.129 J/g·°C، وهي أقل كثيرًا من القيمة المحسوبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-03T20:51:23.835Z"}'::jsonb),
('mcq', 4, 0, 'q = 2.10 kJ = 2100 J، وΔT = 80.0°C − 30.0°C = 50.0°C؛ c = 2100 J / (50.0 g × 50.0°C) = 0.840 J/g·°C.', '["","لم تُحوَّل 2.10 kJ إلى 2100 J.","استُعملت درجة الحرارة الابتدائية 80.0°C بدلًا من ΔT.","قُلبت العلاقة: (m × ΔT) / q."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-03T20:51:23.836Z"}'::jsonb),
('mcq', 5, 2, 'بقسمة طرفي العلاقة q = c × m × ΔT على (m × ΔT) نحصل على c = q / (m × ΔT).', '["هذه الصيغة تضرب المتغيرات كلها بدلًا من قسمة q على m × ΔT.","هذه الصيغة مقلوب الصيغة الصحيحة.","","ΔT يجب أن يكون في المقام مع الكتلة لا في البسط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-03T20:51:23.836Z"}'::jsonb),
('mcq', 6, 3, 'q_water = 4.184 × 100.0 × 3.00 = 1255 J؛ q_metal = −1255 J؛ ΔT للفلز = 25.00 − 95.0 = −70.0°C؛ c = −1255 J / (30.0 g × −70.0°C) = 0.598 J/g·°C.', '["استُعملت درجة الحرارة الابتدائية للفلز 95.0°C بدلًا من تغيرها 70.0°C.","استُعملت كتلة الماء 100.0 g بدلًا من كتلة الفلز 30.0 g.","قُلبت العلاقة: (m × ΔT) / q.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-03T20:51:23.836Z"}'::jsonb),
('mcq', 7, 0, 'c = q / (m × ΔT)؛ وعند تساوي q وm تتناسب c عكسيًا مع ΔT، فبما أن ΔT لـ A نصف ΔT لـ B، تكون الحرارة النوعية لـ A ضعف الحرارة النوعية لـ B.', '["","العلاقة بين c وΔT عكسية لا طردية؛ فالعينة الأكثر ارتفاعًا في درجة الحرارة حرارتها النوعية أقل.","تساوي الحرارة الممتصة لا يعني تساوي الحرارة النوعية؛ فالتغير في درجة الحرارة مختلف.","نسبة ΔT هي 2 فقط، فتكون نسبة الحرارة النوعية 2 لا 4."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-03T20:51:23.837Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) q = 1.35 kJ = 1350 J، وΔT = 42.0 − 22.0 = 20.0°C؛ c = q / (m × ΔT) = 1350 J / (75.0 g × 20.0°C) = 0.900 J/g·°C. (ب) أقرب قيمة هي 0.897 J/g·°C، فالفلز المرجح هو الألومنيوم.', '["تحويل kJ إلى J","حساب ΔT","تطبيق c = q / (m × ΔT)","الناتج 0.900 J/g·°C","تعرف الألومنيوم"]'::jsonb, '["q = 1.35 kJ × 1000 = 1350 J","ΔT = 42.0°C − 22.0°C = 20.0°C","c = 1350 / (75.0 × 20.0) = 0.900 J/g·°C","المقارنة: 0.900 ≈ 0.897 (الألومنيوم)"]'::jsonb, '[{"element":"تحويل الوحدة","marks":1},{"element":"حساب ΔT","marks":1},{"element":"حساب c","marks":2},{"element":"تعرف الفلز","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح كامل بالوحدات وتعرف صحيح للفلز"},{"level":"3–4 درجات","description":"خطأ واحد في التحويل أو الأرقام المعنوية مع منهجية صحيحة"},{"level":"1–2 درجة","description":"كتابة العلاقة أو حساب ΔT فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان تحويل kJ إلى J","استعمال درجة الحرارة النهائية بدلًا من ΔT","قلب العلاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-03T20:51:23.838Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) q = 11.7 kJ = 11700 J (مطلقة، q = −11700 J)، وΔT = 20.0 − 60.0 = −40.0°C؛ c = q / (m × ΔT) = −11700 J / (120.0 g × −40.0°C) = 2.44 J/g·°C. (ب) عند انطلاق الحرارة تكون q سالبة وΔT سالبة أيضًا لأن درجة الحرارة انخفضت، فيكون ناتج القسمة موجبًا؛ فالحرارة النوعية خاصية للمادة قيمتها موجبة دائمًا.', '["تحويل kJ إلى J","حساب ΔT","حساب c = 2.44 J/g·°C","تفسير إشارة c"]'::jsonb, '["q = −11.7 kJ = −11700 J","ΔT = 20.0°C − 60.0°C = −40.0°C","c = −11700 / (120.0 × −40.0) = 2.44 J/g·°C"]'::jsonb, '[{"element":"تحويل الوحدة","marks":1},{"element":"حساب ΔT","marks":1},{"element":"حساب c","marks":2},{"element":"تفسير الإشارة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح وتفسير صحيح للإشارة"},{"level":"3–4 درجات","description":"حساب صحيح مع تفسير ناقص، أو خطأ بسيط في الحساب مع تفسير صحيح"},{"level":"1–2 درجة","description":"كتابة العلاقة الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة c بإشارة سالبة","استعمال 60.0°C بدلًا من ΔT","نسيان تحويل kJ إلى J"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-03T20:51:23.838Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الحل خاطئ؛ لأن الطالب استعمل درجة الحرارة النهائية 75.0°C بدلًا من التغير في درجة الحرارة ΔT. (ب) ΔT = 75.0 − 25.0 = 50.0°C؛ c = 897 J / (20.0 g × 50.0°C) = 0.897 J/g·°C. (ج) الفلز هو الألومنيوم.', '["تحديد الخطأ: استعمال T النهائية بدلًا من ΔT","حساب ΔT = 50.0°C","c = 0.897 J/g·°C","تعرف الألومنيوم"]'::jsonb, '["ΔT = 75.0°C − 25.0°C = 50.0°C","c = 897 / (20.0 × 50.0) = 0.897 J/g·°C","المقارنة بالقيم المعطاة: الألومنيوم"]'::jsonb, '[{"element":"تحديد الخطأ","marks":2},{"element":"حساب القيمة الصحيحة","marks":2},{"element":"تعرف الفلز","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تقييم صحيح للخطأ وحساب صحيح وتعرف صحيح"},{"level":"3–4 درجات","description":"حساب صحيح مع تحديد غير دقيق للخطأ"},{"level":"1–2 درجة","description":"تحديد الخطأ فقط أو حساب ΔT فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول حل الطالب","استعمال 25.0°C بدلًا من ΔT","اختيار الحديد لقرب 0.598 من 0.449"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-03T20:51:23.838Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
