('mcq', 5, 'يقف متزلج عند بوابة البداية في أعلى المسار، ثم ينطلق نازلًا حتى خط النهاية. أي العبارات الآتية تصف طاقته وصفًا صحيحًا؟', null, null, '["تكون طاقة وضعه أكبر ما يمكن في الأعلى، ثم تتحول إلى طاقة حركية في أثناء النزول","تكون طاقته الحركية أكبر ما يمكن عند بوابة البداية، ثم تتحول إلى طاقة وضع في أثناء النزول","تبقى طاقة وضعه ثابتة على طول المسار لأن كتلته لا تتغير","لا يمتلك المتزلج أي طاقة عند بوابة البداية لأنه لا يتحرك"]'::jsonb, 'فهم', 'تفسير موقف', 'متوسط', 'الكتاب ص 12 — طبيعة الطاقة (مثال المتزلج)'),
('mcq', 6, 'تُعرَّف الطاقة بأنها القدرة على بذل شغل أو إنتاج حرارة. أيّ المواقف الآتية يظهر فيه شقّا هذا التعريف معًا (بذل شغل وإنتاج حرارة)؟', null, null, '["كتاب ساكن على رف مرتفع لا يتغير موضعه","قطعة جليد تنصهر بامتصاص حرارة من الهواء","ماء ساكن في كأس عند درجة حرارة الغرفة","جازولين يحترق في محرك فيحرك المكابس ويطلق حرارة"]'::jsonb, 'فهم', 'ربط مفاهيم', 'متوسط', 'الكتاب ص 12، 14 — تعريف الطاقة، الحرارة (الأوكتان في الجازولين)'),
('mcq', 7, 'أي الأمثلة الآتية يمثل جسمًا يمتلك طاقة حركية بسبب حركته؟', null, null, '["كتب موضوعة على رفّ مرتفع","ماء نهر يجري","بطارية مشحونة غير مستعملة","مغناطيسان منفصلان متقابلان"]'::jsonb, 'فهم', 'تصنيف أمثلة', 'صعب', 'الكتاب ص 12، 18 — طبيعة الطاقة، التقويم 1-1 (س8)'),
('essay', 1, 'عرّف الطاقة، ثم اذكر صورتيها الرئيستين مع مثال واحد لكل صورة.', null, null, null, 'فهم', 'تعريف وتصنيف', 'متوسط', 'الكتاب ص 12 — طبيعة الطاقة'),
('essay', 2, 'قارن بين طاقة الوضع والطاقة الحركية لمتزلج عند بوابة البداية في أعلى المسار وعند خط النهاية أسفله، ثم وضّح كيف يدل هذا المثال على تعريف الطاقة.', null, null, null, 'فهم', 'مقارنة وتفسير', 'صعب', 'الكتاب ص 12 — طبيعة الطاقة (الشكل 1-1، المتزلج)'),
('essay', 3, 'يخلط بعض الطلاب بين مصطلحات الطاقة والحرارة ودرجة الحرارة. اكتب تعريفًا لكل مصطلح منها، ثم بيّن العلاقة بين الطاقة الحركية لجسيمات المادة ودرجة حرارتها.', null, null, null, 'تحليل', 'تمييز مصطلحات', 'صعب', 'الكتاب ص 12–14، 42 — طبيعة الطاقة، الحرارة، التقويم (س44)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
