select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'تُعرّف الطاقة بأنها القدرة على بذل شغل أو إنتاج حرارة.', '["هذا تعريف درجة الحرارة، وهي مقياس لمتوسط الطاقة الحركية للجسيمات، وليست تعريفًا للطاقة نفسها.","","هذا تعريف الحرارة النوعية للمادة، لا تعريف الطاقة.","هذا وصف للحرارة q، وهي صورة من صور انتقال الطاقة، ولا يشمل التعريف العام للطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-03T20:51:23.839Z"}'::jsonb),
('mcq', 2, 3, 'القدرة على بذل شغل أو إنتاج حرارة هي تعريف الطاقة؛ فالمصطلح المطلوب هو الطاقة.', '["درجة الحرارة مقياس لمتوسط الطاقة الحركية للجسيمات في عينة المادة، وليست القدرة على بذل شغل.","الحرارة النوعية كمية الحرارة اللازمة لرفع درجة حرارة 1 g من المادة 1°C.","السُّعر وحدة لقياس الطاقة (كمية الحرارة اللازمة لرفع درجة حرارة 1 g من الماء 1°C)، وليس هو الطاقة نفسها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-03T20:51:23.839Z"}'::jsonb),
('mcq', 3, 0, 'توجد الطاقة عمومًا في صورة طاقة وضع وطاقة حركية، والأنظمة الكيميائية تحتوي على الصورتين معًا.', '["","الحرارة والضوء أشكال تظهر فيها الطاقة عند تحولها، لكن الصورتين العامتين للطاقة هما الوضع والحركية.","الكهرباء والطاقة النووية من استعمالات الطاقة ومصادرها، وليستا الصورتين العامتين اللتين توجد بهما الطاقة.","هذه مصادر للطاقة، وليست الصورتين اللتين تُصنّف فيهما الطاقة عمومًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-03T20:51:23.839Z"}'::jsonb),
('mcq', 4, 2, 'تسمى الطاقة التي تعتمد على تركيب الجسم أو موضعه طاقة الوضع، أما الطاقة الحركية فتنتج عن حركة الأجسام.', '["الطاقة الحركية تنتج عن حركة الأجسام، لا عن تركيبها أو موضعها.","الحرارة طاقة تنتقل من الجسم الساخن إلى الجسم الأبرد، ولا تعتمد على موضع الجسم.","","درجة الحرارة مقياس لمتوسط الطاقة الحركية للجسيمات، وليست طاقة مرتبطة بالموضع أو التركيب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-03T20:51:23.839Z"}'::jsonb),
('mcq', 5, 0, 'عند نقطة البداية في أعلى المسار تكون طاقة وضع المتزلج أكبر ما يمكن ولا يكون له طاقة حركية، وما إن يبدأ الحركة حتى تتحول طاقة وضعه إلى طاقة حركية على طول المسار.', '["","هذا عكس الصحيح؛ فالمتزلج ساكن في الأعلى فطاقته الحركية لا تكون أكبر ما يمكن هناك، والتحول يكون من الوضع إلى الحركة.","طاقة الوضع تعتمد على الموضع، وموضعه يتغير في أثناء النزول فتتناقص طاقة وضعه.","السكون يعني انعدام الطاقة الحركية فقط، أما طاقة الوضع فتكون في أعلى قيمها عند البداية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-03T20:51:23.839Z"}'::jsonb),
('mcq', 6, 3, 'عند احتراق الجازولين في المحرك يتحول جزء من طاقة الوضع الكيميائية إلى شغل يحرك المكابس، وينطلق جزء كبير منها حرارةً؛ فيظهر فيه شقّا تعريف الطاقة: بذل الشغل وإنتاج الحرارة.', '["الكتاب الساكن يمتلك طاقة وضع، لكنه في هذا الموقف لا يبذل شغلًا ولا ينتج حرارة.","الجليد هنا يمتص الحرارة من الهواء ولا ينتجها، ولا يبذل شغلًا.","الماء الساكن عند درجة حرارة الغرفة لا يبذل شغلًا ولا ينتج حرارة في هذا الموقف.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-03T20:51:23.840Z"}'::jsonb),
('mcq', 7, 1, 'الطاقة الحركية تنتج عن حركة الأجسام، والماء الجاري في النهر جسم متحرك. أما بقية الأمثلة فطاقتها طاقة وضع ناتجة عن الموضع أو التركيب.', '["الكتب الساكنة على رف مرتفع تمتلك طاقة وضع بسبب موضعها، لا طاقة حركية.","","البطارية المشحونة تخزن طاقة وضع كيميائية في تركيب موادها، ولا تتحرك.","المغناطيسان المنفصلان يمتلكان طاقة وضع بسبب موضع أحدهما بالنسبة للآخر، وليسا في حالة حركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-03T20:51:23.840Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الطاقة هي القدرة على بذل شغل أو إنتاج حرارة. وتوجد عمومًا في صورتين: طاقة الوضع، وهي طاقة تعتمد على تركيب الجسم أو موضعه، ومثالها كتاب موضوع على رف مرتفع أو ماء مخزّن خلف سد؛ والطاقة الحركية، وهي الطاقة الناتجة عن حركة الجسم، ومثالها متزلج ينزلق نازلًا أو ماء نهر يجري.', '["تعريف الطاقة: القدرة على بذل شغل أو إنتاج حرارة","الصورة الأولى: طاقة الوضع (تعتمد على التركيب أو الموضع) مع مثال صحيح","الصورة الثانية: الطاقة الحركية (ناتجة عن الحركة) مع مثال صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الطاقة تعريفًا صحيحًا","marks":2},{"element":"طاقة الوضع ومثالها","marks":1},{"element":"الطاقة الحركية ومثالها","marks":1}]'::jsonb, '[{"level":"4","description":"تعريف صحيح كامل للطاقة، وذكر الصورتين بمثال صحيح لكل منهما"},{"level":"3","description":"تعريف صحيح وصورتان، مع خطأ أو نقص في أحد المثالين"},{"level":"2","description":"تعريف صحيح فقط، أو الصورتان بمثاليهما دون تعريف"},{"level":"1","description":"ذكر إحدى الصورتين أو تعريف ناقص"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين تعريف الطاقة وتعريف درجة الحرارة أو الحرارة","ذكر مصادر الطاقة (شمسية، نووية) بدلًا من صورتيها","إعطاء مثال لجسم ساكن على أنه يمتلك طاقة حركية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-03T20:51:23.840Z"}'::jsonb),
('essay', 2, null::int, null, null, 'عند بوابة البداية في أعلى المسار تكون طاقة وضع المتزلج عالية بسبب موضعه المرتفع، ولا يكون له طاقة حركية لأنه ساكن. وعندما ينطلق تتحول طاقة وضعه تدريجيًّا إلى طاقة حركية، فعند خط النهاية تكون طاقة وضعه أقل بكثير وطاقته الحركية كبيرة. ويدل المثال على تعريف الطاقة بأنها القدرة على بذل شغل؛ فالطاقة المخزنة في موضع المتزلج هي التي مكّنته من الحركة وقطع المسار.', '["عند البداية: طاقة وضع عالية وطاقة حركية منعدمة","عند خط النهاية: طاقة وضع أقل وطاقة حركية كبيرة","التحول من طاقة وضع إلى طاقة حركية في أثناء النزول","الربط بالتعريف: الطاقة هي القدرة على بذل شغل (تحريك المتزلج)"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الطاقة عند البداية","marks":1},{"element":"وصف الطاقة عند خط النهاية","marks":1},{"element":"بيان التحول من الوضع إلى الحركة","marks":1},{"element":"الربط بتعريف الطاقة","marks":1}]'::jsonb, '[{"level":"4","description":"مقارنة صحيحة في الموضعين مع بيان التحول والربط الصحيح بالتعريف"},{"level":"3","description":"مقارنة صحيحة وبيان التحول دون ربط واضح بالتعريف"},{"level":"2","description":"وصف صحيح لأحد الموضعين مع إشارة إلى التحول"},{"level":"1","description":"وصف جزئي صحيح لطاقة المتزلج في موضع واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المتزلج الساكن في الأعلى لا يمتلك أي طاقة","عكس اتجاه التحول (من حركية إلى وضع في أثناء النزول)","إغفال الربط بين المثال وتعريف الطاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-03T20:51:23.840Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الطاقة: القدرة على بذل شغل أو إنتاج حرارة. الحرارة (q): طاقة تنتقل من الجسم الساخن إلى الجسم الأبرد. درجة الحرارة: مقياس لمتوسط الطاقة الحركية للجسيمات الموجودة في عينة من المادة. والعلاقة: الطاقة الحركية للمادة ترتبط بالحركة العشوائية الدائمة لجسيماتها وتتناسب مع درجة الحرارة، فكلما ارتفعت درجة الحرارة زادت حركة الجسيمات وزادت طاقتها الحركية.', '["تعريف الطاقة: القدرة على بذل شغل أو إنتاج حرارة","تعريف الحرارة: طاقة تنتقل من الجسم الساخن إلى الأبرد","تعريف درجة الحرارة: مقياس لمتوسط الطاقة الحركية للجسيمات","العلاقة: ارتفاع درجة الحرارة يعني زيادة حركة الجسيمات وطاقتها الحركية"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الطاقة","marks":1},{"element":"تعريف الحرارة","marks":1},{"element":"تعريف درجة الحرارة","marks":1},{"element":"بيان العلاقة بين الطاقة الحركية ودرجة الحرارة","marks":1}]'::jsonb, '[{"level":"4","description":"تعريفات الثلاثة صحيحة مع بيان صحيح للعلاقة"},{"level":"3","description":"تعريفات الثلاثة صحيحة دون العلاقة، أو تعريفان والعلاقة"},{"level":"2","description":"تعريفان صحيحان فقط، أو تعريف واحد والعلاقة"},{"level":"1","description":"تعريف واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف الحرارة بأنها درجة سخونة الجسم","اعتبار درجة الحرارة كمية الطاقة الكلية في الجسم","القول إن الحرارة تنتقل من البارد إلى الساخن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-03T20:51:23.840Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
