from (values
('mcq', 1, 'ما نص قانون حفظ الطاقة؟', null, null, '["في أي تفاعل كيميائي أو عملية فيزيائية تُستهلك الطاقة كلها وتفنى بانتهاء التفاعل","في أي تفاعل كيميائي أو عملية فيزيائية تُستحدث طاقة جديدة، ولكنها لا تتحول من شكل إلى آخر","في أي تفاعل كيميائي أو عملية فيزيائية يمكن أن تتحول الطاقة من شكل إلى آخر، ولكنها لا تُستحدث ولا تفنى","في أي تفاعل كيميائي أو عملية فيزيائية تبقى الطاقة في شكلها الأصلي، فلا تتحول إلى شكل آخر"]'::jsonb, 'تذكر', 'تذكر نص قانون', 'سهل', 'الكتاب ص 13 — قانون حفظ الطاقة'),
('mcq', 2, 'يُعرف قانون حفظ الطاقة أيضًا باسم:', null, null, '["القانون الأول في الديناميكا الحرارية","قانون هس في حساب المحتوى الحراري","قانون حفظ الكتلة في التفاعلات الكيميائية","قانون الاتزان الكيميائي"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'سهل', 'الكتاب ص 13 — قانون حفظ الطاقة'),
('mcq', 3, 'في محطة توليد كهرومائية يتدفق الماء المخزن خلف السد عبر فتحة إلى أسفل فيُدير التوربينات. ما تسلسل تحولات الطاقة الصحيح؟', null, null, '["طاقة كهربائية ← طاقة حركية ← طاقة وضع","طاقة حركية ← طاقة وضع ← طاقة كهربائية","طاقة وضع كيميائية ← حرارة ← طاقة كهربائية","طاقة وضع ← طاقة حركية ← طاقة كهربائية"]'::jsonb, 'فهم', 'تتبع تحولات الطاقة', 'متوسط', 'الكتاب ص 13 — قانون حفظ الطاقة (الشكل 1-2a)'),
('mcq', 4, 'عند استعمال غاز البروبان C₃H₈ وقودًا للطهو، يتحد مع الأكسجين مكونًا ثاني أكسيد الكربون والماء. ما الذي يحدث للطاقة في هذه العملية؟', null, null, '["تُستحدث طاقة جديدة من التفاعل لم تكن موجودة في المواد المتفاعلة","تتحرر طاقة الوضع المخزنة في روابط البروبان في صورة حرارة","تفنى طاقة البروبان كلها فيقل مجموع الطاقة بعد التفاعل","تتحول الحرارة المحيطة إلى طاقة وضع مخزنة في روابط البروبان"]'::jsonb, 'فهم', 'تفسير تحول طاقة', 'متوسط', 'الكتاب ص 13 — قانون حفظ الطاقة (الشكل 1-2b، البروبان)'),
('mcq', 5, 'يُشبَّه قانون حفظ الطاقة بشخص لديه حسابان في البنك، يحوّل نقودًا من أحدهما إلى الآخر. ما الفكرة التي يوضحها هذا التشبيه؟', null, null, '["تزداد الطاقة الكلية كلما تحولت من شكل إلى آخر","تنتقل الطاقة من شكل إلى آخر مرة واحدة فقط","يتغير مقدار كل شكل من أشكال الطاقة، ويبقى مجموع الطاقة ثابتًا","يتساوى مقدار الطاقة في جميع أشكالها في أي لحظة"]'::jsonb, 'فهم', 'تفسير تشبيه', 'متوسط', 'الكتاب ص 13 — قانون حفظ الطاقة (تشبيه الحسابين في البنك)'),
('mcq', 6, 'عند احتراق كمية من الوقود في محرك سيارة تحررت منها طاقة وضع كيميائية مقدارها 500 kJ، تحوّل 120 kJ منها إلى شغل يحرك السيارة. ما مقدار الطاقة التي انطلقت في صورة حرارة، بافتراض عدم وجود أشكال أخرى؟', null, null, '["620 kJ","380 kJ","500 kJ","120 kJ"]'::jsonb, 'تطبيق', 'تطبيق قانون حسابيًّا', 'صعب', 'الكتاب ص 13–14 — قانون حفظ الطاقة، الحرارة (احتراق الجازولين)'),
('mcq', 7, 'يمتص تفاعل ماص للحرارة 50 kJ من الحرارة من محيطه. ما الوصف الذي يتفق مع قانون حفظ الطاقة؟', null, null, '["تفنى 50 kJ من طاقة المحيط، ولا تتغير طاقة المواد المتفاعلة","تُستحدث 50 kJ من الطاقة داخل المواد الناتجة","تقل طاقة الوضع الكيميائية للمواد بمقدار 50 kJ وتبرد المواد المتفاعلة","تقل طاقة المحيط بمقدار 50 kJ وتزداد طاقة الوضع الكيميائية للمواد بالمقدار نفسه"]'::jsonb, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 13، 18، 42 — قانون حفظ الطاقة، التقويم (س7، س45)'),
('essay', 1, 'اذكر نص قانون حفظ الطاقة، ثم وضّح كيف ينطبق على احتراق الجازولين (الأوكتان C₈H₁₈) في محرك السيارة.', null, null, null, 'فهم', 'نص قانون وتطبيقه', 'سهل', 'الكتاب ص 13–14، 42 — قانون حفظ الطاقة، الحرارة، التقويم (س47)'),
('essay', 2, 'عند احتراق كمية من الوقود في محرك تحررت منها طاقة وضع كيميائية مقدارها 2.50 × 10³ kJ، وتحوّل 25% منها إلى شغل يحرك الآلة، وانطلق الباقي حرارةً. احسب مقدار الشغل ومقدار الحرارة، ثم بيّن كيف تتفق نتيجتك مع قانون حفظ الطاقة.', null, null, null, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 13–14 — قانون حفظ الطاقة (تطبيق على احتراق الوقود)'),
('essay', 3, 'وضّح كيف تتغير الطاقة من شكل إلى آخر في كلٍّ من التفاعل الطارد للحرارة والتفاعل الماص للحرارة، مبيّنًا في كل حالة ما يحدث لطاقة الوضع الكيميائية للمواد ولطاقة المحيط، وكيف يبقى قانون حفظ الطاقة متحققًا.', null, null, null, 'تحليل', 'تفسير ومقارنة', 'صعب', 'الكتاب ص 13، 18، 42 — قانون حفظ الطاقة، التقويم 1-1 (س7)، التقويم (س45)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
