insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'ينص قانون حفظ الطاقة على أنه في أي تفاعل كيميائي أو عملية فيزيائية يمكن أن تتحول الطاقة من شكل إلى آخر، ولكنها لا تُستحدث ولا تفنى.', '["الطاقة لا تفنى؛ فهي تتحول إلى أشكال أخرى ويبقى مجموعها ثابتًا.","الطاقة لا تُستحدث في أي تفاعل، ويمكن أن تتحول من شكل إلى آخر؛ فالتفاعل الطارد يطلق طاقة كانت مخزنة في روابط المواد المتفاعلة.","","الطاقة يمكن أن تتحول من شكل إلى آخر، كتحول طاقة الوضع الكيميائية إلى حرارة عند احتراق البروبان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-03T20:51:23.841Z"}'::jsonb),
('mcq', 2, 0, 'يُعرف قانون حفظ الطاقة أيضًا بالقانون الأول في الديناميكا الحرارية.', '["","قانون هس يتعلق بحساب التغير في المحتوى الحراري لتفاعل من مجموع معادلات حرارية، وليس اسمًا آخر لقانون حفظ الطاقة.","قانون حفظ الكتلة يتعلق بثبات الكتلة في التفاعل الكيميائي، لا بالطاقة.","قانون الاتزان الكيميائي يربط تراكيز المواد عند الاتزان، ولا علاقة له بحفظ الطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-03T20:51:23.841Z"}'::jsonb),
('mcq', 3, 3, 'الماء المخزن خلف السد يمتلك طاقة وضع، وعندما يتدفق تتحول طاقة وضعه إلى طاقة حركية، ثم يتحول جزء من طاقته الحركية إلى طاقة كهربائية عبر التوربينات.', '["هذا عكس الاتجاه الصحيح؛ فالطاقة الكهربائية ناتج نهائي هنا وليست البداية.","الماء المخزن خلف السد يبدأ بطاقة وضع بسبب ارتفاعه، لا بطاقة حركية.","لا يحدث تفاعل كيميائي في المحطة الكهرومائية؛ فالطاقة الأصلية طاقة وضع بسبب ارتفاع الماء لا طاقة وضع كيميائية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-03T20:51:23.842Z"}'::jsonb),
('mcq', 4, 1, 'عند احتراق البروبان تتحرر طاقة الوضع المخزنة في روابطه في صورة حرارة، فتتحول الطاقة من شكل إلى آخر ويبقى مجموعها ثابتًا.', '["الطاقة لا تُستحدث؛ فالحرارة المنطلقة كانت مخزنة طاقةَ وضع كيميائية في روابط البروبان.","","الطاقة لا تفنى؛ فهي تتحول إلى حرارة ويبقى مجموعها ثابتًا.","احتراق البروبان يطلق الحرارة إلى المحيط ولا يمتصها؛ فهذا وصف معكوس للعملية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-03T20:51:23.842Z"}'::jsonb),
('mcq', 5, 2, 'كما أن مقدار النقود في كل حساب يتغير مع بقاء مجموع النقود في البنك دون تغيير، فإن مقادير أشكال الطاقة تتغير عند تحولها ويبقى مجموع الطاقة ثابتًا.', '["مجموع النقود في التشبيه لا يزداد بالتحويل، وكذلك مجموع الطاقة لا يزداد عند تحولها.","التحويل بين الحسابين يمكن أن يتكرر، وكذلك تتحول الطاقة بين أشكالها مرات عديدة.","","لا يشترط أن يتساوى المبلغ في الحسابين، وكذلك لا يشترط تساوي مقادير أشكال الطاقة؛ المهم ثبات المجموع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:51:23.842Z"}'::jsonb),
('mcq', 6, 1, 'وفق قانون حفظ الطاقة يبقى مجموع الطاقة ثابتًا: الحرارة = 500 kJ − 120 kJ = 380 kJ.', '["جمع الطاقتين (500 + 120) يعني استحداث طاقة لم تكن موجودة، وهذا يخالف قانون حفظ الطاقة.","","هذا يفترض أن الطاقة كلها تحولت إلى حرارة، مع أن 120 kJ منها تحولت إلى شغل.","هذا مقدار الشغل نفسه، لا مقدار الحرارة المنطلقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-03T20:51:23.843Z"}'::jsonb),
('mcq', 7, 3, 'في التفاعل الماص تنتقل الحرارة من المحيط إلى المواد، فتقل طاقة المحيط بمقدار 50 kJ وتُخزَّن هذه الطاقة في المواد فتزداد طاقة وضعها الكيميائية بالمقدار نفسه، ويبقى المجموع ثابتًا.', '["الطاقة لا تفنى؛ فالحرارة التي فقدها المحيط انتقلت إلى المواد المتفاعلة وغيّرت طاقتها.","الطاقة لا تُستحدث؛ فالطاقة المخزنة في النواتج مصدرها الحرارة الممتصة من المحيط.","في التفاعل الماص تزداد طاقة الوضع الكيميائية للمواد لا تقل؛ فهي تكتسب الحرارة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-03T20:51:23.843Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نص القانون: في أي تفاعل كيميائي أو عملية فيزيائية يمكن أن تتحول الطاقة من شكل إلى آخر، ولكنها لا تُستحدث ولا تفنى. وعند احتراق الجازولين في محرك السيارة يتحول جزء من طاقة الوضع الكيميائية للأوكتان إلى شغل يحرك المكابس التي تحرك الإطارات فتتحرك السيارة (طاقة حركية)، وينطلق جزء كبير منها في صورة حرارة. ومجموع الشغل والحرارة يساوي طاقة الوضع الكيميائية التي تحررت، فلم تُستحدث طاقة ولم تفنَ.', '["نص القانون كاملًا (تتحول ولا تُستحدث ولا تفنى)","تحول جزء من طاقة الوضع الكيميائية إلى شغل يحرك المكابس والسيارة","انطلاق جزء كبير من الطاقة في صورة حرارة","مجموع الطاقة الناتجة يساوي الطاقة المتحررة (ثبات المجموع)"]'::jsonb, '[]'::jsonb, '[{"element":"نص القانون","marks":2},{"element":"التحول إلى شغل وحركة","marks":1},{"element":"انطلاق جزء كبير في صورة حرارة","marks":1},{"element":"بيان ثبات مجموع الطاقة","marks":1}]'::jsonb, '[{"level":"5","description":"نص صحيح كامل وتطبيق صحيح يشمل الشغل والحرارة وثبات المجموع"},{"level":"4","description":"نص صحيح وتطبيق يغفل عنصرًا واحدًا"},{"level":"3","description":"نص صحيح مع تطبيق جزئي، أو نص ناقص مع تطبيق كامل"},{"level":"2","description":"نص صحيح فقط، أو تطبيق صحيح دون نص"},{"level":"1","description":"إشارة صحيحة واحدة إلى تحول الطاقة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الطاقة تُستهلك أو تفنى في المحرك","إغفال أن جزءًا كبيرًا من الطاقة ينطلق حرارةً","نسيان عبارة «لا تُستحدث» من نص القانون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-03T20:51:23.843Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الشغل = 0.25 × 2.50 × 10³ kJ = 625 kJ. الحرارة = 2.50 × 10³ kJ − 625 kJ = 1875 kJ ≈ 1.88 × 10³ kJ. مجموع الشغل والحرارة = 625 kJ + 1875 kJ = 2.50 × 10³ kJ، وهو يساوي طاقة الوضع الكيميائية المتحررة؛ أي إن الطاقة تحولت من شكل إلى آخر دون أن تُستحدث أو تفنى، وهذا ما ينص عليه قانون حفظ الطاقة.', '["حساب الشغل = 625 kJ","حساب الحرارة ≈ 1.88 × 10³ kJ","التحقق: مجموع الشغل والحرارة يساوي 2.50 × 10³ kJ","الربط بقانون حفظ الطاقة"]'::jsonb, '["الشغل = 0.25 × 2.50 × 10³ kJ = 625 kJ","الحرارة = 2.50 × 10³ kJ − 625 kJ = 1875 kJ ≈ 1.88 × 10³ kJ","625 kJ + 1875 kJ = 2.50 × 10³ kJ = الطاقة المتحررة"]'::jsonb, '[{"element":"حساب الشغل","marks":1},{"element":"حساب الحرارة","marks":1},{"element":"التحقق من ثبات المجموع","marks":1},{"element":"الربط بنص القانون","marks":1}]'::jsonb, '[{"level":"4","description":"حسابان صحيحان مع التحقق والربط الصحيح بالقانون"},{"level":"3","description":"حسابان صحيحان مع ربط ناقص بالقانون"},{"level":"2","description":"حساب واحد صحيح مع إشارة إلى ثبات المجموع"},{"level":"1","description":"حساب واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع الشغل إلى الطاقة الكلية بدل طرحه منها","استعمال 25 بدل 0.25 عند حساب النسبة","القول إن الحرارة المنطلقة طاقة ضائعة فنيت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-03T20:51:23.843Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في التفاعل الطارد للحرارة يتحول جزء من طاقة الوضع الكيميائية المخزنة في روابط المواد المتفاعلة إلى حرارة تنطلق إلى المحيط، فتقل طاقة الوضع الكيميائية للمواد وتزداد طاقة المحيط بالمقدار نفسه. وفي التفاعل الماص للحرارة تمتص المواد حرارة من المحيط فتُخزَّن في روابطها، فتزداد طاقة الوضع الكيميائية للمواد وتقل طاقة المحيط بالمقدار نفسه. وفي الحالتين لا تُستحدث الطاقة ولا تفنى، وإنما تنتقل وتتحول، فيبقى مجموع طاقة المواد والمحيط ثابتًا، وهذا هو قانون حفظ الطاقة.', '["الطارد: تتحول طاقة الوضع الكيميائية إلى حرارة تنطلق، فتقل طاقة وضع المواد","الطارد: تزداد طاقة المحيط بالمقدار نفسه","الماص: تمتص المواد حرارة فتزداد طاقة وضعها الكيميائية","الماص: تقل طاقة المحيط بالمقدار نفسه","ثبات المجموع في الحالتين وفق قانون حفظ الطاقة"]'::jsonb, '[]'::jsonb, '[{"element":"وصف التفاعل الطارد","marks":2},{"element":"وصف التفاعل الماص","marks":2},{"element":"الربط بقانون حفظ الطاقة","marks":1}]'::jsonb, '[{"level":"5","description":"وصف صحيح للنوعين بطرفيهما (المواد والمحيط) مع ربط صحيح بالقانون"},{"level":"4","description":"وصف صحيح للنوعين مع ربط ناقص أو إغفال طرف واحد"},{"level":"3","description":"وصف صحيح لنوع واحد مع ربط بالقانون"},{"level":"2","description":"وصف صحيح لنوع واحد فقط"},{"level":"1","description":"إشارة صحيحة إلى أن الطاقة تتحول ولا تفنى دون وصف التفاعلين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التفاعل الطارد يستحدث حرارة","عكس اتجاه تغير طاقة الوضع الكيميائية في التفاعل الماص","إغفال تغير طاقة المحيط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-03T20:51:23.843Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
