('mcq', 2, 'على أي مما يأتي تعتمد طاقة الوضع الكيميائية للمادة؟', null, null, '["درجة حرارة العينة وحجم الإناء الذي توضع فيه","أنواع الذرات وعدد الروابط بينها ونوعها وطريقة ترتيب الذرات","ارتفاع العينة عن سطح الأرض وسرعة حركتها","لون المادة وحالتها الفيزيائية وشكل بلوراتها"]'::jsonb, 'فهم', 'تحديد عوامل', 'سهل', 'الكتاب ص 13، 18 — طاقة الوضع الكيميائية، الخلاصة'),
('mcq', 3, 'يُستعمل غاز البروبان C₃H₈ وقودًا للطهو والتسخين. مِمَّ تنتج طاقة الوضع الكيميائية للبروبان؟', null, null, '["من ترتيب ذرات الكربون والهيدروجين وقوة الروابط التي تربط بينها","من سرعة حركة جزيئات البروبان داخل الأسطوانة","من ارتفاع أسطوانة الغاز عن سطح الأرض","من الحرارة التي يمتصها الغاز من المحيط في أثناء الاحتراق"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 13 — طاقة الوضع الكيميائية (البروبان)'),
('mcq', 4, 'للإيثانول C₂H₅OH وثنائي ميثيل الإيثر CH₃OCH₃ الصيغة الجزيئية نفسها C₂H₆O. لماذا يُتوقع أن تختلف طاقة الوضع الكيميائية لمول واحد من كل منهما؟', null, null, '["لأن عدد ذرات الكربون في أحدهما أكبر من الآخر","لأن كتلة المول الواحد من أحدهما أكبر من الآخر","لأن ترتيب الذرات والروابط التي تربطها مختلفان فيهما","لأن أنواع الذرات المكوِّنة لهما مختلفة"]'::jsonb, 'فهم', 'تطبيق مفهوم على مثال جديد', 'متوسط', 'الكتاب ص 13 — طاقة الوضع الكيميائية (اعتمادها على ترتيب الذرات)'),
('mcq', 5, 'عندما يحترق الجازولين في محرك السيارة، إلامَ تتحول طاقة الوضع الكيميائية المختزنة في الأوكتان C₈H₁₈؟', null, null, '["إلى طاقة وضع كيميائية أكبر مخزنة في النواتج","إلى ضوء فقط دون أي حرارة","إلى كتلة إضافية في ثاني أكسيد الكربون والماء","إلى شغل يحرك المكابس، وينطلق جزء كبير منها حرارةً"]'::jsonb, 'فهم', 'تفسير تحول طاقة', 'متوسط', 'الكتاب ص 14 — الحرارة (الأوكتان في الجازولين)'),
('mcq', 6, 'عند إشعال شمعة ينبعث منها ضوء وحرارة. ما مصدر هذه الطاقة؟', null, null, '["طاقة الوضع الكيميائية المخزنة في روابط مكونات الشمع","الحرارة التي يمتصها الشمع من عود الثقاب فقط، ثم يعيد إطلاقها","الطاقة الحركية لجزيئات الهواء المحيط بالشمعة","طاقة جديدة تُستحدث في اللهب لم تكن موجودة في الشمع والهواء"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'صعب', 'الكتاب ص 18 — التقويم 1-1 (س9)، الخلاصة'),
('mcq', 7, 'تفاعل كيميائي يمتص حرارة من محيطه في أثناء حدوثه. ماذا تستنتج عن طاقة الوضع الكيميائية للمواد الناتجة مقارنة بالمواد المتفاعلة؟', null, null, '["أقل من طاقة الوضع الكيميائية للمواد المتفاعلة","مساوية لطاقة الوضع الكيميائية للمواد المتفاعلة","أكبر من طاقة الوضع الكيميائية للمواد المتفاعلة","صفر، لأن الحرارة الممتصة تفكك الروابط كلها"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 18، 42 — الخلاصة، التقويم (س45)'),
('essay', 1, 'عرّف طاقة الوضع الكيميائية، واذكر العوامل التي تعتمد عليها.', null, null, null, 'فهم', 'تعريف وتعداد', 'سهل', 'الكتاب ص 13، 18 — طاقة الوضع الكيميائية، الخلاصة'),
('essay', 2, 'وضّح العلاقة بين طاقة الوضع الكيميائية من جهة، والضوء والحرارة الناتجين عن شمعة مشتعلة من جهة أخرى، مستعينًا بقانون حفظ الطاقة.', null, null, null, 'فهم', 'تفسير ظاهرة', 'متوسط', 'الكتاب ص 13، 18 — طاقة الوضع الكيميائية، التقويم 1-1 (س9)'),
('essay', 3, 'قارن بين التفاعل الطارد للحرارة والتفاعل الماص للحرارة من حيث: طاقة الوضع الكيميائية للنواتج مقارنة بالمتفاعلات، واتجاه انتقال الحرارة بين النظام والمحيط. ثم فسّر لماذا تُعد طاقة الوضع الكيميائية مهمة في التفاعلات الكيميائية.', null, null, null, 'تحليل', 'مقارنة وتفسير', 'صعب', 'الكتاب ص 13–14، 18، 42 — طاقة الوضع الكيميائية، الخلاصة، التقويم (س45)')
