('mcq', 1, 3, 'تسمى الطاقة المخزنة في الروابط الكيميائية للمادة طاقة الوضع الكيميائية.', '["الطاقة الناتجة عن حركة الجسيمات طاقة حركية، وهي ترتبط بدرجة الحرارة لا بالروابط.","هذا وصف الحرارة q، وهي طاقة منتقلة وليست طاقة مخزنة في الروابط.","هذا تعريف الحرارة النوعية للمادة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-03T20:51:23.844Z"}'::jsonb),
('mcq', 2, 1, 'تعتمد طاقة الوضع للمادة على تركيبها الكيميائي: أنواع الذرات في المادة، وعدد الروابط الكيميائية التي تربط الذرات معًا ونوعها، وطريقة ترتيب هذه الذرات.', '["درجة الحرارة ترتبط بالطاقة الحركية للجسيمات، وحجم الإناء لا يغيّر الطاقة المخزنة في الروابط.","","الارتفاع يحدد طاقة الوضع الناتجة عن الموضع، والسرعة تحدد الطاقة الحركية؛ وكلاهما لا يحدد الطاقة المخزنة في الروابط.","اللون وشكل البلورات خصائص فيزيائية ظاهرية، وطاقة الوضع الكيميائية تعتمد على الذرات والروابط وترتيبها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-03T20:51:23.844Z"}'::jsonb),
('mcq', 3, 0, 'تنتج طاقة الوضع الكيميائية للبروبان عن ترتيب ذرات الكربون والهيدروجين وقوة الروابط التي تربط بينها.', '["","سرعة حركة الجزيئات ترتبط بطاقتها الحركية ودرجة حرارتها، لا بطاقة الوضع الكيميائية.","ارتفاع الأسطوانة يرتبط بطاقة الوضع الناتجة عن الموضع، لا بالطاقة المخزنة في روابط البروبان.","احتراق البروبان يطلق الحرارة ولا يمتصها؛ والطاقة المنطلقة مصدرها طاقة الوضع المخزنة أصلًا في روابطه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-03T20:51:23.844Z"}'::jsonb),
('mcq', 4, 2, 'للمركبين أنواع الذرات نفسها وأعدادها نفسها، لكن ترتيب الذرات والروابط بينها مختلف، وطاقة الوضع الكيميائية تعتمد على ترتيب الذرات ونوع الروابط.', '["للمركبين الصيغة الجزيئية نفسها، فعدد ذرات الكربون في كل منهما ذرتان.","الصيغة الجزيئية نفسها تعني أن الكتلة المولية واحدة لكليهما.","","المركبان يتكونان من الذرات نفسها (C وH وO) بالأعداد نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-03T20:51:23.845Z"}'::jsonb),
('mcq', 5, 3, 'عند احتراق الجازولين يتحول جزء من طاقة الوضع الكيميائية للأوكتان إلى شغل يحرك المكابس التي تحرك الإطارات، لكن جزءًا كبيرًا منها ينطلق في صورة حرارة.', '["الاحتراق تفاعل طارد يطلق الطاقة، فطاقة الوضع الكيميائية للنواتج أقل لا أكبر.","الجزء الكبير من الطاقة المنطلقة في المحرك يكون حرارة، والجزء الآخر شغل.","الطاقة لا تتحول إلى كتلة في التفاعلات الكيميائية العادية؛ بل تنطلق شغلًا وحرارة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-03T20:51:23.845Z"}'::jsonb),
('mcq', 6, 0, 'الشمع يخزن طاقة وضع كيميائية في روابطه، وتُطلق هذه الطاقة في أثناء الاحتراق في صورة ضوء وحرارة.', '["","عود الثقاب يبدأ التفاعل فقط، أما الطاقة الكبيرة المنطلقة فمصدرها روابط مكونات الشمع.","الهواء يوفر الأكسجين للاحتراق، ولكن طاقة جزيئاته الحركية ليست مصدر الضوء والحرارة.","الطاقة لا تُستحدث وفق قانون حفظ الطاقة؛ فهي تتحول من طاقة وضع كيميائية إلى ضوء وحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-03T20:51:23.845Z"}'::jsonb),
('mcq', 7, 2, 'الحرارة التي يمتصها النظام من المحيط تُخزَّن في روابط المواد، فتصبح طاقة الوضع الكيميائية للنواتج أكبر من طاقة المتفاعلات.', '["النواتج تكون أقل طاقة في التفاعل الطارد الذي يطلق الحرارة، لا في التفاعل الماص.","لو تساوت الطاقتان لما امتص التفاعل حرارة ولا أطلقها.","","النواتج مواد لها روابط، فطاقة وضعها الكيميائية لا تكون صفرًا؛ والحرارة الممتصة تُخزَّن فيها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-03T20:51:23.845Z"}'::jsonb),
('essay', 1, null::int, null, null, 'طاقة الوضع الكيميائية هي الطاقة المخزنة في الروابط الكيميائية للمادة. وتعتمد على التركيب الكيميائي للمادة من حيث: أنواع الذرات في المادة، وعدد الروابط الكيميائية التي تربط الذرات معًا ونوعها، وطريقة ترتيب هذه الذرات.', '["التعريف: الطاقة المخزنة في الروابط الكيميائية للمادة","أنواع الذرات في المادة","عدد الروابط الكيميائية ونوعها","طريقة ترتيب الذرات"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"أنواع الذرات","marks":1},{"element":"عدد الروابط ونوعها","marks":1},{"element":"ترتيب الذرات","marks":1}]'::jsonb, '[{"level":"4","description":"تعريف صحيح مع العوامل الثلاثة"},{"level":"3","description":"تعريف صحيح مع عاملين، أو العوامل الثلاثة دون تعريف"},{"level":"2","description":"تعريف صحيح مع عامل واحد، أو عاملان دون تعريف"},{"level":"1","description":"تعريف صحيح فقط أو عامل واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر درجة الحرارة أو الارتفاع عاملًا تعتمد عليه طاقة الوضع الكيميائية","الخلط بين طاقة الوضع الكيميائية والطاقة الحركية للجسيمات","إغفال عامل ترتيب الذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-03T20:51:23.845Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يحتوي الشمع على طاقة وضع كيميائية مخزنة في الروابط الكيميائية بين ذراته. وعند اشتعال الشمعة يتفاعل الشمع مع الأكسجين، فتنكسر روابط وتتكون روابط جديدة في النواتج ذات طاقة وضع كيميائية أقل، ويُطلق الفرق في الطاقة في صورة ضوء وحرارة. ووفق قانون حفظ الطاقة فإن الضوء والحرارة لم يُستحدثا، وإنما هما ناتجان عن تحول جزء من طاقة الوضع الكيميائية المخزنة في الشمع إلى أشكال أخرى من الطاقة.', '["الشمع يخزن طاقة وضع كيميائية في روابطه","في أثناء الاحتراق تتحول طاقة الوضع الكيميائية إلى ضوء وحرارة","النواتج أقل في طاقة الوضع الكيميائية من المتفاعلات","الضوء والحرارة لم يُستحدثا (قانون حفظ الطاقة)"]'::jsonb, '[]'::jsonb, '[{"element":"تخزين الطاقة في روابط الشمع","marks":1},{"element":"تحولها إلى ضوء وحرارة","marks":1},{"element":"مقارنة طاقة النواتج بالمتفاعلات","marks":1},{"element":"الربط بقانون حفظ الطاقة","marks":1}]'::jsonb, '[{"level":"4","description":"توضيح كامل يشمل التخزين والتحول ومقارنة الطاقة والربط بالقانون"},{"level":"3","description":"توضيح التخزين والتحول مع أحد العنصرين الآخرين"},{"level":"2","description":"توضيح التخزين والتحول فقط"},{"level":"1","description":"إشارة صحيحة إلى أن مصدر الطاقة هو الشمع"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار عود الثقاب مصدر الطاقة المنطلقة كلها","القول إن اللهب يستحدث الطاقة","القول إن طاقة الوضع الكيميائية للنواتج أكبر من طاقة الشمع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-03T20:51:23.846Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في التفاعل الطارد للحرارة تكون طاقة الوضع الكيميائية للنواتج أقل من طاقة المتفاعلات، ويُطلق الفرق حرارةً تنتقل من النظام إلى المحيط. وفي التفاعل الماص للحرارة تكون طاقة الوضع الكيميائية للنواتج أكبر من طاقة المتفاعلات، وتنتقل الحرارة من المحيط إلى النظام فتُخزَّن في روابط النواتج. وتُعد طاقة الوضع الكيميائية مهمة لأنها الطاقة المخزنة في الروابط التي تُطلق أو تُمتص في أثناء التفاعلات على أشكال مثل الحرارة أو الضوء أو الكهرباء، فهي التي تحدد ما إذا كان التفاعل يطلق الطاقة أو يمتصها.', '["الطارد: طاقة النواتج أقل، والحرارة تنتقل من النظام إلى المحيط","الماص: طاقة النواتج أكبر، والحرارة تنتقل من المحيط إلى النظام","طاقة الوضع الكيميائية تُطلق أو تُمتص على أشكال (حرارة، ضوء، كهرباء)","الفرق في طاقة الوضع الكيميائية يحدد إطلاق الطاقة أو امتصاصها"]'::jsonb, '[]'::jsonb, '[{"element":"التفاعل الطارد (الطاقة واتجاه الحرارة)","marks":2},{"element":"التفاعل الماص (الطاقة واتجاه الحرارة)","marks":2},{"element":"تفسير أهمية طاقة الوضع الكيميائية","marks":2}]'::jsonb, '[{"level":"6","description":"مقارنة صحيحة كاملة للنوعين وتفسير صحيح للأهمية"},{"level":"4–5","description":"مقارنة صحيحة للنوعين مع تفسير ناقص، أو نقص في معيار واحد"},{"level":"2–3","description":"مقارنة صحيحة لنوع واحد مع تفسير جزئي"},{"level":"1","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس مقارنة طاقة النواتج بالمتفاعلات في النوعين","القول إن الحرارة تنتقل من المحيط إلى النظام في التفاعل الطارد","حصر أشكال الطاقة المنطلقة في الحرارة فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-03T20:51:23.847Z"}'::jsonb)
