select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'ΔT = q ÷ (c × m) = 2092 J ÷ (4.184 J/g·°C × 50.0 g) = 10.0°C، وبما أن الماء امتص الحرارة فإن Tf = Ti + ΔT = 20.0°C + 10.0°C = 30.0°C.', '["","هذه قيمة ΔT فقط؛ نسي الطالب إضافة درجة الحرارة الابتدائية 20.0°C.","قلب الطالب النسبة فحسب (c × m) ÷ q = 0.100 ثم أضافها إلى 20.0°C.","أهمل الطالب الحرارة النوعية فقسم q على الكتلة فقط (2092 ÷ 50.0 = 41.8) ثم أضاف 20.0°C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-03T20:51:23.848Z"}'::jsonb),
('mcq', 2, 2, 'ΔT = 45.0°C − 25.0°C = 20.0°C، و m = q ÷ (c × ΔT) = 1794 J ÷ (0.897 J/g·°C × 20.0°C) = 100 g.', '["استعمل الطالب درجة الحرارة النهائية 45.0°C بدل ΔT في القسمة.","استعمل الطالب الحرارة النوعية للماء 4.184 J/g·°C بدل الحرارة النوعية للألومنيوم.","","استعمل الطالب درجة الحرارة الابتدائية 25.0°C بدل ΔT في القسمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-03T20:51:23.849Z"}'::jsonb),
('mcq', 3, 1, 'q = 20.92 kJ = 20920 J، و ΔT = 20920 J ÷ (4.184 J/g·°C × 250 g) = 20.0°C، وبما أن الماء فقد الحرارة فإن درجة حرارته تنخفض: Tf = 80.0°C − 20.0°C = 60.0°C.', '["أضاف الطالب ΔT إلى درجة الحرارة الابتدائية، مع أن الماء فقد حرارة فانخفضت درجة حرارته.","","هذه قيمة مقدار التغير ΔT فقط وليست درجة الحرارة النهائية.","نسي الطالب تحويل kJ إلى J فحسب ΔT = 0.0200°C وطرحه من 80.0°C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-03T20:51:23.849Z"}'::jsonb),
('mcq', 4, 3, 'من q = c × m × ΔT نجد ΔT = q ÷ (c × m)، وبما أن العينة امتصت الحرارة فإن ΔT = Tf − Ti موجبة، إذن Tf = Ti + q ÷ (c × m).', '["الطرح يناسب عينة فقدت الحرارة، أما العينة التي امتصت الحرارة فترتفع درجة حرارتها.","ضرب q في c و m خطأ في إعادة ترتيب المعادلة؛ فـ ΔT تساوي q مقسومة على حاصل ضرب c و m.","هذه العلاقة مقلوبة؛ فالنسبة الصحيحة هي q مقسومة على (c × m) لا العكس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-03T20:51:23.850Z"}'::jsonb),
('mcq', 5, 1, 'm = 2.00 L × 1000 mL/L × 1.00 g/mL = 2.00 × 10³ g، و q = 418.4 kJ = 4.184 × 10⁵ J، إذن ΔT = 4.184 × 10⁵ J ÷ (4.184 J/g·°C × 2.00 × 10³ g) = 50.0°C، و Tf = 15.0°C + 50.0°C = 65.0°C.', '["هذه قيمة ΔT فقط؛ نسي الطالب إضافة درجة الحرارة الابتدائية 15.0°C.","","نسي الطالب تحويل kJ إلى J فحصل على ΔT = 0.0500°C.","طرح الطالب ΔT من درجة الحرارة الابتدائية كأن الماء فقد الحرارة، مع أنه امتصها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-03T20:51:23.851Z"}'::jsonb),
('mcq', 6, 0, 'مقدار التغير في درجة الحرارة = 95.0°C − 25.0°C = 70.0°C، و m = q ÷ (c × ΔT) = 6286 J ÷ (0.449 J/g·°C × 70.0°C) = 200 g.', '["","استعمل الطالب درجة الحرارة النهائية 25.0°C بدل مقدار التغير في درجة الحرارة.","استعمل الطالب درجة الحرارة الابتدائية 95.0°C بدل مقدار التغير في درجة الحرارة.","جمع الطالب درجتي الحرارة (95.0 + 25.0 = 120°C) بدل طرحهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-03T20:51:23.851Z"}'::jsonb),
('mcq', 7, 3, 'ΔT = q ÷ (c × m) = 235 J ÷ (0.235 J/g·°C × 25.0 g) = 40.0°C، وبما أن العينة امتصت الحرارة فإن Ti = Tf − ΔT = 60.0°C − 40.0°C = 20.0°C.', '["أضاف الطالب ΔT إلى درجة الحرارة النهائية، مع أن العينة سخنت فكانت درجة حرارتها الابتدائية أقل.","هذه قيمة ΔT وليست درجة الحرارة الابتدائية.","استعمل الطالب الحرارة النوعية للماء 4.184 J/g·°C بدل الحرارة النوعية للفضة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-03T20:51:23.852Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ΔT = q ÷ (c × m) = 512 J ÷ (0.128 J/g·°C × 20.0 g) = 200°C. وبما أن الرصاص امتص الحرارة فإن Tf = Ti + ΔT = 25.0°C + 200°C = 225°C.', '["كتابة العلاقة q = c × m × ΔT وإعادة ترتيبها لإيجاد ΔT","التعويض الصحيح والحصول على ΔT = 200°C","حساب Tf = 225°C بإضافة ΔT إلى Ti"]'::jsonb, '["q = c × m × ΔT ⇒ ΔT = q ÷ (c × m)","ΔT = 512 J ÷ (0.128 J/g·°C × 20.0 g) = 512 J ÷ 2.56 J/°C = 200°C","Tf = Ti + ΔT = 25.0°C + 200°C = 225°C"]'::jsonb, '[{"element":"العلاقة وإعادة ترتيبها","marks":1},{"element":"حساب ΔT","marks":1},{"element":"حساب Tf بالوحدة","marks":1}]'::jsonb, '[{"level":"3","description":"علاقة صحيحة وحساب صحيح لـ ΔT و Tf بالوحدة"},{"level":"2","description":"حساب صحيح لـ ΔT مع خطأ في إيجاد Tf أو إغفال الوحدة"},{"level":"1","description":"كتابة العلاقة وإعادة ترتيبها صحيحًا فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التوقف عند ΔT = 200°C واعتبارها درجة الحرارة النهائية","ضرب q في c و m بدل القسمة","استعمال الحرارة النوعية للماء بدل الرصاص"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-11-03T20:51:23.852Z"}'::jsonb),
('essay', 2, null::int, null, null, 'ΔT = Tf − Ti = 43.0°C − 18.0°C = 25.0°C. ومن q = c × m × ΔT نجد m = q ÷ (c × ΔT) = 1830 J ÷ (2.44 J/g·°C × 25.0°C) = 30.0 g.', '["حساب ΔT = 25.0°C","إعادة ترتيب العلاقة: m = q ÷ (c × ΔT)","التعويض والحصول على m = 30.0 g"]'::jsonb, '["ΔT = 43.0°C − 18.0°C = 25.0°C","m = q ÷ (c × ΔT)","m = 1830 J ÷ (2.44 J/g·°C × 25.0°C) = 1830 J ÷ 61.0 J/g = 30.0 g"]'::jsonb, '[{"element":"حساب ΔT","marks":1},{"element":"إعادة ترتيب العلاقة","marks":1},{"element":"التعويض والناتج بالوحدة","marks":2}]'::jsonb, '[{"level":"4","description":"خطوات صحيحة كاملة وناتج 30.0 g بالوحدة"},{"level":"3","description":"خطوات صحيحة مع خطأ حسابي بسيط أو إغفال الوحدة"},{"level":"2","description":"حساب ΔT وإعادة ترتيب العلاقة صحيحًا دون الوصول إلى الناتج"},{"level":"1","description":"حساب ΔT فقط أو كتابة العلاقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال درجة الحرارة النهائية 43.0°C بدل ΔT","استعمال الحرارة النوعية للماء بدل الإيثانول","قلب العلاقة: m = (c × ΔT) ÷ q"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-03T20:51:23.853Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) m = 2.00 kg = 2.00 × 10³ g، و q = 48.2 kJ = 4.82 × 10⁴ J. ΔT = 4.82 × 10⁴ J ÷ (0.803 J/g·°C × 2.00 × 10³ g) = 30.0°C، وبما أن الصخرة فقدت الحرارة فإن Tf = 40.0°C − 30.0°C = 10.0°C. (ب) للماء: ΔT = 4.82 × 10⁴ J ÷ (4.184 J/g·°C × 2.00 × 10³ g) = 5.76°C، و Tf = 40.0°C − 5.76°C = 34.2°C. (ج) الحرارة النوعية للماء أكبر بكثير من الحرارة النوعية للجرانيت، فعند فقد كمية الحرارة نفسها من كتلتين متساويتين يكون انخفاض درجة حرارة الماء أقل بكثير.', '["تحويل الكتلة إلى g والحرارة إلى J","ΔT للجرانيت = 30.0°C و Tf = 10.0°C","ΔT للماء = 5.76°C و Tf = 34.2°C","التفسير: الحرارة النوعية الأكبر تعني تغيرًا أقل في درجة الحرارة"]'::jsonb, '["m = 2.00 kg × 1000 g/kg = 2.00 × 10³ g ؛ q = 48.2 kJ × 1000 J/kJ = 4.82 × 10⁴ J","ΔT (جرانيت) = 4.82 × 10⁴ J ÷ (0.803 J/g·°C × 2.00 × 10³ g) = 30.0°C","Tf (جرانيت) = 40.0°C − 30.0°C = 10.0°C","ΔT (ماء) = 4.82 × 10⁴ J ÷ (4.184 J/g·°C × 2.00 × 10³ g) = 5.76°C","Tf (ماء) = 40.0°C − 5.76°C = 34.2°C"]'::jsonb, '[{"element":"تحويل الوحدات","marks":1},{"element":"درجة الحرارة النهائية للجرانيت","marks":2},{"element":"درجة الحرارة النهائية للماء","marks":2},{"element":"تفسير الفرق","marks":1}]'::jsonb, '[{"level":"6","description":"تحويلات صحيحة وحسابان صحيحان وتفسير صحيح"},{"level":"4–5","description":"حسابان صحيحان مع نقص في التفسير أو خطأ بسيط في أحد الحسابين"},{"level":"2–3","description":"حساب واحد صحيح كامل مع تحويل الوحدات"},{"level":"1","description":"تحويل الوحدات أو حساب ΔT لمادة واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان تحويل kg إلى g أو kJ إلى J","إضافة ΔT إلى درجة الحرارة الابتدائية مع أن المادة فقدت الحرارة","تفسير الفرق بالكتلة مع أن الكتلتين متساويتان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-03T20:51:23.853Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
