from (values
('mcq', 1, 'عيّنات متساوية الكتلة من مواد مختلفة امتصت كميات متساوية من الحرارة. أي هذه المواد ترتفع درجة حرارتها أكثر من غيرها؟', null, null, '["المادة ذات الحرارة النوعية الأكبر","المادة ذات الكثافة الأكبر","المادة ذات الحرارة النوعية الأصغر","ترتفع درجات حرارتها جميعًا بالمقدار نفسه"]'::jsonb, 'فهم', 'تفسير علاقة', 'سهل', 'الكتاب ص 15–16 — الحرارة النوعية'),
('mcq', 2, 'عيّنات متساوية الكتلة من أربعة فلزات امتصت كميات متساوية من الحرارة. اعتمادًا على قيم الحرارة النوعية المعطاة، أي الفلزات ترتفع درجة حرارته بأسرع ما يمكن؟', '{"headers":["الفلز","الحرارة النوعية (J/g·°C)"],"rows":[["الماغنسيوم","1.023"],["الكالسيوم","0.647"],["البريليوم","1.825"],["الرصاص","0.128"]]}'::jsonb, null, '["الماغنسيوم","الكالسيوم","البريليوم","الرصاص"]'::jsonb, 'تطبيق', 'قراءة جدول واستنتاج', 'سهل', 'الكتاب ص 16 — الجدول 1-2 (الحرارة النوعية لبعض المواد)'),
('mcq', 3, 'وُضعت كتل متساوية من الألومنيوم والذهب والحديد والفضة تحت أشعة الشمس في الوقت نفسه ولفترة زمنية محددة. ما الترتيب الصحيح لها وفق ازدياد درجات حرارتها من الأعلى إلى الأقل؟', '{"headers":["الفلز","الحرارة النوعية (J/g·°C)"],"rows":[["الألومنيوم","0.897"],["الذهب","0.129"],["الحديد","0.449"],["الفضة","0.235"]]}'::jsonb, null, '["الألومنيوم ← الحديد ← الفضة ← الذهب","الذهب ← الفضة ← الحديد ← الألومنيوم","الفضة ← الذهب ← الحديد ← الألومنيوم","الحديد ← الألومنيوم ← الفضة ← الذهب"]'::jsonb, 'تطبيق', 'ترتيب', 'متوسط', 'الكتاب ص 16، 18 — الجدول 1-2، التقويم 1-1 (س11)'),
('mcq', 4, 'عيّنات متساوية الكتلة من أربع مواد تمتص كميات متساوية من الحرارة. ما ترتيبها وفق سرعة ارتفاع درجة حرارتها من الأبطأ إلى الأسرع؟', '{"headers":["المادة","الحرارة النوعية (J/g·°C)"],"rows":[["الماء (l)","4.184"],["الإيثانول (l)","2.44"],["الجرانيت (s)","0.803"],["الإسترانشيوم (s)","0.301"]]}'::jsonb, null, '["الماء ← الإيثانول ← الجرانيت ← الإسترانشيوم","الإسترانشيوم ← الجرانيت ← الإيثانول ← الماء","الإيثانول ← الماء ← الإسترانشيوم ← الجرانيت","الجرانيت ← الإسترانشيوم ← الماء ← الإيثانول"]'::jsonb, 'تطبيق', 'ترتيب', 'متوسط', 'الكتاب ص 16 — الجدول 1-2'),
('mcq', 5, 'الحرارة النوعية للماء السائل 4.184 J/g·°C، وللأسمنت 0.84 J/g·°C. إذا امتصت كتلتان متساويتان من الماء والأسمنت كمية الحرارة نفسها، فكم مرة تقريبًا يكون ارتفاع درجة حرارة الأسمنت مقارنة بارتفاع درجة حرارة الماء؟', null, null, '["0.2 مرة","مرة واحدة","5 مرات","3.3 مرات"]'::jsonb, 'تحليل', 'مقارنة كمية', 'متوسط', 'الكتاب ص 15 — الحرارة النوعية (الأسمنت والماء)'),
('mcq', 6, 'امتصت كل عينة من العينات الأربع الآتية كمية الحرارة نفسها 50.0 J. أي العينات ترتفع درجة حرارتها أكثر من غيرها؟', '{"headers":["العينة","الكتلة (g)","الحرارة النوعية (J/g·°C)"],"rows":[["ذهب","10.0","0.129"],["فضة","10.0","0.235"],["ألومنيوم","5.00","0.897"],["حديد","2.00","0.449"]]}'::jsonb, null, '["عينة الذهب","عينة الفضة","عينة الألومنيوم","عينة الحديد"]'::jsonb, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 16 — الجدول 1-2، معادلة حساب الحرارة'),
('mcq', 7, 'زُوّدت عيّنات متساوية الكتلة من أربعة فلزات مجهولة (A وB وC وD) بكميات متساوية من الحرارة، فارتفعت درجات حرارتها كما يأتي. ما ترتيب الفلزات وفق حرارتها النوعية من الأكبر إلى الأصغر؟', '{"headers":["الفلز","الارتفاع في درجة الحرارة (°C)"],"rows":[["A","12"],["B","45"],["C","6"],["D","23"]]}'::jsonb, null, '["C ← A ← D ← B","B ← D ← A ← C","A ← C ← D ← B","C ← D ← A ← B"]'::jsonb, 'تحليل', 'استنتاج من بيانات', 'صعب', 'الكتاب ص 15–16، 18 — الحرارة النوعية، التقويم 1-1 (س11)'),
('essay', 1, 'رتّب الفلزات الآتية وفق سرعة ارتفاع درجة حرارتها من الأسرع إلى الأبطأ عندما تمتص كتل متساوية منها كميات متساوية من الحرارة، ثم فسّر أساس الترتيب: الماغنسيوم (1.023 J/g·°C)، الحديد (0.449 J/g·°C)، الرصاص (0.128 J/g·°C)، البريليوم (1.825 J/g·°C).', null, null, null, 'تطبيق', 'ترتيب وتفسير', 'سهل', 'الكتاب ص 16 — الجدول 1-2'),
('essay', 2, 'في يوم صيفي مشمس، يكون رصيف الأسمنت أسخن بكثير من ماء بركة مجاورة له، مع أنهما يتعرضان لأشعة الشمس نفسها. فسّر ذلك، ثم قدّر النسبة بين ارتفاع درجة حرارة الأسمنت وارتفاع درجة حرارة الماء لكتلتين متساويتين تمتصان كمية الحرارة نفسها. (الحرارة النوعية للأسمنت 0.84 J/g·°C، وللماء السائل 4.184 J/g·°C)', null, null, null, 'تحليل', 'تفسير ومقارنة كمية', 'متوسط', 'الكتاب ص 15 — الحرارة النوعية (الأسمنت والماء)'),
('essay', 3, 'امتصت عيّنات كتلة كل منها 10.0 g من الألومنيوم والذهب والحديد والفضة كمية الحرارة نفسها 100 J. احسب الارتفاع في درجة حرارة كل عينة، ثم رتّب الفلزات وفق ارتفاع درجات حرارتها من الأعلى إلى الأقل، وبيّن كيف يؤكد الحساب العلاقة بين الحرارة النوعية وسرعة ارتفاع درجة الحرارة. (الحرارة النوعية بوحدة J/g·°C: الألومنيوم 0.897، الذهب 0.129، الحديد 0.449، الفضة 0.235)', null, null, null, 'تحليل', 'حساب وترتيب', 'صعب', 'الكتاب ص 16، 18 — الجدول 1-2، التقويم 1-1 (س11)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C1-L1-O12') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'من q = c × m × ΔT نجد ΔT = q ÷ (c × m)؛ فإذا تساوت q و m كان التغير في درجة الحرارة أكبر كلما صغرت الحرارة النوعية c.', '["الحرارة النوعية الأكبر تعني أن المادة تحتاج إلى حرارة أكثر لرفع درجة حرارتها، فترتفع درجة حرارتها أقل.","الكثافة لا تظهر في علاقة الحرارة النوعية؛ والعامل المحدد عند تساوي الكتلة والحرارة هو الحرارة النوعية.","","لكل مادة حرارة نوعية مميزة لها، لذا تختلف مقادير ارتفاع درجات الحرارة رغم تساوي الحرارة والكتلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-03T20:51:23.855Z"}'::jsonb),
('mcq', 2, 3, 'أصغر حرارة نوعية بين الفلزات الأربعة للرصاص (0.128 J/g·°C)، فهو يحتاج إلى أقل كمية حرارة لرفع درجة حرارة 1 g منه 1°C، لذا ترتفع درجة حرارته أسرع.', '["حرارة الماغنسيوم النوعية (1.023) أكبر بكثير من حرارة الرصاص، فترتفع درجة حرارته أبطأ.","حرارة الكالسيوم النوعية (0.647) أكبر من حرارة الرصاص (0.128)، فترتفع درجة حرارته أبطأ منه.","البريليوم صاحب أكبر حرارة نوعية بين الفلزات الأربعة، فهو الأبطأ في ارتفاع درجة حرارته لا الأسرع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-03T20:51:23.856Z"}'::jsonb),
('mcq', 3, 1, 'عند تساوي الكتلة والحرارة الممتصة يكون الارتفاع في درجة الحرارة أكبر كلما صغرت الحرارة النوعية. ترتيب الحرارة النوعية تصاعديًّا: الذهب 0.129 < الفضة 0.235 < الحديد 0.449 < الألومنيوم 0.897، إذن الترتيب من الأعلى ارتفاعًا: الذهب ← الفضة ← الحديد ← الألومنيوم.', '["هذا الترتيب معكوس؛ رتّب الطالب الفلزات من الحرارة النوعية الأكبر إلى الأصغر، فجعل الأبطأ تسخنًا أولًا.","","قدّم الطالب الفضة على الذهب، مع أن حرارة الذهب النوعية (0.129) أصغر من حرارة الفضة (0.235)، فالذهب يسخن أكثر.","هذا ترتيب عشوائي لا يتبع قيم الحرارة النوعية؛ فالألومنيوم أكبرها حرارة نوعية فيجب أن يكون الأخير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-03T20:51:23.857Z"}'::jsonb),
('mcq', 4, 0, 'الأبطأ ارتفاعًا في درجة الحرارة هو الأكبر حرارة نوعية، والأسرع هو الأصغر حرارة نوعية: الماء 4.184 ثم الإيثانول 2.44 ثم الجرانيت 0.803 ثم الإسترانشيوم 0.301.', '["","هذا ترتيب من الأسرع إلى الأبطأ، أي عكس المطلوب في السؤال.","قدّم الطالب الإيثانول على الماء، مع أن حرارة الماء النوعية أكبر فهو الأبطأ.","رتّب الطالب الصلبين قبل السائلين، مع أن الجرانيت والإسترانشيوم أصغر حرارة نوعية فهما الأسرع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-03T20:51:23.857Z"}'::jsonb),
('mcq', 5, 2, 'عند تساوي q و m يتناسب ΔT عكسيًّا مع c: ΔT(أسمنت) ÷ ΔT(ماء) = 4.184 ÷ 0.84 ≈ 5؛ أي ترتفع درجة حرارة الأسمنت نحو خمس مرات قدر ارتفاع درجة حرارة الماء.', '["قلب الطالب النسبة (0.84 ÷ 4.184 ≈ 0.2)، وهذه نسبة ارتفاع درجة حرارة الماء إلى الأسمنت.","ظن الطالب أن تساوي الحرارة الممتصة يعني تساوي الارتفاع في درجة الحرارة، متجاهلًا اختلاف الحرارة النوعية.","","طرح الطالب القيمتين (4.184 − 0.84 = 3.3) بدل قسمة إحداهما على الأخرى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-03T20:51:23.857Z"}'::jsonb),
('mcq', 6, 3, 'الكتل غير متساوية، فيجب المقارنة بحاصل الضرب c × m: الذهب 1.29 J/°C، الفضة 2.35 J/°C، الألومنيوم 4.49 J/°C، الحديد 0.898 J/°C. أصغر حاصل ضرب للحديد، فارتفاع درجة حرارته هو الأكبر (ΔT = 50.0 ÷ 0.898 ≈ 55.7°C مقابل 38.8°C للذهب).', '["اعتمد الطالب على الحرارة النوعية وحدها، مع أن الكتل مختلفة؛ فحاصل c × m للذهب (1.29) أكبر من حاصله للحديد (0.898).","حاصل c × m للفضة 2.35 J/°C، وهو أكبر من حاصل الحديد، فترتفع درجة حرارتها أقل (≈ 21.3°C).","حاصل c × m للألومنيوم 4.49 J/°C هو الأكبر، فارتفاع درجة حرارته هو الأقل (≈ 11.1°C).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-03T20:51:23.858Z"}'::jsonb),
('mcq', 7, 0, 'عند تساوي الكتلة والحرارة يتناسب الارتفاع في درجة الحرارة عكسيًّا مع الحرارة النوعية؛ فأقل ارتفاع يعني أكبر حرارة نوعية: C (6°C) ثم A (12°C) ثم D (23°C) ثم B (45°C).', '["","رتّب الطالب الفلزات وفق الارتفاع في درجة الحرارة من الأكبر إلى الأصغر، فعكس العلاقة؛ فالارتفاع الأكبر يعني حرارة نوعية أصغر.","قدّم الطالب A على C، مع أن ارتفاع C (6°C) أقل، فحرارتها النوعية أكبر.","قدّم الطالب D على A، مع أن ارتفاع A (12°C) أقل من ارتفاع D (23°C)، فحرارة A النوعية أكبر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-03T20:51:23.858Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الترتيب من الأسرع إلى الأبطأ: الرصاص ← الحديد ← الماغنسيوم ← البريليوم. التفسير: من العلاقة q = c × m × ΔT يكون ΔT = q ÷ (c × m)، فعند تساوي الكتلة وكمية الحرارة يكون الارتفاع في درجة الحرارة أكبر كلما صغرت الحرارة النوعية؛ فالرصاص أصغرها حرارة نوعية فهو الأسرع، والبريليوم أكبرها فهو الأبطأ.', '["الترتيب الصحيح: الرصاص، الحديد، الماغنسيوم، البريليوم","العلاقة العكسية بين الحرارة النوعية والارتفاع في درجة الحرارة عند تساوي q و m","الاستناد إلى العلاقة q = c × m × ΔT"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب الصحيح","marks":2},{"element":"التفسير بالعلاقة العكسية","marks":1}]'::jsonb, '[{"level":"3","description":"ترتيب صحيح كامل مع تفسير صحيح"},{"level":"2","description":"ترتيب صحيح دون تفسير، أو تفسير صحيح مع خطأ في موضع واحد من الترتيب"},{"level":"1","description":"تفسير صحيح فقط، أو ترتيب معكوس كاملًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الترتيب من الحرارة النوعية الأكبر إلى الأصغر بوصفه الأسرع","إغفال شرط تساوي الكتل وكميات الحرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-03T20:51:23.859Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الحرارة النوعية للأسمنت (0.84 J/g·°C) أصغر بكثير من الحرارة النوعية للماء (4.184 J/g·°C)، أي إن الأسمنت يحتاج إلى كمية أقل من الحرارة لرفع درجة حرارة 1 g منه 1°C، فعند امتصاص الكمية نفسها من طاقة الشمس ترتفع درجة حرارته أكثر. ولكتلتين متساويتين تمتصان الحرارة نفسها: ΔT(أسمنت) ÷ ΔT(ماء) = c(ماء) ÷ c(أسمنت) = 4.184 ÷ 0.84 ≈ 5، أي ترتفع درجة حرارة الأسمنت نحو خمس مرات قدر ارتفاع درجة حرارة الماء.', '["الحرارة النوعية للأسمنت أصغر من الحرارة النوعية للماء","المادة ذات الحرارة النوعية الأصغر ترتفع درجة حرارتها أكثر عند امتصاص الحرارة نفسها","حساب النسبة 4.184 ÷ 0.84 ≈ 5"]'::jsonb, '["عند تساوي q و m: ΔT ∝ 1 ÷ c","ΔT(أسمنت) ÷ ΔT(ماء) = c(ماء) ÷ c(أسمنت) = 4.184 ÷ 0.84 ≈ 5.0"]'::jsonb, '[{"element":"مقارنة الحرارتين النوعيتين","marks":1},{"element":"التفسير بالعلاقة العكسية","marks":1},{"element":"حساب النسبة","marks":2}]'::jsonb, '[{"level":"4","description":"تفسير صحيح ونسبة صحيحة (≈ 5) بخطوات واضحة"},{"level":"3","description":"تفسير صحيح ونسبة صحيحة دون خطوات، أو خطأ بسيط في الحساب"},{"level":"2","description":"تفسير صحيح دون حساب، أو حساب صحيح دون تفسير"},{"level":"1","description":"مقارنة صحيحة للحرارتين النوعيتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قلب النسبة فتكون 0.2","طرح الحرارتين النوعيتين بدل قسمتهما","تفسير السخونة بلون الأسمنت دون ذكر الحرارة النوعية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-03T20:51:23.859Z"}'::jsonb),
('essay', 3, null::int, null, null, 'ΔT = q ÷ (c × m): الذهب 100 J ÷ (0.129 × 10.0) = 77.5°C؛ الفضة 100 J ÷ (0.235 × 10.0) = 42.6°C؛ الحديد 100 J ÷ (0.449 × 10.0) = 22.3°C؛ الألومنيوم 100 J ÷ (0.897 × 10.0) = 11.1°C. الترتيب من الأعلى إلى الأقل: الذهب ← الفضة ← الحديد ← الألومنيوم. ويؤكد الحساب أنه عند تساوي الكتلة وكمية الحرارة يزداد الارتفاع في درجة الحرارة كلما صغرت الحرارة النوعية؛ فالذهب أصغرها حرارة نوعية وارتفعت درجة حرارته أكثر، والألومنيوم أكبرها وارتفعت درجة حرارته أقل.', '["ΔT للذهب = 77.5°C","ΔT للفضة = 42.6°C","ΔT للحديد = 22.3°C","ΔT للألومنيوم = 11.1°C","الترتيب: الذهب، الفضة، الحديد، الألومنيوم","بيان العلاقة العكسية بين الحرارة النوعية والارتفاع في درجة الحرارة"]'::jsonb, '["ΔT = q ÷ (c × m)","الذهب: 100 J ÷ (0.129 J/g·°C × 10.0 g) = 77.5°C","الفضة: 100 J ÷ (0.235 J/g·°C × 10.0 g) = 42.6°C","الحديد: 100 J ÷ (0.449 J/g·°C × 10.0 g) = 22.3°C","الألومنيوم: 100 J ÷ (0.897 J/g·°C × 10.0 g) = 11.1°C"]'::jsonb, '[{"element":"الحسابات الأربعة (نصف درجة لكل حساب)","marks":2},{"element":"الترتيب الصحيح","marks":1},{"element":"بيان العلاقة","marks":1}]'::jsonb, '[{"level":"4","description":"حسابات صحيحة كلها وترتيب صحيح وبيان صحيح للعلاقة"},{"level":"3","description":"خطأ في حساب واحد مع ترتيب وبيان صحيحين"},{"level":"2","description":"حسابات صحيحة أو ترتيب صحيح مع نقص في البقية"},{"level":"1","description":"ترتيب صحيح دون حسابات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب q في c بدل القسمة","عكس الترتيب","نسيان الكتلة في المقام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-03T20:51:23.860Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C1-L1-O12') and x.type = v.type and x.number = v.number
