insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C1-L1-O13'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يُستغل الماء أحيانًا لأخذ الطاقة من الشمس ثم تدويره في البيوت لتدفئتها. ما خاصية الماء التي تجعله مناسبًا لذلك؟', null, null, '["كثافته المنخفضة مقارنة بالفلزات","حرارته النوعية العالية","درجة غليانه المنخفضة","قدرته على توصيل الكهرباء"]'::jsonb, 'تذكر', 'تذكر سبب', 'سهل', 'الكتاب ص 18 — الطاقة الشمسية'),
('mcq', 2, 'ما وظيفة الخلايا الكهروضوئية؟', null, null, '["تحويل الإشعاع الشمسي مباشرة إلى كهرباء","تحويل الطاقة الكهربائية إلى ضوء","تسخين الماء بأشعة الشمس لتدفئة البيوت","تخزين الحرارة في الصخور لاستعمالها ليلًا"]'::jsonb, 'تذكر', 'تذكر وظيفة', 'سهل', 'الكتاب ص 18 — الطاقة الشمسية (الخلايا الكهروضوئية)'),
('mcq', 3, 'تزوّد الخلايا الكهروضوئية رواد الفضاء بالطاقة، لكنها لا تُستعمل لتوفير الطاقة اللازمة للاحتياجات العادية. ما سبب ذلك؟', null, null, '["لأنها لا تعمل إلا خارج الغلاف الجوي للأرض","لأنها تنتج كميات كبيرة من ثاني أكسيد الكربون","لأن تكلفة إنتاج الكهرباء بها مرتفعة مقارنة بتكلفة حرق الفحم أو البترول","لأنها تحول الإشعاع الشمسي إلى حرارة فقط لا إلى كهرباء"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 18 — الطاقة الشمسية (الخلايا الكهروضوئية)'),
('mcq', 4, 'أدت عدة عوامل إلى تأخير تطوير التقنيات الشمسية، مما جعل من الضروري ابتكار طرائق فعالة لتخزين الطاقة. ما هذه العوامل؟', null, null, '["ارتفاع درجة حرارة الشمس وزيادة الإشعاع الساقط على الأرض","ندرة المواد اللازمة لتسخين الماء بأشعة الشمس","أن أشعة الشمس تنتج ثاني أكسيد الكربون عند استعمالها","أن الشمس تسطع فترة محددة كل يوم، وأن تراكم الغيوم يخفف أشعتها الساقطة"]'::jsonb, 'فهم', 'تحديد عوامل', 'صعب', 'الكتاب ص 18 — الطاقة الشمسية'),
('mcq', 5, 'مُنح البروفيسور مايكل جراتزل جائزة الملك فيصل فرع العلوم عام 1436هـ في مجال الكيمياء. مِمَّ تُصنع الخلايا المعروفة عالميًّا بخلايا جراتزل؟', null, null, '["من أفلام ثاني أكسيد التيتانيوم النانوية المغطاة بأصباغ جزيئية","من صفائح الرصاص المغمورة في محلول حمضي","من ألواح الأسمنت الداكنة الممتصة لأشعة الشمس","من خزانات ماء معزولة تختزن حرارة الشمس"]'::jsonb, 'تذكر', 'تذكر معلومة', 'متوسط', 'الكتاب ص 18 — جائزة الملك فيصل (مايكل جراتزل)'),
('mcq', 6, 'ما الجهة الوطنية الرائدة في مجالات البحوث التطبيقية في المملكة العربية السعودية، والتي برزت جهودها في مجال الطاقة؟', null, null, '["جائزة الملك فيصل العالمية","مدينة الملك عبدالعزيز للعلوم والتقنية","وزارة التعليم في المملكة","منظمة رؤية المملكة 2030"]'::jsonb, 'تذكر', 'تذكر معلومة', 'متوسط', 'الكتاب ص 18 — مدينة الملك عبدالعزيز للعلوم والتقنية'),
('mcq', 7, 'تعمل مدرستان في الرياض بالطاقة الشمسية لإنتاج الطاقة الكهربائية. بأي أهداف رؤية المملكة 2030 يرتبط هذا المشروع ارتباطًا مباشرًا؟', null, null, '["زيادة صادرات البترول الخام إلى الخارج","زيادة استعمال الفحم في توليد الكهرباء","زيادة مساهمة مصادر الطاقة المتجددة في مزيج الطاقة","خفض تكلفة حرق الوقود في محطات التوليد"]'::jsonb, 'فهم', 'ربط بأهداف وطنية', 'صعب', 'الكتاب ص 18 — الربط مع رؤية 2030، الشكل 1-3'),
('essay', 1, 'صف استعمالين للطاقة الشمسية، واذكر فائدة بيئية واحدة لاستعمالها بدلًا من أنواع الوقود الأخرى.', null, null, null, 'فهم', 'وصف', 'سهل', 'الكتاب ص 18 — الطاقة الشمسية'),
('essay', 2, 'على الرغم من أن أشعة الشمس يمكن أن تزود احتياجات العالم من الطاقة، فإن تطوير التقنيات الشمسية تأخر. وضّح العوامل التي أدت إلى ذلك، ولماذا كان لا بد من ابتكار طرائق فعالة لتخزين الطاقة، ولماذا لا تُستعمل الخلايا الكهروضوئية حاليًّا لتلبية الاحتياجات العادية.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 18 — الطاقة الشمسية'),
('essay', 3, 'صف ثلاثة من جهود المملكة العربية السعودية في مجال الطاقة الشمسية والطاقة المتجددة، ثم قوّم أهمية هذه الجهود في ضوء العوائق التي تواجه التقنيات الشمسية.', null, null, null, 'تقويم', 'وصف وتقويم', 'صعب', 'الكتاب ص 18 — الطاقة الشمسية، جائزة الملك فيصل، مدينة الملك عبدالعزيز للعلوم والتقنية، رؤية 2030')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
