from (values
('mcq', 1, 1, 'يُستغل الماء لأخذ الطاقة من الشمس بسبب حرارته النوعية العالية؛ فهو يمتص كمية كبيرة من الحرارة ويختزنها، ثم يمكن تدويره لتدفئة البيوت.', '["الكثافة لا تحدد قدرة المادة على اختزان الحرارة؛ والخاصية المقصودة هي الحرارة النوعية.","","درجة غليان الماء ليست منخفضة، ولا علاقة لها باختزان طاقة الشمس للتدفئة.","تدفئة البيوت بالماء المسخن تعتمد على اختزانه الحرارة لا على توصيله الكهرباء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-03T20:51:23.861Z"}'::jsonb),
('mcq', 2, 0, 'الخلايا الكهروضوئية تحول الإشعاع الشمسي مباشرة إلى كهرباء.', '["","هذا عكس وظيفة الخلايا الكهروضوئية؛ فهي تنتج الكهرباء من الضوء ولا تستهلكها لإنتاجه.","هذا وصف لاستعمال الماء في أخذ الطاقة من الشمس، لا لعمل الخلايا الكهروضوئية.","الخلايا الكهروضوئية لا تخزن الحرارة؛ بل تحول الإشعاع الشمسي إلى كهرباء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-03T20:51:23.861Z"}'::jsonb),
('mcq', 3, 2, 'لا تُستعمل الخلايا الكهروضوئية للاحتياجات العادية لأن تكلفة إنتاج الكهرباء بها مرتفعة مقارنة بتكلفة حرق الفحم أو البترول.', '["الخلايا الكهروضوئية تعمل على سطح الأرض أيضًا، ومنها ما يشغّل مدارس في الرياض.","استعمال الطاقة الشمسية يقلل استعمال أنواع الوقود التي تنتج ثاني أكسيد الكربون، فهي لا تنتجه.","","الخلايا الكهروضوئية تحول الإشعاع الشمسي مباشرة إلى كهرباء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:51:23.862Z"}'::jsonb),
('mcq', 4, 3, 'من العوامل التي أخرت تطوير التقنيات الشمسية أن الشمس تسطع فترة محددة كل يوم، وأن تراكم الغيوم فوق بعض الأماكن يخفف كمية أشعة الشمس الساقطة عليها؛ ولذلك لزم ابتكار طرائق فعالة لتخزين الطاقة.', '["زيادة الإشعاع الساقط ليست عائقًا؛ فالعائق تغيّر كمية الأشعة وعدم توافرها في كل الأوقات.","الماء متوافر، والعائق المذكور هو تغيّر سطوع الشمس لا ندرة المواد.","أشعة الشمس لا تنتج ثاني أكسيد الكربون؛ بل إن استعمالها يقلل حرق الوقود المنتج له.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-03T20:51:23.862Z"}'::jsonb),
('mcq', 5, 0, 'خلايا جراتزل أجهزة طُوّرت من أفلام ثاني أكسيد التيتانيوم النانوية المغطاة بأصباغ جزيئية، وتُستعمل في تحويل الطاقة الشمسية.', '["","صفائح الرصاص في محلول حمضي تصف بطارية تخزين، لا خلايا جراتزل الشمسية.","الأسمنت يسخن تحت الشمس بسبب حرارته النوعية المنخفضة، لكنه لا يحول الطاقة الشمسية إلى كهرباء.","خزانات الماء تختزن الحرارة لتدفئة البيوت، وليست هي خلايا جراتزل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-03T20:51:23.863Z"}'::jsonb),
('mcq', 6, 1, 'تُعد مدينة الملك عبدالعزيز للعلوم والتقنية (kacst) الجهة الوطنية الرائدة في مجالات البحوث التطبيقية، ومن المجالات التي برزت فيها جهودها مجال الطاقة.', '["جائزة الملك فيصل تكرّم العلماء المتميزين، مثل مايكل جراتزل، وليست جهة بحثية تطبيقية.","","وزارة التعليم ليست الجهة الوطنية المسؤولة عن البحوث التطبيقية في الطاقة.","رؤية 2030 خطة وطنية تتضمن أهدافًا مثل زيادة مساهمة الطاقة المتجددة، وليست جهة بحثية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:51:23.863Z"}'::jsonb),
('mcq', 7, 2, 'من أهداف رؤية 2030 زيادة مساهمة مصادر الطاقة المتجددة في مزيج الطاقة، وتشغيل المدرستين بالطاقة الشمسية تمهيد لخطة الطاقة الشمسية.', '["تشغيل المدارس بالطاقة الشمسية لا يتعلق بتصدير البترول، بل بالتوسع في الطاقة المتجددة.","الفحم وقود أحفوري ينتج ثاني أكسيد الكربون، والطاقة الشمسية بديل عنه لا وسيلة لزيادته.","","المشروع يستبدل الطاقة الشمسية بحرق الوقود، ولا يهدف إلى تحسين تكلفة حرقه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-03T20:51:23.863Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الاستعمال الأول: تسخين الماء بأشعة الشمس، إذ يُستغل الماء لأخذ الطاقة من الشمس بسبب حرارته النوعية العالية، ثم يُدوَّر في البيوت والأماكن الأخرى لتدفئتها. الاستعمال الثاني: الخلايا الكهروضوئية التي تحول الإشعاع الشمسي مباشرة إلى كهرباء، وتزود رواد الفضاء بالطاقة، وتُشغَّل بها مبانٍ مثل مدرستين في الرياض. الفائدة البيئية: استعمال الطاقة الشمسية يقلل استعمال أنواع الوقود التي تنتج ثاني أكسيد الكربون.', '["تسخين الماء لتدفئة البيوت بسبب حرارته النوعية العالية","الخلايا الكهروضوئية تحول الإشعاع الشمسي مباشرة إلى كهرباء","تقليل استعمال الوقود المنتج لثاني أكسيد الكربون"]'::jsonb, '[]'::jsonb, '[{"element":"الاستعمال الأول بوصف صحيح","marks":1},{"element":"الاستعمال الثاني بوصف صحيح","marks":1},{"element":"الفائدة البيئية","marks":1}]'::jsonb, '[{"level":"3","description":"استعمالان موصوفان وصفًا صحيحًا مع فائدة بيئية صحيحة"},{"level":"2","description":"استعمالان صحيحان دون الفائدة، أو استعمال وفائدة"},{"level":"1","description":"استعمال واحد صحيح أو الفائدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الخلايا الكهروضوئية تسخن الماء","ذكر الاستعمال دون وصف كيفية عمله","القول إن الطاقة الشمسية تنتج ثاني أكسيد الكربون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-03T20:51:23.864Z"}'::jsonb),
('essay', 2, null::int, null, null, 'من العوامل التي أخرت تطوير التقنيات الشمسية أن الشمس تسطع فترة محددة كل يوم، وأن تراكم الغيوم فوق بعض الأماكن يخفف كمية أشعة الشمس الساقطة عليها. وبسبب هذا التغير في كمية الطاقة الواصلة كان لا بد من ابتكار طرائق فعالة لتخزين الطاقة لاستعمالها حين لا تتوافر أشعة الشمس. أما الخلايا الكهروضوئية فلا تُستعمل لتوفير الطاقة للاحتياجات العادية لأن تكلفة إنتاج الكهرباء بها مرتفعة مقارنة بتكلفة حرق الفحم أو البترول.', '["الشمس تسطع فترة محددة كل يوم","تراكم الغيوم يخفف الأشعة الساقطة","الحاجة إلى التخزين بسبب تغير كمية الأشعة المتوافرة","ارتفاع تكلفة إنتاج الكهرباء بالخلايا الكهروضوئية مقارنة بالفحم والبترول"]'::jsonb, '[]'::jsonb, '[{"element":"العاملان (سطوع محدد، الغيوم)","marks":2},{"element":"تفسير الحاجة إلى التخزين","marks":1},{"element":"سبب عدم استعمال الخلايا الكهروضوئية","marks":1}]'::jsonb, '[{"level":"4","description":"العاملان وتفسير التخزين وسبب التكلفة كلها صحيحة"},{"level":"3","description":"ثلاثة عناصر صحيحة"},{"level":"2","description":"عنصران صحيحان"},{"level":"1","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الخلايا الكهروضوئية لا تعمل على الأرض","إغفال الربط بين تغير الأشعة والحاجة إلى التخزين","ذكر أسباب غير صحيحة مثل خطورة أشعة الشمس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-03T20:51:23.864Z"}'::jsonb),
('essay', 3, null::int, null, null, 'من جهود المملكة: (1) مدينة الملك عبدالعزيز للعلوم والتقنية (kacst) الجهة الوطنية الرائدة في البحوث التطبيقية، وقد برزت جهودها في مجال الطاقة. (2) رؤية المملكة 2030 التي من أهدافها زيادة مساهمة مصادر الطاقة المتجددة في مزيج الطاقة، ومن تطبيقاتها تشغيل مدرستين في الرياض بالطاقة الشمسية لإنتاج الكهرباء تمهيدًا لخطة الطاقة الشمسية. (3) تكريم العلماء عبر جائزة الملك فيصل، ومنها منح مايكل جراتزل الجائزة عام 1436هـ لتطويره أنظمة ضوئية وكهروكيميائية لتحويل الطاقة الشمسية (خلايا جراتزل من أفلام ثاني أكسيد التيتانيوم النانوية المغطاة بأصباغ جزيئية). التقويم: هذه الجهود مهمة لأن التقنيات الشمسية تواجه عوائق مثل محدودية ساعات السطوع والغيوم والحاجة إلى التخزين وارتفاع تكلفة الخلايا الكهروضوئية مقارنة بالفحم والبترول؛ والبحث التطبيقي وتشجيع العلماء والمشروعات التجريبية تسهم في خفض التكلفة وتطوير طرائق التخزين، كما تقلل الاعتماد على الوقود المنتج لثاني أكسيد الكربون.', '["مدينة الملك عبدالعزيز للعلوم والتقنية ودورها في البحوث التطبيقية في الطاقة","رؤية 2030 وهدف زيادة مساهمة الطاقة المتجددة، ومثال المدرستين في الرياض","جائزة الملك فيصل لمايكل جراتزل 1436هـ وخلاياه","تقويم مدعوم بربط الجهود بالعوائق (التكلفة، التخزين، محدودية الأشعة) أو بالفائدة البيئية"]'::jsonb, '[]'::jsonb, '[{"element":"الجهد الأول","marks":1},{"element":"الجهد الثاني","marks":1},{"element":"الجهد الثالث","marks":1},{"element":"التقويم المدعوم بأسباب","marks":2}]'::jsonb, '[{"level":"5","description":"ثلاثة جهود موصوفة بدقة مع تقويم مدعوم بربط واضح بالعوائق"},{"level":"4","description":"ثلاثة جهود صحيحة مع تقويم مختصر"},{"level":"3","description":"جهدان صحيحان مع تقويم، أو ثلاثة جهود دون تقويم"},{"level":"2","description":"جهدان صحيحان دون تقويم، أو جهد واحد مع تقويم"},{"level":"1","description":"جهد واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين جائزة الملك فيصل ومدينة الملك عبدالعزيز للعلوم والتقنية","تقويم عام دون ربطه بعوائق التقنيات الشمسية","نسبة خلايا جراتزل إلى السيليكون بدل ثاني أكسيد التيتانيوم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:51:23.864Z"}'::jsonb)
