('mcq', 5, 'ما فرع الكيمياء الذي يدرس كمية الحرارة المنطلقة من الكمّادة الساخنة عند تأكسد الحديد فيها؟', null, null, '["الكيمياء النووية","الكيمياء الحرارية","الكيمياء العضوية","الكيمياء الحيوية"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'سهل', 'الكتاب ص 21 — الطاقة الكيميائية والكون (تعريف الكيمياء الحرارية)'),
('mcq', 6, 'عندما يغلي ماء في إناء مفتوح دون حدوث تفاعل كيميائي، فإن دراسة الحرارة الممتصة في هذه العملية:', null, null, '["تدخل في الكيمياء الحرارية؛ لأنها تغير في الحالة الفيزيائية يرافقه امتصاص حرارة","لا تدخل في الكيمياء الحرارية؛ لأنها لا تتضمن تفاعلًا كيميائيًّا","تدخل في الكيمياء الحرارية؛ لأن الغليان تفاعل كيميائي يكوّن مادة جديدة","لا تدخل في الكيمياء الحرارية؛ لأن الغليان لا يرافقه انتقال للحرارة"]'::jsonb, 'فهم', 'تطبيق تعريف مع تعليل', 'متوسط', 'الكتاب ص 21 — الطاقة الكيميائية والكون (تعريف الكيمياء الحرارية)'),
('mcq', 7, 'قاس طالب الحرارة المنطلقة من احتراق الميثان، ثم قاس الحرارة اللازمة لصهر كمية من الجليد. أيّ العبارات الآتية صحيحة؟', null, null, '["دراسة الاحتراق وحدها من مجال الكيمياء الحرارية","دراسة الانصهار وحدها من مجال الكيمياء الحرارية","لا تنتمي أيّ من الدراستين إلى الكيمياء الحرارية","كلتا الدراستين من مجال الكيمياء الحرارية"]'::jsonb, 'فهم', 'تصنيف حالات', 'صعب', 'الكتاب ص 21 — الطاقة الكيميائية والكون (تعريف الكيمياء الحرارية)'),
('essay', 1, 'عرّف الكيمياء الحرارية، ثم اذكر مثالين مما تدرسه: أحدهما تفاعل كيميائي، والآخر تغير في الحالة الفيزيائية، مع بيان هل الحرارة في كل مثال منطلقة أم ممتصة.', null, null, null, 'فهم', 'تعريف وتمثيل', 'متوسط', 'الكتاب ص 21 — الطاقة الكيميائية والكون (تعريف الكيمياء الحرارية)'),
('essay', 2, 'يرى طالب أن الكيمياء الحرارية تدرس التفاعلات الكيميائية فقط، ولا علاقة لها بتبخر الماء لأنه تغير فيزيائي. قوّم رأي الطالب، مستشهدًا بتعريف الكيمياء الحرارية، ومبيّنًا لماذا يُعدّ قياس الحرارة اللازمة لتبخير الماء من موضوعاتها.', null, null, null, 'تقويم', 'تقويم رأي', 'صعب', 'الكتاب ص 21 — الطاقة الكيميائية والكون (تعريف الكيمياء الحرارية)'),
('essay', 3, 'وضّح لماذا يُعدّ تفاعل الكمّادة الساخنة من موضوعات الكيمياء الحرارية، واكتب المعادلة الكيميائية الحرارية له، ثم اذكر ثلاثة أشياء يهتم الكيميائي الحراري بمعرفتها عند دراسته.', null, null, null, 'فهم', 'توضيح بمثال وكتابة معادلة', 'صعب', 'الكتاب ص 21، 23 — الكيمياء الحرارية والكمّادة الساخنة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C1-L2-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الكيمياء الحرارية هي دراسة تغيرات الحرارة التي ترافق التفاعلات الكيميائية وتغيرات الحالة الفيزيائية؛ فهي تشمل التفاعل الكيميائي وتغير الحالة معًا.', '["هذا مجال سرعة التفاعلات الكيميائية، وهو لا يدرس تغيرات الحرارة المرافقة للتفاعلات.","","هذا تعريف المسعر، وهو أداة تستعملها الكيمياء الحرارية وليس العلم نفسه.","هذا تعريف الحرارة النوعية، وهي خاصية للمادة وليست تعريفًا لفرع من الكيمياء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-03T20:51:23.865Z"}'::jsonb),
('mcq', 2, 3, 'يرافق كل تفاعل كيميائي وكل تغير في الحالة الفيزيائية إطلاق حرارة أو امتصاصها، وهذا ما تدرسه الكيمياء الحرارية.', '["بعض التفاعلات والتغيرات تمتص الحرارة، مثل إذابة NH₄NO₃ في الكمّادة الباردة؛ فالإطلاق ليس الحالة الوحيدة.","بعض التفاعلات تطلق الحرارة، مثل تأكسد الحديد في الكمّادة الساخنة؛ فالامتصاص ليس الحالة الوحيدة.","كل تفاعل كيميائي وكل تغير في الحالة الفيزيائية يرافقه انتقال للحرارة، ولذلك وُجد علم الكيمياء الحرارية لدراسته.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-03T20:51:23.865Z"}'::jsonb),
('mcq', 3, 0, 'التجمد تغير في الحالة الفيزيائية يرافقه إطلاق حرارة، والكيمياء الحرارية تدرس تغيرات الحرارة المرافقة للتفاعلات الكيميائية وتغيرات الحالة الفيزيائية؛ لذا فالحرارة المنطلقة عند تجمد الماء من موضوعاتها.', '["","هذه دراسة لسرعة التفاعل، لا لكمية الحرارة المرافقة له.","هذا من موضوعات تركيب الذرة، ولا علاقة له بتغيرات الحرارة.","ترتيب العناصر موضوع في الجدول الدوري، ولا يتضمن تغيرًا في الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-03T20:51:23.866Z"}'::jsonb),
('mcq', 4, 2, 'تدرس الكيمياء الحرارية تغيرات الحرارة التي ترافق التفاعلات الكيميائية وتغيرات الحالة الفيزيائية؛ فالنوعان هما التفاعلات الكيميائية وتغيرات الحالة الفيزيائية.', '["التحولات النووية ليست ما يحدده تعريف الكيمياء الحرارية، فهو يذكر التفاعلات الكيميائية وتغيرات الحالة الفيزيائية.","الكيمياء الحرارية تدرس تغيرات الحرارة، لا تغيرات الكتلة أو الحجم.","","قصر المجال على نوعين من التفاعلات خطأ؛ فالتعريف يشمل التفاعلات الكيميائية كلها وتغيرات الحالة الفيزيائية أيضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-03T20:51:23.866Z"}'::jsonb),
('mcq', 5, 1, 'دراسة الحرارة المنطلقة من تفاعل كيميائي، مثل 4Fe(s) + 3O₂(g) → 2Fe₂O₃(s) + 1625 kJ في الكمّادة الساخنة، من مجال الكيمياء الحرارية.', '["الكيمياء النووية تدرس التغيرات في نوى الذرات، وتأكسد الحديد تفاعل كيميائي لا يغير النوى.","","الكيمياء العضوية تدرس مركبات الكربون، ودراسة الحرارة المنطلقة من التفاعل ليست مجالها.","الكيمياء الحيوية تدرس العمليات الكيميائية في المخلوقات الحية، والكمّادة ليست منها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-03T20:51:23.866Z"}'::jsonb),
('mcq', 6, 0, 'الغليان تغير في الحالة الفيزيائية يرافقه امتصاص حرارة، والكيمياء الحرارية تدرس تغيرات الحرارة المرافقة للتفاعلات الكيميائية وتغيرات الحالة الفيزيائية؛ لذا تدخل دراسته فيها.', '["","الكيمياء الحرارية لا تقتصر على التفاعلات الكيميائية، بل تشمل تغيرات الحالة الفيزيائية أيضًا.","الغليان تغير فيزيائي، والماء يبقى ماءً؛ فالتعليل خاطئ وإن كانت النتيجة صحيحة.","الغليان يحتاج إلى امتصاص حرارة؛ فكل تغير في الحالة الفيزيائية يرافقه انتقال للحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-03T20:51:23.866Z"}'::jsonb),
('mcq', 7, 3, 'احتراق الميثان تفاعل كيميائي يطلق حرارة، وانصهار الجليد تغير في الحالة الفيزيائية يمتص حرارة، والكيمياء الحرارية تدرس تغيرات الحرارة في النوعين؛ إذن كلتا الدراستين من مجالها.', '["انصهار الجليد تغير في الحالة الفيزيائية يرافقه امتصاص حرارة، فهو أيضًا من مجالها.","احتراق الميثان تفاعل كيميائي يطلق حرارة، فهو أيضًا من مجالها.","كلتاهما تدرس تغيرًا في الحرارة يرافق تفاعلًا كيميائيًّا أو تغيرًا في الحالة الفيزيائية، وهذا هو مجال الكيمياء الحرارية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-03T20:51:23.866Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الكيمياء الحرارية: دراسة تغيرات الحرارة التي ترافق التفاعلات الكيميائية وتغيرات الحالة الفيزيائية. مثال التفاعل الكيميائي: تأكسد الحديد في الكمّادة الساخنة 4Fe(s) + 3O₂(g) → 2Fe₂O₃(s) + 1625 kJ، والحرارة فيه منطلقة. مثال تغير الحالة: انصهار الجليد، والحرارة فيه ممتصة (أو غليان الماء، والحرارة فيه ممتصة).', '["تعريف الكيمياء الحرارية بذكر تغيرات الحرارة","ذكر أنها ترافق التفاعلات الكيميائية وتغيرات الحالة الفيزيائية","مثال صحيح لتفاعل كيميائي مع نوع الحرارة","مثال صحيح لتغير في الحالة مع نوع الحرارة"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الكيمياء الحرارية كاملًا","marks":2},{"element":"مثال التفاعل الكيميائي مع بيان أن الحرارة منطلقة أو ممتصة","marks":1},{"element":"مثال تغير الحالة مع بيان أن الحرارة منطلقة أو ممتصة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل يذكر التفاعلات وتغيرات الحالة، ومثالان صحيحان مع نوع الحرارة في كل منهما"},{"level":"2–3 درجات","description":"تعريف صحيح مع نقص في أحد المثالين أو في بيان نوع الحرارة"},{"level":"1 درجة","description":"تعريف ناقص يذكر الحرارة دون التفاعلات أو تغيرات الحالة، أو مثال واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قصر التعريف على التفاعلات الكيميائية وإغفال تغيرات الحالة الفيزيائية","الخلط بين الكيمياء الحرارية والمسعر أو الحرارة النوعية","عدّ الانصهار تفاعلًا كيميائيًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-03T20:51:23.867Z"}'::jsonb),
('essay', 2, null::int, null, null, 'رأي الطالب غير صحيح. فالكيمياء الحرارية تدرس تغيرات الحرارة التي ترافق التفاعلات الكيميائية وتغيرات الحالة الفيزيائية معًا، ولا تقتصر على التفاعلات. وتبخر الماء تغير في الحالة الفيزيائية من سائل إلى غاز، يرافقه امتصاص حرارة من المحيط؛ لذا فقياس الحرارة اللازمة لتبخيره من موضوعات الكيمياء الحرارية، مع أنه لا يكوّن مادة جديدة.', '["الحكم بأن الرأي غير صحيح","الاستشهاد بالتعريف الذي يشمل تغيرات الحالة الفيزيائية","التبخر تغير في الحالة الفيزيائية","التبخر يرافقه امتصاص حرارة فيدخل في مجال الكيمياء الحرارية"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح على الرأي","marks":1},{"element":"الاستشهاد بالتعريف كاملًا","marks":1},{"element":"تصنيف التبخر تغيرًا في الحالة الفيزيائية","marks":1},{"element":"بيان أن التبخر يرافقه امتصاص حرارة فهو من موضوعاتها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تعريف كامل وتصنيف صحيح للتبخر وبيان امتصاصه للحرارة"},{"level":"2–3 درجات","description":"حكم صحيح مع نقص في التعريف أو في التعليل"},{"level":"1 درجة","description":"حكم صحيح دون تعليل مقبول"},{"level":"صفر","description":"تأييد رأي الطالب أو لا إجابة"}]'::jsonb, '["تأييد الطالب بحجة أن التبخر لا يكوّن مادة جديدة","القول إن التبخر يطلق حرارة","ذكر التعريف دون ربطه بالتبخر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-03T20:51:23.867Z"}'::jsonb),
('essay', 3, null::int, null, null, 'يُعدّ تفاعل الكمّادة الساخنة من موضوعات الكيمياء الحرارية لأنه تفاعل كيميائي يرافقه تغير في الحرارة (إطلاق حرارة)، والكيمياء الحرارية تدرس تغيرات الحرارة المرافقة للتفاعلات الكيميائية وتغيرات الحالة. المعادلة: 4Fe(s) + 3O₂(g) → 2Fe₂O₃(s)  ΔH_rxn = −1625 kJ (أو 4Fe(s) + 3O₂(g) → 2Fe₂O₃(s) + 1625 kJ). ويهتم الكيميائي الحراري بمعرفة: (1) هل الحرارة منطلقة أم ممتصة (التفاعل طارد للحرارة)، (2) مقدار الحرارة المنطلقة (1625 kJ لكل 4 mol من Fe)، (3) اتجاه انتقال الحرارة: من النظام (التفاعل) إلى المحيط (اليدين)، أو إشارة ΔH (سالبة).', '["التفاعل يرافقه تغير في الحرارة، وهذا مجال الكيمياء الحرارية","كتابة المعادلة الحرارية موزونة بالحالات وقيمة الحرارة","ثلاثة أمور يدرسها: نوع التغير، مقدار الحرارة، اتجاه الانتقال أو إشارة ΔH"]'::jsonb, '[]'::jsonb, '[{"element":"ربط التفاعل بتعريف الكيمياء الحرارية","marks":1},{"element":"المعادلة الحرارية صحيحة موزونة بالحالات وقيمة الحرارة","marks":2},{"element":"ثلاثة أمور صحيحة يدرسها الكيميائي الحراري (درجة لكل منها)","marks":3}]'::jsonb, '[{"level":"6 درجات","description":"ربط صحيح بالتعريف، ومعادلة صحيحة كاملة، وثلاثة أمور صحيحة"},{"level":"4–5 درجات","description":"ربط صحيح ومعادلة مع خطأ بسيط في الحالات أو الإشارة، أو أمران صحيحان فقط"},{"level":"2–3 درجات","description":"ربط صحيح دون معادلة صحيحة، أو معادلة دون ربط"},{"level":"1 درجة","description":"ذكر أن التفاعل يطلق حرارة دون تفصيل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة ΔH موجبة للكمّادة الساخنة","إغفال الحالات الفيزيائية في المعادلة","عدم موازنة المعادلة (Fe وO₂)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-03T20:51:23.867Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
