from (values
('mcq', 1, 'يتفاعل الحديد مع الأكسجين داخل كمّادة ساخنة يمسكها شخص بيديه. في أيّ اتجاه تنتقل الحرارة؟', null, null, '["من المحيط (اليدين) إلى النظام (التفاعل)","لا تنتقل حرارة؛ لأن الكمّادة مغلقة","من النظام (التفاعل) إلى المحيط (اليدين)","في الاتجاهين بالمقدار نفسه دون تغير"]'::jsonb, 'فهم', 'تحديد اتجاه انتقال الحرارة', 'سهل', 'الكتاب ص 22 — النظام والمحيط واتجاه انتقال الحرارة'),
('mcq', 2, 'عند خلط هيدروكسيد الباريوم مع بلورات ثيوسيانات الأمونيوم في كأس موضوعة على لوح مبلل بالماء، يتجمد الماء فيلتصق الكأس باللوح. ما سبب تجمد الماء؟', null, null, '["انتقال الحرارة من الماء واللوح (المحيط) إلى التفاعل (النظام)","انتقال الحرارة من التفاعل (النظام) إلى الماء واللوح (المحيط)","انتقال البرودة من التفاعل إلى الماء واللوح","تكوّن ماء جديد من التفاعل يتجمد عند درجة حرارة الغرفة"]'::jsonb, 'فهم', 'تفسير ملاحظة', 'متوسط', 'الكتاب ص 22 — النظام والمحيط واتجاه انتقال الحرارة'),
('mcq', 3, 'إشارة ΔH لتفاعل ما موجبة. أيّ الأوصاف الآتية لانتقال الحرارة صحيح؟', null, null, '["تنتقل الحرارة من النظام إلى المحيط، فترتفع درجة حرارة المحيط","تنتقل الحرارة من المحيط إلى النظام، فترتفع درجة حرارة المحيط","تنتقل الحرارة من النظام إلى المحيط، فتنخفض درجة حرارة المحيط","تنتقل الحرارة من المحيط إلى النظام، فتنخفض درجة حرارة المحيط"]'::jsonb, 'فهم', 'ربط إشارة ΔH باتجاه الانتقال', 'متوسط', 'الكتاب ص 22، 24 — اتجاه انتقال الحرارة وإشارة ΔH'),
('mcq', 4, 'يشعر شخص بالبرودة عند وضع كمّادة باردة على كاحله المصاب. ما سبب ذلك؟', null, null, '["إذابة NH₄NO₃ في الكمّادة تطلق الحرارة إلى الكاحل","إذابة NH₄NO₃ في الكمّادة تمتص الحرارة من الكاحل","الكاحل يمتص البرودة المنطلقة من NH₄NO₃","إذابة NH₄NO₃ لا يرافقها انتقال للحرارة"]'::jsonb, 'فهم', 'تفسير تطبيق حياتي', 'سهل', 'الكتاب ص 24 — الكمّادة الباردة'),
('mcq', 5, 'وُضع مقياس حرارة في ماء يحيط بأنبوب يحدث فيه تفاعل، فارتفعت قراءته من 25.0°C إلى 31.0°C. ماذا تستنتج؟', null, null, '["التفاعل ماص للحرارة، وانتقلت الحرارة من المحيط إلى النظام","التفاعل ماص للحرارة، وانتقلت الحرارة من النظام إلى المحيط","التفاعل طارد للحرارة، وانتقلت الحرارة من النظام إلى المحيط","التفاعل طارد للحرارة، وانتقلت الحرارة من المحيط إلى النظام"]'::jsonb, 'تطبيق', 'استنتاج من بيانات', 'متوسط', 'الكتاب ص 22 — النظام والمحيط واتجاه انتقال الحرارة'),
('mcq', 6, 'تُكتب معادلة إذابة نترات الأمونيوم كما يأتي: 27 kJ + NH₄NO₃(s) → NH₄⁺(aq) + NO₃⁻(aq). علامَ يدل موقع 27 kJ في المعادلة؟', null, null, '["انتقال 27 kJ من الحرارة من النظام إلى المحيط","أن المحتوى الحراري للنواتج أقل من المتفاعلات بمقدار 27 kJ","أن 27 kJ تلزم لبدء التفاعل ثم يطلق التفاعل حرارة","انتقال 27 kJ من الحرارة من المحيط إلى النظام"]'::jsonb, 'تحليل', 'تفسير معادلة حرارية', 'صعب', 'الكتاب ص 24 — الكمّادة الباردة'),
('mcq', 7, 'عُدّ جسمك نظامًا وأنت تقف تحت ماء دش دافئ، ثم وأنت تقفز في مسبح بارد. ما اتجاه انتقال الحرارة في الحالتين؟', null, null, '["من الماء إلى جسمك تحت الدش، ومن جسمك إلى الماء في المسبح","من جسمك إلى الماء تحت الدش، ومن الماء إلى جسمك في المسبح","من جسمك إلى الماء في الحالتين","من الماء إلى جسمك في الحالتين"]'::jsonb, 'تطبيق', 'تحديد اتجاه الانتقال في موقفين', 'متوسط', 'الكتاب ص 19، 22 — الربط مع الحياة، والنظام والمحيط'),
('essay', 1, 'قارن بين الكمّادة الساخنة والكمّادة الباردة من حيث: نوع العملية (طاردة أم ماصة للحرارة)، واتجاه انتقال الحرارة بين النظام والمحيط، وأثر ذلك في درجة حرارة الجلد.', null, null, null, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 21–24 — الكمّادتان الساخنة والباردة'),
('essay', 2, 'خُلط هيدروكسيد الباريوم مع بلورات ثيوسيانات الأمونيوم في كأس موضوعة على لوح خشبي مبلل بالماء، فتجمد الماء والتصق الكأس باللوح. (أ) حدد النظام والمحيط. (ب) حدد اتجاه انتقال الحرارة. (ج) صنّف التفاعل وحدد إشارة ΔH له. (د) فسّر تجمد الماء.', null, null, null, 'تحليل', 'تحليل موقف تجريبي', 'صعب', 'الكتاب ص 22 — النظام والمحيط واتجاه انتقال الحرارة'),
('essay', 3, 'أُجري تفاعلان في أنبوبين مغمورين في كأسين من الماء، درجة حرارة الماء في كل منهما 25.0°C. بعد التفاعل أصبحت درجة حرارة الماء في الكأس الأولى 31.0°C، وفي الثانية 19.0°C. حدد لكل تفاعل: اتجاه انتقال الحرارة، ونوعه، وإشارة ΔH، مع التعليل.', null, null, null, 'تحليل', 'استنتاج من بيانات وتعليل', 'صعب', 'الكتاب ص 22 — النظام والمحيط واتجاه انتقال الحرارة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
