from (values
('mcq', 1, 2, 'تفاعل الكمّادة الساخنة 4Fe(s) + 3O₂(g) → 2Fe₂O₃(s) + 1625 kJ طارد للحرارة؛ فتنتقل الحرارة من النظام (التفاعل) إلى المحيط (اليدين) فتدفأ اليدان.', '["هذا اتجاه الانتقال في التفاعل الماص للحرارة، أما تفاعل الكمّادة الساخنة فطارد للحرارة.","الكمّادة تدفئ اليدين، وهذا دليل على انتقال الحرارة منها إلى اليدين وإن كانت مغلقة.","","لو انتقلت الحرارة بالمقدار نفسه في الاتجاهين لما شعر الشخص بالدفء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-03T20:51:23.868Z"}'::jsonb),
('mcq', 2, 0, 'التفاعل ماص للحرارة؛ فتنتقل الحرارة من الماء واللوح (المحيط) إلى الكأس (النظام)، فتنخفض درجة حرارة الماء كثيرًا حتى يتجمد.', '["","لو انتقلت الحرارة إلى الماء لارتفعت درجة حرارته ولم يتجمد؛ وهذا يحدث في التفاعل الطارد.","البرودة ليست شيئًا ينتقل؛ الذي ينتقل هو الحرارة، وتنتقل هنا من الماء إلى التفاعل.","الماء لا يتجمد عند درجة حرارة الغرفة؛ وتجمده سببه فقد حرارته لصالح التفاعل الماص."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-03T20:51:23.869Z"}'::jsonb),
('mcq', 3, 3, 'ΔH الموجبة تعني أن التفاعل ماص للحرارة؛ فالنظام يكتسب الحرارة من المحيط، والمحيط يفقدها فتنخفض درجة حرارته.', '["هذا وصف التفاعل الطارد للحرارة الذي تكون فيه ΔH سالبة.","الاتجاه صحيح، لكن المحيط يفقد حرارة فتنخفض درجة حرارته ولا ترتفع.","ΔH الموجبة تعني امتصاص النظام للحرارة، ثم إن المحيط إذا اكتسب حرارة ترتفع درجة حرارته لا تنخفض.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-03T20:51:23.869Z"}'::jsonb),
('mcq', 4, 1, 'إذابة NH₄NO₃ عملية ماصة للحرارة: 27 kJ + NH₄NO₃(s) → NH₄⁺(aq) + NO₃⁻(aq)؛ فتنتقل الحرارة من الكاحل (المحيط) إلى الكمّادة (النظام)، فيبرد الكاحل.', '["لو أطلقت الحرارة إلى الكاحل لشعر الشخص بالدفء لا بالبرودة.","","البرودة لا تنتقل؛ الذي يحدث هو انتقال الحرارة من الكاحل إلى الكمّادة.","إذابة NH₄NO₃ عملية ماصة للحرارة (ΔH = +27 kJ)، فهي يرافقها انتقال للحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-03T20:51:23.869Z"}'::jsonb),
('mcq', 5, 2, 'الماء هو المحيط، وارتفاع درجة حرارته يعني أنه اكتسب حرارة من التفاعل (النظام)؛ إذن التفاعل طارد للحرارة، والحرارة انتقلت من النظام إلى المحيط.', '["لو امتص التفاعل الحرارة من الماء لانخفضت قراءة المقياس.","انتقال الحرارة من النظام إلى المحيط هو صفة التفاعل الطارد، لا الماص؛ فالعبارة متناقضة.","","التفاعل الطارد يطلق الحرارة إلى المحيط، ولا يكتسبها منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-03T20:51:23.869Z"}'::jsonb),
('mcq', 6, 3, 'كتابة الحرارة في جهة المتفاعلات تعني أن العملية ماصة للحرارة؛ فالنظام يمتص 27 kJ من المحيط، أي أن الحرارة تنتقل من المحيط إلى النظام.', '["الحرارة مكتوبة في جهة المتفاعلات، أي أنها تُمتص كالمتفاعل؛ فهي تدخل النظام ولا تخرج منه.","امتصاص الحرارة يجعل المحتوى الحراري للنواتج أكبر من المتفاعلات بمقدار 27 kJ، لا أقل.","المعادلة تبين أن العملية كلها تمتص 27 kJ، ولا تدل على إطلاق حرارة بعد بدئها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-03T20:51:23.870Z"}'::jsonb),
('mcq', 7, 0, 'تنتقل الحرارة من الجسم الأسخن إلى الأبرد: تحت الدش الدافئ يمتص جسمك (النظام) الحرارة من الماء (المحيط)، وفي المسبح البارد يفقد جسمك الحرارة إلى الماء.', '["","عكس الاتجاهين؛ فالحرارة تنتقل من الأسخن إلى الأبرد، وماء الدش أسخن من جسمك، وماء المسبح أبرد منه.","تحت الدش الماء أسخن من جسمك، فجسمك يكتسب الحرارة ولا يفقدها.","في المسبح البارد جسمك أسخن من الماء، فيفقد جسمك الحرارة ولا يكتسبها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-03T20:51:23.870Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الكمّادة الساخنة: التفاعل فيها 4Fe(s) + 3O₂(g) → 2Fe₂O₃(s) طارد للحرارة (ΔH = −1625 kJ)، تنتقل الحرارة من النظام (التفاعل) إلى المحيط (الجلد)، فترتفع درجة حرارة الجلد ويشعر بالدفء. الكمّادة الباردة: إذابة NH₄NO₃ فيها ماصة للحرارة (ΔH = +27 kJ)، تنتقل الحرارة من المحيط (الجلد) إلى النظام (الكمّادة)، فتنخفض درجة حرارة الجلد ويشعر بالبرودة.', '["الساخنة طاردة للحرارة","في الساخنة تنتقل الحرارة من النظام إلى المحيط فيدفأ الجلد","الباردة ماصة للحرارة","في الباردة تنتقل الحرارة من المحيط إلى النظام فيبرد الجلد"]'::jsonb, '[]'::jsonb, '[{"element":"نوع العملية في الكمّادة الساخنة","marks":1},{"element":"اتجاه الانتقال وأثره في الجلد للكمّادة الساخنة","marks":1},{"element":"نوع العملية في الكمّادة الباردة","marks":1},{"element":"اتجاه الانتقال وأثره في الجلد للكمّادة الباردة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة كاملة في النقاط الثلاث للكمّادتين"},{"level":"2–3 درجات","description":"مقارنة صحيحة لإحدى الكمّادتين كاملة مع نقص في الأخرى"},{"level":"1 درجة","description":"تحديد نوع العملية فقط دون اتجاه الانتقال"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكمّادة الباردة تطلق برودة إلى الجلد","عكس اتجاه انتقال الحرارة","عدّ الجلد نظامًا والكمّادة محيطًا دون تعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-03T20:51:23.871Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) النظام: خليط هيدروكسيد الباريوم وثيوسيانات الأمونيوم المتفاعل في الكأس؛ والمحيط: الكأس من الخارج والماء واللوح والهواء. (ب) تنتقل الحرارة من المحيط (الماء واللوح) إلى النظام (التفاعل). (ج) التفاعل ماص للحرارة، وإشارة ΔH موجبة. (د) يمتص التفاعل كمية كافية من الحرارة من الماء الموجود بين الكأس واللوح، فتنخفض درجة حرارة الماء حتى يتجمد، فيلتصق الكأس باللوح.', '["النظام هو خليط التفاعل","المحيط هو الماء واللوح والهواء","انتقال الحرارة من المحيط إلى النظام","التفاعل ماص وΔH موجبة","فقد الماء للحرارة يخفض درجة حرارته حتى يتجمد"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد النظام والمحيط","marks":2},{"element":"اتجاه انتقال الحرارة","marks":1},{"element":"تصنيف التفاعل وإشارة ΔH","marks":2},{"element":"تفسير تجمد الماء","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة صحيحة كاملة للأجزاء الأربعة"},{"level":"4–5 درجات","description":"خطأ أو نقص في جزء واحد"},{"level":"2–3 درجات","description":"إجابة صحيحة لجزأين فقط"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن البرودة تنتقل من التفاعل إلى الماء","إعطاء ΔH إشارة سالبة لأن درجة الحرارة انخفضت","عدّ الماء واللوح جزءًا من النظام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-03T20:51:23.871Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التفاعل الأول: ارتفعت درجة حرارة الماء (المحيط) بمقدار 6.0°C، إذن اكتسب الماء حرارة من التفاعل؛ فالحرارة انتقلت من النظام إلى المحيط، والتفاعل طارد للحرارة، وإشارة ΔH سالبة. التفاعل الثاني: انخفضت درجة حرارة الماء بمقدار 6.0°C، إذن فقد الماء حرارة لصالح التفاعل؛ فالحرارة انتقلت من المحيط إلى النظام، والتفاعل ماص للحرارة، وإشارة ΔH موجبة.', '["الأول: الحرارة من النظام إلى المحيط","الأول طارد وΔH سالبة","الثاني: الحرارة من المحيط إلى النظام","الثاني ماص وΔH موجبة","التعليل بتغير درجة حرارة الماء (المحيط)"]'::jsonb, '[]'::jsonb, '[{"element":"اتجاه الانتقال في التفاعل الأول","marks":1},{"element":"نوع التفاعل الأول وإشارة ΔH","marks":1},{"element":"اتجاه الانتقال في التفاعل الثاني","marks":1},{"element":"نوع التفاعل الثاني وإشارة ΔH","marks":1},{"element":"التعليل بتغير درجة حرارة المحيط","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد صحيح كامل للتفاعلين مع تعليل بتغير درجة حرارة الماء"},{"level":"3–4 درجات","description":"تحديد صحيح للتفاعلين دون تعليل، أو تعليل مع خطأ في عنصر واحد"},{"level":"1–2 درجة","description":"تحديد صحيح لتفاعل واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين درجة حرارة الماء ودرجة حرارة النظام","ربط ارتفاع درجة الحرارة بالتفاعل الماص","إعطاء ΔH إشارة موجبة للتفاعل الأول"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:51:23.871Z"}'::jsonb)
