('essay', 1, 'صف معنى النظام في الكيمياء الحرارية، واشرح العلاقة بين النظام والمحيط والكون.', null, null, null, 'فهم', 'وصف وشرح علاقة', 'سهل', 'الكتاب ص 22، 24 — النظام والمحيط والكون (س20)'),
('essay', 2, 'أعطِ مثالين لنظامين كيميائيين مختلفين: أحدهما يطلق الحرارة والآخر يمتصها، وحدد في كل منهما النظام والمحيط، ثم عرّف الكون من خلال هذين المثالين.', null, null, null, 'تطبيق', 'تمثيل وتحديد', 'صعب', 'الكتاب ص 22، 42 — النظام والمحيط والكون (س61)'),
('essay', 3, 'يسخّن طالب كأسًا من الماء على موقد غاز حتى يغلي. حدد النظام والمحيط واتجاه انتقال الحرارة في حالتين: (أ) العملية المدروسة احتراق غاز الموقد. (ب) العملية المدروسة غليان الماء. ثم بيّن لماذا تغيّر تحديد النظام بين الحالتين.', null, null, null, 'تحليل', 'تحديد ومقارنة وتعليل', 'صعب', 'الكتاب ص 22 — النظام والمحيط والكون')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
