from (values
('mcq', 1, 3, 'النظام جزء معين من الكون يحتوي على التفاعل أو العملية التي نريد دراستها، وكل ما عداه هو المحيط.', '["هذا تعريف المحيط، وهو كل ما في الكون غير النظام.","هذا وصف الكون، وهو النظام والمحيط معًا.","هذا وصف المسعر، وهو أداة قياس وليس النظام.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-03T20:51:23.872Z"}'::jsonb),
('mcq', 2, 1, 'يعرّف الكون بأنه النظام مع المحيط: الكون = النظام + المحيط.', '["الكون يشمل النظام والمحيط معًا، فهو مجموعهما لا الفرق بينهما.","","المحيط جزء من الكون، والجزء الآخر هو النظام.","النظام جزء معين من الكون فقط، ويحيط به المحيط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-03T20:51:23.873Z"}'::jsonb),
('mcq', 3, 2, 'النظام هو التفاعل بمواده المتفاعلة والناتجة داخل الكمّادة، وكل ما عداه هو المحيط؛ فالمحيط هنا يدا الشخص والهواء من حولهما، وإليه تنتقل الحرارة.', '["الحديد والأكسجين هما المتفاعلان، فهما جزء من النظام لا من المحيط.","Fe₂O₃ ناتج التفاعل، فهو جزء من النظام.","","هذا يجمع جزءًا من النظام مع جزء من المحيط، فهو أقرب إلى الكون لا إلى المحيط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-03T20:51:23.873Z"}'::jsonb),
('mcq', 4, 0, 'النظام هو الجزء الذي يحتوي على التفاعل المدروس، أي خليط هيدروكسيد الباريوم وثيوسيانات الأمونيوم المتفاعل في الكأس؛ أما الماء واللوح والهواء فهي المحيط.', '["","اللوح والماء يفقدان الحرارة لصالح التفاعل، فهما جزء من المحيط.","الهواء خارج التفاعل، فهو جزء من المحيط.","هذا يمثل الكون (النظام + المحيط)، لا النظام وحده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-03T20:51:23.873Z"}'::jsonb),
('mcq', 5, 1, 'المحيط هو كل ما في الكون غير النظام؛ فإذا كانت مكعبات الجليد هي النظام، فالعصير المحيط بها جزء من المحيط، ومنه تمتص المكعبات الحرارة لتنصهر.', '["هذه الجزيئات هي مادة الجليد نفسها، فهي النظام.","","هذا يجمع النظام والمحيط، فهو يمثل الكون في هذه الحالة لا المحيط وحده.","النظام قد يكون عملية فيزيائية كالانصهار، ويبقى كل ما عداه محيطًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-03T20:51:23.873Z"}'::jsonb),
('mcq', 6, 2, 'إذا كان الفلز هو النظام، فالماء الذي يحيط به في المسعر جزء من المحيط، وإليه تنتقل الحرارة من الفلز حتى تتساوى درجتا حرارتيهما.', '["قطعة الفلز هي النظام في هذا الافتراض، فلا تكون محيطًا لنفسها.","هذا يجمع النظام مع المحيط، فهو جزء من الكون لا المحيط وحده.","","الحرارة تنتقل من الفلز إلى الماء بعد وضعه في المسعر، لا إلى مصدر اللهب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-03T20:51:23.874Z"}'::jsonb),
('mcq', 7, 0, 'الكون = النظام + المحيط؛ فالنظام هنا تفاعل الاحتراق، والمحيط القدر والماء والهواء، والكون يضمهما معًا.', '["","هذا هو النظام فقط، والكون يضم معه المحيط.","هذا هو المحيط فقط، والكون يضم معه النظام.","الماء والقدر جزء من المحيط فقط، والكون يضم النظام والمحيط كله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-03T20:51:23.874Z"}'::jsonb),
('essay', 1, null::int, null, null, 'النظام: جزء معين من الكون يحتوي على التفاعل أو العملية التي نريد دراستها. والمحيط: كل شيء في الكون غير النظام. والكون: النظام مع المحيط، أي الكون = النظام + المحيط. وتنتقل الحرارة بين النظام والمحيط: من النظام إلى المحيط في العمليات الطاردة، ومن المحيط إلى النظام في العمليات الماصة.', '["تعريف النظام","تعريف المحيط","الكون = النظام + المحيط","تبادل الحرارة بين النظام والمحيط"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف النظام","marks":1},{"element":"تعريف المحيط","marks":1},{"element":"العلاقة: الكون = النظام + المحيط","marks":1},{"element":"الإشارة إلى انتقال الحرارة بين النظام والمحيط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريفان صحيحان مع العلاقة وانتقال الحرارة بينهما"},{"level":"2–3 درجات","description":"تعريف النظام والعلاقة مع نقص في تعريف المحيط أو انتقال الحرارة"},{"level":"1 درجة","description":"ذكر العلاقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف النظام بأنه الكأس أو الجهاز","كتابة الكون = النظام − المحيط","عدّ المحيط جزءًا من النظام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:51:23.874Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المثال الأول (يطلق الحرارة): الكمّادة الساخنة؛ النظام: تفاعل الحديد مع الأكسجين 4Fe(s) + 3O₂(g) → 2Fe₂O₃(s) داخل الكمّادة، والمحيط: يدا الشخص والهواء. المثال الثاني (يمتص الحرارة): الكمّادة الباردة؛ النظام: إذابة NH₄NO₃ في الماء داخل الكمّادة، والمحيط: الكاحل والهواء. الكون في كل مثال هو النظام مع محيطه: الكمّادة الساخنة واليدان والهواء معًا، أو الكمّادة الباردة والكاحل والهواء معًا.', '["مثال صحيح لنظام يطلق الحرارة","تحديد نظامه ومحيطه","مثال صحيح لنظام يمتص الحرارة","تحديد نظامه ومحيطه","تعريف الكون بأنه النظام + المحيط مطبقًا على المثالين"]'::jsonb, '[]'::jsonb, '[{"element":"مثال النظام الطارد مع تحديد نظامه ومحيطه","marks":2},{"element":"مثال النظام الماص مع تحديد نظامه ومحيطه","marks":2},{"element":"تعريف الكون وتطبيقه على المثالين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مثالان صحيحان بنظام ومحيط محددين، وتعريف الكون مطبقًا عليهما"},{"level":"3–4 درجات","description":"مثالان صحيحان مع خطأ في تحديد النظام أو المحيط في أحدهما، أو دون تطبيق تعريف الكون"},{"level":"1–2 درجة","description":"مثال واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر مثالين كلاهما طارد للحرارة","عدّ يد الشخص جزءًا من النظام","تعريف الكون دون ربطه بالمثالين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-03T20:51:23.876Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) النظام: تفاعل احتراق غاز الموقد؛ المحيط: الكأس والماء والهواء؛ تنتقل الحرارة من النظام إلى المحيط لأن الاحتراق طارد للحرارة. (ب) النظام: الماء الذي يغلي؛ المحيط: اللهب والكأس والهواء؛ تنتقل الحرارة من المحيط إلى النظام لأن الغليان يمتص الحرارة. تغيّر تحديد النظام لأن النظام هو الجزء الذي يحتوي على العملية التي نريد دراستها؛ فتغيير العملية المدروسة يغير النظام، ويصبح كل ما عداه محيطًا، أما الكون فيبقى النظام + المحيط في الحالتين.', '["(أ) النظام الاحتراق والمحيط الماء والكأس والهواء","(أ) الحرارة من النظام إلى المحيط","(ب) النظام الماء والمحيط اللهب والكأس والهواء","(ب) الحرارة من المحيط إلى النظام","النظام يتحدد بالعملية المدروسة"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد النظام والمحيط في (أ)","marks":1},{"element":"اتجاه الانتقال في (أ)","marks":1},{"element":"تحديد النظام والمحيط في (ب)","marks":1},{"element":"اتجاه الانتقال في (ب)","marks":1},{"element":"تعليل تغيّر تحديد النظام","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تحديد صحيح كامل للحالتين مع تعليل يربط النظام بالعملية المدروسة"},{"level":"4–5 درجات","description":"تحديد صحيح للحالتين مع تعليل ناقص، أو خطأ في اتجاه واحد"},{"level":"2–3 درجات","description":"تحديد صحيح لحالة واحدة"},{"level":"1 درجة","description":"تعريف النظام دون تطبيق صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الماء نظامًا في الحالتين","القول إن النظام ثابت مهما تغيرت العملية المدروسة","عكس اتجاه الانتقال في الغليان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-03T20:51:23.876Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
