('mcq', 1, 'ما إشارة ΔH_rxn للتفاعل الطارد للحرارة، ولماذا؟', null, null, '["سالبة؛ لأن H_products < H_reactants","موجبة؛ لأن H_products > H_reactants","سالبة؛ لأن H_products > H_reactants","موجبة؛ لأن H_products < H_reactants"]'::jsonb, 'فهم', 'ربط الإشارة بالمحتوى الحراري', 'سهل', 'الكتاب ص 23–24 — إشارة المحتوى الحراري للتفاعل'),
('mcq', 2, 'أيّ العمليات الآتية ماصة للحرارة؟', null, null, '["4Fe(s) + 3O₂(g) → 2Fe₂O₃(s)  ΔH = −1625 kJ","CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(l)  ΔH = −891 kJ","NH₄NO₃(s) → NH₄⁺(aq) + NO₃⁻(aq)  ΔH = +27 kJ","H₂O(g) → H₂O(l)  ΔH = −40.7 kJ"]'::jsonb, 'فهم', 'تصنيف بالإشارة', 'سهل', 'الكتاب ص 23–24 — الكمّادتان الساخنة والباردة'),
('mcq', 3, 'عند كتابة الحرارة جزءًا من معادلة تفاعل ماص للحرارة، في أيّ جهة تُكتب؟', null, null, '["في جهة النواتج؛ لأن الحرارة تنتج من التفاعل","في جهة المتفاعلات؛ لأن الحرارة تُمتص كأنها متفاعل","على جانبي المعادلة بالمقدار نفسه","لا تُكتب الحرارة في معادلات التفاعلات الماصة"]'::jsonb, 'فهم', 'موضع الحرارة في المعادلة', 'متوسط', 'الكتاب ص 21، 24 — معادلتا الكمّادتين'),
('mcq', 4, 'يمثل المخطط الآتي المحتوى الحراري لتفاعل ما. ما نوع التفاعل؟', null, '[{"src":"qimg/chem22/c1-endo-233.svg","alt":"مخطط محتوى حراري: مستوى المتفاعلات في الأسفل ومستوى النواتج في الأعلى، وسهم إلى أعلى مكتوب عليه ΔH = +233 kJ"}]'::jsonb, '["طارد للحرارة؛ لأن المحتوى الحراري للنواتج أكبر","طارد للحرارة؛ لأن السهم يمثل حرارة منطلقة","لا يمكن تحديد نوعه دون معرفة درجة الحرارة","ماص للحرارة؛ لأن المحتوى الحراري للنواتج أكبر"]'::jsonb, 'فهم', 'تفسير مخطط موصوف', 'متوسط', 'الكتاب ص 23–24، 42 — مخططات المحتوى الحراري (س60)'),
('mcq', 5, 'أيّ المقارنات الآتية بين التفاعل الطارد للحرارة والتفاعل الماص للحرارة صحيحة؟', null, null, '["الطارد يمتص الحرارة من المحيط، والماص يطلق الحرارة إلى المحيط","الطارد إشارة ΔH فيه موجبة، والماص إشارة ΔH فيه سالبة","الطارد محتوى نواتجه الحراري أكبر، والماص محتوى نواتجه الحراري أقل","الطارد ترتفع فيه درجة حرارة المحيط، والماص تنخفض فيه درجة حرارة المحيط"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 23–24 — إشارة المحتوى الحراري للتفاعل'),
('mcq', 6, 'عند خلط مادتين في أنبوب يمسكه طالب بيده، شعر الطالب ببرودة الأنبوب. أيّ مما يأتي يصف العملية بدقة؟', null, null, '["ماصة للحرارة، وΔH سالبة، والمحتوى الحراري للنواتج أكبر","طاردة للحرارة، وΔH سالبة، والمحتوى الحراري للنواتج أقل","ماصة للحرارة، وΔH موجبة، والمحتوى الحراري للنواتج أكبر","طاردة للحرارة، وΔH موجبة، والمحتوى الحراري للنواتج أقل"]'::jsonb, 'تحليل', 'استنتاج من ملاحظة', 'صعب', 'الكتاب ص 23–24 — إشارة المحتوى الحراري للتفاعل'),
('mcq', 7, 'للتفاعل 4Fe(s) + 3O₂(g) → 2Fe₂O₃(s) تكون ΔH_rxn = −1625 kJ. أيّ العبارات الآتية صحيحة؟', null, null, '["المحتوى الحراري لـ 2Fe₂O₃ أكبر من مجموع محتوى 4Fe و3O₂ بمقدار 1625 kJ","المحتوى الحراري لـ 2Fe₂O₃ أقل من مجموع محتوى 4Fe و3O₂ بمقدار 1625 kJ","المحتوى الحراري لـ 2Fe₂O₃ يساوي −1625 kJ","المحتوى الحراري للمتفاعلات والنواتج متساويان لأن الكتلة محفوظة"]'::jsonb, 'تحليل', 'تفسير قيمة ΔH', 'صعب', 'الكتاب ص 23 — إشارة المحتوى الحراري للتفاعل (الكمّادة الساخنة)'),
('essay', 1, 'قارن بين التفاعل الطارد للحرارة والتفاعل الماص للحرارة من حيث: (1) اتجاه انتقال الحرارة، (2) إشارة ΔH، (3) العلاقة بين H_products وH_reactants، (4) موضع الحرارة عند كتابتها في المعادلة، مع ذكر مثال لكل منهما.', null, null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 21–24 — الطارد والماص للحرارة'),
('essay', 2, 'اشرح لماذا تكون إشارة ΔH_rxn سالبة للتفاعلات الطاردة للحرارة وموجبة للتفاعلات الماصة، مستعينًا بالعلاقة ΔH_rxn = H_products − H_reactants.', null, null, null, 'فهم', 'شرح وتعليل', 'سهل', 'الكتاب ص 23–24 — إشارة المحتوى الحراري للتفاعل (س17)'),
('essay', 3, 'صف مخطط المحتوى الحراري لكل من تفاعل الكمّادة الساخنة 4Fe(s) + 3O₂(g) → 2Fe₂O₃(s) (ΔH = −1625 kJ) وعملية الكمّادة الباردة NH₄NO₃(s) → NH₄⁺(aq) + NO₃⁻(aq) (ΔH = +27 kJ)، موضحًا موضع المتفاعلات والنواتج واتجاه السهم في كل منهما، ثم أعد كتابة كل معادلة بإدراج الحرارة فيها.', null, null, null, 'تحليل', 'وصف مخططات وكتابة معادلات', 'صعب', 'الكتاب ص 23–24 — مخططا المحتوى الحراري للكمّادتين')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C1-L2-O04') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'في التفاعل الطارد تفقد المواد المتفاعلة حرارة، فيكون H_products < H_reactants، وبما أن ΔH_rxn = H_products − H_reactants فإن ΔH_rxn سالبة.', '["","هذه إشارة التفاعل الماص للحرارة الذي يزيد فيه المحتوى الحراري للنواتج.","لو كان H_products أكبر لكان الفرق H_products − H_reactants موجبًا لا سالبًا.","طرح كمية كبيرة من كمية صغيرة يعطي قيمة سالبة، فالإشارة لا تكون موجبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-03T20:51:23.877Z"}'::jsonb),
('mcq', 2, 2, 'العملية الماصة للحرارة تكون إشارة ΔH فيها موجبة، والوحيدة ذات الإشارة الموجبة هي إذابة NH₄NO₃ (ΔH = +27 kJ).', '["ΔH سالبة، فالتفاعل طارد للحرارة (تفاعل الكمّادة الساخنة).","ΔH سالبة، فاحتراق الميثان طارد للحرارة.","","ΔH سالبة، فتكثف بخار الماء يطلق الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-03T20:51:23.877Z"}'::jsonb),
('mcq', 3, 1, 'في التفاعل الماص تُمتص الحرارة كأنها إحدى المواد المتفاعلة، فتُكتب في جهة المتفاعلات، مثل: 27 kJ + NH₄NO₃(s) → NH₄⁺(aq) + NO₃⁻(aq).', '["هذا موضع الحرارة في التفاعل الطارد، مثل 4Fe + 3O₂ → 2Fe₂O₃ + 1625 kJ.","","لو كُتبت بالمقدار نفسه على الجانبين لما كان هناك امتصاص ولا إطلاق للحرارة.","الحرارة تُكتب في معادلة الماص أيضًا، مثل 27 kJ + NH₄NO₃(s) → NH₄⁺(aq) + NO₃⁻(aq)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-03T20:51:23.878Z"}'::jsonb),
('mcq', 4, 3, 'النواتج أعلى من المتفاعلات، فـ H_products > H_reactants و ΔH = +233 kJ موجبة؛ إذن التفاعل ماص للحرارة لأن المحتوى الحراري للنواتج أكبر.', '["زيادة المحتوى الحراري للنواتج تعني أن النظام امتص حرارة، فالتفاعل ماص لا طارد.","السهم المتجه إلى أعلى يمثل زيادة في المحتوى الحراري، أي حرارة ممتصة لا منطلقة.","يكفي موقع النواتج بالنسبة إلى المتفاعلات وإشارة ΔH لتحديد نوع التفاعل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-03T20:51:23.878Z"}'::jsonb),
('mcq', 5, 3, 'الطارد يطلق الحرارة إلى المحيط فترتفع درجة حرارة المحيط، والماص يمتص الحرارة من المحيط فتنخفض درجة حرارته؛ وهذه هي المقارنة الصحيحة الوحيدة.', '["المقارنة معكوسة؛ فالطارد يطلق الحرارة إلى المحيط والماص يمتصها منه.","الإشارتان معكوستان؛ فـ ΔH سالبة للطارد وموجبة للماص.","معكوسة؛ فالنواتج في الطارد أقل محتوى حراريًّا من المتفاعلات، وفي الماص أكبر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-03T20:51:23.878Z"}'::jsonb),
('mcq', 6, 2, 'برودة الأنبوب تعني أن الحرارة انتقلت من اليد (المحيط) إلى الخليط (النظام)؛ فالعملية ماصة للحرارة، والمحتوى الحراري للنواتج أكبر من المتفاعلات، فتكون ΔH موجبة.', '["العملية الماصة تكون ΔH فيها موجبة؛ فزيادة المحتوى الحراري للنواتج تعطي فرقًا موجبًا.","الطارد يطلق الحرارة إلى اليد فتشعر بالدفء، والطالب شعر بالبرودة.","","الوصف خاطئ ومتناقض؛ فالعملية ماصة، ثم إن المحتوى الأقل للنواتج يعطي ΔH سالبة لا موجبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-03T20:51:23.878Z"}'::jsonb),
('mcq', 7, 1, 'ΔH_rxn = H_products − H_reactants = −1625 kJ؛ فالقيمة السالبة تعني أن المحتوى الحراري لـ 2Fe₂O₃ أقل من مجموع محتوى 4Fe و3O₂ بمقدار 1625 kJ، وهذا الفرق انطلق إلى المحيط.', '["لو كان أكبر لكانت ΔH موجبة والتفاعل ماصًّا، لكن ΔH سالبة.","","−1625 kJ هي التغير في المحتوى الحراري (الفرق)، لا المحتوى الحراري للنواتج نفسه.","حفظ الكتلة لا يعني تساوي المحتوى الحراري؛ فالتفاعل أطلق 1625 kJ إلى المحيط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-03T20:51:23.879Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الطارد: (1) تنتقل الحرارة من النظام إلى المحيط. (2) ΔH سالبة. (3) H_products < H_reactants. (4) تُكتب الحرارة في جهة النواتج. مثال: 4Fe(s) + 3O₂(g) → 2Fe₂O₃(s) + 1625 kJ (الكمّادة الساخنة، ΔH = −1625 kJ). الماص: (1) تنتقل الحرارة من المحيط إلى النظام. (2) ΔH موجبة. (3) H_products > H_reactants. (4) تُكتب الحرارة في جهة المتفاعلات. مثال: 27 kJ + NH₄NO₃(s) → NH₄⁺(aq) + NO₃⁻(aq) (الكمّادة الباردة، ΔH = +27 kJ).', '["اتجاه انتقال الحرارة لكل منهما","إشارة ΔH لكل منهما","العلاقة بين H_products وH_reactants لكل منهما","موضع الحرارة في المعادلة لكل منهما","مثال صحيح لكل منهما"]'::jsonb, '[]'::jsonb, '[{"element":"اتجاه انتقال الحرارة للنوعين","marks":2},{"element":"إشارة ΔH للنوعين","marks":2},{"element":"العلاقة بين H_products وH_reactants للنوعين","marks":2},{"element":"موضع الحرارة في المعادلة للنوعين","marks":1},{"element":"مثال صحيح لكل نوع","marks":1}]'::jsonb, '[{"level":"8 درجات","description":"مقارنة صحيحة كاملة في البنود الأربعة مع مثالين صحيحين"},{"level":"5–7 درجات","description":"خطأ أو نقص في بند واحد أو مثال واحد"},{"level":"2–4 درجات","description":"بندان صحيحان فقط"},{"level":"1 درجة","description":"بند واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس العلاقة بين H_products وH_reactants","كتابة حرارة التفاعل الماص في جهة النواتج","إعطاء الكمّادة الباردة ΔH سالبة لأنها تبرد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (8 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-03T20:51:23.879Z"}'::jsonb),
('essay', 2, null::int, null, null, 'في التفاعل الطارد تفقد المواد المتفاعلة حرارة إلى المحيط، فيكون المحتوى الحراري للنواتج أقل من المتفاعلات (H_products < H_reactants)، وطرح الكمية الكبرى من الصغرى يعطي قيمة سالبة، فتكون ΔH_rxn سالبة. وفي التفاعل الماص تكتسب المواد حرارة من المحيط، فيكون H_products > H_reactants، وطرح الكمية الصغرى من الكبرى يعطي قيمة موجبة، فتكون ΔH_rxn موجبة.', '["الطارد يفقد حرارة فـ H_products < H_reactants","الفرق سالب فـ ΔH سالبة","الماص يكتسب حرارة فـ H_products > H_reactants","الفرق موجب فـ ΔH موجبة"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير الإشارة السالبة للطارد","marks":2},{"element":"تفسير الإشارة الموجبة للماص","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح كامل للإشارتين باستعمال العلاقة"},{"level":"2–3 درجات","description":"تفسير صحيح لإحدى الإشارتين أو للاثنتين دون استعمال العلاقة"},{"level":"1 درجة","description":"ذكر الإشارتين دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة العلاقة معكوسة H_reactants − H_products","ربط الإشارة بدرجة حرارة النظام لا بالمحتوى الحراري","القول إن ΔH السالبة تعني امتصاص الحرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-03T20:51:23.879Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الكمّادة الساخنة: يقع مستوى المتفاعلات 4Fe(s) + 3O₂(g) في الأعلى، ومستوى الناتج 2Fe₂O₃(s) في الأسفل، والسهم يتجه إلى أسفل مكتوب عليه ΔH = −1625 kJ، دلالة على انطلاق الحرارة إلى المحيط (ΔH < 0). المعادلة: 4Fe(s) + 3O₂(g) → 2Fe₂O₃(s) + 1625 kJ. الكمّادة الباردة: يقع مستوى المتفاعل NH₄NO₃(s) في الأسفل، ومستوى النواتج NH₄⁺(aq) + NO₃⁻(aq) في الأعلى، والسهم يتجه إلى أعلى مكتوب عليه ΔH = +27 kJ، دلالة على امتصاص الحرارة من المحيط (ΔH > 0). المعادلة: 27 kJ + NH₄NO₃(s) → NH₄⁺(aq) + NO₃⁻(aq).', '["الساخنة: المتفاعلات أعلى والنواتج أسفل","الساخنة: سهم إلى أسفل ΔH = −1625 kJ","الباردة: المتفاعل أسفل والنواتج أعلى","الباردة: سهم إلى أعلى ΔH = +27 kJ","المعادلتان مع الحرارة في الجهة الصحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"وصف مخطط الكمّادة الساخنة (المواضع والسهم)","marks":2},{"element":"وصف مخطط الكمّادة الباردة (المواضع والسهم)","marks":2},{"element":"إعادة كتابة معادلة الساخنة بالحرارة في جهة النواتج","marks":1},{"element":"إعادة كتابة معادلة الباردة بالحرارة في جهة المتفاعلات","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"وصف صحيح للمخططين ومعادلتان صحيحتان"},{"level":"4–5 درجات","description":"وصف صحيح للمخططين مع خطأ في إحدى المعادلتين، أو العكس"},{"level":"2–3 درجات","description":"وصف صحيح لمخطط واحد مع معادلته"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم السهم إلى أعلى للتفاعل الطارد","كتابة الحرارة في جهة النواتج للعملية الماصة","وضع النواتج أعلى من المتفاعلات في الطارد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-03T20:51:23.879Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C1-L2-O04') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C1-L2-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'في مسعر يحتوي على 100.0 g من الماء، ارتفعت درجة حرارة الماء من 22.00°C إلى 27.50°C. ما كمية الحرارة التي اكتسبها الماء؟ (الحرارة النوعية للماء 4.184 J/g·°C)', null, null, '["1.15 × 10⁴ J","2.30 × 10³ J","550 J","9.20 × 10³ J"]'::jsonb, 'تطبيق', 'حساب q للماء', 'سهل', 'الكتاب ص 19–20 — المسعر وتحديد الحرارة النوعية'),
('mcq', 2, 'وُضعت قطعة فلز ساخنة في مسعر يحتوي على 150.0 g من الماء، فارتفعت درجة حرارة الماء 4.20°C. إذا افترضنا عدم فقد حرارة إلى خارج المسعر، فما قيمة q_metal؟ (الحرارة النوعية للماء 4.184 J/g·°C)', null, null, '["−2.64 × 10³ J","+2.64 × 10³ J","−630 J","−151 J"]'::jsonb, 'تطبيق', 'تطبيق q_metal = −q_water', 'متوسط', 'الكتاب ص 19–20 — المسعر وتحديد الحرارة النوعية'),
('mcq', 3, 'وُضعت قطعة فلز كتلتها 30.0 g ودرجة حرارتها 95.0°C في مسعر يحتوي على 80.0 g من الماء عند 22.0°C، فاستقرت درجة الحرارة النهائية عند 27.4°C. ما الحرارة النوعية للفلز؟ (الحرارة النوعية للماء 4.184 J/g·°C)', null, null, '["11.2 J/g·°C","0.825 J/g·°C","1.12 J/g·°C","0.891 J/g·°C"]'::jsonb, 'تطبيق', 'حساب الحرارة النوعية لفلز', 'متوسط', 'الكتاب ص 19–20 — المسعر وتحديد الحرارة النوعية'),
('mcq', 4, 'وُضعت قطعة فلز كتلتها 50.0 g عند 100.0°C في مسعر يحتوي على 100.0 g من الماء عند 20.0°C، فأصبحت درجة الحرارة النهائية 24.1°C. اعتمادًا على قيم الحرارة النوعية المعطاة، ما الفلز على الأرجح؟ (الحرارة النوعية للماء 4.184 J/g·°C)', '{"headers":["الفلز","الحرارة النوعية (J/g·°C)"],"rows":[["الألومنيوم","0.897"],["الحديد","0.449"],["الفضة","0.235"],["الرصاص","0.128"]]}'::jsonb, null, '["الألومنيوم","الفضة","الحديد","الرصاص"]'::jsonb, 'تحليل', 'تعرّف فلز من بيانات المسعر', 'صعب', 'الكتاب ص 19–20 — المسعر وتحديد الحرارة النوعية'),
('mcq', 5, 'حدث تفاعل في مسعر من البوليسترين يحتوي على 50.0 g من الماء، فارتفعت درجة حرارة الماء من 21.00°C إلى 27.80°C. ما كمية الحرارة المرتبطة بالتفاعل؟ (الحرارة النوعية للماء 4.184 J/g·°C)', null, null, '["أطلق التفاعل 1.42 kJ","امتص التفاعل 1.42 kJ","أطلق التفاعل 5.82 kJ","أطلق التفاعل 0.209 kJ"]'::jsonb, 'تطبيق', 'حساب حرارة تفاعل في مسعر', 'متوسط', 'الكتاب ص 19–20، 24 — المسعر، q = ΔH عند ضغط ثابت'),
('mcq', 6, 'وُضعت قطعة فلز ساخنة في ماء مسعر معزول حتى تساوت درجتا حرارتيهما. أيّ العلاقات الآتية تربط الحرارة التي فقدها الفلز بالحرارة التي اكتسبها الماء؟', null, null, '["q_metal = q_water","q_metal = −q_water","q_metal = q_water ÷ ΔT","q_metal = c_metal × q_water"]'::jsonb, 'فهم', 'تذكر العلاقة وفهمها', 'سهل', 'الكتاب ص 19–20 — المسعر وتحديد الحرارة النوعية'),
('mcq', 7, 'امتص الماء في مسعر 3.35 kJ من الحرارة، فارتفعت درجة حرارته من 20.0°C إلى 36.0°C. ما كتلة الماء؟ (الحرارة النوعية للماء 4.184 J/g·°C)', null, null, '["0.0500 g","22.2 g","0.0200 g","50.0 g"]'::jsonb, 'تطبيق', 'حساب الكتلة من بيانات المسعر', 'صعب', 'الكتاب ص 16، 21 — معادلة كمية الحرارة (مسائل 13)'),
('essay', 1, 'أطلقت عينة كتلتها 5.00 g من مادة مجهولة 30.0 cal عندما انخفضت درجة حرارتها من 45.0°C إلى 30.0°C. احسب الحرارة النوعية للمادة بوحدة J/g·°C. (1 cal = 4.184 J)', null, null, null, 'تطبيق', 'مسألة حسابية بخطوات', 'متوسط', 'الكتاب ص 16، 24 — معادلة كمية الحرارة (س21)'),
('essay', 2, 'وُضعت قطعة فلز كتلتها 60.0 g ودرجة حرارتها 99.0°C في مسعر من البوليسترين يحتوي على 50.0 g من الماء عند 23.00°C، فاستقرت درجة الحرارة عند 27.80°C. (أ) احسب الحرارة التي اكتسبها الماء. (ب) احسب q_metal. (ج) احسب الحرارة النوعية للفلز. (د) حدد الفلز من القيم: الألومنيوم 0.897، الحديد 0.449، الفضة 0.235، الذهب 0.129 J/g·°C. (الحرارة النوعية للماء 4.184 J/g·°C)', null, null, null, 'تحليل', 'مسألة متعددة الخطوات', 'صعب', 'الكتاب ص 19–20 — المسعر وتحديد الحرارة النوعية'),
('essay', 3, 'أُذيبت كمية من NH₄NO₃ في مسعر من البوليسترين يحتوي على 100.0 g من الماء، فانخفضت درجة حرارة الماء من 22.00°C إلى 18.20°C. (أ) احسب q للماء. (ب) ما كمية الحرارة التي امتصتها عملية الإذابة؟ (ج) صنّف العملية وحدد إشارة ΔH لها. (الحرارة النوعية للماء 4.184 J/g·°C)', null, null, null, 'تطبيق', 'حساب وتصنيف', 'سهل', 'الكتاب ص 19–20، 24 — المسعر والكمّادة الباردة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C1-L2-O05') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'ΔT = 27.50°C − 22.00°C = 5.50°C، و q = c × m × ΔT = 4.184 J/g·°C × 100.0 g × 5.50°C = 2301 J ≈ 2.30 × 10³ J.', '["استُعملت درجة الحرارة النهائية 27.50°C بدلًا من ΔT = 5.50°C.","","أُهملت الحرارة النوعية للماء، فحُسب m × ΔT فقط.","استُعملت درجة الحرارة الابتدائية 22.00°C بدلًا من ΔT."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-03T20:51:23.880Z"}'::jsonb),
('mcq', 2, 0, 'q_water = 4.184 × 150.0 × 4.20 = 2636 J، وبما أن q_metal = −q_water فإن q_metal = −2.64 × 10³ J.', '["","أُهملت الإشارة؛ فالفلز فقد الحرارة، و q_metal = −q_water سالبة.","أُهملت الحرارة النوعية للماء، فحُسب m × ΔT = 150.0 × 4.20 فقط.","قُسم على الحرارة النوعية بدلًا من الضرب فيها: 150.0 × 4.20 ÷ 4.184."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-03T20:51:23.881Z"}'::jsonb),
('mcq', 3, 3, 'q_water = 4.184 × 80.0 × (27.4 − 22.0) = 1807 J، فـ q_metal = −1807 J، و ΔT_metal = 27.4 − 95.0 = −67.6°C؛ إذن c = −1807 J ÷ (30.0 g × −67.6°C) = 0.891 J/g·°C.', '["استُعمل التغير في درجة حرارة الماء (5.4°C) بدلًا من التغير في درجة حرارة الفلز (−67.6°C).","حُسب ΔT للفلز بطرح درجة حرارة الماء الابتدائية (95.0 − 22.0 = 73.0°C) بدلًا من درجة الحرارة النهائية.","قُلبت النسبة فحُسب (m × ΔT) ÷ q بدلًا من q ÷ (m × ΔT).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-03T20:51:23.882Z"}'::jsonb),
('mcq', 4, 2, 'q_water = 4.184 × 100.0 × (24.1 − 20.0) = 1715 J، و ΔT_metal = 24.1 − 100.0 = −75.9°C؛ فـ c = 1715 ÷ (50.0 × 75.9) = 0.452 J/g·°C، وهي أقرب قيمة إلى الحديد (0.449 J/g·°C).', '["حرارته النوعية 0.897 J/g·°C، أي نحو ضعف القيمة المحسوبة 0.452 J/g·°C؛ وتنتج هذه القيمة تقريبًا إذا قُسم على نصف كتلة الفلز.","حرارتها النوعية 0.235 J/g·°C، وهي نحو نصف القيمة المحسوبة؛ فلا تطابقها.","","حرارته النوعية 0.128 J/g·°C، وهي بعيدة جدًّا عن القيمة المحسوبة 0.452 J/g·°C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-03T20:51:23.882Z"}'::jsonb),
('mcq', 5, 0, 'q_water = 4.184 × 50.0 × (27.80 − 21.00) = 1423 J ≈ 1.42 kJ اكتسبها الماء، وهي الحرارة التي فقدها التفاعل؛ إذن أطلق التفاعل 1.42 kJ.', '["","المقدار صحيح، لكن ارتفاع درجة حرارة الماء يعني أن التفاعل أطلق الحرارة ولم يمتصها.","استُعملت درجة الحرارة النهائية 27.80°C بدلًا من ΔT = 6.80°C.","أُهمل التغير في درجة الحرارة، فحُسب c × m فقط = 209 J."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-03T20:51:23.883Z"}'::jsonb),
('mcq', 6, 1, 'إذا لم تُفقد حرارة إلى المحيط، فالحرارة التي فقدها الفلز تساوي الحرارة التي اكتسبها الماء مقدارًا وتعاكسها إشارة: q_metal = −q_water.', '["أُهملت الإشارة؛ فالفلز يفقد الحرارة (q سالبة) والماء يكتسبها (q موجبة).","","القسمة على ΔT خلط بين كمية الحرارة والحرارة النوعية، والحرارتان متساويتان في المقدار.","لا تُضرب حرارة الماء في الحرارة النوعية للفلز؛ فالحرارة المفقودة تساوي المكتسبة مقدارًا وتعاكسها إشارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-03T20:51:23.883Z"}'::jsonb),
('mcq', 7, 3, 'm = q ÷ (c × ΔT) = 3350 J ÷ (4.184 J/g·°C × 16.0°C) = 50.0 g.', '["لم تُحوَّل الحرارة من kJ إلى J قبل القسمة (3.35 بدلًا من 3350 J).","استُعملت درجة الحرارة النهائية 36.0°C بدلًا من ΔT = 16.0°C.","قُلبت النسبة فحُسب (c × ΔT) ÷ q بدلًا من q ÷ (c × ΔT).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-03T20:51:23.884Z"}'::jsonb),
('essay', 1, null::int, null, null, 'q = −30.0 cal × 4.184 J/cal = −125.5 J، و ΔT = 30.0°C − 45.0°C = −15.0°C، و c = q ÷ (m × ΔT) = −125.5 J ÷ (5.00 g × −15.0°C) = 1.67 J/g·°C.', '["تحويل الحرارة من cal إلى J","حساب ΔT","إعادة ترتيب المعادلة c = q ÷ (m × ΔT)","الناتج 1.67 J/g·°C بالوحدة والأرقام المعنوية الصحيحة"]'::jsonb, '["q = 30.0 cal × 4.184 J/cal = 125.5 J (منطلقة، أي q = −125.5 J)","ΔT = 30.0 − 45.0 = −15.0°C","c = q ÷ (m × ΔT)","c = −125.5 J ÷ (5.00 g × −15.0°C) = 1.67 J/g·°C"]'::jsonb, '[{"element":"تحويل cal إلى J","marks":1},{"element":"حساب ΔT","marks":1},{"element":"كتابة العلاقة والتعويض","marks":1},{"element":"الناتج النهائي بالوحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطوات صحيحة كاملة وناتج 1.67 J/g·°C"},{"level":"2–3 درجات","description":"طريقة صحيحة مع خطأ في التحويل أو في الحساب"},{"level":"1 درجة","description":"كتابة العلاقة الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال التحويل من cal إلى J فيكون الناتج 0.400","استعمال 45.0°C أو 30.0°C بدلًا من ΔT","الضرب في 0.2390 بدلًا من 4.184"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:51:23.884Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) q_water = 4.184 × 50.0 × (27.80 − 23.00) = 1004 J ≈ 1.00 × 10³ J. (ب) q_metal = −q_water = −1.00 × 10³ J. (ج) ΔT_metal = 27.80 − 99.0 = −71.2°C، و c = −1004 J ÷ (60.0 g × −71.2°C) = 0.235 J/g·°C. (د) الفلز هو الفضة.', '["q_water = 1.00 × 10³ J","q_metal = −1.00 × 10³ J","ΔT_metal = −71.2°C","c = 0.235 J/g·°C","الفلز الفضة"]'::jsonb, '["ΔT_water = 27.80 − 23.00 = 4.80°C","q_water = 4.184 × 50.0 × 4.80 = 1004 J","q_metal = −q_water = −1004 J","ΔT_metal = 27.80 − 99.0 = −71.2°C","c = −1004 ÷ (60.0 × −71.2) = 0.235 J/g·°C","المقارنة بالقيم: الفضة"]'::jsonb, '[{"element":"حساب q_water","marks":2},{"element":"q_metal بالإشارة الصحيحة","marks":1},{"element":"حساب ΔT_metal","marks":1},{"element":"حساب c","marks":1},{"element":"تحديد الفلز","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"جميع الخطوات صحيحة مع الإشارات والوحدات وتحديد الفضة"},{"level":"4–5 درجات","description":"خطأ في الإشارة أو في خطوة واحدة مع صحة الطريقة"},{"level":"2–3 درجات","description":"حساب q_water صحيح فقط أو مع q_metal"},{"level":"1 درجة","description":"كتابة المعادلات دون حساب صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال ΔT للماء عند حساب c للفلز","إهمال الإشارة في q_metal = −q_water","طرح 23.00°C من 99.0°C لحساب ΔT_metal"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-03T20:51:23.885Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) q_water = 4.184 × 100.0 × (18.20 − 22.00) = −1.59 × 10³ J (فقد الماء حرارة). (ب) امتصت عملية الإذابة +1.59 × 10³ J = 1.59 kJ، لأن الحرارة التي فقدها الماء انتقلت إلى العملية. (ج) العملية ماصة للحرارة، وإشارة ΔH موجبة.', '["q_water = −1.59 × 10³ J","الحرارة الممتصة 1.59 kJ","العملية ماصة وΔH موجبة"]'::jsonb, '["ΔT = 18.20 − 22.00 = −3.80°C","q_water = 4.184 × 100.0 × (−3.80) = −1590 J","q_process = −q_water = +1590 J = 1.59 kJ","q موجبة للنظام: ماصة، ΔH > 0"]'::jsonb, '[{"element":"حساب ΔT وq_water بالإشارة","marks":2},{"element":"الحرارة التي امتصتها العملية","marks":1},{"element":"التصنيف وإشارة ΔH","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة بالإشارات وتصنيف صحيح"},{"level":"2–3 درجات","description":"حساب صحيح للمقدار مع خطأ في الإشارة أو التصنيف"},{"level":"1 درجة","description":"كتابة المعادلة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ انخفاض درجة الحرارة دليلًا على أن العملية طاردة","إهمال إشارة ΔT","الخلط بين q للماء وq للعملية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-03T20:51:23.886Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
