from (values
('mcq', 1, 'في يوم مشمس ترتفع درجة حرارة الرمل على الشاطئ أكثر بكثير من مياه البحر المجاورة. ما التفسير؟ (الحرارة النوعية للماء 4.184 J/g·°C، وللرمل الجاف نحو 0.80 J/g·°C)', null, null, '["الحرارة النوعية للرمل أكبر كثيرًا من الحرارة النوعية للماء","الماء يعكس أشعة الشمس كلها ولا يمتص منها شيئًا","الحرارة النوعية للرمل أقل كثيرًا من الحرارة النوعية للماء","الحرارة تنتقل دائمًا من ماء البحر إلى الرمل"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'سهل', 'الكتاب ص 15–16 — الحرارة النوعية (الأسمنت والماء)'),
('mcq', 2, 'الحرارة النوعية لمادة هي كمية الحرارة اللازمة لـ:', null, null, '["رفع درجة حرارة 1 mol من المادة 1°C","صهر 1 g من المادة عند درجة انصهارها","رفع درجة حرارة المادة كلها حتى الغليان","رفع درجة حرارة 1 g من المادة 1°C"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 15–16 — الحرارة النوعية (الأسمنت والماء)'),
('mcq', 3, 'امتصت كتلة مقدارها 100 g من الأسمنت، وكتلة مماثلة من الماء، 1000 J لكل منهما. ما مقدار الارتفاع في درجة حرارة كل منهما؟ (c للأسمنت 0.84 J/g·°C، وللماء 4.184 J/g·°C)', null, null, '["الأسمنت 11.9°C والماء 2.39°C","الأسمنت 2.39°C والماء 11.9°C","الأسمنت 8.40°C والماء 41.8°C","الأسمنت 11.9°C والماء 11.9°C"]'::jsonb, 'تطبيق', 'حساب ΔT للمقارنة', 'متوسط', 'الكتاب ص 15–16 — الحرارة النوعية (الأسمنت والماء)'),
('mcq', 4, 'الحرارة النوعية للماء 4.184 J/g·°C، وللأسمنت 0.84 J/g·°C. عندما تمتص كتلتان متساويتان منهما كمية الطاقة نفسها، فإن الارتفاع في درجة حرارة الأسمنت يساوي تقريبًا:', null, null, '["خُمس الارتفاع في درجة حرارة الماء","خمسة أمثال الارتفاع في درجة حرارة الماء","الارتفاع في درجة حرارة الماء نفسه","3.3 أمثال الارتفاع في درجة حرارة الماء"]'::jsonb, 'تطبيق', 'استدلال نسبي', 'متوسط', 'الكتاب ص 15–16 — الحرارة النوعية (الأسمنت والماء)'),
('mcq', 5, 'بعد غروب الشمس يبرد رمل الشاطئ أسرع من مياه البحر. ما التفسير؟ (الحرارة النوعية للماء 4.184 J/g·°C، وللرمل الجاف نحو 0.80 J/g·°C)', null, null, '["حرارة الرمل النوعية مرتفعة، فيفقد حرارته المخزنة دفعة واحدة","مياه البحر تكتسب الحرارة من الرمل ليلًا فلا تتغير درجة حرارتها","حرارة الرمل النوعية منخفضة، ففقد كمية صغيرة من الحرارة يخفض درجة حرارته كثيرًا","الرمل يمتص البرودة من الهواء أسرع من الماء"]'::jsonb, 'فهم', 'تفسير ظاهرة معاكسة', 'متوسط', 'الكتاب ص 15–16 — الحرارة النوعية (الأسمنت والماء)'),
('mcq', 6, 'وُضعت كتل متساوية من الألومنيوم والذهب والحديد والفضة تحت أشعة الشمس مدة زمنية واحدة، فامتصت كمية الحرارة نفسها. اعتمادًا على قيم الحرارة النوعية المعطاة، ما ترتيبها وفق الازدياد في درجة حرارتها من الأعلى إلى الأقل؟', '{"headers":["الفلز","الحرارة النوعية (J/g·°C)"],"rows":[["الألومنيوم","0.897"],["الذهب","0.129"],["الحديد","0.449"],["الفضة","0.235"]]}'::jsonb, null, '["الذهب > الفضة > الحديد > الألومنيوم","الألومنيوم > الحديد > الفضة > الذهب","الذهب > الحديد > الفضة > الألومنيوم","الفضة > الذهب > الحديد > الألومنيوم"]'::jsonb, 'تحليل', 'ترتيب من بيانات جدول', 'صعب', 'الكتاب ص 16، 18 — الجدول 1-2 (س11)'),
('mcq', 7, 'لماذا يُستغل الماء في تخزين الطاقة الشمسية لتدفئة البيوت؟', null, null, '["لأن حرارته النوعية المنخفضة تجعله يسخن بسرعة كبيرة","لأن حرارته النوعية العالية تمكّنه من تخزين كمية كبيرة من الحرارة","لأنه يحوّل أشعة الشمس مباشرة إلى كهرباء","لأنه لا يفقد الحرارة المخزنة فيه مهما طال الزمن"]'::jsonb, 'فهم', 'تفسير تطبيق', 'متوسط', 'الكتاب ص 18 — الطاقة الشمسية'),
('essay', 1, 'فسّر ارتفاع درجة حرارة رمال الشاطئ بأشعة الشمس أكثر من مياه البحر، مستعينًا بمفهوم الحرارة النوعية والعلاقة q = c × m × ΔT.', null, null, null, 'فهم', 'تفسير علمي', 'سهل', 'الكتاب ص 15–16 — الحرارة النوعية (الأسمنت والماء)'),
('essay', 2, 'الحرارة النوعية لرمل جاف نحو 0.80 J/g·°C. امتصت عينة من الرمل كتلتها 50.0 g، وعينة من الماء كتلتها 50.0 g، 500 J من الحرارة لكل منهما. (أ) احسب الارتفاع في درجة حرارة كل منهما. (ب) احسب نسبة ارتفاع درجة حرارة الرمل إلى ارتفاع درجة حرارة الماء. (ج) فسّر النتيجة. (الحرارة النوعية للماء 4.184 J/g·°C)', null, null, null, 'تطبيق', 'حساب ومقارنة وتفسير', 'صعب', 'الكتاب ص 15–16 — الحرارة النوعية (قيمة الرمل معطاة في السؤال)'),
('essay', 3, 'تنبأ: لو كانت الحرارة النوعية لماء البحر مساوية للحرارة النوعية للرمل، كيف ستتغير درجة حرارة البحر بين النهار والليل؟ وما أثر ذلك في المخلوقات البحرية والمناطق الساحلية؟ علّل إجابتك.', null, null, null, 'تحليل', 'تنبؤ وتعليل', 'صعب', 'الكتاب ص 15، 18 — الحرارة النوعية والطاقة الشمسية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
