select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'الحرارة النوعية للماء 4.184 J/g·°C، وللرمل نحو 0.80 J/g·°C، أي أقل كثيرًا؛ فعندما تمتص كتل متساوية الطاقة نفسها يكون ΔT = q ÷ (c × m) أكبر للرمل، فيسخن أكثر لأن حرارته النوعية أقل كثيرًا.', '["المادة ذات الحرارة النوعية الأكبر تحتاج إلى حرارة أكثر لرفع درجة حرارتها، فتسخن أبطأ لا أسرع.","الماء يمتص طاقة الشمس، بل يُستغل في تخزينها؛ لكن درجة حرارته ترتفع ببطء لارتفاع حرارته النوعية.","","الحرارة تنتقل من الأسخن إلى الأبرد، والرمل في النهار أسخن من الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-03T20:51:23.887Z"}'::jsonb),
('mcq', 2, 3, 'الحرارة النوعية لأي مادة هي كمية الحرارة اللازمة لرفع درجة حرارة 1 g من تلك المادة 1°C، ولكل مادة حرارة نوعية مميزة.', '["الحرارة النوعية تُنسب إلى جرام واحد لا إلى مول، ووحدتها J/g·°C.","هذا وصف لحرارة الانصهار، لا للحرارة النوعية.","الحرارة النوعية تخص 1 g ورفعًا مقداره 1°C فقط، ولا تتعلق بالغليان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-03T20:51:23.887Z"}'::jsonb),
('mcq', 3, 0, 'ΔT = q ÷ (c × m): للأسمنت 1000 ÷ (0.84 × 100) = 11.9°C، وللماء 1000 ÷ (4.184 × 100) = 2.39°C.', '["","النتيجتان معكوستان؛ فالمادة ذات الحرارة النوعية الأقل (الأسمنت) هي التي ترتفع درجة حرارتها أكثر.","حُسب ΔT = q × c ÷ m بالضرب في الحرارة النوعية بدلًا من القسمة عليها.","افتُرض أن تساوي الطاقة والكتلة يعني تساوي ΔT، مع أن الحرارة النوعية مختلفة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-03T20:51:23.888Z"}'::jsonb),
('mcq', 4, 1, 'ΔT يتناسب عكسيًّا مع c عند تساوي q وm؛ فالنسبة = 4.184 ÷ 0.84 ≈ 5، أي أن ارتفاع درجة حرارة الأسمنت خمسة أمثال ارتفاع درجة حرارة الماء.', '["النسبة مقلوبة؛ فالأسمنت ذو الحرارة النوعية الأقل يرتفع أكثر لا أقل.","","تساوي الكتلة والطاقة لا يعني تساوي ΔT، لأن الحرارة النوعية مختلفة.","طُرحت الحرارتان النوعيتان (4.184 − 0.84) بدلًا من قسمة إحداهما على الأخرى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-03T20:51:23.889Z"}'::jsonb),
('mcq', 5, 2, 'عند فقد كتلتين متساويتين الكمية نفسها من الحرارة يكون الانخفاض في درجة الحرارة أكبر للمادة ذات الحرارة النوعية الأقل؛ فالرمل يبرد أسرع لأن حرارته النوعية منخفضة، والماء يحتفظ بحرارته لأن حرارته النوعية عالية.', '["الحرارة النوعية للرمل منخفضة مقارنة بالماء، والمرتفعة هي حرارة الماء النوعية.","انخفاض درجة حرارة الماء ببطء سببه حرارته النوعية العالية، لا اكتسابه حرارة من الرمل.","","البرودة لا تنتقل؛ الذي يحدث أن الرمل يفقد الحرارة إلى الهواء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-03T20:51:23.889Z"}'::jsonb),
('mcq', 6, 0, 'عند تساوي q وm يكون ΔT أكبر كلما قلت الحرارة النوعية: الذهب 0.129 < الفضة 0.235 < الحديد 0.449 < الألومنيوم 0.897؛ إذن الترتيب: الذهب > الفضة > الحديد > الألومنيوم.', '["","رُتبت الفلزات وفق ازدياد الحرارة النوعية لا الارتفاع في درجة الحرارة؛ فالترتيب معكوس.","الفضة (0.235) حرارتها النوعية أقل من الحديد (0.449)، فترتفع درجة حرارتها أكثر منه.","الذهب (0.129) حرارته النوعية أقل من الفضة، فهو الأعلى ارتفاعًا في درجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-03T20:51:23.890Z"}'::jsonb),
('mcq', 7, 1, 'الحرارة النوعية للماء عالية، فيمتص كمية كبيرة من حرارة الشمس مع تغير قليل نسبيًّا في درجة حرارته، ثم يُدوَّر لتدفئة البيوت؛ فهو يخزن كمية كبيرة من الحرارة.', '["الحرارة النوعية للماء من أعلى القيم (4.184 J/g·°C)، لا منخفضة.","","تحويل أشعة الشمس إلى كهرباء عمل الخلايا الكهروضوئية، لا الماء.","الماء يفقد حرارته، لكن ببطء؛ فلا يُقال إنه لا يفقدها أبدًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-03T20:51:23.891Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الحرارة النوعية هي كمية الحرارة اللازمة لرفع درجة حرارة 1 g من المادة 1°C. والحرارة النوعية للماء مرتفعة (4.184 J/g·°C)، أما الرمل فحرارته النوعية أقل كثيرًا (كالمواد الصلبة مثل الأسمنت 0.84 J/g·°C). ومن العلاقة q = c × m × ΔT يكون ΔT = q ÷ (c × m)؛ فعند امتصاص كتل متساوية الكمية نفسها من طاقة الشمس يكون ΔT أكبر للمادة ذات c الأصغر، فترتفع درجة حرارة الرمل أكثر من الماء.', '["تعريف الحرارة النوعية","c للماء مرتفعة وللرمل منخفضة","إعادة ترتيب العلاقة ΔT = q ÷ (c × m)","عند تساوي q وm يكون ΔT أكبر للرمل"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الحرارة النوعية","marks":1},{"element":"المقارنة بين c للماء وللرمل","marks":1},{"element":"استعمال العلاقة وإعادة ترتيبها","marks":1},{"element":"الاستنتاج الصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يربط الحرارة النوعية بالعلاقة والاستنتاج"},{"level":"2–3 درجات","description":"تفسير صحيح بالحرارة النوعية دون استعمال العلاقة، أو استعمالها مع نقص"},{"level":"1 درجة","description":"ذكر أن الحرارة النوعية للرمل أقل دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الرمل يمتص طاقة أكثر من الماء","القول إن الحرارة النوعية للرمل أكبر","إغفال شرط تساوي الكتلة والطاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-03T20:51:23.891Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) ΔT_sand = 500 J ÷ (0.80 J/g·°C × 50.0 g) = 12.5°C؛ ΔT_water = 500 J ÷ (4.184 J/g·°C × 50.0 g) = 2.39°C. (ب) النسبة = 12.5 ÷ 2.39 ≈ 5.2. (ج) ترتفع درجة حرارة الرمل نحو خمسة أمثال ارتفاع درجة حرارة الماء لأن حرارته النوعية أقل بنحو خمس مرات؛ فالماء يحتاج إلى حرارة أكثر لكل جرام لرفع درجة حرارته 1°C.', '["ΔT للرمل 12.5°C","ΔT للماء 2.39°C","النسبة ≈ 5.2","التفسير بالحرارة النوعية"]'::jsonb, '["ΔT = q ÷ (c × m)","ΔT_sand = 500 ÷ (0.80 × 50.0) = 12.5°C","ΔT_water = 500 ÷ (4.184 × 50.0) = 2.39°C","النسبة = 12.5 ÷ 2.39 = 5.2 (= 4.184 ÷ 0.80)"]'::jsonb, '[{"element":"حساب ΔT للرمل","marks":1},{"element":"حساب ΔT للماء","marks":1},{"element":"حساب النسبة","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة ونسبة صحيحة وتفسير بالحرارة النوعية"},{"level":"2–3 درجات","description":"حسابان صحيحان مع خطأ في النسبة أو نقص في التفسير"},{"level":"1 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الضرب في c بدلًا من القسمة عليه","قلب النسبة","حساب ΔT للماء بالحرارة النوعية للرمل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-03T20:51:23.892Z"}'::jsonb),
('essay', 3, null::int, null, null, 'لو أصبحت الحرارة النوعية لماء البحر منخفضة كحرارة الرمل، فإن امتصاص الكمية نفسها من طاقة الشمس سيرفع درجة حرارته كثيرًا في النهار (ΔT = q ÷ (c × m) يكبر عندما يصغر c)، وفقد الحرارة ليلًا سيخفضها كثيرًا؛ فيصبح الفرق بين درجتي حرارة النهار والليل كبيرًا كما في الرمل. وهذا يعرّض المخلوقات البحرية لتقلبات حادة في درجة الحرارة قد لا تتحملها، ويفقد البحر دوره في تلطيف مناخ المناطق الساحلية لأنه لن يخزن كمية كبيرة من الحرارة مع تغير قليل في درجة حرارته.', '["ارتفاع كبير في درجة حرارة البحر نهارًا","انخفاض كبير ليلًا وفرق كبير بين النهار والليل","التعليل بالعلاقة بين ΔT وc","أثر في المخلوقات البحرية","فقد دور البحر في تلطيف المناخ الساحلي"]'::jsonb, '[]'::jsonb, '[{"element":"التنبؤ الصحيح بتغير درجة الحرارة نهارًا وليلًا","marks":2},{"element":"التعليل بالحرارة النوعية والعلاقة","marks":2},{"element":"أثر في المخلوقات البحرية","marks":1},{"element":"أثر في المناطق الساحلية","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تنبؤ صحيح مع تعليل كامل وأثرين منطقيين"},{"level":"4–5 درجات","description":"تنبؤ وتعليل صحيحان مع أثر واحد"},{"level":"2–3 درجات","description":"تنبؤ صحيح دون تعليل كافٍ"},{"level":"1 درجة","description":"عبارة صحيحة جزئيًّا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التنبؤ بأن البحر سيبقى معتدل الحرارة","إغفال تغير درجة الحرارة ليلًا","ذكر آثار دون ربطها بالحرارة النوعية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-03T20:51:23.892Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C1-L2-O06') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C1-L2-O07'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المسعر؟', null, null, '["جهاز يقيس سرعة التفاعل بتتبع تغير تركيز المواد مع الزمن","وعاء مفتوح يسمح بتبادل الحرارة بحرية مع الهواء المحيط به","جهاز يحوّل الطاقة الشمسية إلى طاقة كهربائية مباشرة","جهاز معزول حراريًّا يقيس كمية الحرارة الممتصة أو المنطلقة"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 19 — المسعر ومسعر القنبلة'),
('mcq', 2, 'في مسعر القنبلة، أين توضع العينة المراد حرقها؟', null, null, '["في الماء المحيط بالحجرة الفولاذية مباشرة","في حجرة فولاذية داخلية مملوءة بالأكسجين المضغوط","في كأس من البوليسترين مفتوحة على الهواء الجوي","في حجرة فولاذية داخلية مفرغة تمامًا من الغازات"]'::jsonb, 'تذكر', 'تذكر تركيب جهاز', 'سهل', 'الكتاب ص 19 — المسعر ومسعر القنبلة'),
('mcq', 3, 'يُحرَّك الماء المحيط بحجرة مسعر القنبلة بمحرك قليل الاحتكاك. لماذا يجب ألا يُنتج المحرك احتكاكًا؟', null, null, '["لأن الاحتكاك يبرّد الماء فتقل الحرارة المقيسة عن حقيقتها","لأن الاحتكاك يزيد سرعة التفاعل الكيميائي داخل الحجرة","لأن حرارة الاحتكاك تُضاف إلى الماء فتزيد الحرارة المقيسة","لأن الاحتكاك يُبطئ تحريك الماء فلا تتوزع الحرارة بانتظام"]'::jsonb, 'فهم', 'تعليل إجراء', 'متوسط', 'الكتاب ص 19 — المسعر ومسعر القنبلة'),
('mcq', 4, 'لماذا تُستعمل كأس البوليسترين مسعرًا بدلًا من كأس زجاجية؟', null, null, '["لأن البوليسترين عازل حراري يقلل انتقال الحرارة بين ما في الكأس والمحيط","لأن البوليسترين موصل جيد للحرارة ينقلها بسرعة إلى الماء","لأن البوليسترين يتفاعل مع الماء فيطلق حرارة تساعد على القياس","لأن البوليسترين يمتص كمية كبيرة من الحرارة فيرفع دقة القياس"]'::jsonb, 'فهم', 'تعليل اختيار مادة', 'متوسط', 'الكتاب ص 19، 42 — مسعر البوليسترين (س59)'),
('mcq', 5, 'تحت أيّ ظرف تحدث التفاعلات في مسعر كأس البوليسترين؟', null, null, '["عند حجم ثابت؛ لأن الكأس محكمة الإغلاق","عند ضغط مرتفع؛ لأن الكأس مملوءة بالأكسجين المضغوط","عند درجة حرارة ثابتة؛ لأن الماء لا تتغير حرارته","عند ضغط ثابت؛ لأن الكأس غير محكمة الإغلاق ومفتوحة على الجو"]'::jsonb, 'فهم', 'تحديد ظروف القياس', 'متوسط', 'الكتاب ص 19، 23 — مسعر البوليسترين والضغط الثابت'),
('mcq', 6, 'لتحديد الحرارة النوعية لفلز بمسعر البوليسترين تُنفَّذ الخطوات: (1) نقل الفلز الساخن إلى ماء المسعر، (2) قياس كتلة الماء ودرجة حرارته الأولية، (3) تحريك الماء وتسجيل أعلى درجة حرارة يصل إليها، (4) تسخين الفلز إلى درجة حرارة معلومة. ما الترتيب الصحيح؟', null, null, '["2، 1، 4، 3","2، 4، 1، 3","1، 2، 4، 3","2، 4، 3، 1"]'::jsonb, 'تطبيق', 'ترتيب خطوات إجراء', 'صعب', 'الكتاب ص 19–20، 22 — خطوات تحديد الحرارة النوعية لفلز'),
('mcq', 7, 'متى تُسجَّل درجة الحرارة النهائية عند تحديد الحرارة النوعية لفلز في المسعر؟', null, null, '["فور وضع الفلز في الماء قبل تحريكه","عندما تعود درجة حرارة الماء إلى قيمتها الأولية","عندما تتساوى درجتا حرارة الفلز والماء فتثبت القراءة","عندما تصل درجة حرارة الماء إلى درجة حرارة الفلز الأولية"]'::jsonb, 'فهم', 'فهم مبدأ القياس', 'متوسط', 'الكتاب ص 19–20 — مسعر كأس البوليسترين وتحديد الحرارة النوعية'),
('essay', 1, 'اشرح لماذا يجب معرفة كتلة الماء في المسعر بدقة، ولماذا يُستعمل البوليسترين في صنع المسعر البسيط.', null, null, null, 'فهم', 'شرح وتعليل', 'سهل', 'الكتاب ص 19، 24، 42 — المسعر (س18، س59)'),
('essay', 2, 'صف تركيب مسعر القنبلة، وكيف يُستعمل لقياس الطاقة المنطلقة من احتراق عينة من الطعام.', null, null, null, 'فهم', 'وصف جهاز وإجراء', 'صعب', 'الكتاب ص 19 — المسعر ومسعر القنبلة'),
('essay', 3, 'صمّم تجربة لتحديد الحرارة النوعية لقطعة فلز كتلتها 45.0 g باستعمال مسعر من البوليسترين، مبيّنًا الأدوات، والخطوات، والقياسات التي تسجلها، وطريقة الحساب، والافتراض الذي تقوم عليه.', null, null, null, 'إبداع', 'تصميم تجربة', 'صعب', 'الكتاب ص 19–20، 22، 24 — تحديد الحرارة النوعية لفلز (س22)')
