select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'المسعر جهاز معزول حراريًّا يُستعمل لقياس كمية الحرارة الممتصة أو المنطلقة في أثناء عملية كيميائية أو فيزيائية.', '["قياس سرعة التفاعل ليس وظيفة المسعر؛ فالمسعر يقيس كمية الحرارة.","المسعر معزول حراريًّا ليمنع تبادل الحرارة مع المحيط الخارجي، لا ليسمح به.","هذا وصف الخلية الكهروضوئية، لا المسعر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-03T20:51:23.892Z"}'::jsonb),
('mcq', 2, 1, 'في مسعر القنبلة توضع العينة في حجرة فولاذية داخلية مملوءة بالأكسجين المضغوط ضغطًا عاليًا، وحولها كمية معلومة من الماء.', '["الماء يحيط بالحجرة ليمتص الحرارة، والعينة لا توضع فيه.","","هذا وصف المسعر البسيط، لا مسعر القنبلة.","الاحتراق يحتاج إلى أكسجين، فالحجرة مملوءة بالأكسجين المضغوط لا مفرغة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-03T20:51:23.893Z"}'::jsonb),
('mcq', 3, 2, 'يقيس المسعر الحرارة من ارتفاع درجة حرارة الماء؛ فإذا أنتج المحرك احتكاكًا أضاف حرارة إلى الماء ليست من التفاعل، فتزيد الحرارة المقيسة على حقيقتها.', '["الاحتكاك يولّد حرارة ولا يبرّد الماء؛ فالخطأ يكون بالزيادة لا بالنقصان.","الاحتكاك يحدث في الماء خارج الحجرة، ومشكلته الحرارة الإضافية لا سرعة التفاعل.","","المشكلة الأساسية أن الاحتكاك يضيف حرارة غير ناتجة من التفاعل إلى الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-03T20:51:23.893Z"}'::jsonb),
('mcq', 4, 0, 'يجب أن تبقى الحرارة المنطلقة أو الممتصة داخل المسعر؛ والبوليسترين عازل حراري يقلل انتقال الحرارة بين ما في الكأس والمحيط، أما الزجاج فيوصل الحرارة ويمتص جزءًا منها.', '["","البوليسترين عازل حراري لا موصل، وهذا سبب استعماله.","البوليسترين لا يتفاعل مع الماء، وأي حرارة إضافية تفسد القياس.","امتصاص الكأس للحرارة يقلل دقة القياس؛ والمطلوب أن تكتسب الحرارة الماء وحده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:51:23.893Z"}'::jsonb),
('mcq', 5, 3, 'كأس البوليسترين مفتوحة على الجو فتحدث التفاعلات فيها عند ضغط ثابت، ولذلك تساوي الحرارة المقيسة فيها التغير في المحتوى الحراري: q_p = ΔH.', '["كأس البوليسترين غير محكمة الإغلاق، فهي مفتوحة على الجو.","الأكسجين المضغوط يخص حجرة مسعر القنبلة، لا كأس البوليسترين.","درجة حرارة الماء تتغير، وقياس هذا التغير هو أساس عمل المسعر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:51:23.893Z"}'::jsonb),
('mcq', 6, 1, 'تُقاس كتلة الماء ودرجة حرارته الأولية (2)، ويُسخَّن الفلز إلى درجة حرارة معلومة (4)، ثم يُنقل إلى ماء المسعر (1)، ثم يُحرَّك الماء وتُسجَّل أعلى درجة حرارة (3)؛ فالترتيب 2، 4، 1، 3.', '["لا يُنقل الفلز إلى الماء قبل تسخينه؛ فالتسخين يسبق النقل.","","نقل الفلز لا يمكن أن يكون الخطوة الأولى قبل تسخينه وقياس درجة حرارة الماء الأولية.","أعلى درجة حرارة تُسجَّل بعد نقل الفلز إلى الماء، لا قبله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-03T20:51:23.893Z"}'::jsonb),
('mcq', 7, 2, 'تنتقل الحرارة من الفلز الساخن إلى الماء، ويتوقف انتقالها عندما تتساوى درجتا حرارة الفلز والماء، فتثبت القراءة وتُسجَّل درجة الحرارة النهائية.', '["الحرارة لم تكن قد انتقلت بعدُ من الفلز إلى الماء، فالقراءة لا تمثل الحالة النهائية.","الماء اكتسب حرارة من الفلز فارتفعت درجة حرارته، ولا تعود إلى قيمتها الأولية في مسعر معزول.","","الفلز يبرد والماء يسخن حتى يلتقيا عند درجة حرارة بينهما، لا عند درجة حرارة الفلز الأولية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-03T20:51:23.894Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يقيس المسعر الحرارة الممتصة أو المنطلقة عن طريق التغير في درجة حرارة الماء، وتُحسب الحرارة من العلاقة q = c × m × ΔT؛ فلا يمكن حسابها دون معرفة كتلة الماء m، وأي خطأ فيها يسبب خطأً في q. ويُستعمل البوليسترين لأنه عازل حراري يقلل انتقال الحرارة بين محتويات الكأس والمحيط، فتبقى الحرارة داخل المسعر ويكتسبها الماء.', '["الحرارة تُحسب من التغير في درجة حرارة الماء","العلاقة q = c × m × ΔT تحتاج إلى m","البوليسترين عازل حراري","يقلل انتقال الحرارة إلى المحيط"]'::jsonb, '[]'::jsonb, '[{"element":"ربط كتلة الماء بحساب q بالعلاقة","marks":2},{"element":"تعليل استعمال البوليسترين بالعزل الحراري","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعليلان صحيحان كاملان"},{"level":"2–3 درجات","description":"تعليل صحيح كامل وآخر ناقص"},{"level":"1 درجة","description":"ذكر عبارة صحيحة دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن البوليسترين موصل جيد للحرارة","إغفال العلاقة q = c × m × ΔT","الخلط بين كتلة الماء وكتلة الفلز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-03T20:51:23.894Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يتكون مسعر القنبلة من حجرة تفاعل فولاذية داخلية محكمة الإغلاق تسمى القنبلة، توضع فيها العينة وتُملأ بالأكسجين المضغوط ضغطًا عاليًا، ويحيط بها كمية معلومة من الماء داخل وعاء محاط بمادة عازلة، ومعه محرك قليل الاحتكاك ومقياس حرارة وطرفا اشتعال. طريقة الاستعمال: توضع العينة في الحجرة، ويُحرَّك الماء للمحافظة على درجة حرارة منتظمة وتُسجَّل درجة حرارته الأولية، ثم يبدأ التفاعل بشرارة عبر طرفي الاشتعال، فتنتقل الحرارة المنطلقة من الاحتراق إلى الماء، وتُسجَّل درجة الحرارة حتى تصل إلى أقصاها. ثم تُحسب الحرارة التي اكتسبها الماء بالعلاقة q = c × m × ΔT، وهي تساوي الطاقة المنطلقة من احتراق العينة.', '["حجرة فولاذية فيها العينة والأكسجين المضغوط","كمية معلومة من الماء حولها ومادة عازلة","محرك قليل الاحتكاك ومقياس حرارة","بدء التفاعل بشرارة","تسجيل أعلى درجة حرارة","حساب q للماء بالعلاقة q = c × m × ΔT"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الحجرة الفولاذية ومحتوياتها","marks":1},{"element":"وصف الماء والعزل والمحرك ومقياس الحرارة","marks":1},{"element":"خطوات التشغيل: الشرارة وتسجيل أقصى درجة حرارة","marks":2},{"element":"حساب الطاقة من تغير درجة حرارة الماء","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"وصف كامل للتركيب وخطوات الاستعمال والحساب"},{"level":"4–5 درجات","description":"وصف صحيح مع نقص في عنصر واحد"},{"level":"2–3 درجات","description":"وصف التركيب دون خطوات القياس، أو العكس"},{"level":"1 درجة","description":"ذكر أنه جهاز لقياس الحرارة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن العينة توضع في الماء مباشرة","إغفال الأكسجين المضغوط","إغفال أن الحساب يعتمد على تغير درجة حرارة الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-03T20:51:23.894Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الأدوات: كأس بوليسترين (مسعر) بغطاء، ومقياس حرارة، وميزان، ومخبار مدرج، وكأس زجاجية فيها ماء يغلي على سخان، وملقط. الخطوات: (1) تُقاس كتلة الفلز (45.0 g). (2) يوضع الفلز في الماء المغلي مدة كافية، وتُعدّ درجة حرارة الماء المغلي درجة حرارته الأولية. (3) يوضع في كأس البوليسترين حجم معلوم من الماء (مثلًا 90.0 mL ≈ 90.0 g لأن كثافة الماء 1.0 g/mL) وتُقاس درجة حرارته الأولية. (4) يُنقل الفلز بالملقط بسرعة إلى المسعر ويُغطى. (5) يُحرَّك الماء وتُسجَّل أعلى درجة حرارة يصل إليها (درجة الحرارة النهائية). الحساب: q_water = 4.184 × m_water × (T_f − T_i,water)، ثم q_metal = −q_water، ثم c_metal = q_metal ÷ (45.0 g × (T_f − T_i,metal)). الافتراض: لا تُفقد حرارة إلى المحيط، فالحرارة التي فقدها الفلز تساوي الحرارة التي اكتسبها الماء.', '["أدوات مناسبة","تسخين الفلز إلى درجة حرارة معلومة","قياس كتلة الماء ودرجة حرارته الأولية","نقل الفلز وتسجيل أعلى درجة حرارة","حساب q_water ثم q_metal = −q_water ثم c","افتراض عدم فقد حرارة إلى المحيط"]'::jsonb, '["q_water = c_water × m_water × ΔT_water","q_metal = −q_water","c_metal = q_metal ÷ (m_metal × ΔT_metal)"]'::jsonb, '[{"element":"الأدوات","marks":1},{"element":"خطوات مرتبة صحيحة","marks":2},{"element":"القياسات المسجلة","marks":1},{"element":"طريقة الحساب","marks":1},{"element":"الافتراض","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تصميم كامل بخطوات مرتبة وقياسات وحساب وافتراض"},{"level":"4–5 درجات","description":"تصميم صحيح مع نقص في عنصر واحد"},{"level":"2–3 درجات","description":"خطوات صحيحة دون حساب أو افتراض"},{"level":"1 درجة","description":"عناصر متفرقة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال قياس درجة حرارة الماء الأولية","تسجيل درجة الحرارة فور وضع الفلز","إهمال الإشارة في q_metal = −q_water","إغفال افتراض عدم فقد الحرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-03T20:51:23.894Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
