('mcq', 2, 'أيّ العلاقات الآتية تعبّر عن التغير في المحتوى الحراري للتفاعل ΔHrxn؟', null, null, '["ΔHrxn = Hreactants − Hproducts","ΔHrxn = Hproducts + Hreactants","ΔHrxn = Hproducts ÷ Hreactants","ΔHrxn = Hproducts − Hreactants"]'::jsonb, 'تذكر', 'تذكر علاقة', 'سهل', 'الكتاب ص 23 — المحتوى الحراري وتغيراته'),
('mcq', 3, 'لماذا يقيس الكيميائيون التغير في المحتوى الحراري ΔH بدلًا من المحتوى الحراري H للمادة؟', null, null, '["لأنه لا يمكن قياس المحتوى الحراري الفعلي للمادة، ويمكن قياس التغير فيه","لأن المحتوى الحراري للمادة يساوي صفرًا دائمًا عند ضغط ثابت","لأن التغير في المحتوى الحراري لا يعتمد على المواد المتفاعلة والناتجة","لأن المحتوى الحراري لا يتغير في أثناء التفاعلات الكيميائية"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 22–23 — المحتوى الحراري وتغيراته'),
('mcq', 4, 'ما الاسم الآخر الذي يُطلق على التغير في المحتوى الحراري للتفاعل (ΔHrxn)؟', null, null, '["الحرارة النوعية","طاقة الوضع الكيميائية","حرارة التفاعل","المحتوى الحراري"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'سهل', 'الكتاب ص 23 — المحتوى الحراري للتفاعل (حرارة التفاعل)'),
('mcq', 5, 'في العلاقة ΔHrxn = Hfinal − Hinitial، إلامَ يشير الرمز Hfinal؟', null, null, '["المحتوى الحراري للمواد الموجودة عند نهاية التفاعل، أي النواتج","المحتوى الحراري للمواد الموجودة في بداية التفاعل، أي المتفاعلات","كمية الحرارة التي يكتسبها المحيط في نهاية التفاعل","أعلى درجة حرارة يصل إليها خليط التفاعل في المسعر"]'::jsonb, 'فهم', 'تفسير رمز', 'متوسط', 'الكتاب ص 23 — ΔHrxn = Hfinal − Hinitial'),
('mcq', 6, 'إذا كان المحتوى الحراري للنواتج في تفاعل ما أقل من المحتوى الحراري للمتفاعلات بمقدار 50 kJ، فما قيمة ΔHrxn؟', null, null, '["+50 kJ","صفر kJ","+100 kJ","−50 kJ"]'::jsonb, 'تطبيق', 'تطبيق علاقة', 'متوسط', 'الكتاب ص 23 — ΔHrxn = Hproducts − Hreactants'),
('mcq', 7, 'للتفاعل الذي يحدث في الكمادة الساخنة: 4Fe(s) + 3O₂(g) → 2Fe₂O₃(s)، أيّ العلاقات الآتية تعبّر عن ΔHrxn؟', null, null, '["ΔHrxn = H(4Fe + 3O₂) − H(2Fe₂O₃)","ΔHrxn = H(2Fe₂O₃) − H(4Fe + 3O₂)","ΔHrxn = H(2Fe₂O₃) + H(4Fe + 3O₂)","ΔHrxn = H(4Fe) − H(3O₂)"]'::jsonb, 'تطبيق', 'تطبيق علاقة على تفاعل', 'صعب', 'الكتاب ص 23 — إشارة المحتوى الحراري للتفاعل (الكمادة الساخنة)'),
('essay', 1, 'عرّف كلًّا من: المحتوى الحراري (H)، والتغير في المحتوى الحراري للتفاعل (ΔHrxn)، ثم اكتب العلاقة التي تُحسب بها ΔHrxn موضحًا معنى كل رمز فيها.', null, null, null, 'تذكر', 'تعريف وكتابة علاقة', 'سهل', 'الكتاب ص 23 — المحتوى الحراري وتغيراته'),
('essay', 2, '«لا نستطيع قياس المحتوى الحراري لمادة ما، لكننا نستطيع قياس التغير فيه». فسّر هذه العبارة، ووضّح كيف يمكن قياس التغير في المحتوى الحراري لتفاعل ما عمليًّا.', null, null, null, 'فهم', 'تفسير عبارة', 'متوسط', 'الكتاب ص 22–23 — المحتوى الحراري وتغيراته'),
('essay', 3, 'تعمل الكمادة الباردة وفق العملية: NH₄NO₃(s) → NH₄⁺(aq) + NO₃⁻(aq)، وفيها يزيد المحتوى الحراري للنواتج على المحتوى الحراري للمتفاعلات بمقدار 27 kJ. حدّد المتفاعلات والنواتج، واكتب علاقة ΔHrxn لهذه العملية بدلالة المحتوى الحراري لكل منها، ثم استنتج قيمة ΔHrxn.', null, null, null, 'تطبيق', 'تطبيق علاقة واستنتاج', 'صعب', 'الكتاب ص 23–24 — ΔHrxn = Hproducts − Hreactants (الكمادة الباردة)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
