from (values
('mcq', 1, 1, 'المحتوى الحراري (H) هو مقدار الطاقة الحرارية المخزنة في مول واحد من المادة تحت ضغط ثابت.', '["هذا تعريف الحرارة النوعية للمادة، لا المحتوى الحراري.","","التعريف يخص مولًا واحدًا من المادة تحت ضغط ثابت، لا جرامًا واحدًا تحت حجم ثابت.","هذا وصف حرارة الاحتراق، وهي نوع من التغير في المحتوى الحراري وليست تعريف المحتوى الحراري نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-03T20:51:23.895Z"}'::jsonb),
('mcq', 2, 3, 'ΔHrxn هو الفرق بين المحتوى الحراري للمواد عند نهاية التفاعل (النواتج) والمحتوى الحراري للمواد في بدايته (المتفاعلات): ΔHrxn = Hproducts − Hreactants.', '["عكس ترتيب الطرح؛ التغير يساوي القيمة النهائية مطروحًا منها القيمة الابتدائية، أي النواتج ناقص المتفاعلات.","الرمز Δ يعني التغير، أي الفرق بين قيمتين، لا مجموعهما.","التغير في خاصية ما يُحسب بالطرح لا بالقسمة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-03T20:51:23.895Z"}'::jsonb),
('mcq', 3, 0, 'الطاقة الكلية في المادة تعتمد على عوامل كثيرة، فلا يمكن قياس المحتوى الحراري الفعلي للمادة، لكن يمكن قياس التغير فيه، وهو كمية الحرارة الممتصة أو المنطلقة في التفاعل.', '["","المحتوى الحراري للمادة ليس صفرًا؛ لكنه لا يمكن قياسه فعليًّا.","ΔHrxn يعتمد على المحتوى الحراري للنواتج والمتفاعلات، فهو الفرق بينهما.","المحتوى الحراري يتغير في التفاعلات؛ ولهذا نقيس ΔH الذي يساوي الحرارة الممتصة أو المنطلقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-03T20:51:23.896Z"}'::jsonb),
('mcq', 4, 2, 'يُسمّى التغير في المحتوى الحراري للتفاعل ΔHrxn أيضًا حرارة التفاعل.', '["الحرارة النوعية خاصية للمادة تخص رفع درجة حرارة 1 g منها 1°C، ولا تعبر عن حرارة التفاعل.","طاقة الوضع الكيميائية هي الطاقة المخزنة في الروابط، وليست اسمًا للتغير في المحتوى الحراري.","","المحتوى الحراري H هو الطاقة المخزنة نفسها، أما ΔHrxn فهو التغير فيها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-03T20:51:23.896Z"}'::jsonb),
('mcq', 5, 0, 'Hfinal هو المحتوى الحراري للمواد التي توجد عند نهاية التفاعل، وهي النواتج؛ لذا تُكتب العلاقة أيضًا ΔHrxn = Hproducts − Hreactants.', '["","هذا معنى Hinitial، أي المحتوى الحراري للمتفاعلات في البداية.","Hfinal خاصية للمواد الناتجة في النظام، وليس حرارة يكتسبها المحيط.","H يرمز إلى المحتوى الحراري (طاقة)، وليس إلى درجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-03T20:51:23.896Z"}'::jsonb),
('mcq', 6, 3, 'ΔHrxn = Hproducts − Hreactants، وبما أن Hproducts أقل من Hreactants بمقدار 50 kJ فإن الفرق = −50 kJ.', '["هذه نتيجة طرح Hproducts من Hreactants (عكس العلاقة)؛ والصحيح أن النواتج أقل فالفرق سالب.","الفرق بين المحتويين 50 kJ وليس صفرًا؛ الصفر يعني تساوي المحتوى الحراري للنواتج والمتفاعلات.","ضاعف الطالب الفرق وعكس إشارته؛ الفرق بين المحتويين 50 kJ فقط وإشارته سالبة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-03T20:51:23.897Z"}'::jsonb),
('mcq', 7, 1, 'النواتج هنا 2Fe₂O₃ والمتفاعلات 4Fe + 3O₂، ولأن ΔHrxn = Hproducts − Hreactants فإن ΔHrxn = H(2Fe₂O₃) − H(4Fe + 3O₂).', '["طرح الطالب النواتج من المتفاعلات، وهذا عكس العلاقة الصحيحة.","","التغير في المحتوى الحراري فرق بين النواتج والمتفاعلات، لا مجموعهما.","العلاقة تقارن النواتج بالمتفاعلات، لا متفاعلًا بمتفاعل آخر؛ وقد أُهمل الناتج Fe₂O₃."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-03T20:51:23.897Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المحتوى الحراري (H): مقدار الطاقة الحرارية المخزنة في مول واحد من المادة تحت ضغط ثابت. التغير في المحتوى الحراري للتفاعل (ΔHrxn) ويسمى حرارة التفاعل: كمية الحرارة الممتصة أو المنطلقة في التفاعل الكيميائي، وهو الفرق بين المحتوى الحراري للمواد في نهاية التفاعل والمحتوى الحراري للمواد في بدايته. العلاقة: ΔHrxn = Hproducts − Hreactants، حيث Hproducts المحتوى الحراري للنواتج (المواد عند نهاية التفاعل)، وHreactants المحتوى الحراري للمتفاعلات (المواد في بداية التفاعل)، والرمز Δ يعني التغير.', '["تعريف H: الطاقة الحرارية المخزنة في مول واحد من المادة تحت ضغط ثابت","تعريف ΔHrxn: كمية الحرارة الممتصة أو المنطلقة في التفاعل (حرارة التفاعل)","العلاقة ΔHrxn = Hproducts − Hreactants","توضيح الرموز: النواتج في النهاية، والمتفاعلات في البداية، وΔ تعني التغير"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف المحتوى الحراري","marks":1},{"element":"تعريف التغير في المحتوى الحراري للتفاعل","marks":1},{"element":"كتابة العلاقة صحيحة","marks":1},{"element":"توضيح معنى الرموز","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريفان صحيحان كاملان، وعلاقة صحيحة، ورموز موضحة"},{"level":"2–3 درجات","description":"تعريفان صحيحان مع خطأ في العلاقة أو نقص في توضيح الرموز، أو العكس"},{"level":"1 درجة","description":"تعريف واحد صحيح أو العلاقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال شرط «مول واحد» أو «ضغط ثابت» في تعريف المحتوى الحراري","الخلط بين المحتوى الحراري والحرارة النوعية","كتابة العلاقة معكوسة: Hreactants − Hproducts"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-03T20:51:23.897Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تعتمد كمية الحرارة الكلية التي تحتوي عليها المادة على عوامل كثيرة بعضها غير مفهوم تمامًا، لذا يستحيل معرفة الطاقة الكلية أو قياس المحتوى الحراري الفعلي للمادة. أما التغير في المحتوى الحراري فيساوي كمية الحرارة الممتصة أو المنطلقة في التفاعل، ويمكن قياسها: يُجرى التفاعل في مسعر (مثل كأس البوليسترين) عند ضغط ثابت، وتُقاس كتلة الماء والتغير في درجة حرارته، ثم تُحسب الحرارة التي اكتسبها الماء أو فقدها بالعلاقة q = c × m × ΔT، وهي تساوي (بإشارة معاكسة) الحرارة التي أطلقها التفاعل أو امتصها؛ لذلك يهتم الكيميائيون بتغيرات الطاقة أكثر من اهتمامهم بكمية الطاقة نفسها.', '["الطاقة الكلية في المادة تعتمد على عوامل كثيرة فلا يمكن قياس H الفعلي","ΔH يساوي الحرارة الممتصة أو المنطلقة في التفاعل","القياس بالمسعر عند ضغط ثابت","استعمال q = c × m × ΔT لماء المسعر"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير عدم إمكان قياس H","marks":1},{"element":"ربط ΔH بالحرارة الممتصة أو المنطلقة","marks":1},{"element":"وصف القياس بالمسعر عند ضغط ثابت","marks":1},{"element":"ذكر علاقة حساب الحرارة من تغير درجة حرارة الماء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح وربط ΔH بالحرارة ووصف كامل لطريقة القياس"},{"level":"2–3 درجات","description":"تفسير صحيح مع وصف ناقص لطريقة القياس"},{"level":"1 درجة","description":"ذكر أن H لا يقاس دون تفسير أو دون طريقة قياس"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المحتوى الحراري للمادة يساوي صفرًا","الخلط بين قياس درجة الحرارة وقياس المحتوى الحراري","إغفال شرط الضغط الثابت عند القياس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-03T20:51:23.898Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المتفاعل: NH₄NO₃(s) (المادة في بداية العملية)، والنواتج: NH₄⁺(aq) + NO₃⁻(aq) (المواد عند نهايتها). العلاقة: ΔHrxn = Hproducts − Hreactants = H(NH₄⁺ + NO₃⁻) − H(NH₄NO₃). وبما أن المحتوى الحراري للنواتج يزيد على المحتوى الحراري للمتفاعلات بمقدار 27 kJ فإن ΔHrxn = +27 kJ.', '["المتفاعل NH₄NO₃(s)","النواتج NH₄⁺(aq) + NO₃⁻(aq)","ΔHrxn = H(NH₄⁺ + NO₃⁻) − H(NH₄NO₃)","ΔHrxn = +27 kJ"]'::jsonb, '["تحديد المتفاعل (البداية) والنواتج (النهاية)","كتابة ΔHrxn = Hproducts − Hreactants بالمواد المعطاة","Hproducts − Hreactants = +27 kJ لأن النواتج أعلى بمقدار 27 kJ"]'::jsonb, '[{"element":"تحديد المتفاعلات والنواتج","marks":1},{"element":"كتابة العلاقة بالمواد","marks":1},{"element":"استنتاج ΔHrxn = +27 kJ بالإشارة الصحيحة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تحديد صحيح، وعلاقة صحيحة، وقيمة صحيحة بإشارتها"},{"level":"2 درجتان","description":"تحديد وعلاقة صحيحان مع خطأ في الإشارة، أو قيمة صحيحة بلا علاقة"},{"level":"1 درجة","description":"تحديد المتفاعلات والنواتج فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة العلاقة معكوسة فتنتج −27 kJ","عدّ الأيونات الناتجة متفاعلات","إهمال الإشارة الموجبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-03T20:51:23.898Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
