from (values
('mcq', 1, 2, 'في التفاعل الطارد للحرارة يكون المحتوى الحراري للنواتج أقل من المحتوى الحراري للمتفاعلات، فتكون ΔHrxn سالبة دائمًا.', '["الإشارة الموجبة خاصة بالتفاعلات والعمليات الماصة للحرارة.","ΔH = صفر يعني عدم انطلاق حرارة أو امتصاصها، والتفاعل الطارد يطلق حرارة.","","إشارة ΔH للتفاعل الطارد ثابتة وسالبة دائمًا، ولا تتغير من تفاعل طارد إلى آخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-03T20:51:23.899Z"}'::jsonb),
('mcq', 2, 0, 'في التفاعل الطارد تفقد المتفاعلات حرارة، فيكون Hproducts < Hreactants، وعند طرح Hreactants الأكبر من Hproducts الأصغر نحصل على قيمة سالبة لـ ΔHrxn.', '["","هذا ما يحدث في التفاعل الماص للحرارة، وفيه تكون ΔH موجبة.","التفاعل الطارد يطلق حرارة إلى المحيط فترتفع درجة حرارة المحيط؛ والإشارة سببها مقارنة المحتوى الحراري لا انخفاض الحرارة.","في التفاعل الطارد تنتقل الحرارة من النظام إلى المحيط، لا العكس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-03T20:51:23.900Z"}'::jsonb),
('mcq', 3, 3, 'ΔH = +27 kJ موجبة، أي أن Hproducts > Hreactants وأن النظام امتص 27 kJ من المحيط؛ فالعملية ماصة للحرارة.', '["الإشارة الموجبة لـ ΔH تدل على عملية ماصة، لا طاردة.","تحديد النوع يعتمد على إشارة ΔH لا على كون النواتج أيونات، والإشارة هنا موجبة فالعملية ماصة.","النوع صحيح لكن التعليل خاطئ؛ ففي العملية الماصة يكون Hproducts أكبر من Hreactants.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-03T20:51:23.900Z"}'::jsonb),
('mcq', 4, 1, 'ظهور 185 kJ في جهة النواتج يعني أن التفاعل يطلق هذه الحرارة، أي أنه طارد للحرارة، فتكون ΔHrxn = −185 kJ.', '["كتابة الطاقة مع النواتج تعني انطلاقها، والتفاعل الطارد إشارة ΔH له سالبة لا موجبة.","","ضاعف الطالب القيمة بسبب المعامل 2 أمام HCl وأخطأ الإشارة؛ والحرارة المكتوبة تخص المعادلة كما هي.","قسم الطالب على المعامل 2؛ وهذه القيمة تخص مولًا واحدًا من HCl لا المعادلة كما كُتبت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-03T20:51:23.900Z"}'::jsonb),
('mcq', 5, 2, 'ظهور 572 kJ في جهة المتفاعلات يعني أن التفاعل يمتص هذه الطاقة، فهو ماص للحرارة وΔHrxn = +572 kJ.', '["الطاقة المكتوبة مع المتفاعلات تُمتص ولا تنطلق؛ فالتفاعل ماص وإشارته موجبة.","الإشارة الموجبة صحيحة، لكن التفاعل الذي ΔH له موجبة ماص للحرارة لا طارد.","","التفاعل ماص فعلًا، لكن إشارة ΔH للتفاعل الماص موجبة لا سالبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-03T20:51:23.901Z"}'::jsonb),
('mcq', 6, 0, 'ΔH سالبة تعني Hproducts − Hreactants < 0، أي أن المحتوى الحراري للنظام قبل التفاعل (المتفاعلات) أكبر منه بعد التفاعل (النواتج)، والفرق انطلق إلى المحيط.', '["","هذه حال التفاعل الماص الذي تكون ΔH له موجبة.","تساوي الطاقتين يعني ΔH = صفر، لا قيمة سالبة.","ΔH سالبة تعني نقصان المحتوى الحراري، لا انعدامه؛ والمحتوى الحراري الفعلي لا يُقاس أصلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-03T20:51:23.901Z"}'::jsonb),
('mcq', 7, 3, 'العملية الماصة للحرارة إشارة ΔH لها موجبة، والعمليتان ذواتا الإشارة الموجبة هما (1) التبخر +40.7 kJ و(4) الانصهار +6.01 kJ.', '["العملية (2) التجمد ΔH لها −6.01 kJ سالبة، فهي طاردة للحرارة.","كلتا العمليتين (2) و(3) إشارتهما سالبة، فهما طاردتان للحرارة.","العملية (3) احتراق الميثان ΔH لها −891 kJ سالبة، فهي طاردة للحرارة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-03T20:51:23.901Z"}'::jsonb),
('essay', 1, null::int, null, null, 'في التفاعل الطارد للحرارة تفقد المتفاعلات حرارة تنطلق إلى المحيط، فيكون المحتوى الحراري للنواتج أقل من المحتوى الحراري للمتفاعلات (Hproducts < Hreactants)، وعند طرح Hreactants الأكبر من Hproducts الأصغر نحصل على قيمة سالبة لـ ΔHrxn. أما في التفاعل الماص للحرارة فيمتص النظام حرارة من المحيط، فيزيد المحتوى الحراري للنواتج على المحتوى الحراري للمتفاعلات (Hproducts > Hreactants)، وعند طرح Hreactants الأصغر من Hproducts الأكبر نحصل على قيمة موجبة لـ ΔHrxn.', '["الطارد: المتفاعلات تفقد حرارة إلى المحيط","الطارد: Hproducts < Hreactants فتكون ΔH سالبة","الماص: النظام يمتص حرارة من المحيط","الماص: Hproducts > Hreactants فتكون ΔH موجبة"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير الطارد: فقد الحرارة ومقارنة المحتوى الحراري","marks":1},{"element":"استنتاج الإشارة السالبة من العلاقة","marks":1},{"element":"تفسير الماص: امتصاص الحرارة ومقارنة المحتوى الحراري","marks":1},{"element":"استنتاج الإشارة الموجبة من العلاقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل للحالتين مع مقارنة المحتوى الحراري واستنتاج الإشارة من العلاقة"},{"level":"2–3 درجات","description":"تفسير صحيح لحالة واحدة كاملًا، أو للحالتين دون الربط بالعلاقة"},{"level":"1 درجة","description":"ذكر الإشارتين فقط دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الربط بين الإشارة السالبة وانخفاض درجة حرارة المحيط","عكس ترتيب الطرح في العلاقة","ذكر الإشارة دون مقارنة المحتوى الحراري للنواتج والمتفاعلات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-03T20:51:23.902Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) 4Fe(s) + 3O₂(g) → 2Fe₂O₃(s)  ΔHrxn = −1625 kJ؛ التفاعل طارد للحرارة لأن الطاقة تظهر في جهة النواتج (تنطلق)، فيكون Hproducts < Hreactants وΔH سالبة. (ب) NH₄NO₃(s) → NH₄⁺(aq) + NO₃⁻(aq)  ΔHrxn = +27 kJ؛ العملية ماصة للحرارة لأن الطاقة تظهر في جهة المتفاعلات (تُمتص)، فيكون Hproducts > Hreactants وΔH موجبة.', '["(أ) ΔHrxn = −1625 kJ","(أ) طارد للحرارة لأن الطاقة تنطلق مع النواتج","(ب) ΔHrxn = +27 kJ","(ب) ماص للحرارة لأن الطاقة تُمتص مع المتفاعلات"]'::jsonb, '["حذف الطاقة من المعادلة وكتابتها قيمةً لـ ΔHrxn بعد المعادلة","الطاقة في جهة النواتج ← ΔH سالبة؛ وفي جهة المتفاعلات ← ΔH موجبة","تحديد النوع من الإشارة"]'::jsonb, '[{"element":"كتابة معادلة (أ) بقيمة −1625 kJ","marks":1},{"element":"تحديد نوع (أ) وتعليله","marks":1},{"element":"كتابة معادلة (ب) بقيمة +27 kJ","marks":1},{"element":"تحديد نوع (ب) وتعليله","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المعادلتان صحيحتان بإشارتيهما، والنوعان صحيحان معللان"},{"level":"2–3 درجات","description":"معادلة واحدة صحيحة كاملة، أو الإشارتان صحيحتان دون تعليل"},{"level":"1 درجة","description":"تحديد نوع تفاعل واحد فقط تحديدًا صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إبقاء الإشارة موجبة لأن الرقم مكتوب في المعادلة بلا إشارة","ترك الطاقة في المعادلة وكتابة ΔH معها في الوقت نفسه","عكس العلاقة بين موضع الطاقة ونوع التفاعل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-03T20:51:23.902Z"}'::jsonb),
('essay', 3, null::int, null, null, 'النظام هو خليط التفاعل في الكأس، والمحيط يشمل الكأس واللوح والماء. التفاعل ماص للحرارة، فتنتقل الحرارة من المحيط (الماء واللوح) إلى النظام، ويكون المحتوى الحراري للنواتج أكبر من المحتوى الحراري للمتفاعلات، فإشارة ΔH موجبة. ولأن الماء الموجود بين اللوح والكأس يفقد حرارة كافية لصالح التفاعل، تنخفض درجة حرارته إلى درجة التجمد فيتجمد، فيلتصق اللوح بالكأس.', '["التفاعل ماص للحرارة وإشارة ΔH موجبة","تنتقل الحرارة من المحيط (الماء واللوح) إلى النظام (خليط التفاعل)","Hproducts > Hreactants","الماء يفقد حرارة كافية فيتجمد"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الإشارة الموجبة ونوع التفاعل","marks":1},{"element":"اتجاه انتقال الحرارة من المحيط إلى النظام","marks":1},{"element":"ربط الإشارة بمقارنة المحتوى الحراري","marks":1},{"element":"تفسير تجمد الماء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إشارة صحيحة، واتجاه انتقال صحيح، وتعليل بالمحتوى الحراري، وتفسير التجمد"},{"level":"2–3 درجات","description":"إشارة واتجاه صحيحان مع نقص في التعليل أو في تفسير التجمد"},{"level":"1 درجة","description":"تحديد الإشارة أو النوع فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ التفاعل طاردًا لأنه «يُخرج برودة»","عكس اتجاه انتقال الحرارة","الخلط بين النظام والمحيط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-03T20:51:23.902Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C1-L2-O09') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

