select (select id from public.objectives where code = 'K22-C1-L2-O10'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ماذا يمثل المحور الرأسي (؟) في مخطط المحتوى الحراري الآتي؟', null, '[{"src":"qimg/chem22/c1-axis-q.svg","alt":"مخطط محتوى حراري: مستوى المتفاعلات أعلى من مستوى النواتج وسهم ΔH إلى أسفل، والمحور الرأسي عليه علامة استفهام"}]'::jsonb, '["درجة حرارة خليط التفاعل","الزمن اللازم لحدوث التفاعل","كتلة المواد المتفاعلة والناتجة","المحتوى الحراري للمواد"]'::jsonb, 'تذكر', 'قراءة مخطط', 'سهل', 'الكتاب ص 23–24 — الشكلان 1-7 و1-8'),
('mcq', 2, 'يمثل المخطط الآتي المحتوى الحراري لتفاعل الكمادة الساخنة. ماذا يدل اتجاه السهم إلى أسفل؟', null, '[{"src":"qimg/chem22/c1-hot-pack.svg","alt":"مخطط المحتوى الحراري للكمادة الساخنة: مستوى 4Fe(s) + 3O₂(g) أعلى من مستوى 2Fe₂O₃(s)، وسهم إلى أسفل ΔH = −1625 kJ"}]'::jsonb, '["أن 1625 kJ من الحرارة امتصت من المحيط","أن 1625 kJ من الحرارة انطلقت إلى المحيط","أن المحتوى الحراري للنواتج أكبر من المتفاعلات","أن التفاعل لا يحدث إلا عند تسخين المتفاعلات"]'::jsonb, 'فهم', 'تفسير اتجاه السهم', 'سهل', 'الكتاب ص 23 — الشكل 1-7'),
('mcq', 3, 'اعتمادًا على مخطط المحتوى الحراري الآتي، ما نوع التفاعل؟ وكيف عرفت ذلك؟', null, '[{"src":"qimg/chem22/c1-endo-233.svg","alt":"مخطط محتوى حراري: مستوى المتفاعلات في الأسفل ومستوى النواتج في الأعلى، وسهم إلى أعلى مكتوب عليه ΔH = +233 kJ"}]'::jsonb, '["طارد للحرارة؛ لأن السهم يتجه من المتفاعلات إلى النواتج","طارد للحرارة؛ لأن مستوى النواتج أعلى من مستوى المتفاعلات","ماص للحرارة؛ لأن مستوى النواتج أعلى وΔH موجبة","ماص للحرارة؛ لأن مستوى المتفاعلات أعلى وΔH سالبة"]'::jsonb, 'تحليل', 'تفسير مخطط', 'متوسط', 'الكتاب ص 42 — س60 (الشكل 1-17)'),
('mcq', 4, 'أيّ وصف لمخطط المحتوى الحراري يمثل عملية الكمادة الباردة: NH₄NO₃(s) → NH₄⁺(aq) + NO₃⁻(aq)  ΔH = +27 kJ؟', null, null, '["مستوى NH₄⁺(aq) + NO₃⁻(aq) أعلى من مستوى NH₄NO₃(s) بمقدار 27 kJ، والسهم إلى أعلى","مستوى NH₄NO₃(s) أعلى من مستوى NH₄⁺(aq) + NO₃⁻(aq) بمقدار 27 kJ، والسهم إلى أسفل","مستوى NH₄⁺(aq) + NO₃⁻(aq) أدنى من مستوى NH₄NO₃(s) بمقدار 27 kJ، والسهم إلى أعلى","المستويان متساويان، وسهم أفقي مكتوب عليه 27 kJ"]'::jsonb, 'تحليل', 'اختيار المخطط المناسب', 'متوسط', 'الكتاب ص 24 — الشكل 1-8'),
('mcq', 5, 'اعتمادًا على مخطط المحتوى الحراري للماء الآتي، ما قيمة ΔH للتحول H₂O(l) → H₂O(s)؟', null, '[{"src":"qimg/chem22/c1-water-levels.svg","alt":"مستويات المحتوى الحراري للماء: H₂O(s) في الأسفل ثم H₂O(l) أعلى منه بمقدار 6.01 kJ ثم H₂O(g) أعلى بمقدار 40.7 kJ"}]'::jsonb, '["+6.01 kJ","−6.01 kJ","−40.7 kJ","−46.7 kJ"]'::jsonb, 'تحليل', 'قراءة مخطط متعدد المستويات', 'متوسط', 'الكتاب ص 43 — الشكل 1-18'),
('mcq', 6, 'اعتمادًا على مخطط المحتوى الحراري للماء الآتي، ما الطاقة اللازمة لتحويل 1 mol من H₂O(s) إلى H₂O(g)؟', null, '[{"src":"qimg/chem22/c1-water-levels.svg","alt":"مستويات المحتوى الحراري للماء: H₂O(s) في الأسفل ثم H₂O(l) أعلى منه بمقدار 6.01 kJ ثم H₂O(g) أعلى بمقدار 40.7 kJ"}]'::jsonb, '["34.7 kJ","40.7 kJ","46.7 kJ","6.01 kJ"]'::jsonb, 'تحليل', 'استنتاج من مخطط', 'صعب', 'الكتاب ص 43 — الشكل 1-18'),
('mcq', 7, 'يمثل الشكل الآتي مخططي المحتوى الحراري لتفاعلين (س) و(ص). أيّ العبارات الآتية صحيحة؟', null, '[{"src":"qimg/chem22/c1-two-diagrams.svg","alt":"مخططا محتوى حراري: في (س) سهم إلى أسفل مقداره 90 kJ من المتفاعلات إلى النواتج، وفي (ص) سهم إلى أعلى مقداره 30 kJ"}]'::jsonb, '["التفاعل (س) طارد وΔH له −90 kJ، والتفاعل (ص) ماص وΔH له +30 kJ","التفاعل (س) ماص وΔH له +90 kJ، والتفاعل (ص) طارد وΔH له −30 kJ","التفاعلان طاردان؛ لأن السهم في كلا المخططين يبدأ من المتفاعلات","التفاعل (س) طارد وΔH له +90 kJ، والتفاعل (ص) ماص وΔH له −30 kJ"]'::jsonb, 'تحليل', 'مقارنة مخططين', 'صعب', 'الكتاب ص 23–24 — الشكلان 1-7 و1-8'),
('essay', 1, 'يمثل المخطط الآتي المحتوى الحراري لتفاعل الكمادة الساخنة (الحرارة تنطلق من النظام إلى المحيط). فسّر هذا المخطط مبينًا: نوع التفاعل، ودلالة موقعي المستويين، ودلالة اتجاه السهم، وإشارة ΔH.', null, '[{"src":"qimg/chem22/c1-hot-pack.svg","alt":"مخطط المحتوى الحراري للكمادة الساخنة: مستوى 4Fe(s) + 3O₂(g) أعلى من مستوى 2Fe₂O₃(s)، وسهم إلى أسفل ΔH = −1625 kJ"}]'::jsonb, null, 'تحليل', 'تفسير مخطط', 'متوسط', 'الكتاب ص 23 — الشكل 1-7'),
('essay', 2, 'صِف كيف ترسم مخطط المحتوى الحراري لعملية الكمادة الباردة: NH₄NO₃(s) → NH₄⁺(aq) + NO₃⁻(aq)  ΔH = +27 kJ، محددًا: ما يمثله المحور الرأسي، وموقعي مستوى المتفاعل ومستوى النواتج، واتجاه السهم وما يُكتب عليه، واتجاه انتقال الحرارة بين النظام والمحيط. ثم قارن مخططك بمخطط تفاعل طارد للحرارة.', null, null, null, 'إبداع', 'تصميم مخطط ومقارنة', 'صعب', 'الكتاب ص 24 — الشكل 1-8'),
('essay', 3, 'في مخطط المحتوى الحراري للماء تظهر ثلاثة مستويات: H₂O(s) في الأسفل، وH₂O(l) فوقه، وH₂O(g) في الأعلى، وعليه الأسهم: ΔHfus = +6.01 kJ وΔHvap = +40.7 kJ إلى أعلى، وΔHcond = −40.7 kJ وΔHsolid = −6.01 kJ إلى أسفل.
(أ) فسّر لماذا تتساوى ΔHvap وΔHcond في المقدار وتختلفان في الإشارة.
(ب) احسب ΔH لتحويل 1 mol من H₂O(g) إلى H₂O(s)، وحدد هل العملية ماصة أم طاردة للحرارة.', null, '[{"src":"qimg/chem22/c1-water-levels.svg","alt":"مستويات المحتوى الحراري للماء: H₂O(s) في الأسفل ثم H₂O(l) أعلى منه بمقدار 6.01 kJ ثم H₂O(g) أعلى بمقدار 40.7 kJ"}]'::jsonb, null, 'تحليل', 'تحليل مخطط وحساب', 'صعب', 'الكتاب ص 43 — الشكل 1-18')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
