insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'يمثل المحور الرأسي في مخطط المحتوى الحراري المحتوى الحراري H، ويُرسم مستوى المتفاعلات ومستوى النواتج عليه، والفرق بينهما ΔH.', '["المخطط يقارن المحتوى الحراري (طاقة) لا درجة الحرارة.","مخطط المحتوى الحراري لا يمثل الزمن؛ بل يقارن مستويي طاقة المتفاعلات والنواتج.","الكتلة محفوظة في التفاعل، والمخطط يمثل المحتوى الحراري لا الكتلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-03T20:51:23.903Z"}'::jsonb),
('mcq', 2, 1, 'السهم المتجه إلى أسفل من المتفاعلات إلى النواتج يدل على نقص المحتوى الحراري، أي أن 1625 kJ من الحرارة انطلقت إلى المحيط، والتفاعل طارد وΔH < 0.', '["الامتصاص يمثله سهم متجه إلى أعلى، كما في الكمادة الباردة.","","مستوى النواتج 2Fe₂O₃ أدنى من مستوى المتفاعلات، فالمحتوى الحراري للنواتج أصغر لا أكبر.","المخطط يبين التغير في المحتوى الحراري فقط، ولا يدل اتجاه السهم على شروط بدء التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-03T20:51:23.904Z"}'::jsonb),
('mcq', 3, 2, 'مستوى النواتج أعلى من مستوى المتفاعلات، والسهم يتجه إلى أعلى، وΔH = +233 kJ موجبة؛ فالنواتج اكتسبت طاقة والتفاعل ماص للحرارة.', '["السهم يتجه دائمًا من المتفاعلات إلى النواتج، والذي يحدد النوع هو اتجاهه إلى أعلى أو أسفل؛ وهنا إلى أعلى فالتفاعل ماص.","ارتفاع مستوى النواتج يعني زيادة المحتوى الحراري، أي تفاعلًا ماصًّا لا طاردًا.","","وصف المخطط معكوس؛ فمستوى المتفاعلات هنا في الأسفل وΔH موجبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-03T20:51:23.905Z"}'::jsonb),
('mcq', 4, 0, 'ΔH = +27 kJ تعني أن المحتوى الحراري للنواتج (الأيونات) يزيد بمقدار 27 kJ على المتفاعل NH₄NO₃(s)، فيُرسم مستوى النواتج أعلى ويتجه السهم من المتفاعل إلى أعلى نحو النواتج.', '["","هذا مخطط تفاعل طارد ΔH له −27 kJ، لا عملية ماصة.","لا يتفق مستوى نواتج أدنى مع سهم يتجه إلى أعلى؛ فالسهم يتجه من المتفاعلات إلى النواتج.","تساوي المستويين يعني ΔH = صفر، وهذا يناقض امتصاص 27 kJ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-03T20:51:23.905Z"}'::jsonb),
('mcq', 5, 1, 'التحول من H₂O(l) إلى H₂O(s) انتقال إلى مستوى أدنى بمقدار 6.01 kJ، فيتجه السهم إلى أسفل وتكون ΔH = −6.01 kJ (تجمد، طارد للحرارة).', '["هذه قيمة الانصهار H₂O(s) → H₂O(l) الذي يتجه سهمه إلى أعلى، لا التجمد.","","هذه قيمة التكثف H₂O(g) → H₂O(l)، لا التحول من السائل إلى الصلب.","جمع الطالب الفرقين معًا؛ وهذه القيمة تخص التحول من الغاز إلى الصلب مباشرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-03T20:51:23.905Z"}'::jsonb),
('mcq', 6, 2, 'يصعد التحول من مستوى H₂O(s) إلى مستوى H₂O(l) (6.01 kJ) ثم إلى H₂O(g) (40.7 kJ)، فالطاقة اللازمة = 6.01 + 40.7 = 46.7 kJ، وΔH = +46.7 kJ.', '["طرح الطالب القيمتين (40.7 − 6.01)؛ والمستويان فوق بعضهما فتُجمع الفروق.","هذه طاقة التبخر فقط، وأُهملت طاقة الانصهار من الصلب إلى السائل.","","هذه طاقة الانصهار فقط، وأُهملت طاقة التبخر من السائل إلى الغاز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-03T20:51:23.906Z"}'::jsonb),
('mcq', 7, 0, 'السهم إلى أسفل يعني نقص المحتوى الحراري وانطلاق حرارة: (س) طارد وΔH = −90 kJ. والسهم إلى أعلى يعني زيادة المحتوى الحراري وامتصاص حرارة: (ص) ماص وΔH = +30 kJ.', '["","عكس الطالب دلالة اتجاه السهم؛ فالسهم إلى أسفل يدل على تفاعل طارد.","السهم يبدأ من المتفاعلات في كل مخطط، والنوع يحدده اتجاهه: إلى أسفل طارد وإلى أعلى ماص.","النوعان صحيحان لكن الإشارتين معكوستان؛ فالطارد ΔH له سالبة والماص موجبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-03T20:51:23.906Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التفاعل طارد للحرارة. يقع مستوى المتفاعلات (4Fe + 3O₂) أعلى من مستوى الناتج (2Fe₂O₃)، أي أن المحتوى الحراري للنواتج أقل من المحتوى الحراري للمتفاعلات. ويتجه السهم من المتفاعلات إلى أسفل نحو الناتج، دلالةً على نقص المحتوى الحراري بمقدار 1625 kJ انطلقت إلى المحيط (يدي الشخص). لذلك تكون ΔH = Hproducts − Hreactants سالبة: ΔH = −1625 kJ.', '["التفاعل طارد للحرارة","مستوى المتفاعلات أعلى من مستوى النواتج: Hproducts < Hreactants","السهم إلى أسفل يعني انطلاق 1625 kJ إلى المحيط","ΔH سالبة = −1625 kJ"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد نوع التفاعل","marks":1},{"element":"تفسير موقعي المستويين","marks":1},{"element":"تفسير اتجاه السهم","marks":1},{"element":"ربط ذلك بإشارة ΔH","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل للعناصر الأربعة مترابطة"},{"level":"2–3 درجات","description":"تفسير صحيح لعنصرين أو ثلاثة"},{"level":"1 درجة","description":"تحديد نوع التفاعل فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير السهم إلى أسفل على أنه امتصاص للحرارة","القول إن النواتج أعلى طاقة لأنها تتكون بعد التفاعل","إهمال الإشارة السالبة لـ ΔH"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-03T20:51:23.906Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المحور الرأسي يمثل المحتوى الحراري. يُرسم مستوى المتفاعل NH₄NO₃(s) في الأسفل، ومستوى النواتج NH₄⁺(aq) + NO₃⁻(aq) أعلى منه؛ لأن ΔH موجبة أي أن المحتوى الحراري للنواتج أكبر بمقدار 27 kJ. يُرسم سهم من مستوى المتفاعل إلى أعلى نحو مستوى النواتج ويُكتب عليه ΔH = +27 kJ، ويُشار إلى أن الحرارة تنتقل من المحيط (كاحل الشخص) إلى النظام. أما في مخطط التفاعل الطارد فيكون مستوى المتفاعلات أعلى من مستوى النواتج، ويتجه السهم إلى أسفل، وتكون ΔH سالبة، وتنتقل الحرارة من النظام إلى المحيط.', '["المحور الرأسي: المحتوى الحراري","مستوى NH₄NO₃(s) في الأسفل ومستوى الأيونات أعلى منه","سهم إلى أعلى مكتوب عليه ΔH = +27 kJ","الحرارة تنتقل من المحيط إلى النظام","المقارنة: في الطارد المتفاعلات أعلى والسهم إلى أسفل وΔH سالبة"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد المحور الرأسي","marks":1},{"element":"موقعا المستويين صحيحان","marks":1},{"element":"اتجاه السهم وقيمته","marks":1},{"element":"اتجاه انتقال الحرارة","marks":1},{"element":"المقارنة بمخطط التفاعل الطارد","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف كامل صحيح للمخطط مع مقارنة سليمة"},{"level":"3–4 درجات","description":"وصف صحيح للمخطط مع نقص في اتجاه الحرارة أو في المقارنة"},{"level":"1–2 درجة","description":"تحديد موقعي المستويين أو اتجاه السهم فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم مستوى النواتج أدنى من المتفاعل","رسم السهم من النواتج إلى المتفاعلات","جعل المحور الرأسي درجة الحرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-03T20:51:23.907Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) التبخر والتكثف عمليتان متعاكستان بين المستويين نفسيهما (H₂O(l) وH₂O(g))؛ فالفرق في المحتوى الحراري بين المستويين ثابت (40.7 kJ)، وفي التبخر يتجه السهم إلى أعلى فتكون ΔH موجبة (امتصاص)، وفي التكثف يتجه إلى أسفل فتكون سالبة (انطلاق). (ب) من H₂O(g) إلى H₂O(l): −40.7 kJ، ثم من H₂O(l) إلى H₂O(s): −6.01 kJ؛ ΔH = −40.7 + (−6.01) = −46.7 kJ، والعملية طاردة للحرارة لأن السهم يتجه إلى أسفل وΔH سالبة.', '["العمليتان متعاكستان بين المستويين نفسيهما","الفرق بين المستويين ثابت، والاتجاه يحدد الإشارة","ΔH = −40.7 + (−6.01) = −46.7 kJ","العملية طاردة للحرارة"]'::jsonb, '["H₂O(g) → H₂O(l): ΔH = −40.7 kJ","H₂O(l) → H₂O(s): ΔH = −6.01 kJ","المجموع: −40.7 + (−6.01) = −46.7 kJ","الإشارة السالبة ← العملية طاردة للحرارة"]'::jsonb, '[{"element":"تفسير تساوي المقدار","marks":1},{"element":"تفسير اختلاف الإشارة باتجاه السهم","marks":1},{"element":"حساب ΔH = −46.7 kJ","marks":1},{"element":"تحديد أن العملية طاردة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح للفرعين وحساب صحيح بالإشارة والتصنيف"},{"level":"2–3 درجات","description":"تفسير صحيح مع خطأ في الحساب أو الإشارة، أو حساب صحيح مع تفسير ناقص"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["طرح القيمتين بدلًا من جمعهما (34.7 kJ)","كتابة الناتج موجبًا","تفسير اختلاف الإشارة باختلاف كمية المادة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-03T20:51:23.908Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C1-L2-O10') and x.type = v.type and x.number = v.number
