insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C1-L2-O11'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'في تجربة تحديد الحرارة النوعية لفلز باستعمال مسعر، تُكتب العلاقة q_metal = −q_water. ما معنى الإشارة السالبة فيها؟', null, null, '["الحرارة التي فقدها الفلز تساوي في مقدارها الحرارة التي اكتسبها الماء","الحرارة التي فقدها الماء تساوي ضعف الحرارة التي اكتسبها الفلز","الفلز والماء كلاهما يفقدان حرارة إلى المحيط بالمقدار نفسه","الحرارة النوعية للفلز أقل دائمًا من الحرارة النوعية للماء"]'::jsonb, 'فهم', 'تفسير علاقة', 'سهل', 'الكتاب ص 20 — تحديد الحرارة النوعية (q_metal = −q_water)'),
('mcq', 2, 'وُضعت قطعة فلز ساخنة في مسعر يحتوي على 150 g من الماء، فارتفعت درجة حرارة الماء من 24.00°C إلى 28.20°C. ما كمية الحرارة q_metal التي فقدها الفلز؟ (الحرارة النوعية للماء 4.184 J/(g·°C))', null, null, '["+2.64×10³ J","−630 J","−2.64×10³ J","−1.77×10⁴ J"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 20 — حساب الحرارة التي اكتسبها الماء'),
('mcq', 3, 'امتصت عينة من فلز كتلتها 15.0 g مقدار 388 J من الحرارة، فارتفعت درجة حرارتها من 20.0°C إلى 60.0°C. ما الحرارة النوعية للفلز؟', null, null, '["0.431 J/(g·°C)","0.647 J/(g·°C)","1.29 J/(g·°C)","1.55 J/(g·°C)"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 21 — مثال 1-3'),
('mcq', 4, 'سُخنت قطعة فلز مجهول وفق البيانات في الجدول، ثم وُضعت في ماء المسعر حتى تساوت درجتا الحرارة. اعتمادًا على قيم الحرارة النوعية J/(g·°C): الألومنيوم 0.897، والكالسيوم 0.647، والحديد 0.449، والفضة 0.235، ما الفلز المجهول؟ (الحرارة النوعية للماء 4.184 J/(g·°C))', '{"headers":["القياس","القيمة"],"rows":[["كتلة الفلز","40.0 g"],["درجة الحرارة الابتدائية للفلز","100.0°C"],["كتلة الماء","80.0 g"],["درجة الحرارة الابتدائية للماء","20.0°C"],["درجة الحرارة النهائية للماء والفلز","27.7°C"]]}'::jsonb, null, '["الحديد","الكالسيوم","الفضة","الألومنيوم"]'::jsonb, 'تطبيق', 'حساب وتعرّف مادة', 'صعب', 'الكتاب ص 16، 20 — الجدول 1-2، تحديد الحرارة النوعية'),
('mcq', 5, 'في تجربة لتحديد الحرارة النوعية لفلز باستعمال كأس بوليسترين مفتوحة، فُقد جزء من الحرارة التي أطلقها الفلز إلى الهواء المحيط بدلًا من أن يكتسبه الماء. كيف تتأثر قيمة الحرارة النوعية المحسوبة للفلز؟', null, null, '["تصبح أكبر من القيمة الحقيقية؛ لأن ΔT للماء يزداد","لا تتأثر؛ لأن الحرارة النوعية خاصية ثابتة للفلز","تصبح أصغر من القيمة الحقيقية؛ لأن q_water المقيسة أقل","تصبح أكبر من القيمة الحقيقية؛ لأن ΔT للفلز يقل"]'::jsonb, 'تحليل', 'تحليل مصدر خطأ', 'صعب', 'الكتاب ص 19–20، 22 — المسعر، تجربة تحديد الحرارة النوعية لفلز'),
('mcq', 6, 'وُضعت سبيكة كتلتها 60.0 g في مسعر يحتوي على 150 g من الماء البارد، فانخفضت درجة حرارة السبيكة بمقدار 75.0°C، وارتفعت درجة حرارة الماء بمقدار 4.60°C. ما الحرارة النوعية للسبيكة؟ (الحرارة النوعية للماء 4.184 J/(g·°C))', null, null, '["0.103 J/(g·°C)","0.642 J/(g·°C)","171 J/(g·°C)","0.604 J/(g·°C)"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 43 — س69'),
('mcq', 7, 'أيّ مجموعة من القياسات تكفي لحساب الحرارة النوعية لفلز مجهول باستعمال مسعر فيه ماء؟', null, null, '["كتلة الماء ودرجتا حرارته الابتدائية والنهائية فقط","كتلة الفلز ودرجة الحرارة النهائية للمسعر فقط","حجم المسعر وكثافة الفلز ودرجة حرارة الغرفة","كتلتا الماء والفلز، والدرجات الابتدائية لهما، والدرجة النهائية"]'::jsonb, 'فهم', 'تحديد المعطيات اللازمة', 'سهل', 'الكتاب ص 19–20 — تحديد الحرارة النوعية'),
('essay', 1, 'سُخنت عينة من فلز مجهول كتلتها 25.0 g حتى 95.00°C، ثم وُضعت في مسعر يحتوي على 100.0 g من الماء عند 22.00°C، فأصبحت درجة الحرارة النهائية للماء والفلز 26.20°C. احسب الحرارة النوعية للفلز، ثم حدّد هويته من القيم J/(g·°C): الماغنسيوم 1.023، والألومنيوم 0.897، والكالسيوم 0.647، والحديد 0.449. (الحرارة النوعية للماء 4.184 J/(g·°C))', null, null, null, 'تطبيق', 'مسألة حسابية متعددة الخطوات', 'متوسط', 'الكتاب ص 20 — حساب الحرارة النوعية لفلز مجهول، الجدول 1-2'),
('essay', 2, 'سجّل طالب البيانات الواردة في الجدول في تجربة مسعر لفلز مجهول. احسب الحرارة النوعية للفلز، وحدّد هويته من القيم J/(g·°C): الحديد 0.449، والإسترانشيوم 0.301، والفضة 0.235، والباريوم 0.204. ثم فسّر لماذا يتوقف انتقال الحرارة عند وصول الماء والفلز إلى 24.40°C. (الحرارة النوعية للماء 4.184 J/(g·°C))', '{"headers":["القياس","القيمة"],"rows":[["كتلة الفلز","50.0 g"],["درجة الحرارة الابتدائية للفلز","98.00°C"],["كتلة الماء","60.0 g"],["درجة الحرارة الابتدائية للماء","20.00°C"],["درجة الحرارة النهائية","24.40°C"]]}'::jsonb, null, null, 'تحليل', 'تحليل بيانات تجربة', 'متوسط', 'الكتاب ص 19–20 — تحديد الحرارة النوعية، الجدول 1-2'),
('essay', 3, 'أجرى طالب تجربة لتعرّف فلز معروف أنه الحديد (c = 0.449 J/(g·°C)): سخّن 50.0 g منه حتى 100.0°C، ثم نقله إلى كأس بوليسترين مفتوحة فيها 100.0 g من الماء عند 20.0°C، فكانت درجة الحرارة النهائية 23.6°C.
(أ) احسب الحرارة النوعية التي حصل عليها الطالب.
(ب) قوّم نتيجته: هل هي أكبر أم أصغر من القيمة الحقيقية؟ واقترح سببين محتملين للخطأ وتحسينين للتجربة. (الحرارة النوعية للماء 4.184 J/(g·°C))', null, null, null, 'تقويم', 'تقويم نتيجة تجربة', 'صعب', 'الكتاب ص 22 — تجربة تحديد الحرارة النوعية لفلز (التحليل 15)، ص 20')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
