from (values
('mcq', 1, 0, 'بافتراض عدم فقد حرارة إلى المحيط، تنتقل الحرارة من الفلز الساخن إلى الماء؛ فالحرارة التي اكتسبها الماء (موجبة) تساوي في مقدارها الحرارة التي فقدها الفلز (سالبة)، ولهذا q_metal = −q_water.', '["","الفلز الساخن هو الذي يفقد الحرارة والماء يكتسبها، والمقداران متساويان لا أحدهما ضعف الآخر.","الماء يكتسب حرارة فترتفع درجة حرارته، والعلاقة تفترض عدم فقد حرارة إلى المحيط.","الإشارة السالبة تعبر عن اتجاه انتقال الحرارة، لا عن مقارنة الحرارة النوعية للفلز والماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-03T20:51:23.909Z"}'::jsonb),
('mcq', 2, 2, 'q_water = 4.184 J/(g·°C) × 150 g × (28.20 − 24.00)°C = 4.184 × 150 × 4.20 = 2.64×10³ J، وq_metal = −q_water = −2.64×10³ J.', '["هذه q_water؛ والفلز فقد الحرارة فتكون q_metal سالبة.","أُهملت الحرارة النوعية للماء (150 × 4.20 = 630) فلم يُضرب الناتج في 4.184.","","استُعملت درجة الحرارة النهائية 28.20°C بدلًا من التغير ΔT = 4.20°C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-03T20:51:23.909Z"}'::jsonb),
('mcq', 3, 1, 'c = q ÷ (m × ΔT) = 388 J ÷ (15.0 g × 40.0°C) = 0.647 J/(g·°C)، وهي قيمة الكالسيوم.', '["استُعملت درجة الحرارة النهائية 60.0°C بدلًا من ΔT = 40.0°C: 388 ÷ (15.0 × 60.0).","","استُعملت درجة الحرارة الابتدائية 20.0°C بدلًا من ΔT: 388 ÷ (15.0 × 20.0).","قُلبت العلاقة فحُسب (m × ΔT) ÷ q = 600 ÷ 388."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-03T20:51:23.909Z"}'::jsonb),
('mcq', 4, 3, 'q_water = 4.184 × 80.0 g × 7.7°C = 2.58×10³ J، وq_metal = −2.58×10³ J، وΔT للفلز = 27.7 − 100.0 = −72.3°C؛ c = −2577 J ÷ (40.0 g × −72.3°C) = 0.891 J/(g·°C)، وأقرب قيمة لها 0.897، فالفلز الألومنيوم.', '["ينتج 0.446 تقريبًا (قريب من الحديد) إذا استُعملت كتلة الفلز 40.0 g بدلًا من كتلة الماء في حساب q_water.","ينتج 0.644 تقريبًا (قريب من الكالسيوم) إذا استُعملت درجة الحرارة الابتدائية للفلز 100.0°C بدلًا من تغير درجة حرارته 72.3°C.","ينتج 0.223 تقريبًا (قريب من الفضة) إذا تبادلت كتلتا الماء والفلز في الحساب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-03T20:51:23.910Z"}'::jsonb),
('mcq', 5, 2, 'عند فقد حرارة إلى الهواء يكتسب الماء حرارة أقل، فيرتفع ΔT للماء بمقدار أقل وتكون q_water المقيسة أقل من الحرارة التي فقدها الفلز فعلًا؛ وبالتعويض في c = −q_water ÷ (m × ΔT) تنتج قيمة أصغر من الحقيقية.', '["فقد الحرارة إلى الهواء يقلل ارتفاع درجة حرارة الماء ولا يزيده.","الحرارة النوعية الحقيقية ثابتة، لكن القيمة المحسوبة تعتمد على القياسات التي تأثرت بفقد الحرارة.","","فقد الحرارة يجعل درجة الحرارة النهائية أقل، فيكبر مقدار ΔT للفلز ولا يقل، وكلا الأثرين يصغّر القيمة المحسوبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-03T20:51:23.910Z"}'::jsonb),
('mcq', 6, 1, 'q_water = 4.184 × 150 g × 4.60°C = 2887 J، والسبيكة فقدت 2887 J؛ c = 2887 J ÷ (60.0 g × 75.0°C) = 0.642 J/(g·°C).', '["تبادلت الكتلتان: استُعملت كتلة السبيكة 60.0 g للماء وكتلة الماء 150 g للسبيكة.","","تبادل التغيران في درجة الحرارة: استُعمل 75.0°C للماء و4.60°C للسبيكة.","استُعمل 79.6°C (مجموع التغيرين، أي الفرق بين درجتي الحرارة الابتدائيتين) بدلًا من تغير درجة حرارة السبيكة 75.0°C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-03T20:51:23.910Z"}'::jsonb),
('mcq', 7, 3, 'يلزم حساب q_water = c_water × m_water × ΔT_water، ثم c_metal = −q_water ÷ (m_metal × ΔT_metal)؛ ولذلك تلزم كتلتا الماء والفلز، ودرجتا حرارتهما الابتدائيتان، ودرجة الحرارة النهائية المشتركة.', '["هذه القياسات تكفي لحساب q_water فقط، ولا يمكن بدون كتلة الفلز وتغير درجة حرارته حساب c للفلز.","لا يمكن حساب q_water ولا ΔT للفلز بدون كتلة الماء والدرجات الابتدائية.","حجم المسعر وكثافة الفلز ودرجة حرارة الغرفة لا تدخل في معادلة حساب كمية الحرارة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-03T20:51:23.911Z"}'::jsonb),
('essay', 1, null::int, null, null, 'q_water = 4.184 J/(g·°C) × 100.0 g × (26.20 − 22.00)°C = 4.184 × 100.0 × 4.20 = 1757 J. q_metal = −q_water = −1757 J. ΔT للفلز = 26.20 − 95.00 = −68.80°C. c_metal = q_metal ÷ (m × ΔT) = −1757 J ÷ (25.0 g × −68.80°C) = 1.02 J/(g·°C). أقرب قيمة لها 1.023، فالفلز هو الماغنسيوم.', '["q_water = 1757 J (1.76×10³ J)","q_metal = −1757 J","ΔT للفلز = −68.80°C","c = 1.02 J/(g·°C)","الفلز الماغنسيوم"]'::jsonb, '["ΔT للماء = 26.20 − 22.00 = 4.20°C","q_water = 4.184 × 100.0 × 4.20 = 1757 J","q_metal = −q_water = −1757 J","ΔT للفلز = 26.20 − 95.00 = −68.80°C","c_metal = −1757 ÷ (25.0 × −68.80) = 1.02 J/(g·°C)","المقارنة بالقيم المعطاة ← الماغنسيوم (1.023)"]'::jsonb, '[{"element":"حساب q_water","marks":1},{"element":"q_metal = −q_water","marks":1},{"element":"حساب ΔT للفلز","marks":1},{"element":"حساب c بالوحدة وعدد الأرقام المعنوية الصحيحين","marks":1},{"element":"تعرّف الفلز","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"خطوات صحيحة كاملة، وقيمة c صحيحة بوحدتها، وتعرّف صحيح للفلز"},{"level":"3–4 درجات","description":"طريقة صحيحة مع خطأ حسابي أو خطأ في الإشارة أو الوحدة"},{"level":"1–2 درجة","description":"حساب q_water فقط أو كتابة العلاقات دون تعويض صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال تغير درجة حرارة الماء لحساب c للفلز","استعمال كتلة الفلز في حساب q_water","نسيان الإشارة السالبة فتنتج c سالبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-03T20:51:23.911Z"}'::jsonb),
('essay', 2, null::int, null, null, 'q_water = 4.184 × 60.0 g × (24.40 − 20.00)°C = 4.184 × 60.0 × 4.40 = 1105 J (1.10×10³ J). q_metal = −1105 J. ΔT للفلز = 24.40 − 98.00 = −73.60°C. c = −1105 J ÷ (50.0 g × −73.60°C) = 0.300 J/(g·°C)، وهي أقرب إلى 0.301، فالفلز الإسترانشيوم. يتوقف انتقال الحرارة لأن الحرارة تنتقل من الجسم الأسخن إلى الأبرد، فعندما تتساوى درجتا حرارة الماء والفلز لا يبقى فرق في درجة الحرارة يدفع الحرارة للانتقال.', '["q_water = 1.10×10³ J","ΔT للفلز = −73.60°C","c = 0.300 J/(g·°C)","الفلز الإسترانشيوم","توقف الانتقال عند تساوي درجتي الحرارة"]'::jsonb, '["ΔT للماء = 24.40 − 20.00 = 4.40°C","q_water = 4.184 × 60.0 × 4.40 = 1105 J","q_metal = −1105 J","ΔT للفلز = 24.40 − 98.00 = −73.60°C","c = −1105 ÷ (50.0 × −73.60) = 0.300 J/(g·°C)","المقارنة ← الإسترانشيوم"]'::jsonb, '[{"element":"حساب q_water","marks":1},{"element":"حساب ΔT للفلز وq_metal بالإشارة الصحيحة","marks":1},{"element":"حساب c صحيحًا بوحدته","marks":1},{"element":"تعرّف الفلز","marks":1},{"element":"تفسير توقف انتقال الحرارة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح كامل، وتعرّف صحيح، وتفسير سليم"},{"level":"3–4 درجات","description":"حساب وتعرّف صحيحان دون تفسير، أو خطأ حسابي واحد مع تفسير صحيح"},{"level":"1–2 درجة","description":"حساب q_water فقط أو التفسير فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار الفضة بسبب خطأ في ΔT للفلز","استعمال 98.00°C بدلًا من تغير درجة حرارة الفلز","تفسير توقف الانتقال بنفاد حرارة الفلز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-03T20:51:23.912Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) q_water = 4.184 × 100.0 × (23.6 − 20.0) = 4.184 × 100.0 × 3.6 = 1506 J؛ q_metal = −1506 J؛ ΔT للفلز = 23.6 − 100.0 = −76.4°C؛ c = −1506 ÷ (50.0 × −76.4) = 0.39 J/(g·°C). (ب) النتيجة أصغر من القيمة الحقيقية 0.449؛ أي أن الماء اكتسب حرارة أقل مما فقده الفلز فعلًا. أسباب محتملة: فقد جزء من الحرارة إلى الهواء لأن الكأس مفتوحة، أو برد الفلز قليلًا في أثناء نقله فكانت درجة حرارته عند وضعه أقل من 100.0°C. تحسينات: تغطية الكأس بغطاء فيه ثقب لمقياس الحرارة، ونقل الفلز بسرعة، وتحريك الماء وقراءة أعلى درجة حرارة يصل إليها.', '["q_water = 1506 J","c ≈ 0.39 J/(g·°C)","النتيجة أصغر من القيمة الحقيقية","سببان محتملان: فقد الحرارة إلى الهواء، تبريد الفلز في أثناء النقل","تحسينان: الغطاء، النقل السريع، التحريك"]'::jsonb, '["ΔT للماء = 23.6 − 20.0 = 3.6°C","q_water = 4.184 × 100.0 × 3.6 = 1506 J","ΔT للفلز = 23.6 − 100.0 = −76.4°C","c = −1506 ÷ (50.0 × −76.4) = 0.39 J/(g·°C)"]'::jsonb, '[{"element":"حساب q_water وΔT للفلز","marks":1},{"element":"حساب c","marks":1},{"element":"الحكم بأن النتيجة أصغر مع التعليل","marks":1},{"element":"سببان محتملان للخطأ","marks":1},{"element":"تحسينان مناسبان","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح، وحكم معلل، وسببان وتحسينان مناسبان"},{"level":"3–4 درجات","description":"حساب صحيح مع نقص في الأسباب أو التحسينات"},{"level":"1–2 درجة","description":"حساب فقط أو ذكر سبب واحد دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن فقد الحرارة يجعل النتيجة أكبر","اقتراح تحسينات لا علاقة لها بانتقال الحرارة مثل زيادة كتلة الفلز فقط","استعمال 100.0°C بدلًا من تغير درجة حرارة الفلز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:51:23.913Z"}'::jsonb)
