('mcq', 3, 'لماذا يمكن عدّ كمية الحرارة المقيسة في مسعر من كأس بوليسترين مساوية للتغير في المحتوى الحراري للتفاعل ΔH؟', null, null, '["لأن الكأس غير مغلقة، فيحدث التفاعل عند ضغط جوي ثابت","لأن البوليسترين يمتص كل الحرارة المنطلقة من التفاعل","لأن الكأس مغلقة إغلاقًا محكمًا فلا يتغير حجم المواد","لأن درجة حرارة الماء في الكأس تبقى ثابتة في أثناء التفاعل"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 19، 23 — مسعر كأس البوليسترين، ضغط ثابت'),
('mcq', 4, 'حدث تفاعل في مسعر مفتوح يحتوي على 200.0 g من الماء، فارتفعت درجة حرارة الماء بمقدار 3.50°C. ما ΔH لهذا التفاعل؟ (افترض أن الماء اكتسب كل الحرارة، والحرارة النوعية للماء 4.184 J/(g·°C))', null, null, '["+2.93 kJ","−2.93 kJ","−0.700 kJ","−2.93×10⁻³ kJ"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 24 — q = ΔHrxn، ص 20 — q = c × m × ΔT'),
('mcq', 5, 'لماذا يجوز افتراض أن q = ΔHrxn للتفاعلات التي تحدث في المخلوقات الحية وفي البرك والمحيطات؟', null, null, '["لأنها جميعًا تحدث عند حجم ثابت","لأنها جميعًا تفاعلات طاردة للحرارة","لأنها جميعًا تحدث عند درجة حرارة ثابتة","لأنها جميعًا تحدث عند ضغط ثابت"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 24 — q = ΔHrxn'),
('mcq', 6, 'امتصت عملية تحدث عند ضغط ثابت 15.0 kJ من الحرارة من المحيط. ما قيمة ΔH لهذه العملية؟', null, null, '["+15.0 kJ","−15.0 kJ","صفر kJ","+30.0 kJ"]'::jsonb, 'تطبيق', 'تطبيق علاقة', 'متوسط', 'الكتاب ص 24 — q = ΔHrxn'),
('mcq', 7, 'حدث تفاعل في مسعر من كأس بوليسترين، فارتفعت درجة حرارة الماء فيه. ما إشارة ΔH للتفاعل؟ ولماذا؟', null, null, '["موجبة؛ لأن q_water موجبة وΔH = q_water","موجبة؛ لأن التفاعل اكتسب حرارة من الماء","سالبة؛ لأن q_rxn = −q_water وΔH = q_rxn","سالبة؛ لأن درجة حرارة الماء انخفضت في أثناء التفاعل"]'::jsonb, 'تحليل', 'استنتاج وتعليل', 'صعب', 'الكتاب ص 20، 24 — q_metal = −q_water، q = ΔHrxn'),
('essay', 1, 'وضّح المقصود بالعبارة «q = ΔHrxn»، محددًا الشرط اللازم لصحتها، ومعللًا لماذا تصح للتفاعلات التي تُجرى في كأس مفتوحة، مع ذكر مثالين لتفاعلات تحدث في ظروف مماثلة.', null, null, null, 'فهم', 'توضيح وتعليل بأمثلة', 'متوسط', 'الكتاب ص 23–24 — qp، q = ΔHrxn؛ ص 42 — س62'),
('essay', 2, 'أُذيبت عينة من مادة صلبة في مسعر من كأس بوليسترين يحتوي على 100.0 g من الماء، فانخفضت درجة حرارة الماء من 25.00°C إلى 21.40°C. افترض أن الماء وحده يكتسب الحرارة أو يفقدها، وأن الحرارة النوعية له 4.184 J/(g·°C). احسب q للماء، ثم ΔH لعملية الذوبان بوحدة kJ، وحدد هل العملية ماصة أم طاردة للحرارة مع التعليل.', null, null, null, 'تطبيق', 'مسألة حسابية', 'صعب', 'الكتاب ص 24 — q = ΔHrxn؛ ص 20 — q = c × m × ΔT'),
('essay', 3, 'قال طالب: «في مسعر كأس البوليسترين، ΔH للتفاعل يساوي q التي يكتسبها الماء بالإشارة نفسها». حلّل هذه العبارة: بيّن ما الصحيح فيها وما الخطأ، ثم أعد صياغتها صياغة صحيحة مع التعليل.', null, null, null, 'تحليل', 'تحليل عبارة وتصحيحها', 'صعب', 'الكتاب ص 20، 22، 24 — النظام والمحيط، q = ΔHrxn')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
