insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'التغير في المحتوى الحراري ΔH يساوي الحرارة المكتسبة أو المفقودة qp في أي تفاعل أو عملية تحدث عند ضغط ثابت.', '["الشرط المرتبط بتعريف المحتوى الحراري هو ثبات الضغط لا ثبات الحجم.","لا علاقة لتساوي q وΔH بقيمة درجة الحرارة النهائية؛ الشرط هو الضغط الثابت.","","العلاقة q = ΔH صحيحة للتفاعلات الطاردة والماصة معًا ما دام الضغط ثابتًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-03T20:51:23.914Z"}'::jsonb),
('mcq', 2, 3, 'يرمز qp إلى الطاقة المنطلقة أو الممتصة (الحرارة المكتسبة أو المفقودة) في التفاعلات التي تحدث عند ضغط ثابت، والحرف p يشير إلى الضغط.', '["الحرارة النوعية رمزها c، أما q فيرمز إلى كمية الحرارة.","المحتوى الحراري رمزه H، وqp يساوي التغير فيه لا قيمته الكلية.","هذا وصف الحرارة النوعية للماء، لا qp.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-03T20:51:23.914Z"}'::jsonb),
('mcq', 3, 0, 'كأس البوليسترين مفتوحة على الجو، فتحدث التفاعلات فيها تحت ضغط ثابت، وعند ضغط ثابت تكون q = ΔH.', '["","البوليسترين مادة عازلة تقلل انتقال الحرارة، ولا يمتص حرارة التفاعل؛ والماء هو الذي يكتسبها.","كأس البوليسترين غير مغلقة، والشرط المطلوب ثبات الضغط لا الحجم.","درجة حرارة الماء تتغير، ومن تغيرها تُحسب كمية الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-03T20:51:23.914Z"}'::jsonb),
('mcq', 4, 1, 'q_water = 4.184 × 200.0 g × 3.50°C = 2929 J = 2.93 kJ، والتفاعل فقد هذه الحرارة: q_rxn = −2.93 kJ، وعند ضغط ثابت ΔH = q_rxn = −2.93 kJ.', '["هذه q التي اكتسبها الماء؛ والتفاعل فقد الحرارة فتكون ΔH سالبة.","","أُهملت الحرارة النوعية للماء: 200.0 × 3.50 = 700 J.","حُولت الكتلة إلى kg (0.2000) خطأً مع أن وحدة الحرارة النوعية J/(g·°C)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-03T20:51:23.915Z"}'::jsonb),
('mcq', 5, 3, 'هذه التفاعلات تحدث عند ضغط جوي ثابت، وعند ضغط ثابت يساوي ΔH كمية الحرارة المكتسبة أو المفقودة، فيمكن افتراض q = ΔHrxn.', '["الشرط اللازم لتساوي q وΔH هو ثبات الضغط لا ثبات الحجم.","هذه التفاعلات منها الطارد ومنها الماص، والعلاقة تصح لكليهما.","درجة الحرارة تتغير في هذه التفاعلات، ومن تغيرها تُحسب q.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:51:23.915Z"}'::jsonb),
('mcq', 6, 0, 'عند ضغط ثابت ΔH = qp، والعملية امتصت 15.0 kJ فتكون q موجبة؛ ΔH = +15.0 kJ (عملية ماصة).', '["","الإشارة السالبة للحرارة المنطلقة؛ والعملية هنا امتصت الحرارة.","ΔH يساوي الحرارة الممتصة نفسها عند ضغط ثابت، ولا يساوي صفرًا ما دامت حرارة قد امتُصت.","ضوعفت القيمة بلا مبرر؛ فـ ΔH يساوي q تمامًا عند ضغط ثابت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-03T20:51:23.915Z"}'::jsonb),
('mcq', 7, 2, 'ارتفاع درجة حرارة الماء يعني أن q_water موجبة، والحرارة التي اكتسبها الماء فقدها التفاعل: q_rxn = −q_water (سالبة). ولأن الضغط ثابت فإن ΔH = q_rxn، فتكون ΔH سالبة والتفاعل طارد.', '["ΔH يساوي حرارة التفاعل (النظام) لا حرارة الماء (المحيط)، وهما متعاكستان في الإشارة.","ارتفاع درجة حرارة الماء يعني أن التفاعل أعطى الماء حرارة لا أنه اكتسبها منه.","","الإشارة صحيحة لكن التعليل يناقض المعطى؛ فدرجة حرارة الماء ارتفعت ولم تنخفض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-03T20:51:23.917Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تعني العبارة أن التغير في المحتوى الحراري للتفاعل ΔHrxn يساوي كمية الحرارة المكتسبة أو المفقودة q (ويُرمز إليها qp) في التفاعل. وشرط صحتها أن يحدث التفاعل أو العملية عند ضغط ثابت. وتصح للتفاعلات في الكأس المفتوحة لأن الكأس غير مغلقة، فيبقى الضغط ثابتًا (الضغط الجوي). ومن أمثلة التفاعلات التي تحدث عند ضغط ثابت: التفاعلات في المخلوقات الحية على سطح الأرض، والتفاعلات في البرك والمحيطات، والتفاعلات في الكؤوس والدوارق المفتوحة في المختبر.', '["ΔHrxn يساوي الحرارة المكتسبة أو المفقودة","الشرط: ضغط ثابت","الكأس المفتوحة تبقي الضغط ثابتًا (جويًّا)","مثالان: المخلوقات الحية، البرك والمحيطات، الكؤوس والدوارق المفتوحة"]'::jsonb, '[]'::jsonb, '[{"element":"توضيح معنى العبارة","marks":1},{"element":"ذكر شرط الضغط الثابت","marks":1},{"element":"تعليل صحتها في الكأس المفتوحة","marks":1},{"element":"مثالان صحيحان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توضيح وشرط وتعليل ومثالان صحيحة"},{"level":"2–3 درجات","description":"توضيح وشرط صحيحان مع نقص في التعليل أو الأمثلة"},{"level":"1 درجة","description":"ذكر الشرط فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الحجم الثابت أو درجة الحرارة الثابتة شرطًا","عدّ الكأس المفتوحة سببًا لفقد الحرارة فقط دون ربطها بالضغط","أمثلة لتفاعلات في أوعية مغلقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:51:23.917Z"}'::jsonb),
('essay', 2, null::int, null, null, 'ΔT = 21.40 − 25.00 = −3.60°C. q_water = 4.184 × 100.0 g × (−3.60°C) = −1506 J، أي أن الماء فقد 1506 J. q لعملية الذوبان = −q_water = +1506 J = +1.51 kJ. ولأن العملية تحدث عند ضغط ثابت في كأس مفتوحة فإن ΔH = q = +1.51 kJ. العملية ماصة للحرارة لأن ΔH موجبة؛ فالمادة امتصت حرارة من الماء فانخفضت درجة حرارته.', '["ΔT = −3.60°C","q_water = −1506 J","q للذوبان = +1506 J","ΔH = +1.51 kJ لأن الضغط ثابت","العملية ماصة للحرارة"]'::jsonb, '["ΔT = 21.40 − 25.00 = −3.60°C","q_water = 4.184 × 100.0 × (−3.60) = −1506 J","q_dissolving = −q_water = +1506 J","ΔH = q (ضغط ثابت) = +1506 J = +1.51 kJ","ΔH موجبة ← عملية ماصة"]'::jsonb, '[{"element":"حساب q_water بإشارته","marks":1},{"element":"q للذوبان = −q_water","marks":1},{"element":"ΔH = +1.51 kJ مع ذكر شرط الضغط الثابت","marks":1},{"element":"تحديد أن العملية ماصة مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب صحيح بالإشارات، وربط بالضغط الثابت، وتصنيف معلل"},{"level":"2–3 درجات","description":"حساب صحيح مع خطأ في الإشارة أو التحويل إلى kJ، أو نقص في التعليل"},{"level":"1 درجة","description":"حساب q_water فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ΔH مساويًا لـ q_water نفسها فتصبح سالبة","عدم التحويل من J إلى kJ","تصنيف العملية طاردة لأن درجة الحرارة تغيرت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:51:23.917Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الصحيح في العبارة أن ΔH يمكن حسابه من الحرارة التي يكتسبها الماء أو يفقدها؛ لأن الكأس مفتوحة فيحدث التفاعل عند ضغط ثابت، وعند ضغط ثابت ΔH = q للتفاعل. والخطأ في قوله «بالإشارة نفسها»؛ فالتفاعل هو النظام والماء جزء من المحيط، والحرارة التي يكتسبها الماء هي الحرارة التي يفقدها التفاعل، فإشارتاهما متعاكستان: q_rxn = −q_water. الصياغة الصحيحة: «في مسعر كأس البوليسترين، ΔH للتفاعل يساوي q للتفاعل، وهي تساوي سالب الحرارة التي يكتسبها الماء: ΔH = q_rxn = −q_water». فإذا ارتفعت درجة حرارة الماء تكون ΔH سالبة (طارد)، وإذا انخفضت تكون موجبة (ماص).', '["الصحيح: ΔH = q للتفاعل لأن الضغط ثابت","الخطأ: إشارة q للماء معاكسة لإشارة q للتفاعل","التفاعل نظام والماء محيط","الصياغة الصحيحة: ΔH = q_rxn = −q_water","مثال على الإشارة: ارتفاع حرارة الماء ← ΔH سالبة"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الجزء الصحيح مع ربطه بالضغط الثابت","marks":1},{"element":"تحديد الخطأ في الإشارة","marks":1},{"element":"التعليل بالنظام والمحيط","marks":1},{"element":"إعادة الصياغة الصحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحليل كامل للصحيح والخطأ مع تعليل وصياغة صحيحة"},{"level":"2–3 درجات","description":"تحديد الخطأ وإعادة الصياغة دون تعليل كافٍ"},{"level":"1 درجة","description":"الإشارة إلى وجود خطأ دون تحديده بدقة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة كما هي","عدّ الماء هو النظام","إغفال شرط الضغط الثابت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-03T20:51:23.918Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C1-L2-O12') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C1-L2-O13'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما التفاعل الكيميائي الذي تنتج عنه الحرارة في الكمادة الساخنة المستعملة لتدفئة الأيدي؟', null, null, '["NH₄NO₃(s) → NH₄⁺(aq) + NO₃⁻(aq)","4Fe(s) + 3O₂(g) → 2Fe₂O₃(s)","2H₂O(l) → 2H₂(g) + O₂(g)","Fe₂O₃(s) → 2Fe(s) + 3/2 O₂(g)"]'::jsonb, 'تذكر', 'تذكر تفاعل', 'سهل', 'الكتاب ص 21، 23 — الكمادة الساخنة'),
('mcq', 2, 'ما العملية الأساسية التي تعمل بها الكمادة الباردة؟', null, null, '["ذوبان نترات الأمونيوم NH₄NO₃ الذي يمتص 27 kJ من الحرارة","ذوبان نترات الأمونيوم NH₄NO₃ الذي يطلق 27 kJ من الحرارة","تأكسد الحديد الذي يمتص 1625 kJ من الحرارة","تجمد الماء داخل الكمادة الذي يمتص الحرارة من الجلد"]'::jsonb, 'تذكر', 'تذكر عملية', 'سهل', 'الكتاب ص 24 — الكمادة الباردة (الشكل 1-8)'),
('mcq', 3, 'عند وضع كمادة باردة على كاحل مصاب يشعر الشخص بالبرودة. ما التفسير الصحيح لذلك؟', null, null, '["تنتقل البرودة من نترات الأمونيوم إلى الكاحل","يطلق ذوبان نترات الأمونيوم حرارة فيبرد الكاحل","تنخفض حرارة الكاحل لأن ΔH للعملية سالبة","يمتص ذوبان نترات الأمونيوم حرارة من الكاحل"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 24 — الكمادة الباردة'),
('mcq', 4, 'عند استعمال الكمادة الساخنة لتدفئة اليدين، ما الوصف الصحيح للنظام والمحيط واتجاه انتقال الحرارة؟', null, null, '["النظام هو اليدان، وتنتقل الحرارة منهما إلى الكمادة","النظام هو اليدان، وتنتقل الحرارة إليهما من الهواء","النظام هو التفاعل في الكمادة، وتنتقل الحرارة منه إلى اليدين","النظام هو التفاعل في الكمادة، وتنتقل الحرارة إليه من اليدين"]'::jsonb, 'فهم', 'تحديد النظام والمحيط', 'متوسط', 'الكتاب ص 22 — النظام والمحيط في الكمادة الساخنة'),
('mcq', 5, 'تحتوي كمادة باردة على 40.0 g من NH₄NO₃ (الكتلة المولية 80.05 g/mol). إذا كان ذوبان 1 mol منه يمتص 27 kJ، فما كمية الحرارة التي تمتصها الكمادة عند ذوبان كل ما فيها؟', null, null, '["13 kJ","27 kJ","54 kJ","1.1×10³ kJ"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 24 — الكمادة الباردة (27 kJ)'),
('mcq', 6, 'وفق المعادلة 4Fe(s) + 3O₂(g) → 2Fe₂O₃(s)  ΔH = −1625 kJ، ما كمية الحرارة التي تطلقها كمادة ساخنة عند تأكسد 1.00 mol من الحديد؟', null, null, '["1625 kJ","6500 kJ","542 kJ","406 kJ"]'::jsonb, 'تطبيق', 'حساب من معادلة كيميائية حرارية', 'صعب', 'الكتاب ص 21، 23 — الكمادة الساخنة'),
('mcq', 7, 'أيّ المقارنات الآتية بين الكمادة الساخنة والكمادة الباردة صحيحة؟', null, null, '["الساخنة: ΔH موجبة وتمتص حرارة؛ الباردة: ΔH سالبة وتطلق حرارة","الساخنة: ΔH سالبة وتنقل الحرارة إلى الجلد؛ الباردة: ΔH موجبة وتمتص الحرارة من الجلد","الساخنة والباردة كلتاهما ΔH سالبة، والفرق في مقدار الحرارة فقط","الساخنة: ΔH سالبة وتمتص الحرارة من الجلد؛ الباردة: ΔH موجبة وتنقل الحرارة إلى الجلد"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 23–24 — الكمادة الساخنة والكمادة الباردة'),
('essay', 1, 'اشرح آلية عمل الكمادة الساخنة المستعملة لتدفئة الأيدي، متضمنًا: معادلة التفاعل، ونوعه، وقيمة ΔH بإشارتها، واتجاه انتقال الحرارة بين النظام والمحيط.', null, null, null, 'فهم', 'شرح آلية', 'سهل', 'الكتاب ص 21–23 — الكمادة الساخنة (الشكل 1-7)'),
('essay', 2, 'اشرح آلية عمل الكمادة الباردة التي توضع على كاحل مصاب، ثم قارن بينها وبين الكمادة الساخنة من حيث: نوع العملية، وإشارة ΔH، ومقارنة المحتوى الحراري للنواتج والمتفاعلات، واتجاه انتقال الحرارة.', null, null, null, 'تحليل', 'شرح ومقارنة', 'متوسط', 'الكتاب ص 23–24 — الكمادة الساخنة والكمادة الباردة (الشكلان 1-7 و1-8)'),
('essay', 3, 'تحتوي كمادة باردة على 50.0 g من نترات الأمونيوم NH₄NO₃، ويمتص ذوبان 1 mol منها 27 kJ. احسب كمية الحرارة التي تمتصها الكمادة عند ذوبان كل ما فيها، واكتب قيمة ΔH لهذه الكمية بإشارتها، وفسّر لماذا يشعر المصاب بالبرودة. (الكتل الذرية: N 14.01، H 1.008، O 16.00)', null, null, null, 'تطبيق', 'مسألة حسابية وتفسير', 'صعب', 'الكتاب ص 24 — الكمادة الباردة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
