insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'تنتج حرارة الكمادة الساخنة من تأكسد الحديد: 4Fe(s) + 3O₂(g) → 2Fe₂O₃(s) + 1625 kJ، وهو تفاعل طارد للحرارة.', '["هذه عملية ذوبان نترات الأمونيوم، وهي أساس الكمادة الباردة لأنها تمتص الحرارة.","","تحلل الماء تفاعل ماص للحرارة، فلا يمكن أن يدفئ الأيدي.","هذا عكس تفاعل تأكسد الحديد، فهو ماص للحرارة لا طارد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-03T20:51:23.919Z"}'::jsonb),
('mcq', 2, 0, 'تعتمد الكمادة الباردة على ذوبان نترات الأمونيوم: 27 kJ + NH₄NO₃(s) → NH₄⁺(aq) + NO₃⁻(aq)، وهي عملية ماصة للحرارة.', '["","ذوبان نترات الأمونيوم يمتص الحرارة ولا يطلقها؛ ولو أطلقها لسخنت الكمادة.","تأكسد الحديد هو تفاعل الكمادة الساخنة، وهو يطلق 1625 kJ ولا يمتصها.","التجمد عملية طاردة للحرارة، ولا تعتمد عليها الكمادة الباردة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-03T20:51:23.919Z"}'::jsonb),
('mcq', 3, 3, 'ذوبان NH₄NO₃ عملية ماصة للحرارة (ΔH = +27 kJ)، فيمتص النظام (محتويات الكمادة) الحرارة من المحيط (الكاحل)، فتنخفض درجة حرارة الكاحل ويبرد.', '["البرودة ليست شيئًا ينتقل؛ الذي ينتقل هو الحرارة، من الكاحل إلى الكمادة.","لو أطلقت العملية حرارة لسخن الكاحل؛ والذوبان هنا يمتص الحرارة.","إشارة ΔH لعملية الكمادة الباردة موجبة (+27 kJ) لأنها ماصة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-03T20:51:23.919Z"}'::jsonb),
('mcq', 4, 2, 'النظام هو التفاعل الكيميائي ومحتويات الكمادة، واليدان جزء من المحيط؛ ولأن تأكسد الحديد طارد للحرارة تنتقل الحرارة من النظام (الكمادة) إلى المحيط (اليدين الباردتين).', '["اليدان جزء من المحيط لا النظام، والحرارة تنتقل إليهما لا منهما.","النظام هو التفاعل في الكمادة، ومصدر الحرارة تفاعل الكمادة لا الهواء.","","انتقال الحرارة من اليدين إلى النظام يحدث في تفاعل ماص كالكمادة الباردة، لا في الكمادة الساخنة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-03T20:51:23.920Z"}'::jsonb),
('mcq', 5, 0, 'n = 40.0 g ÷ 80.05 g/mol = 0.500 mol، والحرارة الممتصة = 0.500 mol × 27 kJ/mol = 13 kJ (رقمان معنويان كما في 27 kJ).', '["","هذه حرارة ذوبان 1 mol كاملًا، ولم تُحسب عدد مولات العينة (0.500 mol).","قُلبت النسبة فحُسب 80.05 ÷ 40.0 = 2.00 بدلًا من 40.0 ÷ 80.05.","ضُربت الكتلة بالجرام مباشرة في 27 kJ دون تحويلها إلى مولات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-03T20:51:23.920Z"}'::jsonb),
('mcq', 6, 3, '1625 kJ تنطلق عند تأكسد 4 mol من Fe؛ فعند تأكسد 1.00 mol: 1625 ÷ 4 = 406 kJ.', '["هذه الحرارة المنطلقة من 4 mol من الحديد كما في المعادلة، لا من 1.00 mol.","ضُربت القيمة في 4 بدلًا من القسمة عليها.","قُسمت القيمة على معامل O₂ (3) بدلًا من معامل Fe (4).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-03T20:51:23.920Z"}'::jsonb),
('mcq', 7, 1, 'تأكسد الحديد في الكمادة الساخنة طارد (ΔH = −1625 kJ) فتنتقل الحرارة إلى الجلد، وذوبان NH₄NO₃ في الكمادة الباردة ماص (ΔH = +27 kJ) فتُمتص الحرارة من الجلد.', '["الإشارتان معكوستان؛ فالكمادة الساخنة تطلق الحرارة وإشارتها سالبة، والباردة تمتصها وإشارتها موجبة.","","ΔH للكمادة الباردة موجبة (+27 kJ) لأنها عملية ماصة؛ فالإشارتان مختلفتان.","الإشارتان صحيحتان لكن اتجاهي انتقال الحرارة معكوسان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-03T20:51:23.921Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تحتوي الكمادة الساخنة على حديد يتأكسد بالأكسجين وفق المعادلة: 4Fe(s) + 3O₂(g) → 2Fe₂O₃(s)  ΔH = −1625 kJ. التفاعل طارد للحرارة؛ فالمحتوى الحراري للناتج Fe₂O₃ أقل من المحتوى الحراري للمتفاعلات، والفرق 1625 kJ ينطلق حرارةً، لذا ΔH سالبة. النظام هو التفاعل ومحتويات الكمادة، والمحيط يشمل اليدين الباردتين؛ فتنتقل الحرارة من النظام إلى اليدين فتدفأان.', '["المعادلة 4Fe + 3O₂ → 2Fe₂O₃","التفاعل طارد للحرارة","ΔH = −1625 kJ","تنتقل الحرارة من النظام (الكمادة) إلى المحيط (اليدين)"]'::jsonb, '[]'::jsonb, '[{"element":"كتابة المعادلة صحيحة","marks":1},{"element":"تحديد النوع","marks":1},{"element":"قيمة ΔH بإشارتها","marks":1},{"element":"اتجاه انتقال الحرارة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"شرح كامل بالعناصر الأربعة"},{"level":"2–3 درجات","description":"معادلة ونوع صحيحان مع نقص في الإشارة أو اتجاه الحرارة"},{"level":"1 درجة","description":"ذكر أن الكمادة تطلق حرارة دون تفاصيل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة ΔH موجبة لأن الكمادة «تنتج» حرارة","عدّ اليدين هما النظام","الخلط بين تفاعل الكمادة الساخنة وذوبان نترات الأمونيوم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-03T20:51:23.921Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تعمل الكمادة الباردة بذوبان نترات الأمونيوم: NH₄NO₃(s) → NH₄⁺(aq) + NO₃⁻(aq)  ΔH = +27 kJ. هذه العملية ماصة للحرارة، فتمتص محتويات الكمادة (النظام) الحرارة من الكاحل (المحيط)، فيبرد الكاحل. المقارنة: الكمادة الباردة عملية ماصة، ΔH موجبة (+27 kJ)، Hproducts > Hreactants، والحرارة تنتقل من المحيط إلى النظام. أما الكمادة الساخنة فتفاعل طارد (تأكسد الحديد)، ΔH سالبة (−1625 kJ)، Hproducts < Hreactants، والحرارة تنتقل من النظام إلى المحيط.', '["عملية ذوبان NH₄NO₃","الكمادة الباردة ماصة وΔH = +27 kJ","تمتص الحرارة من الكاحل فيبرد","الساخنة طاردة وΔH = −1625 kJ","مقارنة المحتوى الحراري واتجاه الحرارة في الحالتين"]'::jsonb, '[]'::jsonb, '[{"element":"شرح آلية الكمادة الباردة ومعادلتها","marks":2},{"element":"مقارنة نوع العملية وإشارة ΔH","marks":1},{"element":"مقارنة المحتوى الحراري للنواتج والمتفاعلات","marks":1},{"element":"مقارنة اتجاه انتقال الحرارة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"شرح كامل للكمادة الباردة ومقارنة صحيحة في الجوانب الثلاثة"},{"level":"3–4 درجات","description":"شرح صحيح مع مقارنة ناقصة في جانب أو جانبين"},{"level":"1–2 درجة","description":"شرح ناقص للكمادة الباردة دون مقارنة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكمادة الباردة تطلق برودة","كتابة ΔH سالبة للكمادة الباردة","عكس مقارنة المحتوى الحراري للنواتج والمتفاعلات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-03T20:51:23.921Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الكتلة المولية لـ NH₄NO₃ = 2(14.01) + 4(1.008) + 3(16.00) = 80.05 g/mol. n = 50.0 g ÷ 80.05 g/mol = 0.625 mol. q = 0.625 mol × 27 kJ/mol = 17 kJ (رقمان معنويان). ΔH = +17 kJ لأن العملية ماصة للحرارة وتحدث عند ضغط ثابت. يشعر المصاب بالبرودة لأن محتويات الكمادة (النظام) تمتص 17 kJ من الحرارة من كاحله (المحيط)، فتنخفض درجة حرارة الكاحل.', '["الكتلة المولية 80.05 g/mol","n = 0.625 mol","q = 17 kJ","ΔH = +17 kJ","الكمادة تمتص الحرارة من الكاحل فيبرد"]'::jsonb, '["M(NH₄NO₃) = 2(14.01) + 4(1.008) + 3(16.00) = 80.05 g/mol","n = 50.0 ÷ 80.05 = 0.625 mol","q = 0.625 × 27 = 17 kJ","العملية ماصة ← ΔH = +17 kJ"]'::jsonb, '[{"element":"حساب الكتلة المولية","marks":1},{"element":"حساب عدد المولات","marks":1},{"element":"حساب كمية الحرارة","marks":1},{"element":"كتابة ΔH بإشارة موجبة","marks":1},{"element":"تفسير الشعور بالبرودة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح كامل، وإشارة صحيحة، وتفسير سليم"},{"level":"3–4 درجات","description":"حساب صحيح مع خطأ في الإشارة أو نقص في التفسير"},{"level":"1–2 درجة","description":"حساب الكتلة المولية أو عدد المولات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب الكتلة مباشرة في 27 kJ","خطأ في الكتلة المولية بإغفال إحدى ذرتي N","كتابة ΔH سالبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-03T20:51:23.922Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C1-L2-O13') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C1-L3-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الذي يجب أن تشتمل عليه المعادلة الكيميائية الحرارية؟', null, null, '["معادلة موزونة تبيّن الحالات الفيزيائية لجميع المواد والتغير في المحتوى الحراري ΔH","معادلة موزونة تبيّن صيغ المواد المتفاعلة والناتجة فقط دون أي قيمة للطاقة","معادلة غير موزونة تبيّن قيمة ΔH دون الحاجة إلى ذكر الحالات الفيزيائية للمواد","معادلة لفظية تذكر أسماء المواد المتفاعلة والناتجة ومقدار الطاقة الممتصة فقط"]'::jsonb, 'تذكر', 'تذكر مكونات المعادلة الكيميائية الحرارية', 'سهل', 'الكتاب ص 25 — كتابة المعادلات الكيميائية الحرارية'),
('mcq', 2, 'حرارة التبخر المولارية للميثانول 35.2 kJ/mol. أيّ معادلة كيميائية حرارية تمثل تبخر 1 mol من الميثانول السائل؟', null, null, '["CH₃OH(g) → CH₃OH(l)   ΔH = 35.2 kJ","CH₃OH(l) → CH₃OH(g)   ΔH = −35.2 kJ","CH₃OH(l) → CH₃OH(g)   ΔH = 35.2 kJ","CH₃OH(s) → CH₃OH(l)   ΔH = 35.2 kJ"]'::jsonb, 'تطبيق', 'كتابة معادلة تغير حالة', 'سهل', 'الكتاب ص 27 — المعادلات الكيميائية الحرارية لتغيرات الحالة'),
('mcq', 3, 'حرارة الاحتراق المولارية للإيثانول C₂H₅OH(l) هي ΔHcomb = −1367 kJ/mol، وينتج عن احتراقه الكامل CO₂(g) وH₂O(l). أيّ مما يأتي هو المعادلة الكيميائية الحرارية الصحيحة لهذا الاحتراق؟', null, null, '["C₂H₅OH(l) + 3O₂(g) → 2CO₂(g) + 3H₂O(l)   ΔH = −1367 kJ","C₂H₅OH(l) + 3O₂(g) → 2CO₂(g) + 3H₂O(l)   ΔH = +1367 kJ","C₂H₅OH(l) + O₂(g) → 2CO₂(g) + 3H₂O(l)   ΔH = −1367 kJ","C₂H₅OH + 3O₂ → 2CO₂ + 3H₂O   ΔH = −1367 kJ"]'::jsonb, 'تطبيق', 'كتابة معادلة احتراق حرارية', 'متوسط', 'الكتاب ص 30 — تفاعلات الاحتراق، التقويم 1-3'),
('mcq', 4, 'حرارة التبخر المولارية للأمونيا 23.3 kJ/mol. أيّ معادلة كيميائية حرارية تمثل تكثف 1 mol من غاز الأمونيا؟', null, null, '["NH₃(l) → NH₃(g)   ΔH = 23.3 kJ","NH₃(g) → NH₃(l)   ΔH = 23.3 kJ","NH₃(g) → NH₃(s)   ΔH = −23.3 kJ","NH₃(g) → NH₃(l)   ΔH = −23.3 kJ"]'::jsonb, 'تطبيق', 'كتابة معادلة تغير حالة عكسية', 'متوسط', 'الكتاب ص 27 — المعادلات الكيميائية الحرارية لتغيرات الحالة'),
('mcq', 5, 'ماذا تعني المعادلة الكيميائية الحرارية: 4Fe(s) + 3O₂(g) → 2Fe₂O₃(s)   ΔH = −1625 kJ؟', null, null, '["يُمتص 1625 kJ من الحرارة عند تكوّن 2 mol من Fe₂O₃(s)","يُطلق 1625 kJ من الحرارة عند تكوّن 2 mol من Fe₂O₃(s)","يُطلق 1625 kJ من الحرارة عند تكوّن 1 mol من Fe₂O₃(s)","يُطلق 1625 kJ من الحرارة عند تفاعل 1 mol من Fe(s)"]'::jsonb, 'فهم', 'تفسير معادلة كيميائية حرارية', 'متوسط', 'الكتاب ص 25 — كتابة المعادلات الكيميائية الحرارية'),
('mcq', 6, 'حرارة الاحتراق المولارية للأوكتان C₈H₁₈(l) هي −5471 kJ/mol. أيّ معادلة كيميائية حرارية تمثل احتراق 1 mol من الأوكتان احتراقًا كاملًا؟', null, null, '["2C₈H₁₈(l) + 25O₂(g) → 16CO₂(g) + 18H₂O(l)   ΔH = −5471 kJ","C₈H₁₈(l) + (25/2)O₂(g) → 8CO₂(g) + 9H₂O(l)   ΔH = +5471 kJ","C₈H₁₈(l) + (25/2)O₂(g) → 8CO₂(g) + 9H₂O(l)   ΔH = −5471 kJ","C₈H₁₈(l) + 25O₂(g) → 8CO₂(g) + 9H₂O(l)   ΔH = −5471 kJ"]'::jsonb, 'تطبيق', 'كتابة معادلة احتراق بمعامل كسري', 'صعب', 'الكتاب ص 30 — تفاعلات الاحتراق، التقويم 1-3'),
('mcq', 7, 'كُتبت معادلة احتراق الهيدروجين بالصورة: H₂(g) + ½O₂(g) → H₂O(l) + 286 kJ. أيّ مما يأتي يعبّر عن التفاعل نفسه باستعمال ΔH؟', null, null, '["H₂(g) + ½O₂(g) → H₂O(l)   ΔH = +286 kJ","H₂(g) + ½O₂(g) → H₂O(g)   ΔH = −286 kJ","H₂O(l) → H₂(g) + ½O₂(g)   ΔH = −286 kJ","H₂(g) + ½O₂(g) → H₂O(l)   ΔH = −286 kJ"]'::jsonb, 'تحليل', 'تحويل صيغة المعادلة الحرارية', 'صعب', 'الكتاب ص 30 — تفاعلات الاحتراق، التقويم 1-3'),
('essay', 1, 'حرارة الانصهار المولارية للماء 6.01 kJ/mol. اكتب المعادلة الكيميائية الحرارية لكل من: (أ) انصهار 1 mol من الجليد، (ب) تجمد 1 mol من الماء السائل، مبيّنًا إشارة ΔH في كل منهما.', null, null, null, 'تطبيق', 'كتابة معادلات تغير الحالة', 'سهل', 'الكتاب ص 27 — المعادلات الكيميائية الحرارية لتغيرات الحالة'),
('essay', 2, 'حرارة الاحتراق المولارية للبروبان C₃H₈(g) هي −2219 kJ/mol، وينتج عن احتراقه الكامل غاز ثاني أكسيد الكربون والماء السائل. اكتب المعادلة الكيميائية الحرارية لاحتراق 1 mol من البروبان، ثم وضّح ما تعنيه إشارة ΔH فيها.', null, null, null, 'تطبيق', 'كتابة معادلة احتراق موزونة مع ΔH', 'متوسط', 'الكتاب ص 30 — تفاعلات الاحتراق، التقويم 1-3'),
('essay', 3, 'للإيثانول C₂H₅OH: حرارة التبخر المولارية 38.6 kJ/mol، وحرارة الانصهار المولارية 4.94 kJ/mol. اكتب المعادلة الكيميائية الحرارية لكل من العمليات الآتية لـ 1 mol من الإيثانول: (أ) تبخر السائل، (ب) تكثف البخار، (ج) تجمد السائل. ثم صنّف كل عملية إلى ماصة للحرارة أو طاردة لها مع التعليل.', null, null, null, 'تحليل', 'كتابة معادلات وتصنيفها', 'صعب', 'الكتاب ص 26، 27 — الجدول 1-4، المعادلات الكيميائية الحرارية لتغيرات الحالة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
