select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'المعادلة الكيميائية الحرارية معادلة كيميائية موزونة تشتمل على الحالات الفيزيائية لجميع المواد المتفاعلة والناتجة، والتغير في الطاقة الذي يُعبَّر عنه بالتغير في المحتوى الحراري ΔH.', '["","المعادلة الكيميائية العادية تكتفي بالصيغ، أما الحرارية فلا بد أن تتضمن التغير في الطاقة ΔH والحالات الفيزيائية.","المعادلة الكيميائية الحرارية يجب أن تكون موزونة، وذكر الحالات الفيزيائية لجميع المواد شرط فيها.","المعادلة الكيميائية الحرارية تكتب بالصيغ لا بالأسماء، وقد تكون الطاقة ممتصة أو منطلقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:51:23.923Z"}'::jsonb),
('mcq', 2, 2, 'التبخر تحوّل السائل إلى غاز، فيكون المتفاعل CH₃OH(l) والناتج CH₃OH(g)، وهو عملية ماصة للحرارة فتكون ΔH موجبة وتساوي ΔHvap؛ فالمعادلة: CH₃OH(l) → CH₃OH(g)   ΔH = 35.2 kJ.', '["هذه معادلة التكثف (غاز → سائل)، وللتكثف ΔH سالبة تساوي −35.2 kJ لا موجبة.","اتجاه التحول صحيح، لكن التبخر ماص للحرارة فإشارة ΔH موجبة لا سالبة.","","هذه معادلة انصهار (صلب → سائل)، وقيمتها حرارة الانصهار المولارية لا حرارة التبخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-03T20:51:23.923Z"}'::jsonb),
('mcq', 3, 0, 'المعادلة موزونة (C: 2 = 2، H: 6 = 6، O: 1 + 6 = 4 + 3 = 7)، وتبيّن الحالات الفيزيائية لجميع المواد، وإشارة ΔH سالبة لأن الاحتراق طارد للحرارة؛ فالصحيحة: C₂H₅OH(l) + 3O₂(g) → 2CO₂(g) + 3H₂O(l)   ΔH = −1367 kJ.', '["","الاحتراق تفاعل طارد للحرارة، فإشارة ΔH سالبة لا موجبة.","المعادلة غير موزونة؛ عدد ذرات الأكسجين في المتفاعلات 3 وفي النواتج 7، ويلزم 3O₂.","المعادلة موزونة لكنها تخلو من الحالات الفيزيائية للمواد، وهي شرط في المعادلة الكيميائية الحرارية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-03T20:51:23.923Z"}'::jsonb),
('mcq', 4, 3, 'التكثف تحوّل الغاز إلى سائل، وهو عكس التبخر؛ لذا ΔHcond = −ΔHvap = −23.3 kJ، والمعادلة: NH₃(g) → NH₃(l)   ΔH = −23.3 kJ.', '["هذه معادلة التبخر (سائل → غاز) لا التكثف.","الاتجاه صحيح، لكن التكثف طارد للحرارة فإشارة ΔH سالبة لا موجبة.","التكثف ينتج سائلًا لا صلبًا؛ وتحول الغاز إلى صلب مباشرة ليس تكثفًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-03T20:51:23.924Z"}'::jsonb),
('mcq', 5, 1, 'قيمة ΔH في المعادلة الحرارية تخص الكميات المكتوبة بالمعاملات: 4 mol Fe و3 mol O₂ تكوّن 2 mol Fe₂O₃، والإشارة السالبة تعني أن الحرارة منطلقة؛ فيُطلق 1625 kJ عند تكوّن 2 mol من Fe₂O₃(s).', '["الإشارة السالبة لـ ΔH تعني أن التفاعل طارد للحرارة، لا ماص لها.","","القيمة تخص 2 mol من Fe₂O₃ كما في المعامل، أما 1 mol فيطلق نصفها.","القيمة تخص 4 mol من Fe كما في المعامل، لا 1 mol منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:51:23.924Z"}'::jsonb),
('mcq', 6, 2, 'لتمثيل حرارة احتراق 1 mol يُجعل معامل الأوكتان 1، فيلزم (25/2)O₂ لوزن الأكسجين (16 + 9 = 25 ذرة)، وتكون ΔH = −5471 kJ لأن الاحتراق طارد؛ فالصحيحة: C₈H₁₈(l) + (25/2)O₂(g) → 8CO₂(g) + 9H₂O(l)   ΔH = −5471 kJ.', '["المعادلة موزونة لكنها لـ 2 mol من الأوكتان، فتكون ΔH لها ضعف القيمة (−10942 kJ) لا −5471 kJ.","المعادلة موزونة، لكن الاحتراق طارد للحرارة فإشارة ΔH سالبة لا موجبة.","","المعادلة غير موزونة؛ 25O₂ تعطي 50 ذرة أكسجين بينما في النواتج 25 ذرة فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-03T20:51:23.924Z"}'::jsonb),
('mcq', 7, 3, 'كتابة الطاقة في جهة النواتج تعني أن الحرارة منطلقة، فالتفاعل طارد وإشارة ΔH سالبة، مع بقاء المواد وحالاتها كما هي؛ فالمعادلة المكافئة: H₂(g) + ½O₂(g) → H₂O(l)   ΔH = −286 kJ.', '["الطاقة المكتوبة مع النواتج طاقة منطلقة، فإشارة ΔH سالبة لا موجبة.","غُيّرت حالة الماء الناتج من سائل إلى غاز، والحالة الفيزيائية جزء من المعادلة ولا يجوز تغييرها.","هذه معادلة التفاعل العكسي (تفكك الماء)، وهو ماص للحرارة، فلا تمثل التفاعل نفسه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-03T20:51:23.925Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الانصهار: H₂O(s) → H₂O(l)   ΔHfus = 6.01 kJ، وإشارة ΔH موجبة لأن الانصهار ماص للحرارة. (ب) التجمد: H₂O(l) → H₂O(s)   ΔHsolid = −6.01 kJ، وإشارة ΔH سالبة لأن التجمد طارد للحرارة، وقيمتها مساوية لقيمة ΔHfus مع اختلاف الإشارة.', '["معادلة الانصهار H₂O(s) → H₂O(l) بالحالات الفيزيائية","ΔH = +6.01 kJ للانصهار (ماص)","معادلة التجمد H₂O(l) → H₂O(s) بالحالات الفيزيائية","ΔH = −6.01 kJ للتجمد (طارد)"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة الانصهار بالحالات الصحيحة","marks":1},{"element":"قيمة ΔH للانصهار وإشارتها","marks":1},{"element":"معادلة التجمد بالحالات الصحيحة","marks":1},{"element":"قيمة ΔH للتجمد وإشارتها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المعادلتان صحيحتان بالحالات الفيزيائية مع قيمة ΔH وإشارتها في كل منهما"},{"level":"2–3 درجات","description":"معادلة واحدة كاملة، أو المعادلتان بإشارة خاطئة أو حالة ناقصة"},{"level":"1 درجة","description":"كتابة إحدى المعادلتين دون قيمة ΔH أو بحالات خاطئة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة ΔH موجبة للتجمد","إهمال الرموز (s) و(l)","عكس اتجاه معادلة الانصهار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-03T20:51:23.925Z"}'::jsonb),
('essay', 2, null::int, null, null, 'C₃H₈(g) + 5O₂(g) → 3CO₂(g) + 4H₂O(l)   ΔH = −2219 kJ. الوزن: 3 ذرات C تعطي 3CO₂، و8 ذرات H تعطي 4H₂O، فيصبح الأكسجين في النواتج 6 + 4 = 10 ذرات، أي 5O₂. والإشارة السالبة لـ ΔH تعني أن التفاعل طارد للحرارة، أي يُطلق 2219 kJ عند احتراق 1 mol من البروبان، وأن المحتوى الحراري للنواتج أقل منه للمتفاعلات.', '["الصيغ الصحيحة للمتفاعلات والنواتج","وزن المعادلة بمعاملات 1، 5، 3، 4","الحالات الفيزيائية (g) و(l)","ΔH = −2219 kJ","تفسير الإشارة السالبة بأن التفاعل طارد للحرارة"]'::jsonb, '["وزن الكربون: C₃H₈ → 3CO₂","وزن الهيدروجين: 8 H → 4H₂O","وزن الأكسجين: 3 × 2 + 4 × 1 = 10 ذرات → 5O₂","إضافة الحالات الفيزيائية لكل مادة","كتابة ΔH = −2219 kJ بجانب المعادلة"]'::jsonb, '[{"element":"الصيغ والوزن الصحيح","marks":2},{"element":"الحالات الفيزيائية","marks":1},{"element":"قيمة ΔH وإشارتها","marks":1},{"element":"تفسير الإشارة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلة موزونة كاملة بالحالات وقيمة ΔH الصحيحة مع تفسير الإشارة"},{"level":"3–4 درجات","description":"معادلة صحيحة مع نقص في الحالات أو في التفسير"},{"level":"1–2 درجة","description":"صيغ صحيحة دون وزن أو دون ΔH"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الماء غازًا رغم أن المعطى ماء سائل","وزن الأكسجين بـ 4O₂ أو 7O₂","كتابة ΔH موجبة للاحتراق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-03T20:51:23.926Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) C₂H₅OH(l) → C₂H₅OH(g)   ΔH = 38.6 kJ: ماصة؛ لأن السائل يمتص حرارة لتتحرر جزيئاته إلى الحالة الغازية، وΔH موجبة. (ب) C₂H₅OH(g) → C₂H₅OH(l)   ΔH = −38.6 kJ: طاردة؛ لأن التكثف عكس التبخر فتكون ΔHcond = −ΔHvap. (ج) C₂H₅OH(l) → C₂H₅OH(s)   ΔH = −4.94 kJ: طاردة؛ لأن التجمد عكس الانصهار فتكون ΔHsolid = −ΔHfus.', '["معادلة التبخر وΔH = 38.6 kJ","معادلة التكثف وΔH = −38.6 kJ","معادلة التجمد وΔH = −4.94 kJ","تصنيف التبخر ماصًا والتكثف والتجمد طاردين","التعليل بالإشارة أو بالعلاقة ΔHcond = −ΔHvap وΔHsolid = −ΔHfus"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة التبخر مع ΔH","marks":1},{"element":"معادلة التكثف مع ΔH","marks":1},{"element":"معادلة التجمد مع ΔH","marks":1},{"element":"التصنيف الصحيح للعمليات الثلاث","marks":1},{"element":"التعليل","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"المعادلات الثلاث صحيحة بالحالات وقيم ΔH وإشاراتها، مع تصنيف وتعليل صحيحين"},{"level":"4–5 درجات","description":"المعادلات صحيحة مع نقص في التعليل أو خطأ في إشارة واحدة"},{"level":"1–3 درجات","description":"معادلة أو معادلتان صحيحتان، أو تصنيف دون معادلات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال 38.6 kJ لعملية التجمد بدلًا من 4.94 kJ","إعطاء التكثف إشارة موجبة","كتابة الناتج في التجمد بالحالة (g)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-03T20:51:23.926Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C1-L3-O01') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C1-L3-O02'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'أيّ زوج من تغيرات الحالة الآتية يتكون من عمليتين ماصتين للحرارة؟', null, null, '["التبخر والانصهار","التكثف والتجمد","التبخر والتجمد","التكثف والانصهار"]'::jsonb, 'تذكر', 'تصنيف تغيرات الحالة', 'سهل', 'الكتاب ص 26 — تغيرات الحالة'),
('mcq', 2, 'لماذا تشعر ببرودة في جسمك عندما تخرج من حمّام ساخن؟', null, null, '["لأن الماء على الجلد يطلق حرارة إلى الجلد عندما يتبخر","لأن الماء على الجلد يمتص حرارة من الجلد لكي يتبخر","لأن بخار الماء يمتص حرارة من الجلد عندما يتكثف عليه","لأن الجلد يطلق حرارة إلى الماء فيتجمد الماء عليه"]'::jsonb, 'فهم', 'تفسير ظاهرة حياتية', 'متوسط', 'الكتاب ص 26 — تغيرات الحالة'),
('mcq', 3, 'ماذا يحدث لطاقة النظام عندما يتكثف 1 mol من بخار الماء ليكوّن ماءً سائلًا؟', null, null, '["تزداد طاقة النظام؛ إذ يمتص 40.7 kJ","تقل طاقة النظام؛ إذ يُطلق 6.01 kJ","تبقى طاقة النظام ثابتة؛ لأن درجة الحرارة لا تتغير","تقل طاقة النظام؛ إذ يُطلق 40.7 kJ"]'::jsonb, 'فهم', 'وصف تغير طاقة النظام', 'متوسط', 'الكتاب ص 27 — المعادلات الكيميائية الحرارية لتغيرات الحالة (الشكل 1-9)'),
('mcq', 4, 'عندما تضع مكعبًا من الثلج في كأس ماء، يبرد الماء. ما التفسير الصحيح لذلك؟', null, null, '["الثلج يطلق حرارة إلى الماء في أثناء انصهاره","الثلج ينقل البرودة إلى الماء فتنخفض درجة حرارته","الماء يزوّد الثلج بالحرارة التي يحتاج إليها لينصهر","الماء يطلق حرارة لأن جزءًا منه يتبخر عند ملامسة الثلج"]'::jsonb, 'فهم', 'تفسير ظاهرة حياتية', 'سهل', 'الكتاب ص 26 — تغيرات الحالة'),
('mcq', 5, 'حرارة التبخر المولارية للماء 40.7 kJ/mol، والكتلة المولية للماء 18.02 g/mol. ما كمية الحرارة اللازمة لتبخير 36.0 g من الماء عند درجة غليانه؟', null, null, '["81.3 kJ","40.7 kJ","12.0 kJ","1465 kJ"]'::jsonb, 'تطبيق', 'حساب حرارة تغير الحالة', 'متوسط', 'الكتاب ص 26، 29 — الجدول 1-4، مسائل تدريبية'),
('mcq', 6, 'سُخِّنت عينة من الجليد بمعدل ثابت، فسُجلت البيانات في الجدول. فيمَ تُستعمل الحرارة الممتصة في المدة من 1.0 min إلى 2.0 min؟', '{"headers":["الزمن (min)","درجة الحرارة (°C)"],"rows":[["0.0","−20"],["1.0","0"],["2.0","0"],["3.0","9"],["6.0","58"],["9.0","92"],["11.0","100"],["18.0","100"],["24.0","100"],["25.0","120"]]}'::jsonb, null, '["في زيادة طاقة الحركة لجزيئات الماء فترتفع درجة حرارتها","تُفقد كلها إلى المحيط فلا يكتسب الماء أي طاقة","في زيادة طاقة الوضع للجزيئات في أثناء انصهار الجليد","في تكثف بخار الماء وتحوله إلى ماء سائل"]'::jsonb, 'تحليل', 'تحليل بيانات منحنى التسخين', 'صعب', 'الكتاب ص 28 — مختبر حل المشكلات: منحنى التسخين للماء'),
('mcq', 7, 'عند تسخين عينة من الجليد بمعدل ثابت، ظلّت درجة الحرارة ثابتة عند 0 °C مدة قصيرة، ثم ظلّت ثابتة عند 100 °C مدة أطول بكثير. ما سبب طول المدة الثانية؟', null, null, '["لأن حرارة الانصهار المولارية للماء أكبر من حرارة التبخر المولارية","لأن حرارة التبخر المولارية للماء أكبر من حرارة الانصهار المولارية","لأن التبخر عملية طاردة للحرارة بينما الانصهار ماص للحرارة","لأن كتلة الماء تزداد في أثناء الغليان مقارنة بكتلته عند الانصهار"]'::jsonb, 'تحليل', 'تفسير منحنى التسخين', 'صعب', 'الكتاب ص 28 — مختبر حل المشكلات: منحنى التسخين للماء'),
('essay', 1, 'صنّف تغيرات الحالة الآتية إلى ماصة للحرارة أو طاردة لها، وبيّن في كل حالة هل تزداد طاقة النظام أم تقل: التبخر، الانصهار، التكثف، التجمد.', null, null, null, 'فهم', 'تصنيف مع بيان تغير الطاقة', 'سهل', 'الكتاب ص 27 — المعادلات الكيميائية الحرارية لتغيرات الحالة (الشكل 1-9)'),
('essay', 2, 'للماء: ΔHvap = 40.7 kJ/mol وΔHfus = 6.01 kJ/mol. اكتب قيمتي ΔHcond وΔHsolid للماء، ثم صف انتقال الطاقة بين النظام والمحيط في كل من التكثف والتجمد، موضحًا العلاقة بين كل عملية وعكسها.', null, null, null, 'فهم', 'وصف وتفسير', 'متوسط', 'الكتاب ص 27 — المعادلات الكيميائية الحرارية لتغيرات الحالة (الشكل 1-9)'),
('essay', 3, 'الكتلة المولية للماء 18.02 g/mol، وΔHvap = 40.7 kJ/mol، وΔHfus = 6.01 kJ/mol. احسب كمية الحرارة المنطلقة عند: (أ) تجمد 54.0 g من الماء عند 0 °C، (ب) تكثف 54.0 g من بخار الماء عند 100 °C. ثم فسّر لماذا تختلف الكميتان رغم تساوي الكتلة.', null, null, null, 'تطبيق', 'حساب ومقارنة', 'صعب', 'الكتاب ص 26، 27 — الجدول 1-4، تغيرات الحالة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C1-L3-O02') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'يحتاج السائل إلى حرارة لكي يتبخر، وتحتاج المادة الصلبة إلى حرارة لكي تنصهر؛ لذا التبخر والانصهار عمليتان ماصتان للحرارة وΔH لكل منهما موجبة.', '["","التكثف والتجمد عمليتان طاردتان للحرارة، وهما عكس التبخر والانصهار.","التبخر ماص، لكن التجمد طارد للحرارة.","الانصهار ماص، لكن التكثف طارد للحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-03T20:51:23.927Z"}'::jsonb),
('mcq', 2, 1, 'يحتاج الماء إلى حرارة لكي يتبخر، فيمتصها من الجلد؛ وكلما امتص الماء الحرارة من الجلد وتبخر ازدادت برودة الجسم.', '["التبخر عملية ماصة للحرارة، فالماء يأخذ الحرارة من الجلد ولا يعطيه إياها.","","التكثف عملية طاردة للحرارة لا ماصة، والذي يحدث على الجلد هو تبخر الماء.","الماء على الجلد لا يتجمد، والبرودة سببها تبخره بامتصاص الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-03T20:51:23.927Z"}'::jsonb),
('mcq', 3, 3, 'التكثف عكس التبخر، فكمية الحرارة المنطلقة فيه تساوي الكمية الممتصة في التبخر: ΔHcond = −ΔHvap = −40.7 kJ؛ لذا تقل طاقة النظام بإطلاق 40.7 kJ.', '["هذا ما يحدث في التبخر (العملية العكسية)، أما التكثف فطارد للحرارة.","6.01 kJ قيمة تخص الانصهار والتجمد، لا التبخر والتكثف.","ثبات درجة الحرارة في أثناء تغير الحالة لا يعني ثبات الطاقة؛ فالنظام يفقد حرارة في التكثف.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-03T20:51:23.928Z"}'::jsonb),
('mcq', 4, 2, 'الانصهار عملية ماصة للحرارة، فمكعب الثلج يحتاج إلى حرارة لكي ينصهر ويأخذها من الماء المحيط به؛ ففقدان الماء هذه الحرارة يجعله يبرد.', '["الانصهار ماص للحرارة لا طارد لها؛ فالثلج يأخذ الحرارة من الماء ولا يعطيه.","البرودة ليست شيئًا ينتقل؛ الذي ينتقل هو الحرارة من الماء إلى الثلج.","","التبخر ماص للحرارة لا طارد، وليس هو سبب برودة الماء هنا؛ السبب انصهار الثلج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-03T20:51:23.928Z"}'::jsonb),
('mcq', 5, 0, 'عدد المولات = 36.0 g ÷ 18.02 g/mol = 2.00 mol، والحرارة = 2.00 mol × 40.7 kJ/mol = 81.3 kJ.', '["","هذه حرارة تبخير 1 mol فقط؛ نسي الطالب تحويل الكتلة إلى مولات وضربها في ΔHvap.","استُعملت حرارة الانصهار (6.01 kJ/mol) بدلًا من حرارة التبخر: 2.00 × 6.01 = 12.0 kJ.","ضُربت الكتلة بالجرام مباشرة في ΔHvap (36.0 × 40.7) دون تحويلها إلى مولات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-03T20:51:23.928Z"}'::jsonb),
('mcq', 6, 2, 'درجة الحرارة ثابتة عند 0 °C رغم استمرار التسخين، أي أن الجليد ينصهر؛ والحرارة الممتصة تُستعمل في التغلب على قوى التجاذب بين الجزيئات فتزداد طاقة الوضع دون أن تزداد طاقة الحركة.', '["لو زادت طاقة الحركة لارتفعت درجة الحرارة، لكنها ثابتة عند 0 °C في هذه المدة.","التسخين مستمر بمعدل ثابت، والماء يمتص الحرارة لينصهر؛ فهو يكتسب طاقة فعلًا.","","عند 0 °C يتحول الجليد إلى سائل (انصهار)، والتكثف عملية طاردة تحدث عند تحول البخار إلى سائل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-03T20:51:23.929Z"}'::jsonb),
('mcq', 7, 1, 'تبخير 1 mol من الماء يحتاج إلى 40.7 kJ، وصهره يحتاج إلى 6.01 kJ فقط؛ ومع ثبات معدل التسخين يلزم وقت أطول لتزويد الكمية الأكبر من الحرارة؛ فحرارة التبخر المولارية أكبر من حرارة الانصهار المولارية.', '["العكس هو الصحيح: ΔHvap = 40.7 kJ/mol أكبر من ΔHfus = 6.01 kJ/mol.","","التبخر والانصهار كلاهما ماص للحرارة.","كتلة العينة لا تزداد بالتسخين؛ بل الفرق في كمية الحرارة اللازمة لكل مول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-03T20:51:23.929Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التبخر: ماص للحرارة، وتزداد طاقة النظام. الانصهار: ماص للحرارة، وتزداد طاقة النظام. التكثف: طارد للحرارة، وتقل طاقة النظام. التجمد: طارد للحرارة، وتقل طاقة النظام. فالتحول نحو حالة أعلى طاقة (صلب → سائل → غاز) يمتص الحرارة، والتحول العكسي يطلقها.', '["التبخر ماص وتزداد الطاقة","الانصهار ماص وتزداد الطاقة","التكثف طارد وتقل الطاقة","التجمد طارد وتقل الطاقة"]'::jsonb, '[]'::jsonb, '[{"element":"التبخر","marks":1},{"element":"الانصهار","marks":1},{"element":"التكثف","marks":1},{"element":"التجمد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف العمليات الأربع وبيان تغير طاقة النظام في كل منها تصنيفًا صحيحًا"},{"level":"2–3 درجات","description":"تصنيف صحيح لعمليتين أو ثلاث، أو تصنيف دون بيان تغير الطاقة"},{"level":"1 درجة","description":"تصنيف صحيح لعملية واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ التكثف ماصًا للحرارة","الظن أن طاقة النظام ثابتة لأن درجة الحرارة ثابتة","عدّ التجمد ماصًا لأنه يحدث في البرد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-03T20:51:23.930Z"}'::jsonb),
('essay', 2, null::int, null, null, 'ΔHcond = −40.7 kJ/mol وΔHsolid = −6.01 kJ/mol. في التكثف يفقد بخار الماء (النظام) 40.7 kJ لكل 1 mol إلى المحيط فتقل طاقته، وفي التجمد يفقد الماء السائل 6.01 kJ لكل 1 mol إلى المحيط. والحرارة المنطلقة في العملية الطاردة تساوي الحرارة الممتصة في العملية الماصة العكسية: ΔHvap = −ΔHcond وΔHfus = −ΔHsolid؛ أي أن القيمتين متساويتان رقميًّا ومختلفتان في الإشارة.', '["ΔHcond = −40.7 kJ/mol","ΔHsolid = −6.01 kJ/mol","في التكثف والتجمد تنتقل الحرارة من النظام إلى المحيط","العلاقة ΔHvap = −ΔHcond وΔHfus = −ΔHsolid"]'::jsonb, '[]'::jsonb, '[{"element":"قيمة ΔHcond بإشارتها","marks":1},{"element":"قيمة ΔHsolid بإشارتها","marks":1},{"element":"وصف اتجاه انتقال الطاقة","marks":2},{"element":"العلاقة بين العملية وعكسها","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"القيمتان صحيحتان بإشارتيهما، ووصف صحيح لانتقال الطاقة، والعلاقتان مذكورتان"},{"level":"3–4 درجات","description":"القيمتان صحيحتان مع نقص في الوصف أو في العلاقة"},{"level":"1–2 درجة","description":"قيمة واحدة صحيحة أو وصف عام دون قيم"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة ΔHcond موجبة","الخلط بين 40.7 kJ و6.01 kJ","القول إن الطاقة تنتقل من المحيط إلى النظام في التجمد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-03T20:51:23.930Z"}'::jsonb),
('essay', 3, null::int, null, null, 'عدد المولات = 54.0 g ÷ 18.02 g/mol = 3.00 mol. (أ) الحرارة المنطلقة في التجمد = 3.00 mol × 6.01 kJ/mol = 18.0 kJ (ΔH = −18.0 kJ). (ب) الحرارة المنطلقة في التكثف = 3.00 mol × 40.7 kJ/mol = 122 kJ (ΔH = −122 kJ). تختلف الكميتان لأن تحويل الغاز إلى سائل يتضمن تغيرًا أكبر في الطاقة من تحويل السائل إلى صلب؛ فقيمة ΔHcond (−40.7 kJ/mol) أكبر رقميًّا من ΔHsolid (−6.01 kJ/mol) بنحو 7 مرات تقريبًا.', '["تحويل الكتلة إلى مولات: 3.00 mol","حرارة التجمد المنطلقة 18.0 kJ","حرارة التكثف المنطلقة 122 kJ","التعبير عن الإشارة السالبة أو أن الحرارة منطلقة","التفسير بأن ΔHcond أكبر رقميًّا من ΔHsolid"]'::jsonb, '["n = 54.0 g ÷ 18.02 g/mol = 3.00 mol","q(تجمد) = 3.00 mol × 6.01 kJ/mol = 18.0 kJ منطلقة","q(تكثف) = 3.00 mol × 40.7 kJ/mol = 122 kJ منطلقة","المقارنة: 122 kJ ÷ 18.0 kJ ≈ 6.8"]'::jsonb, '[{"element":"حساب عدد المولات","marks":1},{"element":"حساب حرارة التجمد","marks":1},{"element":"حساب حرارة التكثف","marks":1},{"element":"الوحدات والإشارة","marks":1},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"حسابات صحيحة بالوحدات والأرقام المعنوية مع تفسير صحيح للاختلاف"},{"level":"4–5 درجات","description":"حسابات صحيحة مع تفسير ناقص، أو خطأ حسابي واحد مع تفسير صحيح"},{"level":"1–3 درجات","description":"حساب عدد المولات أو أحد الجزأين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب الكتلة مباشرة في ΔH دون التحويل إلى مولات","استعمال القيمة نفسها للعمليتين","إعطاء الحرارة المنطلقة إشارة موجبة لـ ΔH"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-03T20:51:23.931Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C1-L3-O02') and x.type = v.type and x.number = v.number
