insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C1-L3-O03'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يغمر بعض المزارعين في البلاد الباردة بساتينهم بالماء عند توقع الصقيع. أيّ عملية يستغلونها لحماية الفاكهة والخضراوات؟', null, null, '["تبخر الماء الذي يمتص حرارة من الهواء","تجمد الماء الذي يطلق حرارة إلى المحيط","انصهار الجليد الذي يطلق حرارة إلى المحيط","تكثف بخار الماء الذي يمتص حرارة من الثمار"]'::jsonb, 'تذكر', 'تذكر تطبيق حياتي', 'سهل', 'الكتاب ص 27 — استغلال حرارة الانصهار لحماية الفاكهة والخضراوات من التجمد'),
('mcq', 2, 'ما قيمة ΔHsolid للماء، وما دلالة إشارتها؟ (ΔHfus للماء = 6.01 kJ/mol، وΔHvap = 40.7 kJ/mol)', null, null, '["+6.01 kJ/mol؛ لأن التجمد يمتص الحرارة","−40.7 kJ/mol؛ لأن التجمد يطلق الحرارة","+40.7 kJ/mol؛ لأن التجمد يمتص الحرارة","−6.01 kJ/mol؛ لأن التجمد يطلق الحرارة"]'::jsonb, 'فهم', 'ربط القيمة بالإشارة', 'متوسط', 'الكتاب ص 27 — الشكل 1-9، ΔHfus = −ΔHsolid'),
('mcq', 3, 'كيف تحمي الطاقة المنطلقة من تجمد الماء الثمار في البساتين المغمورة بالماء ليلة الصقيع؟', null, null, '["تدفئ الهواء المحيط بالثمار بدرجة تكفي لمنع تلفها","تبرّد الثمار فتصبح أكثر مقاومة لدرجات الحرارة المنخفضة","تحوّل الماء إلى بخار يغطي الثمار ويعزلها عن الهواء","تصهر الجليد المتكوّن على الثمار فور تكوّنه"]'::jsonb, 'فهم', 'تفسير آلية الحماية', 'متوسط', 'الكتاب ص 27 — استغلال حرارة الانصهار لحماية الفاكهة والخضراوات من التجمد'),
('mcq', 4, 'أيّ معادلة كيميائية حرارية تمثل العملية التي تحمي الثمار من التلف عند غمر البستان بالماء ليلة الصقيع؟', null, null, '["H₂O(s) → H₂O(l)   ΔH = +6.01 kJ","H₂O(l) → H₂O(g)   ΔH = +40.7 kJ","H₂O(l) → H₂O(s)   ΔH = −6.01 kJ","H₂O(l) → H₂O(s)   ΔH = +6.01 kJ"]'::jsonb, 'فهم', 'اختيار المعادلة الممثلة', 'متوسط', 'الكتاب ص 27 — المعادلات الكيميائية الحرارية لتغيرات الحالة'),
('mcq', 5, 'تجمّد 9.00 kg من الماء في بستان ليلة الصقيع. ما كمية الحرارة المنطلقة إلى المحيط؟ (ΔHfus للماء = 6.01 kJ/mol، والكتلة المولية للماء = 18.02 g/mol)', null, null, '["5.41×10⁴ kJ","2.03×10⁴ kJ","3.00 kJ","3.00×10³ kJ"]'::jsonb, 'تطبيق', 'حساب الحرارة المنطلقة من التجمد', 'صعب', 'الكتاب ص 26، 27 — الجدول 1-4، حماية الفاكهة من التجمد'),
('mcq', 6, 'لو أن الماء الذي غُمر به البستان تبخّر بدلًا من أن يتجمد، فهل يحمي الثمار من الصقيع؟', null, null, '["لا؛ لأن التبخر يمتص حرارة من المحيط فيزيده برودة","نعم؛ لأن التبخر يطلق حرارة تدفئ الهواء المحيط","نعم؛ لأن أي تغير في حالة الماء يطلق حرارة","لا؛ لأن التبخر لا يصاحبه أي تغير في الطاقة"]'::jsonb, 'تحليل', 'توقع وتبرير', 'صعب', 'الكتاب ص 26، 27 — تغيرات الحالة، حماية الفاكهة'),
('mcq', 7, 'متى يغمر المزارعون في البلاد الباردة بساتينهم بالماء لحماية الثمار؟', null, null, '["عندما يُتوقع ارتفاع درجة الحرارة في النهار","عندما يُتوقع انخفاض درجة الحرارة إلى درجة التجمد","بعد انصهار الجليد المتكوّن على الثمار صباحًا","عندما يكون الجو دافئًا والرطوبة مرتفعة"]'::jsonb, 'تذكر', 'تذكر ظروف التطبيق', 'سهل', 'الكتاب ص 27 — استغلال حرارة الانصهار لحماية الفاكهة والخضراوات من التجمد'),
('essay', 1, 'علّل: يغمر بعض المزارعين في البلاد الباردة بساتينهم وحقولهم بالماء في الليلة التي يُتوقع أن تنخفض فيها درجة الحرارة إلى درجة التجمد.', null, null, null, 'فهم', 'تعليل ظاهرة', 'سهل', 'الكتاب ص 27 — استغلال حرارة الانصهار لحماية الفاكهة والخضراوات من التجمد'),
('essay', 2, 'اكتب المعادلة الكيميائية الحرارية للعملية التي يستغلها المزارعون عند غمر البساتين بالماء ليلة الصقيع، علمًا بأن ΔHfus للماء = 6.01 kJ/mol، ثم وضّح العلاقة بين ΔHsolid وΔHfus، وبيّن لماذا تكون إشارة ΔHsolid مفيدة للمزارع.', null, null, null, 'فهم', 'كتابة معادلة وتفسيرها', 'متوسط', 'الكتاب ص 27 — المعادلات الكيميائية الحرارية لتغيرات الحالة، حماية الفاكهة'),
('essay', 3, 'قدّر مزارع أن حماية بستانه في ليلة باردة تتطلب انطلاق 1.20×10⁴ kJ من الحرارة. احسب كتلة الماء (بالكيلوجرام) التي يجب أن تتجمد لإطلاق هذه الكمية (ΔHfus للماء = 6.01 kJ/mol، والكتلة المولية للماء = 18.02 g/mol)، ثم فسّر لماذا يجب أن يتجمد الماء لا أن يتبخر.', null, null, null, 'تطبيق', 'حساب وتفسير', 'صعب', 'الكتاب ص 26، 27 — الجدول 1-4، حماية الفاكهة من التجمد')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C1-L3-O03') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'عندما تنخفض درجة الحرارة إلى درجة التجمد يتجمد الماء المغمور به البستان، والتجمد عملية طاردة للحرارة تطلق طاقة ΔHsolid تدفئ الهواء المحيط؛ فالعملية المستغلة هي تجمد الماء الذي يطلق حرارة إلى المحيط.', '["التبخر ماص للحرارة فيبرّد المحيط ولا يدفئه، وليس هو ما يحدث للماء عند الصقيع.","","الانصهار عملية ماصة للحرارة لا طاردة، ولا يحدث عند انخفاض الحرارة إلى درجة التجمد.","التكثف عملية طاردة للحرارة لا ماصة، وليس هو العملية التي يعتمد عليها المزارعون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-03T20:51:23.932Z"}'::jsonb),
('mcq', 2, 3, 'التجمد عكس الانصهار، فـ ΔHsolid = −ΔHfus = −6.01 kJ/mol، والإشارة السالبة تدل على أن التجمد يطلق الحرارة إلى المحيط.', '["القيمة الموجبة هي ΔHfus للانصهار؛ أما التجمد فطارد وإشارته سالبة.","40.7 kJ/mol قيمة تخص التبخر والتكثف لا التجمد.","القيمة والإشارة كلتاهما خطأ: هذه ΔHvap للتبخر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-03T20:51:23.932Z"}'::jsonb),
('mcq', 3, 0, 'الطاقة ΔHsolid المنطلقة في أثناء تجمد الماء تنتقل إلى الهواء المحيط فتدفئه لدرجة كافية لمنع الفاكهة والخضراوات من التلف.', '["","الطاقة المنطلقة تدفئ المحيط لا تبرّده؛ فالتجمد عملية طاردة للحرارة.","الحرارة المنطلقة من التجمد لا تكفي لتبخير الماء، والماء يتجمد في الليلة الباردة ولا يتبخر.","الماء المغمور به البستان هو الذي يتجمد، والطاقة المنطلقة تدفئ الهواء ولا تمنع التجمد نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-03T20:51:23.932Z"}'::jsonb),
('mcq', 4, 2, 'العملية الحامية هي تجمد الماء السائل إلى جليد، وهي طاردة للحرارة: H₂O(l) → H₂O(s)   ΔH = −6.01 kJ.', '["هذه معادلة انصهار الجليد، وهي ماصة للحرارة فلا تدفئ المحيط.","هذه معادلة التبخر، وهي ماصة تبرّد المحيط.","","الاتجاه صحيح (تجمد)، لكن التجمد طارد فإشارة ΔH سالبة لا موجبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-03T20:51:23.932Z"}'::jsonb),
('mcq', 5, 3, 'الكتلة = 9.00 kg = 9.00×10³ g، وعدد المولات = 9.00×10³ g ÷ 18.02 g/mol = 499 mol، والحرارة المنطلقة = 499 mol × 6.01 kJ/mol = 3.00×10³ kJ.', '["ضُربت الكتلة بالجرام مباشرة في ΔHfus (9.00×10³ × 6.01) دون تحويلها إلى مولات.","استُعملت حرارة التبخر (40.7 kJ/mol) بدلًا من حرارة الانصهار.","لم تُحوَّل الكتلة من kg إلى g، فحُسب عدد المولات 9.00 ÷ 18.02.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-03T20:51:23.932Z"}'::jsonb),
('mcq', 6, 0, 'التبخر عملية ماصة للحرارة (ΔHvap = +40.7 kJ/mol)، فالماء المتبخر يأخذ الحرارة من الهواء والثمار المحيطة فيزيدها برودة؛ لذا لا يحميها، والحماية تأتي من التجمد الطارد للحرارة.', '["","التبخر ماص للحرارة لا طارد لها، فهو يبرّد المحيط.","ليست كل تغيرات الحالة طاردة؛ فالتبخر والانصهار ماصان للحرارة.","التبخر يصاحبه امتصاص 40.7 kJ لكل 1 mol من الماء، فهو تغير في الطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:51:23.933Z"}'::jsonb),
('mcq', 7, 1, 'يغمر المزارعون بساتينهم بالماء في الليلة التي يُتوقع أن تنخفض فيها درجة الحرارة إلى درجة التجمد، ليتجمد الماء ويطلق حرارة تدفئ الهواء المحيط.', '["ارتفاع درجة الحرارة لا يهدد الثمار بالتجمد، فلا حاجة إلى الغمر.","","بعد انصهار الجليد يكون خطر الصقيع قد انتهى، والمقصود حماية الثمار قبل التلف.","الجو الدافئ لا يسبب تجمد الماء، فلا تنطلق الحرارة اللازمة للحماية ولا حاجة إليها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-03T20:51:23.933Z"}'::jsonb),
('essay', 1, null::int, null, null, 'لأن الماء المغمور به البستان يتجمد عندما تنخفض درجة الحرارة إلى درجة التجمد، والتجمد عملية طاردة للحرارة تطلق طاقة ΔHsolid (−6.01 kJ لكل 1 mol من الماء)، فتنتقل هذه الحرارة إلى الهواء المحيط وتدفئه لدرجة كافية لمنع الفاكهة والخضراوات من التلف.', '["الماء يتجمد عند انخفاض الحرارة","التجمد عملية طاردة للحرارة","الحرارة المنطلقة تدفئ الهواء المحيط","منع تلف الفاكهة والخضراوات"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر أن الماء يتجمد","marks":1},{"element":"التجمد طارد للحرارة (ΔHsolid سالبة)","marks":1},{"element":"الحرارة المنطلقة تدفئ الهواء المحيط وتمنع التلف","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل كامل: تجمد الماء، وإطلاقه الحرارة، ودورها في تدفئة الهواء وحماية الثمار"},{"level":"1–2 درجة","description":"ذكر أن الماء يتجمد أو يطلق حرارة دون ربط ذلك بتدفئة الهواء وحماية الثمار"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الماء يمتص البرودة","عدّ التجمد عملية ماصة للحرارة","تفسير الحماية بتبخر الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-03T20:51:23.933Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المعادلة: H₂O(l) → H₂O(s)   ΔHsolid = −6.01 kJ. العلاقة: ΔHfus = −ΔHsolid؛ أي أن الحرارة المنطلقة عند تجمد 1 mol من الماء تساوي الحرارة الممتصة عند انصهار 1 mol من الجليد مع اختلاف الإشارة. والإشارة السالبة تعني أن التجمد يطلق الحرارة إلى المحيط، فيستفيد المزارع منها في تدفئة الهواء حول الثمار ومنع تلفها.', '["المعادلة H₂O(l) → H₂O(s) بالحالات الفيزيائية","ΔHsolid = −6.01 kJ","العلاقة ΔHfus = −ΔHsolid","الإشارة السالبة تعني إطلاق حرارة تدفئ الهواء المحيط"]'::jsonb, '[]'::jsonb, '[{"element":"المعادلة بالحالات الصحيحة","marks":1},{"element":"قيمة ΔHsolid وإشارتها","marks":1},{"element":"العلاقة بين ΔHsolid وΔHfus","marks":1},{"element":"ربط الإشارة بفائدة المزارع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"معادلة صحيحة بقيمة ΔH وإشارتها، وعلاقة صحيحة، وربط واضح بحماية الثمار"},{"level":"2–3 درجات","description":"معادلة صحيحة مع نقص في العلاقة أو في الربط"},{"level":"1 درجة","description":"معادلة بإشارة خاطئة أو علاقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة معادلة الانصهار بدلًا من التجمد","كتابة ΔHsolid = +6.01 kJ","استعمال 40.7 kJ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-03T20:51:23.933Z"}'::jsonb),
('essay', 3, null::int, null, null, 'عدد المولات = 1.20×10⁴ kJ ÷ 6.01 kJ/mol = 2.00×10³ mol. الكتلة = 2.00×10³ mol × 18.02 g/mol = 3.60×10⁴ g = 36.0 kg. يجب أن يتجمد الماء لأن التجمد طارد للحرارة (ΔHsolid = −6.01 kJ/mol) فيدفئ الهواء المحيط، أما التبخر فماص للحرارة (ΔHvap = +40.7 kJ/mol) يأخذ الحرارة من المحيط فيزيده برودة ويضر الثمار.', '["حساب عدد المولات 2.00×10³ mol","حساب الكتلة 3.60×10⁴ g","التحويل إلى 36.0 kg","التجمد طارد يدفئ المحيط","التبخر ماص يبرّد المحيط"]'::jsonb, '["n = q ÷ ΔHfus = 1.20×10⁴ kJ ÷ 6.01 kJ/mol = 2.00×10³ mol","m = n × M = 2.00×10³ mol × 18.02 g/mol = 3.60×10⁴ g","m = 3.60×10⁴ g ÷ 1000 = 36.0 kg"]'::jsonb, '[{"element":"حساب عدد المولات","marks":1},{"element":"حساب الكتلة بالجرام","marks":1},{"element":"التحويل إلى kg بالأرقام المعنوية","marks":1},{"element":"تفسير اختيار التجمد لا التبخر","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح بالخطوات والوحدات وتفسير صحيح للمقارنة بين التجمد والتبخر"},{"level":"3–4 درجات","description":"حساب صحيح دون تفسير كامل، أو تفسير صحيح مع خطأ في التحويل"},{"level":"1–2 درجة","description":"حساب عدد المولات فقط، أو تفسير دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب الحرارة في ΔHfus بدلًا من القسمة","إغفال التحويل من g إلى kg","استعمال ΔHvap في الحساب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-03T20:51:23.933Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
